window.HARDTRP.receive("212725",[[212726,"2026-09-15T10:39:45",9,"Начало темы.\n\n@QURTZZ  — Дм этой темы.",212725,null],[218168,"2026-09-17T11:36:43",31,"Участники:\n1. Марко Веньер - https://t.me/c/3239766844/8419/8427 @dunchev \n2. Беатриче Висконти да Вальдрио - https://t.me/c/3239766844/8404/8406 @PaIIasCat \n3. Ясмин - https://t.me/c/3239766844/8232/8238 @lady_godzilla",212725,null],[218169,"2026-09-17T11:36:53",31,"Резерв",212725,null],[218170,"2026-09-17T11:36:58",31,"Резерв",212725,null],[218171,"2026-09-17T11:37:00",31,"Резерв",212725,null],[218172,"2026-09-17T11:37:02",31,"Резерв",212725,null],[218173,"2026-09-17T11:37:05",31,"Резерв",212725,null],[218174,"2026-09-17T11:37:07",31,"Резерв",212725,null],[218175,"2026-09-17T11:37:09",31,"Резерв",212725,null],[218176,"2026-09-17T11:37:13",31,"Резерв",212725,null],[218177,"2026-09-17T11:37:15",31,"Резерв",212725,null],[218178,"2026-09-17T11:37:17",31,"Резерв",212725,null],[218890,"2026-09-17T17:52:55",31,"@lady_godzilla @dunchev @PaIIasCat завтра утром стартуем с мини квестов для каждого. Первой будет очередь Ясмин. По моим прикидкам, там не более пары часов должно уйти на каждого. Основная задача всех квестов - собрать вас в одном месте, так что катим по рельсам))//",212725,null],[220247,"2026-09-18T05:41:15",31,"@lady_godzilla начинаем. Как будешь готова, отвечай.",212725,null],[220248,"2026-09-18T05:49:21",31,"Твоё путешествие на корабле, длившееся уже добрые две недели, наконец то заканчивалось. Уже утром \"Серая цапля\" войдет в порт Вальдории и ты попадёшь в новый мир, так не похожий на родной юг. \n\nТы и сама не знаешь, что тебя там ждет, но интуиция говорит, что там твое место. Лучше ведь слушать свою интуицию, чем мерзкое прихихикивание матери и тетушек? Хотя иногда ты его слышишь и даже разбираешь отдельные слова. Впрочем, не стоит об этом думать, особенно ночью.\n\nВрочем, этой ночью не спишь не только ты. С палубы слышны взволнованные голоса, не обычная ругань боцмана на матросов, а именно что суетливая и частая речь матросов и, похоже, даже капитана. Ты слышишь что то о лекаре, но не разбиваешь суть. Проверишь что там происходит, или попробуешь просто доспать эту ночь?",212725,null],[220284,"2026-09-18T08:18:27",22,"Надо проверить, что там. Вдруг меня нашли? А может лучше спрятаться... Как мышка?\n\nКакая ты мышка? Ты крыса. Злобная желтоглазая крыса. Сиди в своей норе и не отсвечивай!\n\nЯсмин сидела у стены, прижав колени ко лбу и раскачивалась. Иногда часть своих мыслей она происзностла вслух. Иногда даже одним и тем же голосом.\n\nНадо идти. Я смелая. Я сильная. Я смогу!\n\nДевушка смахнула прядь волос, прилипшую к потному лбу и резко встала.\n\nТак и пойдешь? Сверкая голым животом? Накинь на себя хотябы тряпку, глупышка. \nИхихи-хи-хи\n\nЯсмин подхватила потрепанный палантин и поспешила на шум, кутаясь в него по пути.",212725,null],[220295,"2026-09-18T08:23:40",31,"на палубе довольно оживленно. Не одну тебя разбудили крики. Толпа пассажиров стоит перед капитаном, что пытается всех отправить по каютам:\n\n- ничего старшного не произошло, сиоры. Всего лишь одному из наших матросов стало плохо со здоровьем. Беда только в том, что наг штатный лекарь в прошлом порту сошел из-за лихорадки, но я уверен, что с Филлипом все будет в порядке, совсем скоро мы прибудем в Вальдорию и он получит помощь. \n\nКапитан помедлил.\n\n- впрочем, если среди вас есть те, кто может помочь или владеет навыками медицинской помощи, то я бы не оказался от нее",212725,null],[220307,"2026-09-18T08:31:21",22,"Я врач!\n\nАга врач она.  Ты книгу в руках когда последний раз держала, \"врач\"?\n\nНе отсвечивай. Куда лезешь?\n\nЯсмин стиснула зубы, чтобы нк проронить лишнего.\n\n- Я могу помочь.",212725,null],[220309,"2026-09-18T08:32:34",31,"мне очень нравится внутернний диалог. Сам хотел тебе мысли мамы подкидывать, н у тебя выходи органичнее/",220307,null],[220324,"2026-09-18T08:35:54",31,"- Вы?\n\nКапитан смотрит на чужестранку с легким недоверием, особенно его привлеают и смущают глаза разного цвета, но похоже ему некуда деваться.\n\n- Тогда пройдемте, Филлип в каюте матросов.",220307,null],[220329,"2026-09-18T08:37:24",31,"Он ведет тебя в каюту, довольно тесное помещение с низким потолком и несколькими кроватями, видимо, матросы спят тут посменно. \n\nФиллип лежит на дальней койке, и судя по всему, его болезнь необычна. Он выглядит словно мумия, иссохшийся и жалкий",212725,null],[220336,"2026-09-18T08:42:54",31,"- вот, сиора, можете его осмотреть",212725,null],[220372,"2026-09-18T08:53:23",22,"Ну ну. С матросами пошла, глядите.\n\nОй, наша девочка такая большая! Решила начать зарабатывать по-взрослому\nИхихи-хи-хи\n\nТИХО!\n\nОна сейчас реально заорала? О, это будет весело.\n\nВсе находящиеся в каюте недоуменно посмотрели на Ясмин.\n\n- Пожалуйста,  не шумите. \n\nТихо продолжила девушка, почти переходя на шепот.\n\n- Как давно он заболел? Есть ещё больные?\n\nДевушка подходит к Филиппу и осматривает его .",212725,null],[220373,"2026-09-18T08:54:13",22,"/r +6 осмотр",212725,null],[220375,"2026-09-18T08:54:14",31,"- пару часов назад он сошел со смены и пошел спать. Вот только что увидели в каком он состонии",212725,null],[220376,"2026-09-18T08:56:10",31,"Ты понимаешь, что в организме парня практически не осталось влаги, как он жив еще - не понянятно. его нужно срочно положить в пресную воду, иначе он станет неотличим от сущеной трески. Также ты понимаешь, что тут не обошлось без какого то проклятия. И что то в нем кажется тебе знакомым",220374,null],[220379,"2026-09-18T09:04:28",22,"- Вы можете набрать в бочку пресной воды? Если нет пресной, подойдёт морская. Я очищу ее.\n\nЯсмин наклонилась к матросу, позвякивая браслетами. Она погладила его по голове, напевая что-то на незнакомом певучем языке.\n\nВ каюте запахло горькими апельсинами, амброй и чёрным перцем. \n\nЯсмин продолжила гладить матроса по голове, проверяя, есть ли у него признаки того, что ему срезали прядь волос.",212725,null],[220381,"2026-09-18T09:17:25",31,"- вода? конечно есть. Эй там, тащите воду в бочке и дно выбейте!",212725,null],[220382,"2026-09-18T09:18:23",31,"ты не обнаруживаешь на голове матроса срезаных прядей, впрочем в его гриве сложно было бы разобраться.",220379,null],[220383,"2026-09-18T09:19:55",31,"можешь росить проверку магии, с преимуществом/",212725,null],[220385,"2026-09-18T09:23:47",22,"/r +d20-1 нужно было ходить в библиотеку и читать книжки",212725,null],[220389,"2026-09-18T09:27:51",31,"Преимущество ты получила, так как почувствовала ту область магии, о которой что то знала - магия проклятия, магия карги. И ты поняла, что парень не являлся целью, он - лишь случайная жертва, что контактировала с проклятием, а скорее, с проклятым предметом. Будь проклятие направлено именно на него - он бы уже был горкой праха. Но ему повезло, и возможно, он выживет. Если проклятый предмет будет найдет и сожжен до того, как истечен время отсрочки до его смерти. Осталось не более часа",220386,null],[220396,"2026-09-18T09:37:09",22,"Ясмин перестала петь и ласково спросила \n\n- Ты не встречал какой-то странный или необычный предмет накануне? Или может одна прекрасная дева попросила у тебя прядь волос на память?\n\nНаконец то она заткнулась.\n\nКак же бесит ее пение.\n\nИ навоняла тут на всю каюту. У меня аллергия!\n\nИ у меня!\n\nАПЧХИ!\n\n- Девушка, будьте здоровы. Вы больны?\n\nПоинтересовался один из матросов.\n\n- Н-нет, тут просто пыльно. И-извините. Так может вы подскажете? Не находили ли что-то странное в последнее время? Что-то,  от чего хотелось бы держаться подальше?",212725,null],[220403,"2026-09-18T09:39:49",31,"- нет, леди, мы ничего не видели. А Филлип выздоровеет? Просто он еще на смене халовался на головную боль, но лекаря не было на борту и он сам сходил в его каюту, травок взял, от боли. Это может как то связано?",220396,null],[220421,"2026-09-18T09:47:15",22,"- Возможно. \n\nЯсмин повернулась к другому матросу, стоявшему рядом.\n\n- Пожалуйста,  положите его в бочку с водой, но так, чтобы голова была на поверхности и он не захлебнулся.\n\nОй захлебнется и ладно. Тоже мне, сердобольная нашлась.\n\n- Проводите меня в каюту лекаря, пожалуйста.\n\nТихо добавила Ясмин.",212725,null],[220426,"2026-09-18T09:50:15",31,"матрос кивает, и риступает к заднию. Второй тянет тебя за собой, в отдъльную каюту, что обычно занимает корабельный лекарь, ныне оставшийся в прошлом порту из-за лихорадки. Это аакуратная маленькая комнатка с кушеткой для юольны и огроным шкафом с различными препаратами. Тут же лежит саквояж лекаря, он открыт, в нем явно рылись",212725,null],[220436,"2026-09-18T09:56:46",22,"Обернув руки тканью, Ясмин аккуратно осматривает  содержимое саквояжа, стараясь не касаться голой кожей.",212725,null],[220439,"2026-09-18T09:56:55",22,"/r +6 пусть будет внимательность",212725,null],[220447,"2026-09-18T10:01:24",31,"твоя предусмотрительность была не напрасной, мама бы гордилось своей умной девочкой. Нельзя трогать подклад голой рукой. Лучше вообще не трогать его. Ты быстро находишь в саквояже мерзковатого вида куриную лапу, вокрг кторой обвита веревочка, сплетенная из волос ярко рыжего цвета. Пожалуй, тут, на корабле,  только однин человек походил на самоходный факел - и это капитан",212725,null],[220481,"2026-09-18T10:18:30",22,"СЮРПРИ-И-ИЗ!!!\n\nЯсмин вздрогнула, чуть не коснувшись лапы.\n\nИхихи-хи-хи \n\nТрусиха \n\nНеуклюжая корова\n\nПочти попалась\n\nЯмин молча берет эту лапу, заворачивая ее в ткань и не касаясь.\n\n- Скажите, а капитан случайно не болен?",212725,null],[220483,"2026-09-18T10:19:53",31,"- Сиор Карло? Нет, с чего бы ему болеть?",212725,null],[220492,"2026-09-18T10:25:49",22,"- Это ш-шапа... \n\nЯсмин ловит недоуменный взгляд моряка.\n\n- Ла'на, бахля..\n\nЧто ты несёшь, идиотка, откуда ему знать, что это?!\n\n- П-прок-ля-тие. Плохой предмет. Зло. Нужно увидеть капитана, показать ему и спросить. Это важно!\n\nВзгляд Ясмин был умоляющиим.",212725,null],[220494,"2026-09-18T10:28:16",31,"- Проклятие Откуда? А, пусть капитан решает, айда\n\nПарень ведет тебя к штурвалу, капитан за ним. Завидев вас он передает руль помощнику и спрашивет:\n\n- ну что там с Филлмипом?",212725,null],[220503,"2026-09-18T10:37:21",22,"- С-сахира же. Подстилка шайтана.\n\nЭто я подстилка?\n\nИли я?\n\nШайтана? Ихихи-хи-хи \nБыло дело да\n\nОй расскажи!\n\nЯсмин стиснула зубы. И стала нервно перебирать свои четки. Ом..ручира..мани..\n\nМолчи-молчи-молчи\n\nПравартайа-хум-пхат..\n\nЩелк, щелк, стучат каменные бусины на ее четках.\n\n- Филиппу нужно посидеть в пресной воде и больше пить. Все будет хорошо. К-капитан. Я нашла это, вам знакомо? Вы никому не дарили накануне прядь своих волос?\n\nЯсмин аккуратно показала находку.\n\n- Это нужно сжечь немедля. Но прежде прошу, ответьте на вопрос.",212725,null],[220511,"2026-09-18T10:41:16",31,"- Прядь волос?\n\nКапитан, кажется, покраснел, что с его цветом волос создало очень забавный контраст.\n\n- как бы вам сказать, леди... Ну скажу прямо, я частенько имею дела с разными... девушками. Не подумайте ничего плохого, но многим нравятся мои волосы, они необычного цвета... и бывает, что у меня просят локон, на память. Ну, мне и не жалко",212725,null],[220523,"2026-09-18T10:47:03",22,"- Это опрометчиво. Впрочем, у вас наверное нет Сахир? Они способны наложить шапу по пряди волос. Проклясть. Просто потому что могут.\n\nЯсмин замолчала. Голоса в голове затихли, но девушка понимала, что они никуда не ушли.\n\n- Помогите мне это сжечь. У вас будет миска или другая железная тара. Шапу нужно уничтожить. Огонь очистит проклятый предмет. Свет поможет.\n\nНа этих словах Ясмин сложила руки в молитвенном жесть, прислонив свободную ладонь к сердцу и склонив голову.",212725,null],[220525,"2026-09-18T10:48:49",31,"Капитан кликнул матроса, выдал распоряждение и через минуту железная миска была у тебя в руках. Капитан не скрыва любопытства наблюдает за твоими действия",212725,null],[220531,"2026-09-18T11:03:56",22,"Ясмин выбирает место возле окна и, убедившись, что ничего рядом не сможет загореться, садится в позу лотоса и ставит миску, в которую вытряхивает лапу. \n\nЧто ты делаешь?!\nИдиотка не лезь!\n\nОна посыпает лапу сверху различными сушёными лепестками и добавляет несколько веточек.\n\nДевушка поджигает и начинает читать мантру, методично щелкая чеками.  Ритмично, в такт своему сердцу.\n\n\nОм бхаскарайа намах…\n\nГолоса стихают в ее голове.\n\nСветом вхожу, светом живу, светом уйду…\n\nПахнет кардамоном. Гвоздикой. Корицей.\n\nСурья, будь моим оком в темноте.\n\nЯркий аромат куркумы.\n\nАрка, гори во мне.\n\nЗапахи становятся все ярче.\n\nСваха.\n\nЯсмин хлопает в ладоши и запахи исчезают. Как и то, что сгорало в миске.",212725,null],[220533,"2026-09-18T11:07:28",31,"ты ощущаешь, как что то темное, сгусток мерзкой магии растворяется в свете. На удивление, ты ощущаешь от него что то вроде... Благодарности?\n\nКапитан стоит разинув рот. \n\n- Это что, вот эта штука могла меня убить, но ударила по Филлипу? а где он ее нашел? И кто бы мне могу ее подкинуть?",212725,null],[220534,"2026-09-18T11:08:24",22,"- Ваш лекарь. Напомните, как давно он с вами и почему его нет сейчас?",212725,null],[220536,"2026-09-18T11:11:14",31,"Капитна задумывается, его лицо становится жестким и сосредоточенным\n\n- Гастон сошел с борта на прошлой швартовке. Он занедужил, лихорадка, и я сам велел ему переждать в портовой гостинице, мы бы забрали его на обратном пути. Это стандартная практика. Он ходит на \"Цапле\" почти три года, как меня назначили капитаном. Вы думаете, он меня хотел убить? Но это нонсенс! Мы не враги, не соперники, нам нечего делить",212725,null],[220541,"2026-09-18T11:13:35",22,"- Не думаю, что он виноват... \n\nЯсмин задумалась. Когда в голове тихо, мысли такие ясные, такие яркие.\n\n- Его саквояж. Кто принес его на корабль? Если Лекарь остался на земле, как его вещи оказались тут?",212725,null],[220548,"2026-09-18T11:17:00",31,"- Признаться, я не знаю. Хотя нет, знаю. Никто не приносил, Гастон верно сам его оставил, ему стало плохо очень неожиданно и он только иуспел уведомить меня об этом",212725,null],[220551,"2026-09-18T11:21:38",31,"Капитан вновь задумывается и начинает рассуждать:\n\n- в то что Гастон хотел меня отравить я не верю. Нет причин верить. Но вот в то, что могли подкинуть ему проклятый предмет я поверить могу. У меня хватает врагов, недображелателей и конкурентов. Правда, колдунов среди нет, наскорлько мне извествно. Но оставлять такое без внимания никак нельзя. У меня не будет времени пройтись по Вальдории и порасспрашивать людей, но я знаю кто может. Сиора, вас не затрудни выполнит одну мою просьбу?",212725,null],[220554,"2026-09-18T11:24:17",22,"- Я думаю, что ему подкинул эту шапу. Он коснулся ее и захворал. Та же судьба постигла матроса. Но прошу, не беспокойтесь, мы ее сожгли. Вреда больше не будет, но саквояж я бы забрала, чтобы осмоттеть ещё раз. Вдруг шапа была не одна?\n\nВ тени комнаты появились золотые глаза.\nПотом ещё одна пара.\nИ ещё.\n\nЗлые глаза.\nСмеющиеся.\nИспуганные.\n\nМаленькая хитрюга\nВоришка!\nТы на верном пути, девочка!",212725,null],[220555,"2026-09-18T11:24:43",22,"- Д-да, конечно.",220551,null],[220560,"2026-09-18T11:30:29",31,"- в городе живет сыщик, сиор Неро Феллино. Он кое чем обязан моей семье, и я думаю, это дело может списать его долг. Пусть поищет моего врага, кому я успел так насолить. Я не просил бы вас, но во первых, вы единственная кто понимает в этих самых \"шапках\", а во вторых, я планрую сразу развернуься и отправится в обратный путь, едва высадив пассажиров. Мне нужно найти Гастона и расспросить ео, если он еще живой. Передайте сиору Феллино мою просьбу, и скажите что я привезу свидетеля примерно через 10 дней. И да, сиора, чтобы отплатить вам за вашу помощь с моим человеком и за мою личную просьбу, я могу предложить вам место, где вы сможете остановится. Моей семье принадлежит неплохой постолый двор, прямо на портовой площади, называется \"Золотой Нарвал\". Я дам вам письмо с моей подписью и вам выделят комнату на то время, что вы планируете провести в городе",212725,null],[220567,"2026-09-18T11:37:10",22,"//шапки😂",220560,null],[220569,"2026-09-18T11:37:27",31,"\\ну не шарит человек/",220567,null],[220571,"2026-09-18T11:40:29",22,"- Да, конечно. Я понимаю вашу тревогу и постараюсь вам помочь. У меня как раз пока нет планов. Я запишу все, что вы сказали, чтобы не запамятовать.\n\nЯсмин зашуршала бумажками, доставая дневник.\n\nПланов у нее нет, ля какая.\n\nВертихвостка, ещё меня подстилкой называла.\n\nСумку лекарскую не забудь!\n\nГлаза синхронно подмигнули.",220560,null],[220573,"2026-09-18T11:41:46",31,"если есть какие то заявки - напиши. если нет, то сделаю описание таймскипа/",212725,null],[220574,"2026-09-18T11:42:02",22,"//забрать сумку лекаря, проведать матроса",212725,null],[220575,"2026-09-18T11:42:23",31,"это все?/",212725,null],[220576,"2026-09-18T11:43:04",31,"ок, тогда матрос/",212725,null],[220581,"2026-09-18T11:45:23",31,"к штурвалу подбегает матрос:\n\n- капитан, Филлип пришел в себя! Он рветс яиз бочки и орет что мы идиоты и должны его выпустить!\n\nКапитан:\n\n- Кадется, ваш обряд сработал быстро, сиора. Навестим Филлипа? И по пути можем прихватить саквояж Гастона, я ему потом новый куплю",212725,null],[220595,"2026-09-18T11:53:07",22,"- Да, конечно навестим",220581,null],[220597,"2026-09-18T11:54:32",22,"Матросик то явно понравился\nОй, у девочки наконец-то появится мальчик?_\nИхихи-хи-хи\n\nШумный вздох. Тихий выдох.\nПовторить.\nЕще раз. \n\nПочему эти глаза до сих пор не исчезли? Новые шуточки? Потрясающе..",212725,null],[220600,"2026-09-18T11:55:57",31,"Болезный матрос и правда сидел в бочке и орал что твоя выпь:\n\n- капитан, это придурки запихнули меня спящего в воду! И не выпускают! Что за шутки?",212725,null],[220602,"2026-09-18T11:56:24",31,"можешь кинуть медицину на остмотр/",212725,null],[220603,"2026-09-18T11:56:29",22,"/r +6",212725,null],[220609,"2026-09-18T11:56:57",22,"//ну конечно, не на лут, а на попялиться на мужика",212725,null],[220613,"2026-09-18T11:58:27",22,"Ууууу бесстыдница\nВся в мать\nВсе разглядела?\nА она точно невинная дева? Вон как зырит и даже не краснеет",212725,null],[220618,"2026-09-18T11:59:10",31,"Парень выглядит совершенного здоровым. Тебя даже кажется, что когда ты видела его за работой на палубе, он так хорошо не выглядел. Словно наложение и снятие проклятия обновило его организм в лучшкю сторону. Подчиняяб приказу капитана он вылез из бочки и дал тебе себя рассмотреть. \n\n/Что ты там увидела, на что смотрела внимательнее всего, решай сама, я тут руки умываю/",212725,null],[220641,"2026-09-18T12:04:59",22,"- Вы здоровы. Поздравляю. \n\nКи ладжа! Какой позор. Пялюсь, словно портовая девка.\n\nЯсмин быстро отвернулась. Ее щеки пылали.\n\nГлаза насмешливо крутились вокруг нее. Хохот то стихал, то нарастал.\n\n- Вы здоровы, сэр. В бочке можете больше не сидеть. Вы потрогали шапу, проклятый предмет. Я вас очистила от проклятья. Прошу, не трогайте в дальнейшем чужие вещи. Это опасно. В них может сидеть Асура или Шайтан. \n\nДевушка не оборачивалась, сжимая до боли свои четки в руке.\n\nСказав это, он выбежала в сторону своей каюты.",212725,null],[220645,"2026-09-18T12:05:33",31,"так мило)/",220641,null],[220647,"2026-09-18T12:06:05",22,"//ну я не извращенка, правда, просто персонажи такие были",220645,null],[220650,"2026-09-18T12:06:20",22,"/r убеждение",212725,null],[220654,"2026-09-18T12:06:27",31,"поверил/",212725,null],[220658,"2026-09-18T12:06:40",31,"ладно, описываю таймскип/",212725,null],[220699,"2026-09-18T12:16:33",31,"Сутки спустя, Вальдория, Страда Валериана, 224.\n\nЯсмин прибыла в большой и шумный город, ее почти сразу попытались ограбить, но чегото испгулись, вызывав раздаржение у внутренних голосов Ясмин, что очень хотели крови наглеца. Но это проишествие не испортило впечатление от огромного шумного города. Письмо капитана Карло Беати и правда произвело впечатление на трактирщицу из \"Золотого Нарвала\", Ясмин получила в свое распоряжение небольшую комнатку над трактиром прямол на Портовой площади. Закинув свои вещи, девушка отправилась по указанному адресу к дому сыщика Феллино. подходя, она заметила двух другх посетителей, что видимо пришли с ней одновременно.\n\nКонец стартового мини-квеста Ясмин. \n\n/свои реакции, пожелания и матершину вы можете оставить в обсуждении квестов, мастер все вытерпит/",212725,null],[220702,"2026-09-18T12:17:00",31,"/дальше будет старт для Беатриче, но чуть позже, мне чуток нужно мысли причесать/",212725,null],[220788,"2026-09-18T12:31:14",31,"@PaIIasCat если ты не против, отыграем твою ветку попозже? Он по ощущениям должна быть совсем маленькой, но я и пропервую так думал))  ты в какое время сможешь быть активна?/",212725,null],[220792,"2026-09-18T12:32:16",20,"/я активна в будни  с 9 до 17 всегда, вечером тоже могу но не так активно из-за домашних дел",220788,null],[220794,"2026-09-18T12:33:31",31,"тогла я тебе сегодня попозже напиушу сюда, обрисую старт и погоним. Часа через 3 наверное./",220792,null],[221268,"2026-09-18T15:51:33",31,"@PaIIasCat начинаем твою историю. Как будешь свободна, отписывай. На выходных у меня мало времени, поэтому я не смогу сидеть несколько часов подряд, но будем стараться.\n\nРаннее осеннее утро в Вальдории прекрасно. Особенно после прекрасной ночи. Ты просыпаешься от того, что Кристина подкатывается к тебе под бочок и ласково покусывает за ушко. Кажется, она забыла что из вас дампир.\n\nТы просыпаешься, но делаешь вид что спишь. Кристина принимает правила игры, и продолжает атаковать твое ухо, постепенно спускаясь к шее, а затем снова к уху.\n\nЕё голос, такой восхитительно грудной и немного хриплый, спрашивает:\n\n- ты ведь вернёшься вечером, правда?",212725,null],[221368,"2026-09-18T16:19:17",20,"*Беатриче лениво приоткрывает  глаза, потягиваясь и одной рукой притягивая к себе Кристину ближе за талию*\n\n- Вернусь ли я? *Она картинно вздыхает, изображая глубокую задумчивость.*\n- Ты же знаешь, mia cara, моя жизнь полна непредвиденного хаоса. Но! *Она ухмыляется, игриво проводя пальцами по бедру любовницы*\n- Если к закату моя сталь не найдет себе достойного развлечения, я обязательно вспомню, что самые жаркие часы в Вальдории проходят именно в этой постели.\n\nОна оставляет на губах Кристины быстрый, обещающий поцелуй и, грациозно соскользнув с кровати, тянется к своей брошенной рубахе.\n- Оставь сегодня окно на балкон открытым, tesoro.",221268,null],[221399,"2026-09-18T16:24:34",31,"Вдруг за дверь раздаётся крик:\n\n- Кристина!? Кто там у тебя? Опять эта чертова кровососка!? \n\nКристина вроде сначала пугается, а потом заливается смехом, заворачивается в одеяло и миленьким голоском говорит:\n\n- не убивай этих дураков, пожалуйста...\n\nВ этот момент дверь в комнату открывается мощным пинком, и два брата Кристины, Матео и Гвидо, пытаются одновременно попасть в комнату. Из габариты мешают сделать это одновременно, но проходит лишь пару секунд и две эти гориллы оказываются в комнате сестры.\n\n- я так и знал! Опять! Ну в этот раз мы точно сможем позор семьи твоей поганой кровью!\n\nМатео кидается на тебя с кулаками",212725,null],[221425,"2026-09-18T16:32:02",20,"*Беатриче громко смеётся, на бегу застегивая свою брагинтину и уже спешит к окну, уворачиваясь от кулаков налетевшего на нее Матео*\n\n- Ах, signori, signori! Ну что же вы так горячитесь! Я ведь просто помогала ей... *Сетует она, прежде чем лукаво добавить*\n - снять корсет \n\n*Она перекидывает ногу через подоконник, посылаю воздушный поцелуй Кристине на прощание*",221399,null],[221429,"2026-09-18T16:32:51",20,"/какая там этаж?",212725,null],[221430,"2026-09-18T16:33:00",31,"Второй",221429,null],[221432,"2026-09-18T16:33:09",31,"Напротив дерево",212725,null],[221436,"2026-09-18T16:34:35",20,"/r d20+5 акробатикой перебираемся на дерево",221432,null],[221442,"2026-09-18T16:35:00",20,"/там если Матео был рядом мог провоцированно ударить, я без отхода",212725,null],[221448,"2026-09-18T16:36:31",31,"/roll d20+3 Матео толкает тебя из окна",212725,null],[221450,"2026-09-18T16:36:45",20,"/не попал",221449,null],[221451,"2026-09-18T16:36:48",31,"Но едва не вываливается сам",212725,null],[221452,"2026-09-18T16:37:21",31,"Гвидо орёт: за ней\n\nТы слышишь как браться топочут пл лестнице",212725,null],[221475,"2026-09-18T16:41:45",20,"*Беатриче сбегает вниз по дереву, спрыгивая с последней ветки на землю и оборачивается к входу в здание, слегка выжидая*\n\n- Ну же, teste di legno! Вы хотели кровь Висконти - так постарайтесь чтобы достать ее! *Кричит она им, явно подзадоривая*\n- Al ritmo, tempo!\n\n/Трачу скорость лазания чтобы спуститься на землю, заготавливаю рывок как только они покажутся из дверей",212725,null],[221476,"2026-09-18T16:42:30",31,"Братья -гориллы показываются в дверях и замечают тебя. Кажется, они очень злы",212725,null],[221479,"2026-09-18T16:42:52",31,"С ревом бегут в твою сторону",212725,null],[221480,"2026-09-18T16:43:09",31,"Их урик слышно на весь Старый Город",212725,null],[221481,"2026-09-18T16:43:27",20,"*Дождавшись аудитории, Беатриче срывается на бег, ее смех присоединяется к их возмущенный крикам в эту рань*\n\n/Рывок",221476,null],[221486,"2026-09-18T16:44:19",20,"/арт забыла",212725,null],[221499,"2026-09-18T16:47:04",31,"Тяжелый топот за спиной, ярость гонить Матео и Гвидо за тобой. \n\nПогоня идёт по старой тихой в это время улочке. Ну как тихой. Вы всех перебудили. В окнах появляются хотели, кто то болеет ха тебя, в кто то подзуживает братьев. \n\nТы бежишь куда глядят глаза, но вдруг упираешься вдом. Клянусь, ещё вчера его тут не было (мелькает шальная мысль), и тебе нужно выбрать, куда дальше? В этот дом в надежде пооскочить насквозь? Налево на лдтвденныею Виа Пальми? Или вон в тот неприметный закуток?",212725,null],[221508,"2026-09-18T16:48:41",20,"/ну конечно мы верны оригиналу",221499,null],[221510,"2026-09-18T16:48:54",20,"/карабкаемся на дом!",212725,null],[221512,"2026-09-18T16:49:16",31,"Проверка акробатики 16",212725,null],[221514,"2026-09-18T16:49:30",20,"/скорость лазания у дампиров же",221512,null],[221515,"2026-09-18T16:49:40",31,"А, точно/",212725,null],[221516,"2026-09-18T16:49:46",31,"Спасибо за поправку/",212725,null],[221520,"2026-09-18T16:50:26",20,"/r d20+5 пусть будет ещё акробатика фоном, насколько пафосно Беатриче это делает",212725,null],[221524,"2026-09-18T16:50:42",31,"- она лезет через дом?! ненормальная. Гвидл, сбоку дом оходи, ей все равно нужно будет спуститься!",212725,null],[221538,"2026-09-18T16:52:41",20,"*Спуститься? Ха! Беатриче хихикает, бежа по крыше дома и прицеливаясь перепрыгивать на следующую*",212725,null],[221539,"2026-09-18T16:52:49",20,"/r d20+5",212725,null],[221545,"2026-09-18T16:53:19",31,"/roll +d20+2 брать высматривают тебя в 4 глаза",212725,null],[221548,"2026-09-18T16:53:34",31,"- вон она, за ней!",212725,null],[221549,"2026-09-18T16:53:42",20,"- Что, уже запыхались так, что даже от земли оторваться не можете? Che delusione! *Беатриче и не скрывает)*",212725,null],[221550,"2026-09-18T16:53:43",31,"Бегут по земле",212725,null],[221580,"2026-09-18T16:57:14",31,"- загоняй ее, к порту гони!",212725,null],[221581,"2026-09-18T16:57:20",20,"/продолжаю бежать по зданиям, они постепенно скорее всего будут отставать, у дампиров ещё и скорость на 5 больше",221550,null],[221604,"2026-09-18T16:59:52",31,"Через 10 минут погони братья выдохлись. Их запал прошел и они отправились выпить \"Сельдяного короля\". Это их любимая таверна, зачем то ты это помнишь, со слов Кристины.\n\n/твой забег стартовал в старом городе, выбкот сама, куда ты прибежала. Любой соседний район. Карта прикреплена в начале темы/",212725,null],[221612,"2026-09-18T17:00:41",20,"/кстати, а где я сама живу? Тоже в старом или в палаццо?\n/Так по описанию на карте скорее всего в старом",221604,null],[221640,"2026-09-18T17:03:26",31,"А где хочешь?) вообще я думаю в старом, у тебя такое длинное традиционное имя, просто говорит что мы тут 300 лет живем)",221612,null],[221645,"2026-09-18T17:04:18",20,"/тогда старый, по классике \n/У меня случайно нет брата чтобы сцену на башне закосплеить?",221640,null],[221667,"2026-09-18T17:07:04",31,"Два брата, сестра, отец и мать. И дядя за городом. Дампир в семье только ты, мать общела все обьяснить когда станешь старше. Семейство твоё - мелкие виноторговцы",221645,null],[221668,"2026-09-18T17:07:13",31,"Имга можешь сама дать/",212725,null],[221675,"2026-09-18T17:08:29",31,"Если что, я прямо на ходу это придумал)/",212725,null],[221707,"2026-09-18T17:12:43",20,"*Беатриче после своей незапланированной(как в целом большинство ее дел) пробежки оказывается в районе Большой гавани, спускаясь с крыш и теперь прогуливаясь по набережной.*\n\n*Она разглядывает паруса кораблей, что пришли в гавань, шпили города, что начал заливать рассвет, волны прибоя.*\n\n- Жизнь прекрасна *улыбается она сама себе, продолжая прогулку без особо цели, просто наслаждаясь последними тёплыми днями осени*\n- Вот бы она никогда не менялась",212725,null],[221874,"2026-09-18T17:31:05",31,"Большая гавань, мировой котел, тут слышна речь на десятках языков, можно найти что угодно, хоть редкую пряность, хоть неприятности на свою задницу. Интересно, что выйдет тебе сегодня\n\nПроводя время в свое удовольствие, ты замечаешь какую то нездоровую суету возле одного из кораблей. Похоже, там происходит что то интересное",212725,null],[221903,"2026-09-18T17:33:35",20,"- А, meraviglioso. Ни дня без происшествий! *Беатриче направляется туда, где суета. Потому что конечно она не может просто пройти мимо*",221874,null],[221972,"2026-09-18T17:42:37",31,"Беседа, точнее ругань, идёт на все повышающихся тонах. Купец, ну или скорее молодой приказчик, что пришёл за грузом, распекает нерадивых грузчиков:\n\n- вы понимаете что с вами сделает сиор Валериу? Ценнейше ювелирное серебро, самой чистой пробы! Как? Кааак!?! Как можно было утопить целый ящик!",212725,null],[221995,"2026-09-18T17:46:38",20,"- Хей, Signore! Что за суматоха с утра пораньше? *Беатриче подходит ближе, не стесняясь влезть в перепалку*\n\n- Случилось чего? Или просто рассветные волны оказались голодны до серебра?",221972,null],[222028,"2026-09-18T17:50:31",31,"Юный купец (или приказчик) оценивающе глянул на тебя и признал ровней из купеческой среды.\n\n- эти идиоты умудрились утопить ящик серебра. Говорят, случайно, но что то я в это не верю. Надо бы послать жа стражей, до боюсь они сбегут, а под покровом ночи нырнут и вытащат серебро. Так как только они и знают, где оно лежит.\n\nОдин из грузчиков поднимает глаза и кидается в бой:\n\n- не несите ерунды, сиор. Мы честные люди! Да и как туда нырнёшь, так надолго дыхание не задержать!\n\n- нет, ну вы видели этих подлецов? Дыхание они не задерживают достаточно!",212725,null],[222055,"2026-09-18T17:54:14",20,"- Хех, ну раз такое дела - могу подсобить вам немного. *Великодушно предлагает Беатриче, слегка выпятив грудь горделиво*\n\n- И не на такую глубину ныряла. А дом Висконти никогда не оставляет без помощи тех, кто честен в своем деле!",222028,null],[222056,"2026-09-18T17:55:19",31,"- дамочка, там глубина на пару этажей. У вас конечно это самое, формы выдающиеся, но дышать то чем будете?\n\nОдин из грузчиков сомневается в тебе",212725,null],[222077,"2026-09-18T17:58:49",20,"- Смеешь сомневаться в способностях Беатриче Висконти да Вальдрио?! А ну быстро показывайте куда нырать - это теперь questione d'onore! Дело чести! 🤌\n\n*Беатриче тут же загорается, явно собираясь показать этим невеждам истинный потенциал крови Висконти*",222056,null],[222101,"2026-09-18T18:01:47",31,"- гу, если вы уверены, сиора... Грузится на лодку, вот ты покжаещь куда вы засунули сундук\n\nТут же начал распоряжятся молодой купец. Уже через пару минут он, Беатриче и грузчик, что говлрил о честности, вышли в море. \n\nПлавание заняло около получаса, и по каким то своим отметками грузчик указал, что нырять нужно вот тут\n\n/если есть заявки, можешь выдать, если нет то готовься нырять/",212725,null],[222117,"2026-09-18T18:05:37",20,"*Беатриче ставит ботинок на борт корабля, смотря в рассветные воды. Ну чтож, была не была!*\n\n/Готова нырять",222101,null],[222133,"2026-09-18T18:08:43",31,"Бульк/\n\nКак дампир, ты не нуждаешься в дыхании. Однако давление воды на тебя действует. Физике похер просто. Поэтому механически твоё погружение будет выглядеть как проверка спаса тела. Чем она выше, тем глубже ты можешь нырнуть. Всего я дам тебе не более пяти погружений. Можешь бросать первую проверку телосложения/",212725,null],[222134,"2026-09-18T18:09:27",20,"/r d20+4 первая пошла",212725,null],[222138,"2026-09-18T18:09:48",31,"Пиздец ты везучая/",212725,null],[222139,"2026-09-18T18:09:53",31,"Сразу пробила/",212725,null],[222151,"2026-09-18T18:12:02",31,"Беатриче с дурной головой ухгула на самую глубину. Что то около 20 метров. Там темновато, и чтобы разглядеть сундук, придётся поднапрячься.\n\n/так как ты показала себя как отличный ныряльщик, больше проверок на тело не нужно. Теперь ищи сундук проверкой восприятия. Если ечть тёмное или слепое зрение, то можешь кинуть с преимуществом. Если нет, то с помехой/",212725,null],[222290,"2026-09-18T18:47:07",20,"/r +d20+3 ищем ящик с темным зрением",222151,null],[222296,"2026-09-18T18:48:08",31,"Да ты издеваешься",212725,null],[222303,"2026-09-18T18:50:31",31,"В кромешной тьме подводного мира ты таки замечаешь сундук. Не соврали грузчики то. Ты подплываешь в сундуку т понимаешь, что он весьма тяжелый. Если решишь еоо вытягивать, то придётся пройти проверку атлетики (18), но может ечть иные варианты?",212725,null],[222306,"2026-09-18T18:52:29",20,"/хм, насколько умен мой персонаж чтобы придумать другие варианты 🤔",222303,null],[222309,"2026-09-18T18:52:59",31,"Ну проблески гениальности бывают даже у самых тупых варваров./",222306,null],[222311,"2026-09-18T18:54:05",20,"*Беатриче рассматривает сундук и решает сначала попробовать вытащить его своими силами - на крайний случай всегда есть веревка, которой можно оборотать и вытащить уже с поверхности с помощью грузчиков*",212725,null],[222313,"2026-09-18T18:54:27",20,"/r d20+1 тягаем сундук 🪎",212725,null],[222315,"2026-09-18T18:54:34",31,"Хех/",212725,null],[222316,"2026-09-18T18:54:49",20,"/аха, почти",212725,null],[222317,"2026-09-18T18:55:09",31,"Ну у тебя ещё 4 попытки вытащить сундук/",212725,null],[222319,"2026-09-18T18:55:24",31,"Или придумать иной план/",212725,null],[222322,"2026-09-18T18:55:48",20,"/r d20+1 ещё одна попытка, мы упрямые",212725,null],[222325,"2026-09-18T18:56:25",31,"Не тянется репка/",212725,null],[222330,"2026-09-18T18:57:11",20,"/r d20+1 святая троица",212725,null],[222333,"2026-09-18T18:57:32",31,"Такое чувство, что сундук еще больше уходит в ил/",212725,null],[222334,"2026-09-18T18:57:33",20,"/ладно думаем над планом б",212725,null],[222335,"2026-09-18T18:58:06",20,"/есть в воде коряга или что-то что можно как рычаг использовать?",212725,null],[222336,"2026-09-18T18:59:19",31,"Боюсь, нет. Вдалеке вроде что то плавает, но такое склизкое и гнилое, что уже не может служить рычагом/",212725,null],[222365,"2026-09-18T19:11:44",20,"/хм, а если я перехожу часть содержимого себе это ведь уменьшит вес сундука и проверку?\n/Ну или по частям серебро наверх перетаскивать",212725,null],[222402,"2026-09-18T19:28:39",31,"Стащить чутка хочешь? Можно, проверка ловкости рук сл 15",222365,null],[222428,"2026-09-18T19:37:47",20,"/ты что, это же против чести!",222402,null],[222429,"2026-09-18T19:38:11",20,"/чисто частями им наверх эти слитки перетаскивать, не ныкать",212725,null],[222774,"2026-09-18T20:55:08",31,"Извини, я уснул. Можешь бросить на ловкость рук для вскрытия замка и все перетаскать по слиточку/",212725,null],[222776,"2026-09-18T20:55:39",20,"/ничего страшного, у тебя там вроде уже очень поздно",222774,null],[222777,"2026-09-18T20:55:52",20,"/r d20+5 ловкость рук",212725,null],[222779,"2026-09-18T20:56:02",20,"/трачу удачу",212725,null],[222783,"2026-09-18T20:57:48",31,"Не зря потратила, замок словно ждал тебя, щелк и открылся. Ты видишь перед собой несколько слитков чистейшего серебра, а также мешочек с каким то порошком на ощупь/",212725,null],[222788,"2026-09-18T21:00:27",20,"/ну чтож, перетаскиваем это все в лодку",222783,null],[222790,"2026-09-18T21:00:54",20,"/интересно что в мешочке, по под водой порошок смотреть такое себе конечно (",212725,null],[222799,"2026-09-18T21:05:56",31,"Сделав десяток нырков туда и обратно, Беатриче доставила всю добычу на лодку. С каждым заходом глаза мужиков все больше охреневали, и когда ты вылезла из воды окончательно, они уже смотрели на тебя словно на какого то водяного полубога\n\n- гкхм, сиора, от лица торгового дома Валериу, я выражаю вам свою искреннюю благодарность. Думаю, сам глсьодин Валериу будет счастлив по достоинству отплвьтьб вам за столь героический поступок. Загляните к нему в контору как нибудь, он базируется в купеческом квартале.\n\n/у тебя появился должник среди купцов. Можешь со временем стребовать долг деньгами, информацией или услугой. Если интересно, кто такой Валериу, можешь прикинуть на историю, либо узнать в ходе сюжета/",212725,null],[222827,"2026-09-18T21:08:45",20,"/r d20 пробуем припомнить без особой надежды",212725,null],[222847,"2026-09-18T21:11:47",20,"- А, не стоит благодарностей, синьоры *Беатриче театрально раскланивается, параллельно отряхивая свой насквозь мокрый плащ*\n\n- Как я уже сказала - дом Висконти всегда готов придти на помощь тем, кто в этом нуждается. Это дело чести!\n\n- А что это за мешочек? *Она прямо указывает на него среди слитков*\n- Странно что он лежал среди слитков, чуть не проглядела такую мелочь пока все вытаскивала",222799,null],[222849,"2026-09-18T21:13:05",31,"На удивление, ты вспомнила знаешь кто это. Твой отец как то по пьяной лавочке злословил про всех подряд, так вот Валериу он называл \"серебряным гусем\". Этот человек, судя по всему, был главной городской фигурой в обороте ювелирного серебра. Деньги т связи у него точно водятся.",212725,null],[222851,"2026-09-18T21:14:31",31,"- так серебро же сиора, только не в слитке, а в пыли.\n\nВ подтверждентк своих слов парень вскрыл мехляеу и показал тебе его содержимое. Совсем мелкая мыль, словно бы серебряная мука. И улсв такое надо?",222847,null],[222852,"2026-09-18T21:15:15",20,"/эх, чьи-то компоненты для свитой воды ...",222851,null],[222865,"2026-09-18T21:17:37",31,"Лодка сдвинулась с места и ратужно поплыла обратно но в город. Ты и не заметила, как прошел день, солнце уже почти скрылось за горизонтом. Кажется, пора домой. Ну или к Кристине, если ты рискнёшь к ней снова сунутся",212725,null],[222866,"2026-09-18T21:17:43",20,"- А capisco, capisco. *Беатриче кивает, рассматривая пыль.*\n- Ну мастерам виднее к чему это использовать. Ну что, на берег, signori?",222851,null],[222874,"2026-09-18T21:20:06",20,"*Беатриче сходит на берег, на прощание махнув парню и грузчикам рукой. Ещё раз поправляет свою мокрую одежду. И смотрит в сторону шпилей старого города.*\n\n*Рисковано? Безусловно*\n\n- И риск мое второе имя *Напевает она, направляясь к уже знакомым окну...*",222865,null],[222886,"2026-09-18T21:24:02",31,"Тихим вечером ты возвращаешься на ту же улицу, с которой убегала утром. Уже стемнело. Но окно Кристины открыто, как у вас и заведено. Что делают ее увальни братцы непонятно, но их не видно и ничего не мешает тебе забраться в спальню девушки",212725,null],[222888,"2026-09-18T21:24:45",20,"/герой любовник лезет в окно",222886,null],[222899,"2026-09-18T21:28:21",31,"Едва забравшись в комнату, ты понимаешь, что тут что то произошло. Кристина не встречает тебя улыбкой, она лежит в кровати без слов и движения. Решив, что она уснула не дождавшись тебя, ты подходишь к кровати и легко касаешься ее плеча. Холодного плеча. Мертвенно-хододного плеча. Уже понимая, что ты увиешь, ты в ужесе переворачиваешь мертвое тело. Кристина мертва. И обескровлена. На ее шее ты видишь характерный след от укуса. Тут поработали зубы кого то из созданий ночи",212725,null],[222944,"2026-09-18T21:46:14",20,"- ...Кристина? Oh Madre di Dio нет... нет! *Беатриче обхватывает лицо возлюбленной ладонями, слегка тряся, будто она вот вот откроет глаза ...будто это лишь жуткий кошмар.*\n\n*Но нет, это не сон. Ее милая Кристина больше никогда не откроет глаза. Не разбудит Беатриче своими поцелуями на рассвете, не будет ждать на закате дня...*\n\n- Клянусь всем святым, своей кровью, именем и последним вздохом...я найду его. Он не уйдет от возмездия. \n\n*Голос звучит с холодной окончательностью в стенах внезапно опустевшей комнаты, где раньше звучал смех.*\n\n- Buona notte...спи спокойно, любовь моя.\n\n*Беатриче бережно берет холодную руку возлюбленной, прижимаясь к ней в прощальном поцелуе. Встаёт и не оборачиваясь покидает комнату, скрываясь в ночи. Теперь не без цели, а в поисках возмездия*",222899,null],[222952,"2026-09-18T21:47:17",20,"/чтож...любовная ветка оборвалась почти не начавшись",212725,null],[222953,"2026-09-18T21:47:27",20,"/пора к детективу",212725,null],[222968,"2026-09-18T21:50:07",31,"/Увы, мне было жаль ее убивать, но вот такую я тебе личную арку сделал. У Эцио семью убили, у тебя возлюбленную. Если бы пошла домой, там бы убили семью/",212725,null],[222974,"2026-09-18T21:50:59",20,"/😨\n/Ладно, хорошо хоть не семью",222968,null],[223005,"2026-09-18T21:56:32",31,"Пылая от ярости, ты однако понимаешь, кого обвинят в смерти Кристины. Кто тут крутился рядом, такой клыкастый, язвительный и нахальный? Тебе нужна защита, прикрытие и возможность найти того кто сотворил такое с твоей девушкой. Ты знаешь куда идти. Старый детктив -домосед Неро Феллино наверняка сможет тебе помочь.\n\nТы не очень запомнила где провела эту ночь. Возможно, в каком то кабаке, дакглцшая боль утраты вином. И попутно создавая себе алиби, хотя ты не думала об этом. Утром следующего дня ты подходила к дому детектива на Страда Валериана, 224. Там ты встретила двух других посетителей. Но это уже другая история\n\nКонец стартового мини квеста Беатриче.\n\n/свои реакции и пожелания можно оставить в обсуждении квестов, мастрк можно и нужно не жалеть/",222944,null],[223009,"2026-09-18T21:57:45",31,"@dunchev твоя очередь следующая. Видимо будем урывками писать на выходных. Ты мне только скажи, ты местный, или мне тебя тд другого города привезти? Мне не принципиально, но для сюжета могут быть различия/",212725,null],[223068,"2026-09-18T22:08:22",17,"/ местный",223009,null],[223069,"2026-09-18T22:08:36",17,"/ По возможности. Дел будет как обычно много",212725,null],[223072,"2026-09-18T22:09:07",31,"Да у меня тоже до задницы. Выходные они такие/",212725,null],[224192,"2026-09-19T07:28:51",31,"@dunchev поехали. Ты блин самый сложный, очень уж подробно у тебя все расписано в предыстории. Попробую что то выжать из этого.",212725,null],[224195,"2026-09-19T07:40:26",31,"Вальдория. Прекрасный город. Для туристов и богатеев из района Палаццо. Не для тебя. Ты слишком хорошо знал оборотную сторону этого мира, да и сам последние годы обретался на городском дне. Насилие всех сортов, воровство, контрабанда - и это если не выходить из трущоб Нижнего города. А чем выше по социальному положению - тем выше ставки. Интриги, заказные убийства и проклятия, и все ради одной цели - наживы. Все в этом городе подчинено золотому тельцу.\n\nТвой день начинается в полуподвале на задворках Нижнего города, который ты называешь базой. Не домом, нет у тебя дома, больше нет. Этот полуподвал достался тебе каким то темным образом, ты не числишься его хозяином в городских документах, но и за аренду не платишь. Да и некому платить, хозяин давно на дне залива. Ты о нем не вспоминаешься.\n\nТы просыпаешься до рассвета, и причиной тому шуршание страниц книги. Похоже, Liber Mortis хочет тебе что-то сказать. На удивление, там не имя, а место, где то в районе Верфей. А рядом какая то клякса, но из за отсутствия света ты не можешь разглядеть, есьь ли в ней какой то смысл",212725,null],[224196,"2026-09-19T07:48:31",17,"В голове шум вчерашней попойки. Не для удовольствия и досуга. Для добычи информации.\n\nПоднявшись, Марко медленно подошёл к книге мертвых. \n\n\"Что то новое. Массовое убийство в этой точке? А что это..?\"\n\nПоднимает книгу отдельно свешивая страницу с адресом и кляксой, щелчком зажигает полусгоревшую свечу в жестяной кружке вместо подсвечника. Пододвигает  метающийся огонек свечи за лист, чтобы просветить бумагу и разглядеть что там под кляксой получше",212725,null],[224197,"2026-09-19T07:53:44",31,"Кажется, эта клякса отдалённо напоминает голову какого то животного, ты ясно видишь что она изображена в профиль, как на изображениях Анубиса (тот же стиль), но морда не такая вытяную, а уши хоть и острые, но уступают в длине шакальим",212725,null],[224198,"2026-09-19T08:00:22",17,"Марко снимает пальто с плечиков у выхода, набрасывает его на плечи\n\nИ перед выходом из подвала бросает взгляд на пробковую доску на стене. Она утыкана кнопками которые соединены красными нитями. Паутина расследования только растет год от года. А он ни на дюйм не приблизился к разгадке. \n\nКто?\n\nЗачем?\n\nПочему?\n\nГде?\n\nПару раз стукнул по дверному косяку кулаком он вышел из убежища чтобы отправиться по адресу и своими глазами удивить, что показывает книга мертвых",212725,null],[224200,"2026-09-19T08:40:42",31,"Путь из нижнего города до верфей проходит по южной части города, прямо по портовой площади. Твой тренированный глаз буквально на автомате отмечает всякие странности или происшествия. \n\nВот кого то зажали в подворотне, \n\nвот тут мальчишка сорвал кошелек у зазевавшейся матроны, \n\nвот девушка, едва сошедшая с корабля уже встретила мошенника, который вдруг неожиданно побледнел и убежал\n\nВот тут явно из под полы продают какой то экзотический препарат для расширения сознания\n\nА тут скандалят молодой купец и толпа грузчиков\n\nЖизнь кипит в этом котле. Но твоя цель дальше. Ты доходишь до района Верфей без приключений. Может, они ждут тебя уже там?\n\nРайон этот сугубо рабочий, тут практически никто не живет, тут не встретить лавочников, сюда стекаются люди со всего города, го только на работу. Верфи дают много рабочих мест, ведь вся экономика города строится на морском могуществе. И как и везде, тут случаются конфликты. Или странные убийства. Ты дошел до того места, что указывала тебе книга.\n\nКого то представшее перед тобой зрелище заставило бы опорожнить желудок от завтрака. Но ты не завтракал сегодня, в значит в безопасности. В тихом переулке, что спрятался между двумя доками неподалёку от воды, ты видишь несколько изуродованных трупов. Судя по всему, смерть у них была болезненная, и одинаковая - их животы вспороты, а вся мостовая укрыта ровным слоем сине-лиловых кишок. Над всем этим мерзким натюрмортом роится стая мух, что жужжит так громко, что ты даже не слышишь, о чем говорят стражники, что прибыли на место раньше тебя. Ты замечаешь и старого знакомого, Беппо Сонти, что когда-то давно был твоим коллегой, еще в то время, когда ты и сам был следователем",212725,null],[224201,"2026-09-19T08:54:35",17,"В воздухе с карниза слетает черный ворон он внимательно осматривает место преступления. Марко получает визуальные образы четчикми вспышками из взять с Жнецом усилилась за последние годы. Ворон не составляет его.\n\nНе теряя времени в записной книжке Марко зарисовывает вид с воздуха. Свежим взглядом смотрит на картину. Нет ли тут сокрытого смысла? Не лежат ли кишки слишком ровно, не образуют ли они какой то глиф?\n\nВ книге мертвых содержатся множество рицталов и следом Марко колет себя большой палец небольшим кинжалом и выводит глиф яда. Книга жадно впитывает его кровь. На странице не остаётся и следа.\n\nМарко на некоторое время начинает ярко ощущать запахи ядов и темные пятна которые указывают на болезни\n\n/Ритуал обнаружения болезней и яда",212725,null],[224202,"2026-09-19T08:56:11",17,"Марко первым делом подойдёт к Беппо Монти\n\n— Беппо, доброго дня. Хотя вижу день уже омрачен ужасным преступлением против жизни человеческой. Что у нас тут, приятель?",212725,null],[224205,"2026-09-19T09:20:33",31,"Предчувствие, или опыт, не обманули тебя. Ты и правда замечаешь, что кишки растянуты в какое то подобие символа связи с загробным миром. Но он неправильный, словно, в зеркальном отображении сделан. Можешь бросить проверку анализа, чтобы попытаться понять что это, и зачем сделано",224201,null],[224206,"2026-09-19T09:22:45",31,"Беппо не удивился, встретив тебя здесь. Ты всегда рядом с какой-то хтонью\n\n- Привет, Марко. Ну ты и сам видишь, 7 трупов, пока не опознаны. Сюдя по запашку миндаля, отравлены и порезаны. Я так думаю, работа какого то культа, а как тебя увидел, только еще больше удостоверился в этом.",224202,null],[224207,"2026-09-19T09:37:02",17,"/r +5 Кто то искажает символы смерти, зачем?",224205,null],[224209,"2026-09-19T09:37:27",31,"Вот вам прет конечно на проверки/",212725,null],[224210,"2026-09-19T09:38:22",17,"— Мне нужно осмотреться на месте, можешь подсобить. Привлечь меня как стороннего консультанта? Есть у меня кое какие мысли, помогу тебе Беппо и дома сегодня будешь вовремя.",224206,null],[224211,"2026-09-19T09:39:52",31,"Похоже, это искажённый символ, что помогает общаться с темными духами. Чем больше жертв - тем сильнее тварь, с которой ты можешь поболтать. Но это одностороннее окно, при ритуале ты задаешь вопрос, а потом сущность тебя ответит. Но сама тебя не слышит. А тут зеркальное расположение черт глифа. Похоже, тот кто это сотворил, просто хотел передать сообщение",224207,null],[224212,"2026-09-19T09:41:08",17,"\"Семь трупов ради того чтобы просто сообщить что то темному духу. Колдун отчитался своему мерзкому покровителю? Возможно.\"",212725,null],[224213,"2026-09-19T09:41:11",31,"- у стражи снижен бюджет на консультантов, платить мне нечем - Беппо сразу предупреждает. - так что если хочешь помочь, то только по доброй воле. А так не откажусь конечно от помощи",224210,null],[224214,"2026-09-19T09:41:50",17,"— Конечно, по доброй воле. Как всегда. Почему говоришь что они отравлены? Какие уже нашел доказательства этой теории? Я пока вижу только кишки на брусчатке",224213,null],[224215,"2026-09-19T09:42:11",17,"Марко с Беппо приближаются к оцеплению у переулка",212725,null],[224216,"2026-09-19T09:43:03",31,"- принюхайся, я то знаю что у тебя нюх как у терьера. Миндалем же пахнет, цианид думаю",224214,null],[224217,"2026-09-19T09:46:29",17,"/ Обнаружение болезней и яда имба. Он четко говорит какой яд и какая болезнь рядом",212725,null],[224218,"2026-09-19T09:47:51",17,"Марко присаживается к ближайшему трупу и принюхивается",212725,null],[224219,"2026-09-19T09:50:14",31,"Сильный запах миндаля. Похоже, Беппо не зря есть свой хлеб. Тут и правда отравление цианидом. Людей потрошили уже мертвыми, цианид работает быстро",224218,null],[224220,"2026-09-19T09:55:02",17,"— Ты прав. Цианид работает быстро. Из разделали мертвыми от яда. Личности установили? Нужно понять отравили их в одном месте или натаскали из разных. Если натоскали, значит люди могут быть особенные. Особые жертвы. А если из таверны неподалеку, значит сам факт семи смертей нужен был.",212725,null],[224221,"2026-09-19T09:55:47",17,"— Тут замешана темная магия. Кишки выложены в виде глифа связи с потусторонними. Но зеркально. Можно только передать сообщение на ту сторону. На сколько я понимаю.",212725,null],[224222,"2026-09-19T09:56:29",17,"/r +5 Медицина осмотр раны, чем нанесена. Кинжал? Особый или обычный?",212725,null],[224224,"2026-09-19T10:00:00",31,"Тебя хватает понимания только на то, что клинок был прямым, не какой то ритуальный фламберг, в утилитарный инструмент с прямым клинком. Раны чистые и аккуратные, нет следов глумления над трупом. Аккуратная работа",224223,null],[224226,"2026-09-19T10:04:52",17,"\"Пол и возраст жертв? Есть тут зацепка?\"",212725,null],[224229,"2026-09-19T10:16:21",31,"Ты видишь что тут в основном молодые мужики, определить возраст сложно, но седых среди нет, и детей тоже нет. Похоже, обычные работяги",224226,null],[224230,"2026-09-19T10:20:11",17,"Марко задумывается мог бы он сейчас пересобрать этот глиф для того чтобы самому установить связь с потусторонним и задать вопрос. Что хотел тот кто это устроил?",212725,null],[224231,"2026-09-19T10:20:12",17,"/r +5 Магия",212725,null],[224233,"2026-09-19T10:38:08",31,"Можешь, чего бы и нет. Семерых только прикончи и истинное имя адресата скажи",224232,null],[224234,"2026-09-19T10:45:10",17,"/ уточню. Ритуал тут такой чтобы передать послание туда. А назад ответа нельзя получить?",212725,null],[224235,"2026-09-19T10:47:22",17,"\"Если только туда передавалось колдуном послание. Что это могло бы быть? Отчёт о выполненной работе?\"\n\n— Беппо, рядом с этим место не было недавно какого нибудь происшествия о котором судачат или заявляли?",212725,null],[224236,"2026-09-19T10:52:24",17,"\"Почему жертв семь? Число что то значит? Седьмой круг Баатора?\"",212725,null],[224237,"2026-09-19T10:53:57",17,"Марко аккуратно прошел внутрь глифа между тел встал в центр\n\n\"Должны быть следы волочения, не по воздуху же он ох сюда тащил. Или... По воздуху?\"\n\nПрисел ближе к земле в поиске следов, того кто раскладывал тела. Может его обувь отличается от обуви жертв",212725,null],[224238,"2026-09-19T10:54:19",17,"/r +5 Историия на знание адской иерархии и слоев Баатора",224236,null],[224240,"2026-09-19T10:54:34",17,"/r +3 Выживание на распознание следов",212725,null],[224242,"2026-09-19T11:19:26",31,"Нельзя. Это такой пейджер, в одну сторону работает/",224234,null],[224243,"2026-09-19T11:22:18",31,"- это Верфи, тут тихо обычно. Мужики работать приходят, любого баламута пинком под сраку гонят, гильдия корабелов бдит. Ничего крупнее кабацкой драки тут не было в последнее время, и то, считай не в Верфях, а на границе с портом, в \"Морском Коньке\", это такая рыгаловка самого низкого пошиба",224235,null],[224247,"2026-09-19T11:25:26",31,"Ты припоминаешь, что этот ритуал применяется редко, в основном из за того, что очень заметен, все таки трупов много оставляет за собой. Зато позволяет установить достаточно прочный мост к самым дальним планам. Похоже, убийца, или убийцы, имеют покровителя далеко отсюда",224239,null],[224248,"2026-09-19T11:26:33",31,"Ты четко видишь следы колес двуколки, на брусчиаке остались рыжеватые следы колес. Похоже мертвецов сюда привезли на телеге или небольшой карете",224241,null],[224272,"2026-09-19T12:42:56",17,"— Беппо, смотри ка. Следы ржавчины от теледных ободов. Привезли белого сюда уже мертвыми от яда. Некто опытный вспорол тут им животы и выложил кишки особым образом. Помоги ка мне понять, у нас одиночка работал или это группа преступников. Давай поищем разные следы подошв и размеров ног.",212725,null],[224273,"2026-09-19T12:43:11",17,"— А уж после последуем по следу кареты.",212725,null],[224276,"2026-09-19T12:45:14",17,"Пока Беппо занят следами Марко чертит свой кровью на странице книги мертвых другой символ. Глаз Анубиса. Закрывает глаза. Кровь впитывается в страницы и отрыв их назад от зрачков исходит лёгкое золотое свечение. \n\n/ ритуал и обнаружение магии. Хочу проверить кроме ритуала вызова иная магия тут использовалась, других школ. Может получится понять заклинание",212725,null],[224281,"2026-09-19T12:53:12",31,"Ты не обнаруживаешь иных магических следов. Похоже, трупы сюда были привезены с единственной целью - создать одноразовый канал связи, более ни бля чего они не потребный были",224276,null],[224282,"2026-09-19T12:54:35",31,"Вы таки замечаете следы как минимум троих человек, следы разного размера, двое довольно крупные, а третьи мелкие, словно от женских туфель без каблуков. Они же и самые неглубокие",224272,null],[224287,"2026-09-19T13:04:12",17,"— Минимум трое. У нас тут банда, а, Беппо. Как в старые добрые. Больше я тут ничего не вижу, мой друг. Нужно разматывать ниточку с телегой. Если получится опознать кого то установите где они были накануне. Я предполагаю все в одном месте, где их и отравили цианидом. \n\nМарко думает как ему пройти по следу кареты и не потерять ниточку",212725,null],[224326,"2026-09-19T13:23:04",31,"Продолжай. Какие у тебя варианты?",212725,null],[224343,"2026-09-19T13:33:20",17,"Пройти по следу кареты узнать откуда похитили людей и где отравили. Пора спрашивать там людей. Поискать илики чтобы выйти на троих колдунов",212725,null],[224354,"2026-09-19T13:45:02",31,"Ворон же фамильяр? Видит хорошо?/",224343,null],[224356,"2026-09-19T13:46:06",17,"/ Да летит над домами и глядит",212725,null],[224358,"2026-09-19T13:46:37",31,"Если придумаешь как он может разглядеть следы, он тебя доведет. Могу и сам предложить, но это скучно/",212725,null],[224360,"2026-09-19T13:46:49",17,"Марко останавливается иногда у стен домов и переносит свое зрение в глаза ворону. Так лучше понимает обстановку сверху",212725,null],[224362,"2026-09-19T13:47:52",17,"Взглядом с неба Марко видит улочки видит варианты как телега могла ехать. Ведь насквозь домов она не проедет. Доходит ногами до развилки и исследует следы там на месте\n\nТак принимает решение куда свернула телега\n\nПродолжает исключать вероятные маршруты",224358,null],[224363,"2026-09-19T13:47:56",17,"Пока не доходит до....",212725,null],[224365,"2026-09-19T13:50:26",31,"Я думал скорее что ты проведешь ритуал чтобы ворон шел по следу или запаху мертвых тел, но ладно, пойдет. Но времени ты потратил почти до самого вечера/",212725,null],[224401,"2026-09-19T14:05:06",17,"/ Ну я могу выдумывать ритуалы на все случаи жизни. Но тогда в чем интерес)",212725,null],[224403,"2026-09-19T14:05:17",17,"/ Использую только те что есть в книжке",212725,null],[224405,"2026-09-19T14:05:23",17,"/ Запаха трупов там нет",212725,null],[224412,"2026-09-19T14:07:19",31,"Ок. Чуть позже опишу куда ты попал/",212725,null],[224480,"2026-09-19T14:30:04",31,"Твоя тщательная розысканая работа, завязанная на отсчерие ложных следов, занявшая все утро и добрыкб половину светового дня, привела тебя к ранее упомянутому Беппо \"Морскому коньку\" - трактиру самого низкого пошиба, где тебе ч равным радушием подадут и кислого пива и удар кулака по морде. \n\nСейчас заведение выглядело особенно жалко, выбитая дверь и разбитые окна, покосившаяся вывеска. Но из открытой двери вы слышите пьяные голоса. Похоже, неприглядный внешний вид никак не мешал местным забулдыгам просаживать нажитое в любимой рыгаловке",212725,null],[224481,"2026-09-19T14:31:09",31,"Беппо останавливается и смотрит на тебя:\n\n- лучше тебе одному пойти. Стражу тут не любят, и чего то полезного не скажут из принципа",212725,null],[224823,"2026-09-19T18:44:01",17,"— Ты знаешь я болтать с отбросами тоже не мастак. Может получится узнать все что нужно без общения с имбицилами.\n\nМарко посмеивается \n\n— Врятли. Но я попробую. \n\nМарко встаёт спиной к стене в скрытом тенью переулке и переключает зрение на ворона. Теперь он стал его глазами. \n\n\"Лети поближе, послушаем о чем они там спорят\"",212725,null],[224825,"2026-09-19T18:45:09",17,"/r d20+2+d4 Скрытность ворона с указанием \n\nd20+5+d4 Восприятие Марко через ворона с указанием",212725,null],[225544,"2026-09-19T22:40:37",31,"Ворон незаметен для всех бухающих, просто тень, не стоящая их драгоценного времени и внимания. \n\nВпрочем, и чего то интересного ты не замечаешь, обычные пропитые и побитые морды. Трактирщик только чем то недоволен, рожа кислая",224826,null],[225550,"2026-09-19T22:44:20",17,"Ворон в засаде продолжает слушать двигается ближе, а Марко смотрит его глазами",212725,null],[225551,"2026-09-19T22:44:33",17,"Он уселся на потолочных балках и не отвечивает",212725,null],[225556,"2026-09-19T22:45:43",31,"Ворон только видит или может слышать и передавать речь?/",212725,null],[225634,"2026-09-19T23:12:20",17,"/ Да всё он может это универсальный дрон",212725,null],[225638,"2026-09-19T23:12:39",17,"/ Мысленно передает мне и я сливаюсь по желанию с его чувствами и сам смотрю и слышу",212725,null],[225665,"2026-09-19T23:20:05",31,"Утром уже отпишу. Я планировал что ты сам пойдешь и поговоришь, а так нужно будет вплести еще пару реплик и действующих лиц. Ну, новый опыт/",225638,null],[225683,"2026-09-19T23:23:46",17,"/ Харизма -1 я привык так добывать информацию)",225665,null],[226317,"2026-09-20T07:03:46",31,"Глазами и ушами ворона ты слышишь и видишь, как кто то из завсегдатаев обращается в трактирщику:\n\n- ты чего такой смурной, Дино? Ты же знаешь, мужики повесят дверь как будут выходить, не первый же раз.\n\nТрактирщик Дино:\n\n- да это меня и не беспокоит, хоть проветрим тут. Просто вчера пришлось страже переплатить, больше обычного...\n\n- эт с хера ли? Я думал у тебя все схвачено давно с местными стражами\n\n- да так и есть, но это при условии что мы ее сильно прямо шумим. А вчера тут был пиздец...\n\n- а чо было то? \n\n- да траванулась тут компашка одна, человек 7 наверное. Сидели, бухали, что то отмечали и жеоак, попадали с пеной у рта... Хорошо хоть рядом телега санитарная была, два санитара их подхватили, да увезли в госпиталь\n\nИх разговор прерывает еще один посетитель:\n\n- да какие санитары, Дино!? Я же тебе вчера еще говорил, этож братья Рино, они мясники, на Стада Пальма у них лавка. Онт свининой торгуют, чо я их не знаю что ли?\n\n- заткнись, Луиджи, просто заткнись. Ты столько выжрал вчера, что удивительно что еще в санитарах зеленых чертей не увидал. Двуколка с крестом была? Была. Значит, санитры из госпиталя.\n\nПочеьитель, что говорил первым:\n\n- так а со стражей то чего?\n\nДино:\n\n- да понятно же. Увидели что санитары уносят из кабака почти десяток мужиков и пришли за своей долей. Дескать, Дино, есть же договорённость, без смертоубийств. А то что им поплохело просто, так и не слушали. Стрясли как за месяц, суки...",212725,null],[226326,"2026-09-20T09:33:59",17,"Марко достаточно этой информации, у местных язык без костей, что ему очень на руку\n\n— Беппо, я всё узнал. Вчера тут семеро отравились. Свидетель утверждают телега санитарная рядом была, двое. С символами креста. Погрузили на телегу и повезли в \"госпиталь\". Но приехали они в тот переулок.\n\nМарко закуривает и красный огонек теперь мелькает в темноте\n\n— Ещё один свитель утверждает, что это были браться Рино, мясники на Страда Пальма. Узнал он из четко.\n\n— Женщины, на которую предположительно указывают следы на прошлом месте, среди них не замечено. \n\nМарко разворачивает карту около уличного факела.\n\n— Здесь. Страда Пальма. Мясницкая лавка.\n\nРисуетп о карте маршрут от текущей точки\n\n— А... Ещё говорят, что стража крышует этутзабегаловку и за семерых отравленных взяли больше обычного. Можно проверить не брали ли они с двух сторон от ьавернщика и оо мясников, чтобы глаза отвести. Но это уж тебе, приятель, проверять.",212725,null],[226416,"2026-09-20T12:20:44",31,"Отправляешь к мясной лавке, верно? Или я неправильно тебя понял? Еще какие то заявки?",226326,null],[226423,"2026-09-20T12:30:37",17,"— Я к мясной лавке, Беппо. Ночь будет долгой.",212725,null],[226425,"2026-09-20T12:35:13",31,"Мясная лавка пряталась в самом сердце Старого города, один ее конец начинался от портов, а второй упирался в площадь перед Собором. Тебе, впрочем, в Собор было не нужно, мясная лавка братьев Рико, которая помещалась на первом этаже семейного дома, находилась ближе к началу улицы. Домик казался вполне милым, но не особо уходенным, похоже, женской руки ему недоставало, а братьям и так было нормально. \n\nТы приблизился к дому и увидел, что в его окнах нет света. Странно, врнмя едва перевалило за 7 вечера, ты слышал колокол Собора вдалеке, что отбил 7 раз, но и лавка была закрыта, и в окнах никто не мелькал. Похоже, дом пуст. Или нет? Твои действия?",212725,null],[226427,"2026-09-20T12:45:25",17,"Сперва Марко пустил ворона облеть лавку вокруг. Не хотелось бы вламываться через главный вход без ордера. На улице то и дело снуют прохожие и кто то мог бы помешать расследованию. В идеале найти окно или заднюю дверь.",212725,null],[226430,"2026-09-20T12:47:31",31,"Ворон почти сразу после тебе весть - задняя дверь приоткрыта",226427,null],[226437,"2026-09-20T12:58:20",17,"Марко быстрым шагом идёт к ней",212725,null],[226439,"2026-09-20T12:58:49",17,"Хочет зайти внутрь перед этим бросая профессиональный взгляд на возможные ловушки, леску, растяжку",212725,null],[226440,"2026-09-20T12:59:03",17,"/r d20+5+d4 Внимание поиск ловушек",212725,null],[226442,"2026-09-20T13:01:34",31,"Ничего нет. Никто не ждет незваных гостей",226441,null],[226446,"2026-09-20T13:12:45",17,"Захожу тихо",212725,null],[226447,"2026-09-20T13:12:55",17,"/r d20+2+d4 Скрытность",212725,null],[226468,"2026-09-20T13:38:24",31,"Дверь скрипнула оглушительно для твоих обостренных чувств. Ты замер, обратился во слух, но никто не поинтересовался у тебя, какого хрена тут происходит, кто ты такой и что забыл в чужом доме. Тишина.\n\nТы оказался в подсобке мясной лавки, тут стояла колода для рубки мяса, в которой торчал нехилого размера топор. Ты прикинул, что такой мог бы приглянутся какому нибудь Варвару с севера. Отсюда вела дверь в лавку, а также лестница наверх, в жилые комнаты, и лаз в подвал",226448,null],[226516,"2026-09-20T14:01:52",17,"Пройдя мимо топора Марко его вытащил и сунет под шкаф\n\n\"Так спокойнее\"",212725,null],[226523,"2026-09-20T14:02:59",17,"\"Проверим подвал...\"\n\nОткрывает люк и смотрит вниз, темно там, поэтому приходится зажигать фонарь",212725,null],[226545,"2026-09-20T14:09:40",31,"В подвале и правда темно. И холодно, это ледник для свинины. Тущи висят тут и там. Подвал, кстати, довольно большой, и туши занимают лишь около трети помещения. Пройдя через них, ты находишь самодельный алтарь, грубо сделанный из камней, уложенных в форме пентаграммы и густо покрытый бурыми разводами. Тут проливали кровь",212725,null],[226563,"2026-09-20T14:14:23",17,"Осматриваю какой сущности тут возносили кровавые дары",212725,null],[226564,"2026-09-20T14:14:30",17,"/r d20+5+d4 Религия",212725,null],[226568,"2026-09-20T14:15:27",17,"\"Кому точно не понятно, но алтарь сам по себе доказательство вины.\" \n\nЗарисовывает символы с алтаря в книгу мертвых\"",212725,null],[226572,"2026-09-20T14:15:54",17,"Марко поднимается наверх, перед этим мысленно вопрошая ворона который остался в помещении выше нет ли никого там",212725,null],[226580,"2026-09-20T14:19:13",31,"Кому то мелкому и безымянному, точнее не понять",226565,null],[226581,"2026-09-20T14:19:34",31,"Ворон сообщает тебе, что видит два тела",226572,null],[226592,"2026-09-20T14:21:27",17,"\"Два тела которых там не было?\"",212725,null],[226593,"2026-09-20T14:21:36",17,"/Я не понял где тела там где мясницкий нож был?",212725,null],[226595,"2026-09-20T14:21:42",17,"/Или наверху?",212725,null],[226641,"2026-09-20T14:29:37",31,"Наверху, в жилой части/",212725,null],[226662,"2026-09-20T14:33:05",17,"Марко выбирается и идёт осматривать трупы\n\n\"Подельники видимо уже пошли в расход, хоть бы это не был очередной тупик\"",212725,null],[226663,"2026-09-20T14:33:20",17,"/r d20+5+d4 Медицина, причина смерти.",212725,null],[226716,"2026-09-20T14:53:03",31,"Тела двух братьев мясников ждали тебя наверху. Приблизившись, ты принялся за осмотр. Когда понял, с чем имеешь дело, тебя затошнило. Они очевидно были мертвы, но что стало причиной смерти? Ты уже видел такое. Тела не тронуты, нет никаких следов насилия. А под ногтями ты увидел то, что иногда приходит к тебе в кошмарах. Тот самый черный песок, что ты впервые увидел на теле дочери. Что бы не убило двух этих здоровых мужиков, но похоже это имело отношение к той давней истории. Опять прошлое нагнало тебя. Но в этот раз была хоть какая то зацепка. Легкие и невесомые следы, что ты видел на месте ритуала в переулке. Их обладатель явно что то знал, и его или ее тела тут явно не было",212725,null],[226734,"2026-09-20T15:02:56",17,"\"Черный... песок...\"\n\nМарко достал четыре монеты и положил их на глаза мёртвым. Он начал обряд упокоения зажав в руке маленькие песочные часы\n\n/Заупокойный обряд. Вы касаетесь одного трупа, и в течение следующих 7 дней цель не может стать Нежитью, кроме как с помощью заклинания исполнения желаний [wish].",212725,null],[226736,"2026-09-20T15:03:29",17,"/ Это отсюда\n\nhttps://dnd.su/spells/465-ceremony/",212725,null],[226737,"2026-09-20T15:03:42",31,"Я тебе верю)/",212725,null],[226738,"2026-09-20T15:04:12",31,"Если хочешь что то описать, вперед. Я продолжу когда ты выйдешь на улицу/",212725,null],[226742,"2026-09-20T15:06:27",17,"Обряд был завершен. Вскоре Марко сообщит об убитых\n\nОн осмотрел личную комнату где лежали трупы на предмет улик, которые могли бы помочь выследить колдунью. /\n\nЕго уже начало подташнивать на мысли о том, что появилась реальная зацепка. Можно продвинуться хоть на шаг. Но если тут пусто, она снова оборвётся. Волнение было подавлено хладнокровной злобой на это существо.",212725,null],[226743,"2026-09-20T15:06:48",17,"/r d20+5+d4 Поиск улик, зацепок",212725,null],[226748,"2026-09-20T15:10:06",31,"Ничего особенного ты не находишь. Борьбы не было, парни умерли словно бы мгновенно. Разве что запах... Так не пахнет в холостятской берлоге над мясной лавкой. Какое то растение? Но этот запах тебе не знаком. Однако бы его запомнил, и теперь сможешь узнать",212725,null],[226802,"2026-09-20T15:32:50",17,"С тяжёлым вздохом Марко поднимается с колена.\n\nТак звучит принятие. Тут больше ничего.\n\nСледователь движется к задней двери, чтобы покинуть лавку и вдохнуть ночной отрезвляющий воздух. Может он даст какую то наводку. \n\n\"Тупик. Снова.\"",212725,null],[226807,"2026-09-20T15:35:37",31,"Словно угадав твои мысли, наводка буквально падает с неба. Точнее, опускается. Это бумажная птичка, довольно сложная кстати. Она кружит надо тобой, словно бы просясь в руки",212725,null],[226808,"2026-09-20T15:36:44",17,"\"Хватай\"\n\nВорон пикирует и клювом хватает бумажную птичку\n\nОпускается и кладет на ладонь Марко\n\nТот разворачивает послание и читает",212725,null],[226814,"2026-09-20T15:41:42",31,"\"Любезный сиор Марко! Мы с вами незнакомы, но я наслышан о ваших талантах и устремлениях. У меня есть кое какая информация, которую я бы хотел с вами обсудить. Зайдите ко мне в любое удобное время, хоть прямо сейчас, Стада Валериана , 221. Поговорим. Искренне ваш, сиор Неро Феллино, частный детектив\"\n\nВместо подписи на бумажке ты видишь оттиск кольца печатки в виде кошачьей головы в профиль. Очень похожий на тот, что тебе с утра показала книга",212725,null],[226856,"2026-09-20T16:08:17",17,"\"Интересно как шакалы относятся к кошкам... Никогда не задумывался\"\n\nМарко сразу же выдвигается по адресу указанному в записке. Других зацепок у него не осталось",212725,null],[226857,"2026-09-20T16:08:47",31,"Дом Феллино",212725,null],[226858,"2026-09-20T16:09:42",31,"На твой стук дверь открывает юный табакси, видимо, слуга или помощник. Он без слов провожает тебя наверх. Тебя тут ждали",212725,null],[226859,"2026-09-20T16:11:07",31,"В кабинете наверху ты видишь жирного старика-табакси, что попивает что то похожее на ликер из валерианки.\n\n- о, сиор Марко, я рад что вы навестили меня. Я Неро, Неро Феллино",212725,null],[226862,"2026-09-20T16:12:47",31,"- угощайтесь ликером, он знаете ли, благотворно влияет на людей. Нервы успокаивает",212725,null],[226865,"2026-09-20T16:13:44",31,"- а я вот его пью для бодрости духа. Возраст, знаете ли.",212725,null],[226919,"2026-09-20T16:45:18",17,"— Благодарю за гостеприимство сеньер Фелино. Не буду отказываться, раз вы предлагаете.\n\nМарко проходит садится за столик и пьет ликер из вальянки\n\n— Успокоить нервы разумно. Особенно, после того, что происходило сегодня. Вы я полагаю вкурсе?",212725,null],[226931,"2026-09-20T16:57:32",31,"- увы, да. Опять смерть без без следов насилия, опять проклятый черный песок. \n\nНеро прочищает горло\n\n- извините, шерсть в горле. О чем бишь я? Ах да, черный песок. Я, волею Аскелатора, наделён некоторой искрой пророческого дара. Нествбильной, увы, но иногда меня посещают видения. Вот сегодня с утра я и увидел смерть двух молодых людей. Я их немного знал, они не ангелы, и проходили иногда в делах, что я веду. Не зная точно, что с этим делать, я решил написать вам письмо и оставил его висеть над домом. Откуда то был уверен, что вы придёте. Не спрашивайте откуда, я опять сошлюсь на предчувствие. Как я уже говорил, я знаю о вас. И соболезную вашей трагедии. \n\nНеро помолчал и продолжил:\n\n- Однако же, с прискорбием вам сообщаю, что подобные инциденты случались не только с вашей дочерью, упокой свет ее душу. У меня довольно большая сеть агентов, в том числе немало ваших бывших коллег, что ушли на вольные хлеба. Так вот, дела л смертях, где фигурировал черный песок под ногтями жертв впервые привлекли мое внимание около 3 лет назад. Тогда за год нашли 4 таких тела. Два года назад 7. В прошлом году 11. А за девять месяцев этого года уже 17, с учетом покойных братьев Рико. \n\nНеро встает и подходит к окну, смотрит в окно, немного комично сложив руки за спиной. Смотрит вдаль, затем разворачивается и продолжает:\n\n- Марко, вы же позволите назвать себя Марко, верно? Так вот, Марко, я не знаю что происходит, но мне очень не нравится этот прирост. Что то очень плохое грядет в этом городе, а что именно - я не знаю, мой дар молчит. Одно я знаю точно, эта гнусь не ходит дальше Вальдории. Мои агенты искали ее следы по всем городам торгового союза. Ничего подобного нет. А тут есть. И давно. Но раньше было не более одного случая за насколько лет. Я весьма привязан к Вальдории и своему дому, и хоть мне и не платят за это дело, я все же хочу в нём разобраться. И надеюсь, что мы друг другу можем помочь",212725,null],[227263,"2026-09-20T20:24:43",17,"— Что ж. Возможно нам стоит объеденить усилия. За пару лет работы в одиночку, я не то чтобы сильно продвинулся в этом расследовании. \n\nМарко отпивает ликера\n\n— В подвале мясников был алтарь, вот я зарисовал пиктограмму на нем и общий вид. Не могу распознать кому они дарили кровь. \n\n— Кроме этого ранее, в переулке семь жертв. Привезли уже мертвых, отравили цианидом в забегаловке. И вспороли животы - это канал связи в потусторонним покровителем. Но вот что интересно. Судя по ритуалу могли передать послание только туда. Но не получить ответ. Я думаю колдунья отчиталась о выполненной работе или подала сигнал к началу чего то. \n\nЕщё немного валерьяновогл ликера\n\n— Колдунья пока условно, руководствуюсь размером обуви и глубиной отпечатков ног.",212725,null],[227287,"2026-09-20T20:37:34",31,"Неро задумывается.\n\n- культисты, значит. Ну, не могу сказать что удивлён. Семь трупов для особого сообщения это кажется излишеством, кого они там вызывали, повелителя всех дьяволов? Я у сожалению не силён в темных ритуалах.\n \nНеро вновь задумывается, пар минут проводит в молчании, словно что то пытается припомнить\n\n- Марко, вы верите в холистику? Я вот верю. Мне было видение, завтра сюда придут два клиента, и не клиента одновременно. У них есть свои истории, но они как то связаны между собой и с вами тоже. Думаю, я дам им работу. Вас же я хочу попросить стать им ну не надзирателем, а скорее старшим товарищем. У вас есть опыт. Помогите им с их историями, а они помогут вам. Вы чем то связаны, но пока я не вижу чем. А я в свою очередь займусь анализом данных, раз процесс ускоряется, значит будут и новые улики. А я, без ложной скромности, могу назвать себя экспертом в подобных паззлах. Если вы согласны, то жду вас завтра, часов в 10 утра, тогда и придут те двое. Встретьте их у моей двери и проходите. Желаю вам спокойной ночи, если вы сможете таки уснуть. Мне от спать не придётся, буду вводить себя в транс и ловить намёки от вселенной. Мы сл всем разберемся",212725,null],[227824,"2026-09-20T23:48:16",17,"— Что ж. Сейчас у меня все равно тупик. Если есть шанс так приблизится к разгадке, я согласен. Завтра я приду к дверям раньше десяти и встречу этих двих., как вы просите.\n\n— Если это все, господин Неро. Я откланюсь. Спасибо вам... Что готовы сотрудничать. Дело оч ерном песке дейтвиеьльно стоит внимания самых пристальных глаз.\n\nМарко кляннется и выходит из кабинета. \n\nОн возвращается на свою базу и проводит ночь? Дабы быстрее встретить новый рассвет. И двоих с кем, возможно, судьба завязала нити судьбы.",212725,null],[227854,"2026-09-21T05:35:55",31,"На этом стартовый мини-квест Марко заканчивается. Все пинки, плевки и слова поддержки можно высказать в обсуждение квестов. Мастер стерпит//",212725,null],[227855,"2026-09-21T05:37:26",31,"@lady_godzilla @PaIIasCat @dunchev В 8 утра по Москве стартуем первый общий квест, пост я напишу раньше, как будете готовы, влетайте//",212725,null],[227856,"2026-09-21T05:39:14",31,"@PaIIasCat скажи пожалуйста, как мне к тебе обращатся? Коля и Полина под своими именами тут, мне не сложно понять как их звать. Я не против анонимности в Интернете, могу звать и по нику, просто скажи Паллас или Пэллас, или Паллэс))",212725,null],[227857,"2026-09-21T07:24:12",31,"Вальдория, Стада Валериана, 221, около 10 утра.\n\nМарко пришел заранее и выглядывал тех самых обещанных Неро клиентов-неклиентов. У него оставались сомнения в пророческих способностях старого табакси, но ведь проверить их было не сложно.\n\nЯркое солнце и безоблачное небо позволяло видеть довольно далеко и вскоре Марко и впрямь заметил двух девушек, что подходили к конторе. Одна шла со стороны порта и выделялась экзотической внешностью и какой то робостью. Очевидно, ей тут было неуютно и она сама была не уверена, правильно ли она пришла. Вторая шла со стороны Старого города, и выглядела как местная аристократка из числа старых небогатых, но гордых семейств. Она была вооружена, что немного необычно для девушки, бледна, что вообще странно для южанки и необычно сосредоточена  серьезна, хотя судя по морщинкам на лице, это не соответствовало ей. Лицо ее было создано для смеха, веселья и озорства. Что же заставило ее хмурится?\n\nДевушки шли с разных сторон, с разной скоростью, но очевидно, должны были подойти в одно и тоже время. Похоже, старый табакси был прав.\n\n@lady_godzilla @dunchev @PaIIasCat",212725,null],[227863,"2026-09-21T08:23:25",20,"/можно просто Катя",227856,null],[227868,"2026-09-21T08:38:11",17,"Марко сперва посмотрел на одну девушку, затем на вторую\n\n\"Слишком разные чтобы прийти сюда вместе. Но старый кот именно так и говорил. Значит не соврал\"\n\n— Доброго утра, сиоры. Полагаю, вы обе к Неро Феллино?\n\nМарко отступил от двери освобождая проход\n\n— Марко Веньер. Сиор Фелино просил встретить вас здесь. Судя по всему, какое то время нам предстоит работать вместе.\n\nЕщё один короткий взгляд на вооруженную бледную девушку. Потом на чужестранку, когда они подошли поближе\n\n— Как могу к вам обращаться?\n\nМарко кивнул в сторону двери\n\n— А причины вашего визита лучше обсудим внутри. На улице у стен слишком много ушей",212725,null],[227896,"2026-09-21T09:22:38",22,"Это ещё что за человек?_\nТочно человек?\nВоняет чем-то знакомым\nСмертью? Прахом? Точно..\n\nШАКАЛ!\n\n- О-ой.. Ясмин, меня з-зовут Ясмин.\n\nДевушка нервно сжала свое платье. Ее костяшки побледнели.\n\nОна не смотрела никому в глаза, чуть отворачивая голову в сторону.",212725,null],[227900,"2026-09-21T09:27:24",20,"*Беатриче останавливается, внезапно оказываясь прямо нос к носу с двумя другими людьми. Неро Феллино ждал ее? Или даже их - она бросает короткий взгляд на иностранку.*\n\n*Неужели слух о смерти Кристины уже достиг ушей этого усатого детектива? Ах kazzo! Совсем нет времени думать об этом! Негоже перед новыми знакомыми стоять молча*\n\n- Беатриче Висконти да Вальдрио *Она делает лёгкий, слегка резкий поклон, приветствуя их*\n- К вашим услугам, сеньор Веньер и bella signorina.",227868,null],[227906,"2026-09-21T09:34:10",22,"Кровью пахнет\n\nЗолотые глаза начали кружиться вокруг Биатриче, насмешливо прищуриваясь.\n\nКровь и холод. Неужели кровосиська?_\n\nИхихи-хи-хи \n\nЯсмин сжала губы и кивнула, старательно смотря в пол.",212725,null],[227909,"2026-09-21T09:35:53",17,"Марко поклонился как требует этикет и руками пригласил пройти синьор первыми",212725,null],[227912,"2026-09-21T09:38:57",31,"ладно, вы заходите. сейчас бахну пост/",212725,null],[227913,"2026-09-21T09:47:22",31,"Марко ведет девушек уже знакомой дорогой в кабинет Феллино. Старый табакси, судя по всему, провел тут всю ночь, выглядит изможденно, годы на нем сказываются очень сильно. Но завидев вас, он приободряется:\n\n- о, доброе утро, сиоры. Сиор Марко, и вас я тоже рад видеть. Эту ночь я провел в медитациях, настраивался на связь с даром, так что буду рд вас выслушатьи попробую помочь. не смущайтесь тем, что я попросил вас зайти вместе, мне было видение, что ваши просьбы и истории связаны. Начнем с вас, юная леди\n\nНеро делает жест лапой в сторону Ясмин, склонят голову набок и неожиданно в его глазах мелькая что опасное, словно он чтио то заметил, и ему это не понравилось. Он тянется к бутылке валерианового ликера, наливает рюмку, делает над ним какой то пасс лапой и протягивает его Ясмин\n\n- только выпейте для начала. это поможет вам слышать только тех, кто и правда сейчас в этой комнате.\n\nБеатриче, кстати, отмечает, что Феллино предпочитает ликер, который производит ее дядя на винокурне за городом, а продает ее отец. на бутылке написано L’Elisir dei Visconti",212725,null],[227918,"2026-09-21T10:09:15",22,"Нельзя пить все подряд, что тебе предлагают всякие дяди!\nПотом очнешься неизвестно где\nНеизвестно с кем\n\nЭто не вам решать!\n\nЯ опять крикнула вслух?! Вон как смотрят.. стыдоба. Плевать, будь что будет.\n\nЯсмин берет рюмку и пьет залпом. \n\nГлаза девушки будто стали ещё больше, а зрачки увеличились. Она начала очень сильно кашлять, из глаз брызнули слезы.",212725,null],[227919,"2026-09-21T10:12:27",31,"- нет больше лишнего?\n\nГлаза табакси смотрят в душу",212725,null],[227920,"2026-09-21T10:19:02",22,"- Н-нормально. Но вы рябите в-в глазах. Это побочные действие л-лекарства? У вас есть ещё? Я хочу его принимать почаще! Тишина.. это прекрасно...\n\nДевушка так обалдела от пустоты внутри, что даже забыла,  зачем она пришла. И лишь уголок письма, торчащий из сумки, вернул Ясмин в реальность.\n\n- Я.. у меня письмо.. вот! Меня попросили помочь в одном деле\n\n*девушка кратко пересказывает события на корабле и просьбу капитана, ее язык иногда заплетался, а сама она чутьпошатывалась*",212725,null],[227924,"2026-09-21T10:29:13",17,"Марко прошел и присел в кресло у окна. Закинул ногу на ногу и внимательно выслушал рассказ Ясмин.\n\n\"Проклятый предмет... Паршиво. А она не промах, смогла избавиться от него и матроса спасла. Добрая душа.\"",212725,null],[227927,"2026-09-21T10:32:08",31,"- ну, можно сказать и лекарство, да. Только оно как и каждая пилюля дает только временный эффект. Очень не советую злоупотребялть. Потом доза будет все больше, а эффект все слабее. Вам, с вашей проблемой, нужно что то более кардинальное. Вот, кстати, закусите. \n\nНеро протягивает тебе бутерброд с рыбой, видимо не хочет чтобы ты окосела, а затем читает письмо. Пробежав его глазами, он поднимает взгляд на тебя:\n\n- ну чтоже, я и правда кое чем обязан семье Беати, и денег с капитана не возьму. А вот насчет вас... я бы хотел попросить вас поработать на меня. У меня большой штат агентов, но тех кто умеет определять проклятия, и более того, снимать их? таких у меня нет. а в этом деле это будет необходимо. Разумеется, я не прошу вас работать бесплатно. Будете получать стандартную ставку. Сейчас мне нужно буде немного послушать дар и понять, куда нам идти дальше в этом деле.\n\nНеро откидывается на скинку своего огромного красного кресла и закрывает глаз. Минут ничего не происходит, вы уже подумали что старик, верно, заснкл, как его глаза открываются, но они не зеленые, а темные, со зрачком на всю радужку. Он хваатет перо и что то пишет, всего несколько слов. Затем падет на спинку кресла, вновь закрывает глаза, а открыв их, уже каждется нормальным. \n\nОн смотрит на лист бумаги, читает, смешно шевеля губами, а затем протягиват лист Ясмин. Там указано: Серебро, любовь, зависть, железо\n\nУбедившись, что ты прочитала, Неро заговаривает вновь:\n\n- я спросил о причинах, способах, мотивах и тайнах. В такой последоватльности я и получил ответы. Пока этого мало и мои агенты будут с этим работать. А может у вас есть какие то умозаключения?\n\nНеро смотрит на тебя, ожидая твоих мыслей. Это не экзамен. Он просто изучает то как ты мыслишь",227920,null],[227943,"2026-09-21T11:04:18",22,"- С-спасибо.\n\nЯсмин жевала бутерброд с благодарностью смотря на табакси.\n\nОна берет лист, дрожащими пальцами и начала читать вслух. \n\n- Серебро, это последнее, что остаётся, когда золото перестают носить. Женщины в моей стране прячут его на дне комода.. не понимаю, но слышала в караванах поверье, что оно защищает от злых духов. Возможно, стоит им запастись..на будущее. \n\n- Любовь? Я не знаю. Когда я слышу это слово, я не могу его удержать. Оно как вода в руках, если зажать, то прольётся. Может, это когда кто-то делает что-то для тебя, и ты не обязана это возвращать? \nНо все, кто делает что-то для меня,  хотят получить что-то взамен. Всегда хотят. Поэтому я не уверена, что любовь существует отдельно от долга. Может, её и нет. Может, есть только долг, который назвали красивым словом.\n\n- Зависть.. она гложет моё сердце.  Завидую тем, кто пуст внутри, у кого там тишина. Как у меня сейчас..так хорошо.\n\n- Железо? О, это то, чем я хотела бы быть. Оно не чувствует, оно не просит. Оно просто стоит и я хочу стоять хотя бы на минуту.. почувствовать себя ничем..\n\nЯсмин сложила лист и разорвала его на четыре части. По одной на каждое из слов и спрятала их в карман.\n\nПусть будет у меня хоть что-то,  о чем они не знают.",212725,null],[227947,"2026-09-21T11:08:50",31,"Неро кивает головой. Он не выражает иных эмоций. Переводит взгляд на Беатриче. \n\n- Сиора Висконти, а что привело вас? Я ощущаю тайну, но честно говря, зная вашу репутацию, теряюсь в догадках. БЫли бы вы вы мужчиной, подумал что дело в шантаже или алиментах, но такие мелочи не исказили бы ваше лицо. Рассказывайте",212725,null],[227957,"2026-09-21T11:16:23",31,"@PaIIasCat",212725,null],[227969,"2026-09-21T11:41:14",20,"- Это не просто дело, сеньор Феллино! Это sacrilegio! *С запалом начинает Беатриче, вскакивая со своего места*\n- Кристина, мою дорогую Кристину убили!\n\n*В ее голосе звучит ярость на пополам с горечью*\n\n- Какая-то мерзкая тварь, pezzo di merda inutile e fottuto, посмело оборвать ее жизнь своими клыками! Прошлой ночью я обнаружила уже ее обескровленный труп со следами зубов на шее.\n\n- Я не могу позволить твари, совершившей это, просто так уйти от правосудия! Не после того как оно забрало у меня mio amato и бросило тень на имя Висконти!",227947,null],[227970,"2026-09-21T12:00:03",31,"- Вампир? Однако... Они в городе конечно есть, само ваше существование говорит об этом. Но нагло лезть в дом уважаемой семьи? Слишком нагло для местного.  Гастролер? Или местный сумасшедший? В любом случае это плохая новость. Позвольте, я снова войду в транс.\n\nТабакси повторяет ту же сцену с трансом и написанием слов на бумаге, что вы видели раньше. На этот раз на клочке бумаги, что передали Беатриче были слова:\n\nКровь. Тень. Пробуждение. Серебро\n\n- Я вновь просил о причинах, способе, мотивах и тайне. И как погляжу, одно из слов у вас с Ясмин сходится. В вашем случае серебро это тайна, в ее случае - причина. Возможно, тут то и скрывается связь ваших историй. Вопрос только в том, настоящее это серебро имеется ввиду, или иносказательное. Есть над чем подумать. Ладно, я напрягу своих агентов поискать вампира-гастролера, пока это будет основной версией. И да, вам бы я тоже предложил работу. Я чувствую свяхь историй, вас троих. лучш будет если вы какое то время будете держатся вместе. Что касается мое оплаты - я не возьму с вас денег, как и с Марко и Ясмин. Но если вдруг у вас окажется лишняя бутылочка L’Elisir dei Visconti...",212725,null],[227972,"2026-09-21T12:03:54",20,"- Благодарю, сеньор *Беатриче кланяется*\n- Мой клинок к вашим услугам в этом деле. \n\n*Она слегка ухмыляется, обнажая острые клыки*\n\n- Ну а если нам получится смыть кровью этого bastardo пятно с имени Висконти...обещаю вам лучшую бутылочку L’Elisir dei Visconti и не одну",227970,null],[227974,"2026-09-21T12:11:41",31,"- тогда подытожим. Яотправлю агентов на поиски и установку связей между покойниками с черным песком под ногтями по делу Марко, определю круг тех, кому выгодна смерть капитана Карло Беати, к тому же имеющих возможность наложить сильное проклятие по делу Ясмин, а аткже поищу вампира-гастролера или намеки на его существование. \n\nНеро что то черкнул пером и снова заговорил. \n\n- По поводу вашей работы на меня. У меня всегда есть дела и всегда не хватает агентов. А бывают такие клиенты, которым я не хочу отказывать. За час до вашего появления у меня пришло письмо от главы гильдии Дварфских кузнецов Вальдории. У них завелся серийный взломщик. Я бы хотел попросить вас заняться этим делом. Врядли там что то серьезное, но вы все таки новички в нашем деле. Вот и потренируетесь заодно. Сиор Болен буде ждать вас в своей кузне в Ремесленном городе, адрес я вам дам. Навестите его, узнайте все возможное и постарайтесь помочь. А затем жду вас с отчетом",212725,null],[227978,"2026-09-21T12:13:39",31,"//все, прием окончен. если есть вопросы, можете задать, если нет - то удачно вам добраться до Дварфа-заказчика//",212725,null],[227979,"2026-09-21T12:15:47",31,"можете социалить и обсуждать то что услышали, мне будет интересно почитать ваши реакции/",212725,null],[227985,"2026-09-21T12:26:22",22,"- С-спасибо. Мне очень жаль вашу п-подругу, Беатриче. Да прибудет с ней свет.\n\nДевушка на мгновение складывает руки в молитвенном жесте. \n\n- Что за черный песок? Никогда о таком не слышала.",212725,null],[227986,"2026-09-21T12:27:18",31,"Думаю, это уже не ко мне вопрос?/ пусть Марко рассказывает/",212725,null],[227988,"2026-09-21T12:28:01",22,"//скорее к Марко. И пока слушает, рука тянется к ещё одной рюмочке. Если она есть",212725,null],[227989,"2026-09-21T12:28:32",20,"/такими темпами сопьется",212725,null],[227990,"2026-09-21T12:28:49",31,"Дружи с Беатриче, она нальет. Правда, потом может и еще чего придумать😏",227988,null],[227991,"2026-09-21T12:29:25",22,"//девочка первый раз попробовала. Ей понравилось, что в голове тихо",212725,null],[227992,"2026-09-21T12:29:51",31,"потом тебе расскажу, почему стало тихо. Но пока рано/",227991,null],[227993,"2026-09-21T12:31:05",20,"- Grazie, signorina. *Кивает Беатриче*\n\n- Свет...да, неплохо было бы. Вот бы этот же свет выжег сердце этого клыкастого stronzo *бормочет она себе под нос*",227985,null],[227994,"2026-09-21T12:41:07",17,"Сперва Марко встаёт и с поклоном говорит Беатриче\n\n— Примите мои соболезнования, гибель дорогого человека бьёт в самое сердце, когда не ждёшь. Можете рассчитывать на мою помощь в поисках упыря.\n\nПотом переводит взгляд на Ясмин. Поднимает книгу в руках она раскрывается и пролистывается сама. До заметок о смертях, где фигурировал черный песок.\n\n— Никто не знает, что это. Под ногтями некоторых жертв мы находим черный песок. И никаких ран или увечий. Но человек мёртв и только черный песок связывает подобные случаи. Дело моей жизни найти, того, кто совершает эти злодейства, сиоры. \n\nВзгляд Марко тяжелеет. Тяжелая грусть с которой он живет последние пару лет всегда где то рядом. Готова упасть на плечи в любой момент. Но это не значит, что нужно пасть под её тяжестью.\n\n— Я с радостью присоединюсь к вам. Сеньёр Фелини редко ошибается в своих пророчествах, если вообще ошибается.",227985,null],[227995,"2026-09-21T12:43:49",31,"в общем, тегните меня когда вас нужно будет вести к дварфу или еще куда то. у вас есть свобода перемещатся по городу, искать допзадания и прочая и прочая. Но учтите что пока город еще не готов до конца и задания для вас как для игроков первого уровня будут соответствующие))//",212725,null],[227996,"2026-09-21T12:45:45",31,"первая арка закончится для вас аослк закрытия первого дела от Феллино, тогда же и опыт получите/",212725,null],[227997,"2026-09-21T12:49:23",31,"да, еще момент. вы можете разделяться и вести свою линию лично, в формате соло квеста. я ебанусь если вы все втроем решите это сделать одновременно, но попробую вести и так/",212725,null],[227999,"2026-09-21T12:52:43",22,"- М-мне жаль...\n\nЯсмин хотела сочувствующе дотронуться рукой, но испуганно ее одернула.\n\n- У всех из нас свои шайтаны... Может направимся к дварфу? Дело отвлечет нас от тяжёлых мыслей.  Всех нас.",227994,null],[228003,"2026-09-21T13:05:51",20,"- Как пожелаете, сеньорита Ясмин. Дела и правда позволяют отвлечься от боли потерь *Беатриче подаёт ей руку*\n\n- И прошу прощения, в пылу не смогла вам поприветствовать надлежащим образом. Примите мои глубочайшие извинения.",227999,null],[228004,"2026-09-21T13:09:19",31,"ну почапали тогда к дварфу. душить вас случайными событиями пока не булу. во первых мне лень. это все, во вторых не будет)))//",212725,null],[228005,"2026-09-21T13:12:22",17,"— Тут на углу есть отличная булочная. Там тётушка Мариэла печет самые нежные круассаны в Вальдории",212725,null],[228006,"2026-09-21T13:13:53",31,"Ведя неспешные разговоры и знакомясь на ходу, вы покинули контору Феллино и отправились в Ремесленный город. \n\nЭтот район встречает вас кипучей энергией, тут отовсюду летят разные звуки: стук молотов, визжание пил, ровный гул гончарных кругов и печей. \n\nВы без проблем находите кузню мастера Болена, главного дварфа-кузнеца Вальдории. Он занят каким то клинком, стоит к вам спиной и явно не подозреет что вы пришли",212725,null],[228007,"2026-09-21T13:14:17",31,"напротив кузни и правда есть булочная. оттуда одуряюще пахнет выпечкой",228005,null],[228012,"2026-09-21T13:16:50",20,"- Хм, звучит как неплохое место чтобы подкрепиться. Да и синьориту Ясмин стоит познакомить с гастрономическими жемчужинами Вальдории *одобрительно кивает Беатриче. А этот Марко знает куда пригласить даму.*",228005,null],[228014,"2026-09-21T13:19:29",17,"— Что вы знаете о сыскном деле сиоры? Нам предстоит дело о серийном взломе, кто то не чист на руку и хочет нажиться воровством за счет честных людей.",212725,null],[228017,"2026-09-21T13:22:48",20,"- Ну, с сыскным делом лично я знакома не очень. *Хмурится Беатриче, пытаясь вспомнить хоть что-то похоже из того, чем она занималась*\n- Вот если вора этого надо будет поймать и проучить хорошенько, чтоб к честным людям в карман не лез - это я всегда готова. Но  как его отыскать - нет\n\n*Он вздыхает*\n\n- Я поэтому и пошла к синьору Феллино за помощью в своем деле - одной мне такие загадки не даются...",228014,null],[228030,"2026-09-21T13:33:59",22,"- Булочки? Чудесная мысль! А на счет вора.. Я думаю, что этот вор мог сделать это по нужде! Может он очень сильно сожалеет о содеянном и теперь страшно переживает... \n\nДевушка нахмурилась и качнула головой, опуская на лицо вуаль, которая тихо зазвенела.\n\n- Мне лучше скрыть глаза.. глаз. Он злой. Он может принести беду. Пусть лучше я буду выглядеть странно, нежели стану вестницей чужих несчастий.\n\nНакинув вуаль, Ясмин будто стала более уверенной. Она выпрямилась и расправила плечи.\n\n- Давайте прежде всего осмотрим скважину, которую вскрыли. Если следов будет много, то конечно же, вор сделал это поневоле..",228014,null],[228031,"2026-09-21T13:34:48",31,"Скважина?/",212725,null],[228032,"2026-09-21T13:35:38",22,"//замочная. Ты же написал взломщик, у меня первая ассоциация была с замочной скважиной: сундук/дверь и тд",228031,null],[228033,"2026-09-21T13:37:13",31,"А, точно, у меня просто скважина ассоциируется с водопроводом))))/",212725,null],[228034,"2026-09-21T13:37:18",31,"Личная боль/",212725,null],[228036,"2026-09-21T13:38:12",22,"//я не шарю в воровском сленге, извините если что, возможно там другой термин используется",212725,null],[228045,"2026-09-21T14:10:46",17,"\"Злой глаз?.. \"\n\nЗаходя в булочную направился к витрине где только что испеченные круассаны ожидали покупателей. \n\n— Сегодня большой выбор!\n\nМарко быстренько купил несколько и предложил синьёрам угостится.\n \n— Знакомство лучше всего начинать за чашечкой чая и чего-нибудь сладкого, не находите?",228030,null],[228048,"2026-09-21T14:12:24",22,"//Полина, которая на диете, громко сглотнула слюну",212725,null],[228051,"2026-09-21T14:12:53",17,"/ Пытки еще никогда не были настоль изощрёнными",228048,null],[228053,"2026-09-21T14:13:14",22,"//где я согрешила, за что🥲",228051,null],[228054,"2026-09-21T14:14:09",17,"/ Злой глаз  🤷",228053,null],[228055,"2026-09-21T14:16:58",22,"- Да..  очень много странствовала по миру и всякий раз, когда люди замечали мой глаз, они начинали много шептаться, а если случалось что плохое  - колесо сломалось или молоко скисло, так сразу во всем мой глаз обвиняли, да гнали меня прочь. С тех пор, как я стала надевать эту вуаль, стало немного легче, возможно однажды, я смогут научиться прятать свое уродство хотя бы магией.\n\nЯсмин заметила круассаны и широко улыбнулась. \n\n- Выглядят просто фантастически!",228047,null],[228058,"2026-09-21T14:17:37",17,"/ Удивительно что Ясмин выкладывает всё начистоту)",212725,null],[228059,"2026-09-21T14:17:43",17,"/ Я даже как то ошарашен",212725,null],[228060,"2026-09-21T14:18:02",20,"- Ммм, пахнет восхитительно *Беатриче тут же берет свежий крупсан*\n- Grazie, signore. Надо будет как-нибудь вас угостить в ответ - тем более если работать будем вместе\n\n*Вгрызается в тесто с явным удовольствием*",228047,null],[228062,"2026-09-21T14:18:23",22,"//дорвалась до собеседников и плюс она под градусом же. 2 рюмки на голодный желудок. Один бутер не спасет",228058,null],[228064,"2026-09-21T14:19:48",22,"//плюс вы сразу вилами тыкать не стали, камни не кидали, значит можно и пообщаться. Не если не нравится, то поправим. Но мне казалось, что тут такая реакция будет уместна.\nСужу по своему опыту",212725,null],[228066,"2026-09-21T14:20:19",20,"- Хах, да мало ли что болтают *фыркает*\n\n- Вон сколько про мои зубы было разговоров - и что? Да по брусчатке этих idioti пару раз протащить - и сразу станут повежливее, ахаха!",228055,null],[228074,"2026-09-21T14:22:36",22,"Ясмин ела крошащийся круасант и слабо улыбнулась, измазавшись кремом. \nПотом вдруг дернулась будто что-то увидела за спиной Биатриче.\n\n- П-понятно. Спасибо.",212725,null],[228075,"2026-09-21T14:22:37",17,"— Быть может вам помогут в нашем храме. Если это проклятье или злой рок. Я не слышал о таком никогда раньше.\n\nМарко не ел, вся эта напускная любезность, чтобы растопить первый лёд. Чтобы расследование шло быстрее. Но его ошарашила искренность еще пять минут назад незнакомки. Она с такой лёгкостью рассказывала о себе и о своей проблеме. \n\nМарко оценочно взгляднул на Беатриче, как ей эта история со злым глазом. И не найдя беспокойства подумал\n\n\"Искренность до добра не доводит. Сейчас, рядом нет людей, кто хотели бы навредить. Использовать это всё против неё, шантажировать или запугать. Но если бы попались другие люди...\"",228055,null],[228077,"2026-09-21T14:23:12",20,"- Вы синьорита не переживайте так сильно - глаза не глаза, а в Вальдории найдутся те, кто примет. Честью и правдой здесь можно заслужить себе доброе имя\n\n- Меня вот даже с клыками принимали... *Уже тише, вспоминая о Кристине*",212725,null],[228083,"2026-09-21T14:24:54",17,"— Всё же нужно помнить, что у вас есть родовое имя. Вы Висконти. Поэтому некоторые двери для вас уже сразу открыты. Иным, особенно приезжим тут куда сложнее.",212725,null],[228088,"2026-09-21T14:26:17",22,"Дамы, кажется мы тут что-то пропустили!\nЭто еще что за компания? Когда она только успела?\nЭй, мелкая, отвечай! Что ты делаешь в компании с псиной и комарихой?\n\nЯсмин скривилась, как от головной боли. Она быстро быстро доела еду и спряталась за вуалью, опустив голову вниз.",212725,null],[228122,"2026-09-21T14:38:42",20,"- В чем то вы правы, синьор Веньер. *Пожимает она плечами*\n- Имя семьи даёт преимущества, но и накладывает свой долг. Впрочем свой я несу вполне добровольно.\n\n- Ну а до приезжих...в этой гаване столько же местных мерзавцев, сколько и благородных душ, что привели сюда странствия. Уверена синьорита Ясмин ещё докажет чего стоит",228083,null],[228129,"2026-09-21T14:41:15",17,"Марко заметил как Ясмин снова спряталась за вуалью. На мгновение задержал взгляд на звенящих украшениях.\n\n\"Хочет стать незаметнее. Выходит наоборот\"\n\n— Сиора Ясмин, позволите один совет? Именно как от следователя\n\nМарко наконец взял чашку, но пить не стал\n\n— Если бы мне поручили найти вас в городе, я бы не спрашивал про цвет глаз\n\nКивнул на вуаль\n\n— Я бы спросил, не видели ли чужестранку, которая прячет лицо за звенящей вуалью. Такое люди запоминают.\nИногда пытаясь скрыть одну примету мы создаём другую. Куда более заметную\n\nМарко чуть пожал плечами\n\n— Но что хуже, чужие взгляды или ваш... злой глаз, решать разумеется вам. Я о таких вещах знаю слишком мало",228088,null],[228146,"2026-09-21T14:48:28",22,"- А кто сказал, что меня уже не нашли?\n\nКонечно нашли, детка\n\nГолос Ясмин стал очень холоден, она качнула головой, но цепочки не издали ни звука.\n\nМы всегда тебя находим\n\n- Ты смотришь лишь на ткань.  Я на тех, кто под ней. Я не прячусь, я не показываю. Это разные вещи.\n\nНо всегда даём тебе фору на побег\nИначе будет не так весело\nИхихи-хи-хи",228129,null],[228150,"2026-09-21T14:49:29",22,"Девушка встала из-за стола.\n\n- Думаю нам пора. Не стоит тратить время впустую. Верно?",212725,null],[228157,"2026-09-21T14:51:55",17,"Марко чуть прищурился. Холод в её голосе он отметил сразу.\n\n\"Уже нашли\"\n\nРасспрашивать \"Кто нашел\" Марко сейчас не стал.\n\n— Верно. Кузница напротив.",212725,null],[228180,"2026-09-21T14:57:45",17,"/ @QURTZZ мы готовы",212725,null],[228309,"2026-09-21T15:18:32",31,"Перекусив и познакомясь поближе, а заодно заронив семена подозрений друг о друге, вы пеесекаете улицу и подходите к кузне. Мастер Болен как раз закончил работу и заметил вас.\n\n- Чем то помочь могу?\n\nЕго голс звучал словно из бочки, низкий и раскатистый.",212725,null],[228516,"2026-09-21T15:58:57",17,"— Доброго дня, ученики сеньора Неро Фелини по вашему происшествию. Прошу вас, расскажите поподробнее, что у вас случилось?",212725,null],[228525,"2026-09-21T16:00:19",20,"/Синьор Болен? Неро Феллино передает привет🚬",212725,null],[228548,"2026-09-21T16:03:14",31,"И заточку под ребро/",228525,null],[228566,"2026-09-21T16:08:25",31,"- Ученики? Я думал, он агентов пришлет. Не уважает нас старый кошак... Ну ладно, раз уж пришли, то вам все расскажу. Короче, повадился к нам в кузни какой то урод ходить по ночам. Двери вскрывает без шума, ходит как призрак, ни один из стражей ничего не замечал. А самое странное что тащит то? Только клещи! Без разбору хапает, и хорошие, дедовские, и наши новодельные, и даже те что мы для смеха у людей покупаем. Ничем не брезгует, все клещи тащит. На днях залез в лавку Тига Золотого Уса, тот с драгоценными металами работает, у него всегда золото в работе. Золото не тронул, а клещи утащил. Там клещи смех один, только в лупу и разглядишь, а подиж ты, и их упёр. Вот такие вот у нас дела, господа ученики",228516,null],[228577,"2026-09-21T16:10:44",22,"- Так странно... Я было подумала, что он ворует из-за голода да худого кошелька.\n\nЯсмин грустно покачала головой. \n\n- Из какого материала были клещи? Мы можем осмотреться?",212725,null],[228584,"2026-09-21T16:12:06",31,"- Клещи как клещи, стальные в основном, высокоуглеродистые, чтобы жар держали. Смотрите все что хотите, всех оповестить можете, нам нечего скрывать. И работать скоро станет нечем, похоже, мда",212725,null],[228777,"2026-09-21T16:28:00",17,"— Золото оставил. Сталь как сырьё тоже не нужна. Старое, новое, большое, маленькое - всё равно. Значит нужны не какие то хорошие клещи. Нужны просто любые клещи.\n\n— Вопрос только зачем?\n\nМарко пролистал книгу мёртвых в поисках сведений и ритуале и проклятии которое заставляет приносить предметы определенного вида, ложки, чайники, пальцы, клещи.\n\n— Поведение слишком нелогично для обычного преступника. Причём он готов регулярно рисковать ради совершенно бесполезных экземпляров. Может быть проклятие - увидел клещи и обязан забрать. Тогда сам вор может быть жертвой этого проклятья",212725,null],[228808,"2026-09-21T16:32:31",22,"Ясмин осматривает рабочих и их места.\n\n Насколько активно они работают? Или без \"основного\" инструмента работа тормозится?",212725,null],[228813,"2026-09-21T16:33:19",22,"/r +6 внимание",228808,null],[228818,"2026-09-21T16:34:37",31,"Работа идет медленно, дварфы передают редкие клещи из кузни в кузню, строго отслеживаю из местоположение. Состояние Кузнецов можно описать как легкая паранойя",228814,null],[228821,"2026-09-21T16:36:48",20,"- Хм, может это какой-то начинающий профессионал? Поспорил по пьяни что условно сворует 101 клещей и не попадется *Беатриче задумывается*\n\n- А что, адакая проверка мастерства. *Она скрывает улыбку - есть что-то в этой истории...*\n- Эх, надо бы клещи раздобыть и как приманку оставить",212725,null],[228822,"2026-09-21T16:37:43",17,"— Сеньор Болен, почему вы не куёте новые клещи? Есть проблемы с сырьём?",212725,null],[228831,"2026-09-21T16:41:59",31,"- куем потихоньку. Только это не выход, опять воруют. А мы не любим работать бесплатно или для воров",228822,null],[228840,"2026-09-21T16:46:24",17,"— А есть кузницы которые не страдают от этого вора? Нам нужно сузить его область воровского промысла",212725,null],[228858,"2026-09-21T16:50:39",22,"- И с чего все началось? Когда начали пропадать клещи и помните ли вы что нибудь, что этому предшествовало?\n\nЛя какая важная дама. Язык выучила и ходит теперь, выпендривается\nЛоботрясы. Что только не придумают лентяи, лишь бы не работать.",212725,null],[228862,"2026-09-21T16:51:38",31,"- тут такое дело, что за ночь этот вор не более одной кузни вскрывает. Да, есть еще несколько что не пострадали, надо подсчитать, но там не более шести осталось. Клещи из этих шести уже по рукам ходят, вон сами же видите. Взаимопомощь у нас, гильдейская. Сегодня вообще планируем у каждой из кузен по сторожу посадить, потому как один на весь квартал не справляется, Вилли наш, он всю ночь ходит между кухнями с факелом, до все равно не ловит ворюгу",228840,null],[228864,"2026-09-21T16:52:24",31,"- да почитай недели две как началось. Ничего особенного не происходило, вроде как",228858,null],[228994,"2026-09-21T17:25:00",17,"— Я осмотрю ваши двери и замки. МОжет есть зацепка, как вор их вскрывает",212725,null],[228996,"2026-09-21T17:25:31",17,"Марко подходит и присаживается к замочной скважине в поисках чего нибудь необычного, зазубрины от отмычек например",212725,null],[228997,"2026-09-21T17:25:50",17,"/r d20+5+d4 Внимание",212725,null],[229005,"2026-09-21T17:27:07",31,"Скважина как скважина, царапин не видать. Или ты плохо видишь, хз",212725,null],[229009,"2026-09-21T17:36:26",20,"*Беатриче пока гуляет вокруг здания, прикидывая - если тут то и дело этот Вилли и стережет, у вора должен был быть какой-то маршрут чтобы его обойти и никому не попасться. Может он вообще заходил через окна? Или тут достаточно удобных мест где можно быстро забраться на крышу?*",212725,null],[229010,"2026-09-21T17:36:37",20,"/r d20+3 внимание",212725,null],[229016,"2026-09-21T17:38:56",31,"Ты видишь что окна закрыты решетками, крыши да, низкие, все таки кухни дварфовские, а они парни не высокие",229011,null],[229054,"2026-09-21T17:45:44",22,"Ясмин смотрит на лица дварфов. Кто из них всех выглядит наименее расстроенным?",212725,null],[229056,"2026-09-21T17:45:54",22,"/r +6 внимание или Проницательность",212725,null],[229065,"2026-09-21T17:47:28",17,"— Мда, похоже вор виртоз. Придется на живца ловить, точнее на клещи. \n\nМарко возвращается к Болену\n\n— Сеньор, если вор настолько рисковый. Можем ли мы к концу дня собрать все клещи из соседних кузниц и ювелирных ну хотябы к вам сюда?",212725,null],[229101,"2026-09-21T17:57:44",31,"Ничего не можешь прочитать по лицам, бороды мешаюи",229057,null],[229105,"2026-09-21T17:59:01",31,"Болен задумывается\n\n- ну мысль здравая на самом деле. Вы внутри засядете?",229065,null],[229108,"2026-09-21T18:00:26",17,"— Хм.. я думаю да",229105,null],[229109,"2026-09-21T18:01:06",31,"- добро. Ты тогда не будем собирать толпу, чтобы ворбгу не спугнуть. Будет просто как всегда Вилли ходить с факелом",212725,null],[229110,"2026-09-21T18:01:43",17,"— Ещё есть вопрос. А Вилли, надёжный ваш человек? Не может ли он быть причастен? Что скажете о нем?",212725,null],[229113,"2026-09-21T18:04:06",31,"- ну, Вилли у нас давно работает. Он парень хороший, только между нами, тормозной чуток. Служил в Хирде, потом по ранению списали, получил палицей по башке. Это не сказать что страшно, если ты в шлеме. А он без шлема был. Гу вот мы его и взяли, чтобы пугал ворбг грозным видом. Ну он и справлялся, до поры",212725,null],[229141,"2026-09-21T18:20:52",22,"- Звучит пока как самый адекватный план.\n\nКонечно адекватный, на большее то мозгов не хватило.\n\nБегают как слепые котята по цеху и только лапками машут.\n\nБЕСПОЛЕЗНАЯ ДЕВЧОНКА!\n\nГромко. Как же громко. Голова болит.\n\nЯсмин кивнула, одобряя план и пошатываясь прислонилась к стене, массируя виски.",212725,null],[229152,"2026-09-21T18:24:50",31,"До конца дня еще довольно долго, время едва за три часа дня перевалило. Будет сидеть в кузне как привязанные?",212725,null],[229217,"2026-09-21T18:39:30",22,"Когда девушке полегчало, она подняла голову.\n\n- Я схожу на рынок. Опрошу местных. Может кто-то что видел или им продавали кузнечные клещи в подозрительных объёмах. К заходу солнца собираемся здесь, верно?\n\nПравильно. Пора от них сваливать.\n\nИз темноты кузни на Ясмин посмотрели прищуренные глаза.\n\nОни тебе не товарищи, малышка.\n\nГлаза подлетели поближе.\n\nНикто не примет тебя, глупышка.\n\nГлаза все ближе. Они пытаются излучать любовь и заботу, но это выглядит слишком неестественно. \n\nНикто кроме нас.\n\nГлаза исчезают.\n\nДождавшись ответа \"коллег\" девушка направилась в сторону рынка.",212725,null],[229221,"2026-09-21T18:50:23",31,"По сути, весь Ремесленный город - это огромный рынок. Каждый дом здесь - это мастерская и лавка в одном лице. Впрочем, и мелкие продуктовые разыалы встречаются тут и там",229217,null],[229222,"2026-09-21T18:51:16",20,"- Эх, думаю схожу лучше с ней - мало ли кто может к такой bella пристать *Беатриче поправляет ножны и направляется за Ясмин*\n\n- А вы куда планируете, синьор Марко? С нами?",212725,null],[229223,"2026-09-21T18:54:29",17,"— Нет. Я хочу найти Вилли и опросить\n\nМарко закрыл книгу мертвых с громким хлопком\n\n— Сеньор Болен, где можно найти вашего ночного сторожа?",212725,null],[229224,"2026-09-21T18:56:07",31,"- да тут где то крутиться. Ща\n\nБолен набирает полную грудь воздуха и резко на выдохе орет\n\n- Виииииилиииииит!!!!!!!",229223,null],[229225,"2026-09-21T18:57:13",31,"На его крик чепущ пару минут пришаркивает дергангого вида дварф с глазами навыкате:\n\n- звали, шеф?\n\n- Звал. Вот, поговори с сыщиком",212725,null],[229228,"2026-09-21T18:58:04",31,"Ясмин т Беатриче тем временем оправились на разведку рынка. Куда именно вы хотите пойти?",212725,null],[229235,"2026-09-21T19:11:45",17,"— Добрый день. Давайте отойдем в сторонку и поговорим на едине.",229225,null],[229239,"2026-09-21T19:17:10",31,"Вилли с опаской косится на тебя, но отходит за кузню, где потише\n\n- чего вам, милсдарь?",229235,null],[229258,"2026-09-21T19:23:47",17,"— Что же ты Вилли, вора никак не схватить. Что ж тебе мешает? Или он невидимка?",229239,null],[229259,"2026-09-21T19:25:59",31,"- почему мне знать, может и невидимка. Я то его ни разу не видал. Я все делаю как сказали, беру факел, беру колокольчик, хожу от объекта до объекта, свечу и звеню",229258,null],[229261,"2026-09-21T19:29:48",17,"— Ну а что подозрительного видел пока ходил?",212725,null],[229263,"2026-09-21T19:31:24",31,"- видеть ничо не видел. Слышал что скребут, но может мыша это была",212725,null],[229265,"2026-09-21T19:33:27",17,"— Ну-ка попробуй припомнить самое странное на обходе и расскажи",212725,null],[229267,"2026-09-21T19:35:49",31,"Вилли напрягается, пытается вспомнить и выдаёт:\n\n- воняло сильно. Когда вскрыли кузню Бенжена, я это первый увидал. Подбежал, в свисток посвистел и почуял вонь, как от нужника. А Бенжен у нас самый аккуратный мастер, у него завсегда порядок",212725,null],[229270,"2026-09-21T19:36:57",17,"— Ну так и что воняло то? Нашли причину?",229267,null],[229271,"2026-09-21T19:37:17",20,"/Беатриче пойдет туда, куда Ясмин. Сопровождает даму)",229228,null],[229274,"2026-09-21T19:37:52",17,"— Может и мне сходить понюхать?",212725,null],[229279,"2026-09-21T19:39:52",31,"- ну я ж вам не запрещу, хоть все перенюхайте. Только выветрилось все. Я так думаю, это вор  где-то изгваздался. Али обосрался, когда понял что я близко\n\nНа последних словах Вилли приосанился, выпятил грудь, такой себе грозный воин, страх всех воров",229274,null],[229284,"2026-09-21T19:41:17",17,"/r d20+5+d4 Говорит правду или брешет? А может утаивает что то? Спал на посту?",212725,null],[229287,"2026-09-21T19:41:23",17,"/ Проницательность",212725,null],[229294,"2026-09-21T19:43:19",31,"Вилли на удивление честен. Он жутко боится тебя и потерять свое место. Он в глубине души понимает, что косячит и не подходит для этой работы, но это все что у него есть.",212725,null],[229299,"2026-09-21T19:45:48",17,"— Ты молодец Вилли. Вижу же, что доблестно службу несёшь. Как насчёт со мной вместе пойти сейчас в кузню Бенжена? Покажешь где там воняло. А ночью как обычно выйдешь на охоту за ворами. \n\nМарко по доброму постучал Вилли по плечу чтобы приободрить",212725,null],[229304,"2026-09-21T19:47:49",31,"Вилли робко улыбается.\n\n- конечно проведу, пойдёмте.\n\nВы добираетесь до кухни Бенжена. Хозяин занят какой-то подгонкой пластин в доспехе, он поднимает оа вас глаза, что то буркает и снова погружается в работу",212725,null],[229312,"2026-09-21T19:52:05",22,"Ясмин шла вперед. Она будто и не замечала, что Биатриче следует за ней.\n\nБеги, дитя, беги быстрее\n\nПодругу свою комариха доела. Как думаешь, почему она последовала за такой слабачкой, как ты?\n\nЯсмин нервно ускорила шаг.\n\nА она идет быстрее.\n\nЯсмин в ужасе перешла на бег, убегая от Биатриче. \n\nКого-то цапнут за бочок!\n\nУБИРАЙТЕСЬ ПРОЧЬ!\n\nВыкрикнула Ясмин, не сразу осознав, что это было вслух.\n\nДевушка прижалась к стене и сползла по ней вниз. \n\nПожалуйста, тише.. умоляю..\n\nЯсмин обхватила руками свои колени и стала делать глубокий вдох-выдох, отщелкивая в такт дыханию свои четки.\n\nЛекарство. Помнишь то лекарство? Оно обязательно поможет\n\n- Ле-кар-ство.. Н-нет! Я справлюсь. Б-беатриче?\n\nДевушка встала и пошатываясь побрела в сторону рынка. Крутя головой в поисках Биатриче.",229228,null],[229314,"2026-09-21T19:53:24",31,"Нормальный такой психоз описывается, одобряю. Главное чтобы ты не устала)/",229312,null],[229315,"2026-09-21T19:53:31",22,"//все ок, наконец то интересныц персонаж наклевывается",212725,null],[229329,"2026-09-21T20:01:13",31,"Ухожу спать/ если что будет, утром прочту и отреагирую",212725,null],[229349,"2026-09-21T20:16:30",20,"*Беатриче сначала вообще не поняла что от нее ну ... убегают. А когда поняла даже инстинктивно ускорила шаг, кладя руку на эфес и озираясь по сторонам. Что ее новую так испугало? Враг, какие-то мерзавцы из нижних районов?*\n\n*Она почти догнала девушку - довольно быстро, обычно людям не удавалось убежать от дампиров. Но крик Ясмин заставил ее слегка тормазнуть - она что *её* испугалась?*\n\n*Беатриче чешет затылок, наблюдая за убегающим силуэтом. Мда...кажется она так привыкла что ее окружение да горожане в целом спокойно относятся к ее природе, что забыла - Ясмин не местная. А вдруг и правда клыков испугалась?*\n\n- Merda...неловко получилось.\n\n*Она оглядывается, сходя с основной дороги и ловко забираясь на крышу ближайшего здания. Теперь следуя за Ясмин чуть издалека и сверху*\n\n*Пугать эту девушку дальше не хотелось, но и без сопровождения в Вальдории там юным красавицам лучше не гулять...*",229312,null],[229396,"2026-09-21T21:09:08",22,"Ясмин крутила головой как котенок, потерявший маму.\n\nЕё нет. Ушла?\n\nКакая же ты никчемная пустышка! Даже вампироска решила держаться от тебя подальше.\n\nБестолковая.\n\nНЕПРАВДА! Я.. Я просто убежала далеко вперед..\n\nВозвращайся домой. В семью. Семья ждет тебя.\n\nЯсмин сжала руки в кулаки и стиснула зубы.\nНу и пусть они все держатся подальше. Плевать. У меня есть цель, начну с ближайших лавок.\n\nПомни Ясмин. \nТы сильная, красивая и уверенная девушка! \nСурья, спрячь меня!\n\nДевушка шумно вдохнула и сняла вуаль. Ее лицо сияло солнечным светом, постепенно утихая. Спустя несколько секунд, на ее лице больше не было ни единого изъяна и даже глаза стали одинакового орехового оттенка. А волосы девушки наполнились ярким ароматом корицы и имбиря.\n\nСемья всегда будет ждать тебя, дитя.\n\nЯсмин вышла из переулка и подошла к одной из ближайших лавок, широко улыбаясь.\n\n- Добрый день, сэр! А что у вас сегодня самое свежее? Я как раз ищу, чем можно перекусить перед долгой прогулкой! - дождавшись ответа продавца, девушка чуть поддалась вперед. - А вы слышали, у дварфов украли все щипцы. Даже не один инструмент, а именно все щипцы! Весь город только об этом и говорит! Как вообще кому-то могла понадобиться такая коллекция?\n\nУслышав ответ продавца и купив пару безделушек, Ясмин направилась к следующему.\n\nЧас, у меня не больше часа, нужно действовать быстро.\n\n- Приветствую, мадам! Эти ткани просто невероятны на ощупь! И такие теплые! И как вам только удалось найти столь отменного поставщика?! - испуганно олянувшись, Ясмин чуть поддалась вперед. - Мне сказали, что вы здесь знаете больше всех местных новостей. Надеюсь, это не клевета, потому что у меня как раз есть один очень странный вопрос....\n\n*В том же духе Ясмин продолжает вести опрос населения на предмет текущей проблемы. Примерно раз в 30-40 минут Ясмин отбегала в темный переулок, где какое-то время просто стояла, прислонившись лбом к прохладному камню. Вспышка света и вновь дева возвращалась на улицы с широкой улыбкой и нормальными глазами*\n\n//немного не знаю по расценкам, но хотела бы в ходе опроса также покупать мелочевку: пирожки с мясом, простые детские игрушки, теплые ткани. Думаю, что 5 золотых хватит с головой, но прошу поправить, если ошибаюсь.",212725,null],[229415,"2026-09-21T21:53:48",17,"/ Щипчики для бровей. Дварфийские. Все украли!)",212725,null],[229500,"2026-09-22T04:56:07",31,"Ясмин, совершая практически героический для интроверта поступок, тратит за час 5 золотых монет. Беатриче, нааблюдающая за ней с крыши, только качает головой, оценивая насколько же ее развели ушлые продавцы, товаров она набрала хорошо если на две монеты, и даже не торговалась.\n\nЯсмин узнала за эти деньги: над дварфами и правда все смеются; предлагают ковать огромные мышеловки для отлова вора; кто то утверждает что это происки темных сил; кто то сказал что слышал топот мелких ног, словно ребёнок бегал у кузнец; кто то опасается что тамнсвенный вор после разорения Кузнецов примется за иную добычу, может деревянные башмаки таскать начнет; кто то говорит что это все не к добру; кто то злословит на конкурентов из Гномьей гильдии Кузнецов; местный алкаш божится что это все зеленые черти; тип с хитрыми глазами заявляет что уважает дварфов за из зитрость в деле обмана страховщиков.\n\n//Ты можешь пробросить проверку мудрости, чтобы отсечь часть точно не верных слухов, или можешь сама логически подумать. Тут есть зацепки, но есть ложные следы и просто фоновый шум и побасенки//",229396,null],[229501,"2026-09-22T04:56:44",31,"Для бороды же/",229415,null],[229502,"2026-09-22T05:47:43",31,"Беатриче, путешествуя по крышам, краем глаза замечает каких то мальчишек на крыше неподалек от кузни мастера Болена. Они возятся со стеклянными бутылками",229349,null],[229503,"2026-09-22T06:48:55",22,"/r +6",229500,null],[229505,"2026-09-22T06:49:32",22,"//это заявка не все, я опишу дальнейшие действия но часа через 2 примерно\nНе зря же набор покупок был именно такой",212725,null],[229506,"2026-09-22T06:51:41",31,"Ок. Тебе сейчас дать реакцию на проверку мудрости, или подождать?/",229505,null],[229507,"2026-09-22T06:54:37",22,"//давай\nИ напоминаю, эта барышня не совсем дурочка же. Она 12 лет по миру шатается и как-то выживает",212725,null],[229508,"2026-09-22T06:55:26",31,"Ну по уровню мудрости видно)",229507,null],[229509,"2026-09-22T06:59:45",31,"Очевидно, все злословие вроде смеха, мышеловок и деревянных башмаков это просто досужие разговоры. \n\nТы выделяешь как достойные рассмотрения версии про мужлеж со страховкой и происки конкурентов гномов.\n\nТакже тебя заинтересовал рассказ о детском топоте у кузен\n\nАлкаш с зелеными чертями диво как убедителен, харизматичный мужик. Ты не знаешь, верить или нет",229504,null],[229519,"2026-09-22T08:11:23",20,"/r -d20+5 скрытность",229502,null],[229521,"2026-09-22T08:11:59",20,"*Беатриче тихонечко подходит к ним со спины, наблюдая за тем что они делают*",212725,null],[229523,"2026-09-22T08:13:20",17,"— Сеньор Бенжен, поделитесь о вашем происшествии, расследуем дело по поручению Неро Фелини. Вилли сообщил о каком то неприятном запахе после того как вор тут побывал?",229304,null],[229534,"2026-09-22T08:21:49",31,"Мальчишки тебя не замечают, увлеченно обсуждая какую бутылку лучше засунуть в трубу. Упомянутая труба лежит рядом.\n\n- Лучше взять темную, чтобв глаз не обжечь!\n- так нам не на солце смотреть же, ты совсем дурак?\n- да, вчера же пробовали темное стекло и ничего не видно было\n- так ты не на небо смотрел, а на огонь в кузне!\n- так я же не дурак чобы сразу в небо смотреть, надо же эта, настроить, и чтобы глаз привык",229521,null],[229536,"2026-09-22T08:23:44",31,"- запах? да, был. Как канализацию прорвало, ядреный такой. Это ворюга неследил, я потом след видел. Маленький такой, словно детский. Уж не знаю где он лазил до того",229523,null],[229540,"2026-09-22T08:26:14",17,"— Может это разновидность так называемого в профессиональных кругах \"Сартирного воришки?\" Где у вас тут нужник?",212725,null],[229541,"2026-09-22T08:27:37",31,"- ну, дак у ккжой кузни свой... Ежели приспичило, то вон там дверь, зайдите",229540,null],[229577,"2026-09-22T08:52:16",22,"Детский топот значит... ладно, соберись, Ясмин, еще куча дел!\n\nДетишки? Она только что подумала о детишках?\n\nШироко распахнутые золотые глаза появились прямо перед Ясмин, от чего девушка опешила и отшагнула назад.\n\nДетишки это весело. Детишки это вкусно!\n\nЯсмин мотнула головой и, накрыв голову вуалью, поспешила в темный переулок.\n\nПопробуй! Обязательно попробуй!\n\nГлаза за Ясмим не последовали, они подмигнули и исчезли.\n\nСвет милосердный, дай мне сил!\n\nДобравшись до спасительной темноты, Ясмин села, уткнувшись лицом в колени и шумно дышала. Спустя четверть часа, девушка привела свои мысли в чувства.\n\nОна медленно сняла вуаль и стала приводить свое сари в порядок, сменив яркую шифоновую антию на более замызганную темно-зеленую льняную. Которая была больше простым куском ткани, нежели антией, но Ясмин хватило и этого. Поверх павады же, нижней юбки, она повязала платок со зверящими цепочками, что ранее служил ей вуалью. \n\nВолосы сплелись в  тугой пучок, а глаза стали тёмно-коричневыми, почти чёрными, типичными для всех южан. Ясмин провела пальцами по кирпичной кадке и вытерла их о свои руки и лицо.\n\nДевушка чуть сгорбилась и, подхватив свою корзину с покупками, направилась в сторону бедного района, где бегает много сирот и мать-одиночек с уставшим и потерянным взглядом.",212725,null],[229578,"2026-09-22T08:52:22",22,"//диалог чуть позже пропишу, как только до работы добегу",212725,null],[229580,"2026-09-22T08:53:30",31,"работа под прикрытием, круть)/",229577,null],[229582,"2026-09-22T08:55:17",22,"//там типа образ странствующей цыганки, но у меня очень сильно болит голова, поэтому без артов сорян\n\nТак то бедное и необразованное население больше всех уязвимо к мистике, чем Ясмин и пользуется внаглую",212725,null],[229584,"2026-09-22T09:06:46",17,"— Сеньоры, вы уж не отвлекайте меня от поиска улик. Возможно это место проникновения нашего вора, мне нужно вдумчиво изучить все мельчайшие улики.\n\nДостаёт Liber Mortis и раскрывает на чистой странице. Небольшим кинжалом колет большой палец и кровью выводит знакомый глиф глаза Анубиса. Книга впитывает кровь почти сразу.\nМарко закрывает глаза на несколько секунд. Когда открывает снова, в зрачках появляется слабое золотое свечение\n\n/Ритуал обнаружения магии\n\nКровь продолжает медленно выступать из прокола.\n\nМарко машинально лезет во внутренний карман пальто и достаёт старый платок.\n\nБелая ткань давно стала сероватой от времени. По краям идут неровные стежки разноцветных ниток. Где-то слишком частые, где-то между ними остаются огромные промежутки. Получилась кривая хаотичная рамка, которую могла вышить только детская рука.\n\nВ самом низу такими же неровными буквами\n\n\"Папе\"\n\nМарко несколько секунд смотрит на надпись.\n\nОсторожно вытирает кровь чистым углом, не задевая вышивку.\n\nПлаток складывает по старым сгибам и сразу убирает обратно во внутренний карман.\n\n— Посмотрим, чего здесь быть не должно.\n\nМарко начинает методично осматривать помещение от двери дальше внутрь",229541,null],[229585,"2026-09-22T09:06:57",17,"/r d20+5+d4 Внимание",212725,null],[229588,"2026-09-22T09:13:32",22,"Одно движение руки и яркий аромат мясных пирогов начинает расходится от корзинки.\n\nЯсмин неспешно подошла к группе женщин, присела рядом с ними и обратилась к ближайшей.\n\n- Ой вэй, красавица! А ну грусти, золотач моя! Дай-ка руку, взгляну на твои линии... \n\nПосмотрите на нее! Как шабашу служить, так ни в какую. А как силы наши разбазаривать, так пожалуйста!\n\nЯсмин берет один из пирогов и выручает женщине, потянув на себя ее правую руку. \n\n*цокает*\n\n\n- Линия жизни долгая, а вот линия удачи уперлась в холодное железо. Ой вэй... Железо? Воровство? У дварфов же клещи пропали! Весь город судачит на вас, бедных людей! \n\nЯссмин качает головой.\n\n- Айя-яй! Нечестно это. Давай помогу очистить твое имя. Вспомни, чьи чужие ноги ходили вокруг кузни последние две недели? Кто с железным звоном в мешке проскальзывал мимо? Иль у пацанов своих шустрых спроси, да товарок своих!\n\nБыстро задавая эти вопросы, Ясмин не выпускала руку женщины, но при этом ловко раздавала пироги да игрушки, пристально смотря каждому в глаза, ожидая ответов.\n\n- И о топоте детском расскажи.. судачат тут всякие.\nШепотом добавила девушка",212725,null],[229593,"2026-09-22T09:20:06",31,"Отойду по работе, может на час примерно или больше. Вернусь - отвечу/",212725,null],[229596,"2026-09-22T09:28:51",20,"*Беатриче подходит ещё ближе, наблюдая за действиями мальчишек*\n\n- Ну ежели на небо смотреть то тут сразу несколько стёклышек линз понадобится *увлеченно замечает она, как будто все время тут стояла*\n- А то из-за преломления изображение будет вверх тормашками.\n\n- Cannocchiale - прямо как то, что используют отважные капитаны, ходящие по морям, смотря на далёкие земли и звёзды.",229534,null],[229607,"2026-09-22T10:29:41",31,"тут чисто, почти как в операционной. Видимо, слава Бенжена как аккуратиста не так и надумана. Ты не находишь чего либо выделяющегося",229586,null],[229608,"2026-09-22T10:30:18",31,"убеждение кинь/",229588,null],[229610,"2026-09-22T10:32:25",31,"Мальчишки резко разворачиваются к тебе\n\n- ого, вы знаете  что это? А откуда знаете как надо делать? Мне вот папка рассказал (это говорит ребенок-гном, совсем крохотный на фоне двух оварищей явно людского племени)",229596,null],[229613,"2026-09-22T10:35:40",22,"/r +3",229608,null],[229615,"2026-09-22T10:35:47",17,"\"Хм... Ничего. И Следов магии тоже. Тупик\"\n\nНичего необычного или интересного не было найдено и Марко слегка разочарованный вернулся к дварфам\n\n— Никаких следов проникновения. Сеньор Бенжен, вас уже сообщили, что планируем сегодня засаду на вора. Соберем все клещи у сеньора Болена к вечеру. Вы поможете поймать злоумышленика?",212725,null],[229616,"2026-09-22T10:35:55",22,"//с преимуществом же? Я их кормила",212725,null],[229620,"2026-09-22T10:37:00",20,"- Ну как откуда - в гаване со всех краев народ стекается, там и не такое увидишь. Да и брат мой младший слегка на вас похож - тоже этим грезит *посмеивается девушка*\n\n- Как начнет болтать - не остановишь. Все о землях за морем да о звёздах. *Ее улыбка смягчается, когда она вспоминает мелкого.*\n\n- А вы зачем пытаетесь такое собрать?",229610,null],[229622,"2026-09-22T10:37:58",31,"можешь/",229616,null],[229624,"2026-09-22T10:38:50",22,"//ненавижу кубы",212725,null],[229626,"2026-09-22T10:39:11",31,"мы хоитим посчитать звезды! только пока мощности не хватате - расстроеный гноменок отвечает тебе - только вблизи и видно",229620,null],[229629,"2026-09-22T10:39:41",17,"/Убежала от вампирши помошницы)",229624,null],[229630,"2026-09-22T10:40:28",31,"женщина вырывает свою руку из твое и со злобой заявляет \n- а ну пошла прочь! мои мальчики ничего не сделали, а будешь еще тут выспрашивать, ищейка чертова, сама тебе волосья повыдергаю!",229623,null],[229631,"2026-09-22T10:41:17",31,"- да мне отдавать нечего, сам из милости в дар принял клещи от Болена. Ну, вечером занесу ему конечно",229615,null],[229632,"2026-09-22T10:43:53",22,"ОТВЕЧАЙ. УБОГОЕ ТЫ СОЗДАНИЕ.\n\nспас мудрости сл 14",229630,null],[229633,"2026-09-22T10:44:05",22,"Приказ",212725,null],[229634,"2026-09-22T10:45:08",22,"Голос девушки изменился на глубокий, гортанный, будто принадлежавший другому существу.\n\nГлаза стали обычными. Один золотой, ярко разгорелся.",212725,null],[229635,"2026-09-22T10:46:59",22,"//вы же не думали, что Ясмин всю игру будет девой в беде.. Она хоть и наполовину, но все же карга.",212725,null],[229636,"2026-09-22T10:46:59",31,"/roll d20-1",229632,null],[229638,"2026-09-22T10:49:36",31,"Женщина падает на колени, дрожит от ужаса, в глазах животный страх и полное отстутствие воли к сопротивлению:\n\n- ничего не знаю... мальчики бегают, в сыщиков и воров играют... может хотели сами дварфского вора поймать....\n\nЗаливается слезами",212725,null],[229639,"2026-09-22T10:54:10",22,"Ясмин неестественно поворачивает голову в сторону мальчишек.\n\nХриплым, каркающим голосом она говорит\n\n- Ах какие вы сорванцы, внучата, помогите матушке, расскажите, что знаете.",212725,null],[229641,"2026-09-22T11:04:23",20,"- Хм... *Беатриче осматривает этот самодельный телескоп*\n\n- Думаю если сделать подходящие линзы, да вот тут зеркальце вставить небольшое...*Она искренне начинает прокручивать в голове, как бы помочь мальчишкам - уж очень они ей братишку напоминают, не может пройти мимо*\n\n*Потом вспоминает*\n\n\"Точно, яж тут расследованием занимаю. Может совместить?\"\n\n- А давайте так - я помогу вам а вы мне. Тут в последнее время завелся вор, клещи таскает из мастерских по ночам - а вы как раз рядом крутитесь - может видели чего важного. Расскажите - а я поговорю с мастерами, может смогу вам материалы какие получше достать. За помощь следствию.",229626,null],[229642,"2026-09-22T11:05:12",31,"Один из пацанов обмочился, увидев такое зрелище, второй подобно матери упал на колени, а затем свернудся клубком. Ьретий, постарше, смотрит на тебя огромными глазами, и выдавливает:\n\n- таааам... гоблин там бвл, мы видели гоблина... он убегал с железякой...",229639,null],[229645,"2026-09-22T11:07:22",31,"- мне папа говорил, чтобы ничего у дварфов не брал. Они кан-ко-рен-ты - продолжает малыш-гном. - да мы и атк поможем, спрашивайте\n\nПарни преисполнены в желании помочь девушке. слишком мелкие чтобы заинтересоваться ей как девушкой, но достаточно взрослые чтобы что то соображать об окружающем мире",229641,null],[229657,"2026-09-22T11:11:22",20,"- Замечали кого-нибудь кто ходит по ночам, кроме сторожа? Может видели следы какие подозрительные? И не пропадало ли чего из мастерской твоего папы?\n\n*Беатриче перечисляет вопросы, которые приходят ей в голову. Эх, сюда бы того следователя - может и что-то более конкретное спросил*\n\n/А ещё хочет припомнить есть ли тут гномьи мастерские",229645,null],[229658,"2026-09-22T11:11:29",22,"- Вот и славно, внучек, кушай кушай пирожок.\n\nЯсмин встала и направилась прочь из переулка. Пока она шла, ее тело неестественно скрючилось, спина выгнулась, будто на ней горб, а голова была повернута в бок.\n\nИхихи-хи-хи \n\nСлавно славно сестра\n\nВ темноте появилось несколько пар золотых глаз.\n\nХахаха было весело\n\nЧТО ЭТО БЫЛО?!\n\nНаша сила, конечно же. Дурочка. Но тебе ведь понравилось?\n\nНЕТ!\n\nКонечно понравилось, врушка...\n\nЯсмин отошла поглубже в переулок и вжалась в стену. Девушку пробила сильная дрожь. В глазах стояли слезы, а горло разрывалось от боли.\n\nЕй действительно понравилось..",212725,null],[229668,"2026-09-22T11:16:33",31,"Гномьи мастерские и кузни есть, это конкуренты дворфам, но гномы больше по тонкой работе и мехнике, но бывают и куют что то. (чисто твое знание как дочери купеческой семьи)\n\n- ну, вообще да, мы не говорим дварфам, но знаем кто тут лазит. Это мелкий такой зеленый гоблин. Он хитрый, ждет пока сторож уйдет в дальнюю сторону, а потом к двери подходит и что то быстро там делает, открывает и заходит. потом опять ждет чтобв сторож прошел и ушел, и тихонько убегает кудато то туда \n\nмальчишка махает в сторону порта\n\n- и папа не говорил что у него что то пропало. я ак думаю, это гоблин просто не дошел до наших мастерских, мы же дальше по улице, а он от порта ходит",229657,null],[229679,"2026-09-22T11:24:26",20,"- Вот оно как? Grazie, ragazzi. *Беатриче улыбается, потрепав их по голове и вставая.*\n\n\"Гоблин, ходит от порта...вроде запомнила, нужно передать синьору Марко.\"\n\n- Ну чтож, дела не ждут. *Она уже хочет пойти, но тормозит*\n\n- Ах, где мои манеры *она слегка театрально кланяется - не как обычно, а шутливо и легко, но все ещё искренне*\n- Я, Беатриче Висконти да Вальдрио, от лица моего дома благодарю вас, piccoli signori, за помощь. \n\n*Выпрямляется, подмигнув им на прощание*\n\n- Назовите свои имена, ведь дом Висконти всегда помнит тех, кто им помог\n\n*Надо будет навестить этих шкетов как ни будь с гостинцами*",229668,null],[229694,"2026-09-22T11:49:56",31,"тройной неуелюжий поклон",229679,null],[229708,"2026-09-22T11:57:33",22,"Примерно спустя час, Ясмин успокоилась.\n\nДрожащими руками она постаралась зафиксировать на лице вуаль.\n\nКого я пытаюсь обмануть...\n\nСебя, дорогая\n\nВуаль дрогнула и со звоном упала в грязь.\n\nЯсмин безэмоционально смотрела на эту грязную тряпку, что служит ей щитом в этом мире. Девушка опустилась на колени, прижала к груди мокрую вуаль и тихо заплакала.\n\nСоберись, размазня. Ты должна держать себя в руках. \n\nЯссмин почистила вуаль и вновь надела ее. Пора направиться туда, где видели гоблина.",212725,null],[229809,"2026-09-22T12:24:03",17,"Марко направился на рынок куда ушли его напарницы. Возможно им улыбнулась удача. У него совсем не было новой информации.",212725,null],[229847,"2026-09-22T12:27:57",17,"/ Собираемся в кучку? Или у вас еще есть идеи для соло отыгрыша?",212725,null],[229851,"2026-09-22T12:28:48",22,"/я готова собираться",212725,null],[229854,"2026-09-22T12:29:14",20,"/аналогично",212725,null],[229855,"2026-09-22T12:29:46",31,"тогда болтайте и обсуждайте, я уже сейчас домой поеду, буду не очень доступен пару часов/",212725,null],[229860,"2026-09-22T12:31:02",17,"По дороге он привычно отмечал происходящее вокруг.\n\nТелега перегородила половину улицы. Возница ругался с торговцем рыбой.\n\nУ лавки растовщика слишком хорошо одетый мальчишка слишком долго крутился возле чужих карманов.\n\nДвое грузчиков несли ящик, на котором было написано \"осторожно\", обращаясь с ним именно так, как обычно обращаются с вещами с такой надписью\n\nМарко проводил их взглядом\n\n\"Не моё дело\"\n\nЧем ближе был рынок, тем плотнее становилась толпа.\n\nУ одного из лоточников среди старого железа лежали ржавые клещи. Марко остановился на пару секунд. Обычные. Старые. Судя по ржавчине несколько месяцев никому не нужные.\n\n\"А тут лежат себе...\"\n\nНапарниц Марко начал искать ещё издалека, высматривая в толпе знакомую вуаль и Беатриче, которую скрыть среди прохожих было несколько сложнее",212725,null],[229877,"2026-09-22T12:36:50",20,"- О, вот вы где синьор Веньер!\n\n*Беатриче буквально свалилась ему как снег на голову, внезапно спрыгнув к нему прямо перед лицом с одной из крыш*\n\n- А я вас как раз везде ищу. Удалось выискать пару интересных фактов! *Явно горда собой, подобная работа для нее впервые*\n\n- Ох, а где кстати наша bella Ясмин? Упустила ее из вида около часа назад... *оглядывается*",212725,null],[229914,"2026-09-22T12:50:08",17,"— Я думал вы пошли вместе сиора Висконти. Прошу вас, поделитесь, что узнали. У меня тупик. Вонючий запах оказался возможно дварфийской шуткой.",212725,null],[229963,"2026-09-22T13:05:23",20,"- Местные мальчишки видели, как по ночам тут от порта ходит гоблин - он и проникал в мастерские, вскрывая замок, подождав момента пока сторож уйдет в другую сторону. У гномьих мастеров пока ничего не пропадало - возможно потому что они чуть дальше от порта",229914,null],[229964,"2026-09-22T13:07:27",22,"В одном из переулков вы замечаете алое сари Ясмин.",212725,null],[229986,"2026-09-22T13:50:22",17,"— Ого, это замечательно. Вы прирождённая сыщица, сиора. \n\nВ переулке замечает Ясмин\n\n— А вон там кажется наша напарница. Давайте узнаем как её успехи.\n\nНаправился в переулок дружелюбно махая рукой\n\nЗа алым сари было тяжело разглядеть лицо девушки, особенно издалека",212725,null],[230020,"2026-09-22T14:14:04",20,"*Беатриче облегчённо выдыхает - ну, их новая знакомая вроде в порядке. А то она чувствовала лёгкую вину что оставила даму без сопровождения, отвлекшись на мелких шкетов*",212725,null],[230125,"2026-09-22T14:47:35",22,"Ясмин заметила \"коллег\".\n\nОни следили за мной?\n\nКонечно следили, тебе же нельзя доверять\n\nТихо зазвенела вуаль, когда Ясмин повернулась в вашу сторону.\n\n- Бедняки говорят, что тут рыскает зелёный гоблин с какими то железяками. Может он и есть наш воришка? \n\nГолос девушки был тихим и хриплым. Она склонила голову набок, вуаль чуть сползла, открывая подборок и губы. Ее губы были бледные и прокусанные до крови.\n\n- А у вас как успехи?",212725,null],[230134,"2026-09-22T14:50:47",17,"Марко закрыл глаза немного грустно\n\n— У меня ничего.",212725,null],[230139,"2026-09-22T14:51:44",20,"- Ну, тоже свидетельства о гоблине *Беатриче слегка наклоняет голову набок, рассматривая девушку*\n\n- Сеньорита, у вас все в порядке? Никакие bastardi ведь не смели к вам приставать, пока нас не было? *спрашивает она с подозрением, видя бледность и искусанные губы*\n- Только скажите - они ответят за свое невежество!",230125,null],[230142,"2026-09-22T14:52:55",20,"/Беатриче чисто - \"дайте мне уже повод кого-то отпиздить🥺\"",212725,null],[230147,"2026-09-22T14:54:24",22,"- Нормально. Тут просто очень жарко. \n\nНасмехаются\nЖалкая\n\n- Давайте поспешим, может и не придётся делать засаду, если найдём воришку раньше. \n\nРАСИСТ!\nЕще не поговорила с гоблином, а уже осуждает\nЛИЦЕМЕРКА!",212725,null],[230161,"2026-09-22T14:56:55",31,"Жди/",230142,null],[230195,"2026-09-22T15:02:02",20,"- Ну, раз вы настаиваете... *Беатриче пожимает плечами, решая не лезть с расспросами к даме*\n\n- Ну что, дождемся ночи и будем караулить? Можно конечно попытаться его и сейчас поймать, но ведь он не единственный гоблин в городе, особенно если из района доков. А более подробного описания кроме расы у нас нет",230147,null],[230215,"2026-09-22T15:05:04",17,"— До вечера еще долго, мы могли бы понаблюдать и порасспрашивать в порту людей. Быть может, кто то его видел.",212725,null],[230222,"2026-09-22T15:09:28",22,"- Хорошо, давайте прежде изучим порт. Эти твари..божьи обычно проживают крупными семьями. Если такая семья в порту завелась, то нам точно смогут подсказать.",212725,null],[230253,"2026-09-22T15:13:25",17,"— Зачем гоблинам клещи?",212725,null],[230287,"2026-09-22T15:20:33",20,"- Все ещё склоняюсь к тому, что это либо наспор, либо его прокляли и теперь он может воровать только клещи",230253,null],[230315,"2026-09-22T15:29:05",22,"- Либо их кто-то подговорил. Работа то встала.",212725,null],[230365,"2026-09-22T15:43:59",17,"— Кстате. Очень интересная версия, мотив может быть у конкурентов дварфийской артели. Но я не знаю, кто у них конкуренты. Можно пойти и узнать",212725,null],[230375,"2026-09-22T15:45:16",20,"- О, так это гномьи мастерские. Хотя они больше по тонкой ювелирной работе.",230365,null],[230415,"2026-09-22T16:03:11",22,"- Но ювелирную мастерскую тоже грабили. Оставив золото не тронутым.",230375,null],[230420,"2026-09-22T16:07:09",20,"- А, я имела ввиду что конкуренты дварфов - гномы, больше специализирующиеся на ювелирном деле. *Беатриче чешет затылок, пытаясь объяснить свою мысль*\n\n- У гномов ещё ничего не воровали. Но если бы они хотели избавиться от конкуренции дворфов в ювелирном деле разве не логично тогда было похищать инструменты для него, вроде лобзиков и штангенциркулей, а не грубые клещи, не подходящие для тонкой работы?",230415,null],[230463,"2026-09-22T16:15:48",22,"- Хм.. логично, версия звучит очень неплохо. Попробуем что нибудь узнать в порту",212725,null],[231230,"2026-09-23T04:32:00",31,"Как придете к решению о дальнейших планах - тегните/",212725,null],[231236,"2026-09-23T06:47:30",22,"@QURTZZ в порт решили идти же/",212725,null],[231237,"2026-09-23T06:48:20",31,"ок. сейчас дам сцену/",212725,null],[231238,"2026-09-23T06:48:45",31,"Я просто не всегда понимаю что решенеи есть, лучше пинайте/",212725,null],[231239,"2026-09-23T06:56:40",31,"День начинал уже клонится к вечеру, тени удлиняться, а вы отправились в портовый район. Идти пришлось недолго, пара переулков и вот вы уже выходит на портовую площадь. Тут шум и гам в любое время суток, корабли приходят и уходят постоянно, тут толчея, идет разгрузка и погрузка, кто то что то роняет, кто то что то тащит, все куда то спешат. \n\nИтак, вы на портовой площади. Вы стоите рядом с большим зданием таможни, напротив, на берегу, самые лучшие пирсы для самых ценных клиентов, через площадь от вас таверна \"Золотой Нарвал\", где квартирует Ясмин. Возле таможни скучает пара стражников. Огромный галеон разгружается на пирсе. Люди разной степени сомнительности наполняют площадь.",212725,null],[231242,"2026-09-23T07:17:49",17,"/ Кажется мы попали в песочницу )",212725,null],[231243,"2026-09-23T07:34:40",31,"сами пошли, я не виноватый/ я был рад что вы решили засаду устроить, но раз уж желаете активничать)) хотя пофиг, все равно вышли на финиш арки почти/",231242,null],[231251,"2026-09-23T07:41:55",22,"Ясмин подходит к двум уже хорошо знакомым стражникам.\n\n- Отто, Виктор, а вы все стойко несёте на себе груз ответственности за нашу безопасность. Спасибо вам. Да прибудет с вами свет.\n\nЯсмин сложила руки в молитвенном жесте. Браслеты мелодично звенели, а воздух напитался ароматом амбры и чёрного перца.\n\n- Слышали же о дварфах и их \"проблеме\"? Весь город судачит! Марта, та что тканями торгует, говорила о каких-то зелёных коротышках, говорит, что уверена и это они приложили свои лапы.\n\nНу понеслось.\nОй, смотри, и эти слюну уже пускают.\n\nЯсмин замешкалась.\n\n- А вы случаем не знаете, что о местных гоблинах? Хочу докопаться до правды.",212725,null],[231252,"2026-09-23T07:42:05",22,"//блин, рассинхрон😅",212725,null],[231257,"2026-09-23T08:05:17",17,"Марко слегка удивился\n\n\"Ясмин кажется застенчивой и скрытной, но как только доходит касается интересного поручения, вроде расследования, бегом бежит во все тяжкие. Что это? Альтруизм? Или любопытство и азарт? Занятно.\"",212725,null],[231273,"2026-09-23T08:58:15",31,"откуда ты их узнала?) я не придираюсь, просто интересно)/",231251,null],[231274,"2026-09-23T09:03:15",22,"//Я предположила, по описаниям, что Ясмин тут уже несколько дней. Она привыкла быть одна и понимает, что лучшее поведение для нее - быть всегда на глазах и вести себя настолько дружелюбно, насколько это возможно.\n\nОна одновременно и хочет нести добро(исцеляя и подкармливая бедных) и быть любимой/уважаемой, а не просто полезной.\n\nГрубо говоря, в эмоциональном фоне у нее глубокая пустота, которую она пытается заполнить суррогатным общением. Поэтому Харизма +1",231273,null],[231275,"2026-09-23T09:09:42",31,"Отто привтеливо улыбается:\n\n- о, здравствуйте госопжа Ясмин. Нет, про дварфов ничего не слышалм, вы же их знаете, они не особо откровенничают, тем более со стражей. В что до гоблинов - в вороватости этих вонючек я не сомневаюсь. Н площади их нету, мы гоняем, но вроде как есть у них логова в старых складах, чуть западнее. Там небезопасно для людей, крыши прохудились и древоточец стены пожрал. Оттуда всех купцов погнали пару лет как, а ремонта не сделали, Магистрат все не выделит денег. Вот там говорят зеленые и устроили логово. Так то они в городе безобидные, в основном воруют, но всеж таки юной девушке лучше к ним не соватся",231251,null],[231286,"2026-09-23T09:18:39",22,"- Ох, Отто,\n\nЯсмин прижала руки к груди и склонила голову.\n\n- Ваше благородство и забота трогают меня до глубины души. Спасибо вам за службу, и да прибудет с вами свет. \n\nЯсмин дотрагивается до плеча приветливого стражника.\n\n/указание/\n\nВоздух наполнился лёгким ароматом жасмина и горьковатыми нотами розмарина.\n\nОпять вонючку свою развела\nОтвратительно. Ни вкуса, ни таланта.\nЖалкая\n\nЯсмин еще раз кивнула стражнику и вернулась к товарищам, передавая им информацию о местонахождении гоблинов.",212725,null],[231289,"2026-09-23T09:27:42",17,"— Отличная работа. У вас талант добывать нужную информацию. Что же, пойдем прямо в логово гоблинов или вернёмся к плану с засадой?\n\nМарко улыбчиво рассматривал лицо Ясмин запоминая особенные детали",212725,null],[231292,"2026-09-23T09:35:27",22,"- Солнце уже близится к закату. Думаю, что будет лучше сейчас отдохнуть и встретить вора в засаде. Если же мы его не найдём, то знаем, куда наведаться по утру.\n\nУже и приговор безымянному гоблину подписала.\nГорделивая нахалка\nГоржусь своей девочкой\n\nЯсмин опустила голову вниз и стиснула кулаки, украшения мелодично зазвенели.\n\n- Если в-вы не п-против, к-конечно же...\n\nТихо добавила она.",212725,null],[231293,"2026-09-23T09:36:48",20,"- Надо купить наручники\n\n*Выдает Беатриче голосом человека, очень серьезно принявшего свою роль*",212725,null],[231295,"2026-09-23T09:44:18",22,"Ясмин кивнула.\n\n- Т-тогда через два часа встретимся на м-месте. Я п-подойду.\n\nЯсмин не поднимала головы, она чувствовала, что глаза где-то рядом. И снова смотрят. Снова осуждают.",212725,null],[231297,"2026-09-23T09:54:22",17,"Марко заметил как уверенный голос Ясмин за несколько секунд снова стал тихим и ломким.\n\n\"Как будто сама испугалась того что предложила\"\n\nНо спрашивать не стал\n\n— Напротив, сиора. Я считаю это разумным.\n\nМарко бросил взгляд на уходящее солнце\n\n— Мы знаем где вор появится. Примерно знаем когда. А искать одного гоблина среди всех портовых складов можно до утра.\n\nОн достал часы, посмотрел время.\n\n— Отдохнём, поедим. Потом вернёмся к кузням до темноты и выберем место откуда видно вход, но не видно нас. правда достойных ресторанов я не знаю, давненько не ходил по ним. Может, сиора Беатриче подскажет?\n\n— И еще одна просьба. Когда он появится, ловим живым.\n\n— Меня распирает от любопытства узнать зачем ему столько клещей.",231292,null],[231301,"2026-09-23T10:12:10",22,"Ясмин удалилась в таверну, где проживает.\n\nПриветсвенно кивнув бармену, она поспешила в свою комнату.\n\nХлопнула дверь. \nЯсмин прислонилась лбом к двери, держа руку на замке.\n\nТишина продлилась недолго. В голове взорвался вихрь чужих эмоций и присутствия. Ледяные пальцы ковырялись в ее душе, с садистким наслаждением перебирая все события этого дня.\n\nГорький какао и хинга(жженая смола) наполнили комнату.\n\nЯсмин сползла по двери и зашлась в тихих рыданиях.\n\n//тегните, когда готовы собираться на месте",212725,null],[231302,"2026-09-23T10:13:31",17,"— Где бы нам их взять, наручники...",231293,null],[231303,"2026-09-23T10:15:09",20,"- Хм, рестораны... Думаю можно и прогуляться до Старого города - он как раз рядом. *Предлагает Беатриче*\n\n- Есть там одно местечко - Il Leone di Velluto. Так подают лучшее дзабальоне в городе!\n\n*Она уже хочет провести новых знакомых, когда видит как Ясмин резко уходит, покидая их. Неужели эта сеньорита настолько стеснительная?*\n\n- Ах, ну... похоже сегодня не судьба",231297,null],[231304,"2026-09-23T10:16:39",20,"- Может на рынке что найдется? Я такие вещи раньше не покупала, но думаю найти их будет не проблема *Легкомысленно пожимает плечами девушка*\n\n- Если хотим схватить его живым, как-то обездвижить гоблина придется",231302,null],[231305,"2026-09-23T10:24:07",17,"В след Ясмин Марко кланяется слегка и произносит учитиво\n\n— Доброго вечера, сиора. До встречи.\n\nПотом поворачивается к Беатриче\n\n— Лавки уже закрываются, а наручники на самом деле просто так не продаются. \n\nОн говорит чуть тише\n\n— Только в особых лавках для... любовных утех и те не совсем, так скажем, надёжные. \n\nИ еще тише\n\n— Но я знаю пару людей, кто может продать нам их, правда втридорога.",231303,null],[231306,"2026-09-23T10:24:30",17,"Марко знал пару сомнительных дельцов из подпольного черного рынка",212725,null],[231310,"2026-09-23T10:29:37",20,"*Беатриче слушает и кивает, проникаясь мудростью профессионала*\n\n- Ох, ваши связи очень кстати сеньор Марко. \n\n\"Так вот зачем они старшему брату были нужны....ещё и с бархатом...\" - тем временем думает про себя. \n\"Может одолжить у него? Не, наверное они специальные, не очень крепкие...\"\n\n- А это много времени займет? Успеем до темноты?",231305,null],[231320,"2026-09-23T10:32:22",17,"— Успеем. Тут недалеко есть их связной.",212725,null],[231322,"2026-09-23T10:32:41",17,"/ @QURTZZ хотим купить наручники из под полы. Норм?",212725,null],[231335,"2026-09-23T10:43:13",31,"без проблем. отыгрывай, думаю где то в нижнем городе найдешь по связям своим/",231322,null],[231337,"2026-09-23T10:45:30",31,"я сегодян чуток торможу, сорян. работа одолела)/",212725,null],[231350,"2026-09-23T11:35:15",17,"Марко повёл Беатриче не к рынку, а обратно в сторону старых улиц возле порта. Прошли одну вполне приличную улицу.\nПотом менее приличную.\n\nПотом свернули в такой узкий переулок, что Марко пришлось пропустить Беатриче вперёд чтобы разминуться с мужчиной несущим корзину тухлой рыбы.\n\n— Почти пришли.\n\nПереулок закончился маленьким внутренним двориком между тремя домами. Здесь пахло сыростью, зерном и голубиным помётом.\nОчень много голубиного помёта.\n\nНа первом этаже одного из домов висела выцветшая вывеска.\n\n\"ПТИЦЫ СИНЬОРА БАРТОЛО. КОРМ. КЛЕТКИ. ЛЕЧЕНИЕ.\"\n\n\"Лечение он предлагает и людям. После которого они подсаживаются на эти лекарства\"\n\nМарко толкнул дверь.\nНад головой сразу звякнул колокольчик.\nПомещение оказалось длинным и узким. Клетки стояли на полках, висели под потолком, занимали подоконники. Канарейки, голуби, какие то серые морские птицы и совершенно лысый попугай молча смотревший на посетителей с явным осуждением.\n\nЗа прилавком сидел крошечный старик.\n\nОн был худым, седым и задумчивым. \nСеньор Бартоло поднял голову.\n\n— Добрый вечер.\n\nНикакой реакции. Марко постучал костяшками по прилавку. Старик увидел его и расплылся в беззубой улыбке.\n\nМарко наклонился к Беатриче.\n\n— Он глухой. Полностью.\n\nБартоло тем временем достал из-под прилавка маленькую грифельную доску и мел.\n\nВЕНЬЕР\n\nНаписал он.\n\nПотом ниже.\n\nДАВНО НЕ БЫЛ\n\nМарко забрал мел.\n\nРАБОТАЛ\n\nБартоло посмотрел на него, потом на Беатриче. Медленно приподнял бровь.\n\nЭТО ТОЖЕ РАБОТА?\n\nМарко несколько секунд смотрел на написанное.\n\nНАРУЧНИКИ. НАСТОЯЩИЕ. КРЕПКИЕ. С КЛЮЧОМ.\n\nБартоло прочитал. Посмотрел на Марко. На Беатриче. Опять на Марко.\nУлыбка стала значительно шире.\n\nМарко закатил глаза и быстро дописал снизу.\n\nДЛЯ ПРЕСТУПНИКА\n\nСтарик хрипло рассмеялся.\nТорговец поднялся и неожиданно бодро исчез за занавеской. Оттуда послышался грохот, звон металла, возмущённый крик какой то птицы.\n\n— Бартоло занимается птицами лет сорок.\n\nОн посмотрел на окружающие клетки.\n\n— Чем занимался до того никто точно не знает.\n\nСтарик вернулся с небольшим деревянным ящиком и поставил его на прилавок. Внутри лежали три пары наручников.\n\nОдни ржавые и массивные, больше похожие на тюремные кандалы.\n\nВторые тонкие, аккуратные, с каким то подозрительно мягким красным бархатом внутри.\n\nМарко сразу перевёл взгляд на третьи.\n\nОбычная сталь. Цепь из трёх толстых звеньев. Два замка.\nОн взял их в руки, проверил петли, потянул цепь. Проверил ключ. Замок открылся без заеданий.\n\nПотом написал\n\nСКОЛЬКО?\n\nБартоло указал цену. Марко посмотрел на цифру. Потом на Бартоло. Снова на цифру.\n\n— Грабёж.\n\nСтарик довольно кивнул, словно прекрасно расслышал.\n\nМарко повернулся к Беатриче.\n\n— Я предупреждал. Втридорога.\n\n/ 10 ЗМ",212725,null],[231357,"2026-09-23T11:40:49",22,"//в таких моментах, главное не потерять ключи",212725,null],[231358,"2026-09-23T11:41:27",20,"*Беатриче явно не привыкла бывать в таких местах, сейчас стоит и переглядывается с лысым попугаем. Пристально*\n\n*Услышав цену, оборачивается к Марко*\n\n- Сколько-сколько там вышло? Cazzo, да за такое деньги можно бутылку отличного вина купить!\n\n*Роется в карманах, передавая ему 8 золотых как свою часть*\n\n- Ну и затратная же у вас следователей работа...",212725,null],[231366,"2026-09-23T11:53:01",17,"— Можно попросить бутылочку у Неро после завершения этого дела. Отметим. У него ликёром целый сервант набит.",212725,null],[231367,"2026-09-23T11:53:39",17,"Марко взял пять монет и вернул три назад Беатриче, вынул свои пять и передал Бартоло вложив в руку и закрыв его ладонь",212725,null],[231371,"2026-09-23T11:57:05",17,"После забрал наручники и связку с двумя ключами\n\n— Ключи одинаковые, одного хватит чтобы закрыть или открыть.\n\nМарко задумался, что сам никогда не пробовал надевать анручники\n\n— Можно потренироваться... за ужином. Надеть эти \"браслеты\" не должно быть сложно, раз и защёлкнуть\n\nМарко накинул один наручник себе на запястие и защелкнул его\n\nПотом взял ключ и начал октрывать\n\n— Не подходит...\n\nПоказывает руку Бартоло\n\nТот смеется руками демонстрируя, \"Простите простите, сию минуту всё исправлю\"\n\nДостаёт другие ключи из под прилавка\n\nИ вот они уже подходят\n\nМарко снисходительно вздыхает\n\n— Да уж, воистину. Доверяй, но проверяй.",212725,null],[231372,"2026-09-23T11:59:59",17,"— Вам, сиора ничего не нужно? Напишите на табличке, Бартоло тот еще фокусник, возможно достанет из своей \"шляпы\" что-то уникальное для вас.",212725,null],[231380,"2026-09-23T12:12:37",20,"*Беатриче чешет затылок, раздумывая что такого особенного может ей тут понадобится. Для дела особо ничего не надо, из личных вещей тоже...*\n\n- Ох, даже не знаю, синьор Марко...О, точно! *Берет табличку и быстро пишет*\n\n'ЗЕРКАЛЬЦЕ И ПАРУ ЛИНЗ'\n\n*Как никак Висконти всегда выполняют свои обещания*",231372,null],[231382,"2026-09-23T12:13:14",31,"почти как Ланнистеры/",231380,null],[231383,"2026-09-23T12:13:53",20,"/только без инцеста👀",231382,null],[231384,"2026-09-23T12:14:02",31,"кто знает.../",231383,null],[231385,"2026-09-23T12:14:16",31,"дело то семейное.../",212725,null],[231386,"2026-09-23T12:14:37",17,"Бартоло читает и кивает тебе\n\nБыстро скрываясь за занавеской\n\nСпустя немного времени возвращается со шкатулкой, внутри зеркало, круглое и круглые линзы",212725,null],[231387,"2026-09-23T12:15:02",20,"/сколько там по цене выйдет?",212725,null],[231388,"2026-09-23T12:16:16",20,"*Беатриче кивает, мол \"Да, отлично подойдёт\"*\n\n'СКОЛЬКО'\n\n*Пишет на доске, уже доставая поясной кошель*",231386,null],[231389,"2026-09-23T12:16:33",17,"/ 3 ЗМ",212725,null],[231391,"2026-09-23T12:17:01",17,"Бартоло показывает три пальца",212725,null],[231392,"2026-09-23T12:17:51",20,"*Не торгуясь выкладывает нужную сумму и довольная убирает детальки в сумку*\n\n\"Вот шкеты обрадуются, хех\"",212725,null],[231393,"2026-09-23T12:18:10",31,"надо бы вам бахнуть какую то систему социального рейтинга. Типа Беатриче пацанам подарок сдлелала - +1 к карме. Ясмин напугала мать с детьми до усрачки - -1 к капме))/ но я ленивая жопа))///",212725,null],[231395,"2026-09-23T12:18:47",22,"//я думала ты ведешь",231393,null],[231401,"2026-09-23T12:19:33",22,"//я просто играла в пф кампейн где суть заключалась в том, что нужно поднять восстание. И соц рейтинг играл большую роль. Думала, что тут так же😅",212725,null],[231405,"2026-09-23T12:21:10",17,"С небольшим поклоном Марко направляется к выходу\n\nЗа дверьми птичьей лавки он спрашивает у Беатриче усталым голосом\n\n— Уже довольно сильно смерклось, может сразу направимся в засаду? Вдруг этот ушлый вор выходит с первыми сумерками? Захватим нашу загадочную иностранку и к кузне Болена?",212725,null],[231406,"2026-09-23T12:21:16",31,"я только сейчас об этом одумал и пока не вижу необходимости. хотя может таакое дало бы больше вариантов на случайные события/",231401,null],[231414,"2026-09-23T12:22:38",20,"*Беатриче согласно кивает*\n\n- Как гоблин появится сразу хватаем или проследим куда он клещи упрет?",231405,null],[231424,"2026-09-23T12:24:50",17,"— Я думаю сперва схватить. А потом допросить. \n\nМарко достает книгу мертвых и разворачивает точно на странице ритуала \"Понимание языков\" на нем нарисован необычный крест с петлей \"Анх\"\n\n— С помощью этого ритуала я смог бы поговорить с ним на гоблинском языке. Сыграем в доброго и злого стражника? Вам, сиора, как удобнее будет? Каким стражником хотите быть?",212725,null],[231425,"2026-09-23T12:25:54",20,"- Ну могу на него клыки поскалить да клинком погреметь. Точно со страху вам все выложит",231424,null],[231426,"2026-09-23T12:26:43",31,"вы все трое злыые. бедный гоблин((\\",212725,null],[231429,"2026-09-23T12:27:06",17,"— Хех. А кто же будет добрым тогда? Я ведь тоже больше люблю злую роль...\n\nМарко слегка рассмеялся, и как то по особенному будто это совсем не шутка",212725,null],[231449,"2026-09-23T12:30:35",20,"- Ну вы мне особым злодеем не видитесь, синьор. Да и как тот кто раскрывает преступления может быть злым? *Беатриче фыркает*\n\n*Она действительно не видела в Марко ничего плохого - наоборот, пока он проявил себя исключительно как учтивый и дружелюбный джентльмен. Ну да, с подпольными связями - ну так это просто специфика работы*",231429,null],[231476,"2026-09-23T12:36:46",31,"еще что то планируете или таймскип до вечера и засады?",212725,null],[231536,"2026-09-23T12:46:00",22,"//мой последний наряд воителя готов, го засаду",212725,null],[231545,"2026-09-23T12:46:59",31,"ок, ща отпишу/",212725,null],[231561,"2026-09-23T12:49:37",31,"Вновь у кузни Болена вы собрались около 8 вечера. Дварф ожидал вас, нервно поглядывая на песочные часы.\n\n- вы не торопились - проворчал он. - Ну хоть пришли. В общем, все оставшиеся клещи мы собрали тут, у меня в кузне. Где вы будете устраивать засаду? Внутри или снаружи?",212725,null],[231587,"2026-09-23T12:56:14",22,"Ясмин тихо пошла последней и откинула капюшон, сверкнув золотым глазом. \n\n- Внутри будет проще, а вы что думаете?\n\nОт заиканий не осталось и следа. Лицо Ясмин было спокойным и не выражало никаких эмоций, словно восковая маска. И лишь по красноватая припухлость вокруг глаз разрушала этот образ.",212725,null],[231592,"2026-09-23T12:57:15",20,"- Могу подкараулить его снаружи, на крышах. Когда он войдёт, возьмём его в клещи *слегка посмеивается на последнем слове*",231587,null],[231623,"2026-09-23T13:07:17",22,"- Хорошая идея, тогда я останусь недалеко от входа.\n\nСказала Ясмин, обернувшись к тебе. Вот только смотрела она не в глаза, а чуть выше, туда, откуда на нее смотрели три пары смеющихся золотых глаз.",231592,null],[231650,"2026-09-23T13:16:37",17,"— Злым и жёстким становишься не тогда, когда закрыл дело. бетарияе. А наоборот, из за того, что не можешь раскрыть. У меня есть такое дело. Очень давнее.",212725,null],[231656,"2026-09-23T13:18:46",17,"— Чтож, я тогда буду внутри, чтобы точно окружить его со всех сторон. Мы добыли наручники, сиора Ясмин. Кто их возьмет?",231623,null],[231661,"2026-09-23T13:22:07",22,"- Я не умею пользоваться подобными устройствами. Оставлю этот.. инструмент на профессионалов.",212725,null],[231683,"2026-09-23T13:26:37",20,"- Давайте я, сеньор. Тут понадобится скорость и ловкость, а ее у меня хоть отбавляй",231656,null],[231687,"2026-09-23T13:27:51",17,"Марко согласно кивает и передает наручники один ключ оставляет себе и один отдает Беатриче",212725,null],[231689,"2026-09-23T13:28:08",17,"Каждый занимает место в засаде и ждут",212725,null],[231690,"2026-09-23T13:29:20",31,"итак, вы заняли следующие позиции:\nБеатриче на крыше напротив (видимо, это крыша кондитерской)\nЯсмин скрылась в тени неподалеку от двери кузни\nМарко внутри засел",212725,null],[231691,"2026-09-23T13:29:47",31,"хочется вам подлянку сделать, но не буду)))/",212725,null],[231718,"2026-09-23T13:35:38",31,"ваша охота началась. вы замерли в тишине. лишь Вилли нарушал ее своим шаканьем и треском факела - дварфы решили что оставить сторожа необходимо, чтобы вор думал что все как обычно происходит. Наблюдая за Вилли, вы поняли почему он никогог не мог поймать - он нереально медлителен. У гоблина был бы шанс кузню целиком утащить, пока сторож бы вернулся на точку.\n\nПримерно через час наблюдения, вы услышали шорох и всплеск откуда то со стороны сточных канав. Приглядевшись, Беатриче, как занимающая домининующую  высоту, заметила длинноухую голову гоблина, что разведывал территорию. Он углядл что Вилли отошел довольно далеко и тихонько выбрался из сточной канавы. Мелкой перебежкой он подскочил к двери и вдруг навострил уши\n\nКидайте скрытность/",212725,null],[231726,"2026-09-23T13:38:47",20,"/r -d20+5",212725,null],[231728,"2026-09-23T13:39:13",31,"я за руль, через час-полтора вернусь/",212725,null],[231729,"2026-09-23T13:39:31",20,"/r d20 трачу единицу удачи",212725,null],[231732,"2026-09-23T13:40:17",20,"/беру значение на кубе из трёх 17 - итоговая скрытность 22",212725,null],[231733,"2026-09-23T13:41:58",22,"/r +2",231718,null],[231739,"2026-09-23T13:42:27",22,"/глаз светится",212725,null],[231769,"2026-09-23T13:52:12",17,"/r +2 Скрытность Марко",212725,null],[231771,"2026-09-23T13:52:32",17,"/ по первым кубам у нас 777",212725,null],[231781,"2026-09-23T13:53:47",20,"/это к удаче 😌",231771,null],[231809,"2026-09-23T13:57:37",22,"/дрим тим я считаю😎",212725,null],[231859,"2026-09-23T14:23:10",31,"/roll +d20+3 внимание гоблина",212725,null],[231870,"2026-09-23T14:26:00",31,"Марко за дверью неосторожно задел какую то железяку, успел ее удержать от падения, но не до конца, тихий звяк насторожил гоблина, он прислушался, собрался и вдруг во тьме заметил жуткий глаз Ясмин. В панике оглянувшись он со страху заметил и Беатриче на крыше напротив. Это окончательно сорвало ему крышу и он рывком бросился наутек, в ту же сточную канаву",212725,null],[231875,"2026-09-23T14:27:13",31,"Ясмин и Беатриче могут попытаться поймать беглеца реакцией",212725,null],[231887,"2026-09-23T14:34:10",22,"ЛЕЖАТЬ!\n\nПриказ прогремел, словно гром. \n\nЭто было не похоже на тонкий девичий голосок, скорее на хор: низкий, скрипучий, уставший. Словно три голоса наложились друг на друга, но не в унисон, а с небольшой задержкой.\n\nМдр 14 спас",231875,null],[231892,"2026-09-23T14:36:56",22,"/или так не работает? Я чутка не шарю..",212725,null],[231908,"2026-09-23T14:42:21",17,"/ Работает всё, щас ляжет)",212725,null],[231997,"2026-09-23T14:57:11",31,"/roll d20+3 гоблин пытается н слушать страшный голос",212725,null],[232002,"2026-09-23T14:57:22",31,"Гоблин сука мудрый/",212725,null],[232005,"2026-09-23T14:58:03",31,"Услышав страшный голос карги гоблин не замер, а побежал ещё быстрее",212725,null],[232006,"2026-09-23T14:58:10",31,"И успешно сбежал",212725,null],[232013,"2026-09-23T15:00:03",22,"/Беатриче еще не прыгнула на него",212725,null],[232014,"2026-09-23T15:00:25",20,"*Беатриче пускается в погоню!*",212725,null],[232018,"2026-09-23T15:00:53",31,"Вот что видела Беатриче с крыши/",212725,null],[232019,"2026-09-23T15:00:55",20,"/ща догоним",212725,null],[232021,"2026-09-23T15:01:22",31,"Можешь прыгнуть на него, если увернется, то сбежал/",232019,null],[232026,"2026-09-23T15:02:16",20,"/r d20+5 акробатика, прыгаем",232021,null],[232031,"2026-09-23T15:03:25",20,"/интересно это колокольчик открывания у него там🤔",232018,null],[232034,"2026-09-23T15:04:01",20,"/хотя вряд ли",212725,null],[232036,"2026-09-23T15:04:11",31,"/roll d20+5 гоблин проверка ловкости",232027,null],[232038,"2026-09-23T15:04:16",22,"//черный плащ! Только свистни и он появится!",232027,null],[232041,"2026-09-23T15:04:28",31,"Гоблин пищит, придавленный Беатриче",212725,null],[232042,"2026-09-23T15:04:32",17,"// Главное не защелкнуть браслеты на себе случайно",212725,null],[232043,"2026-09-23T15:04:46",31,"Проверка ловкости рук, сл 12/",232042,null],[232046,"2026-09-23T15:05:14",22,"Ясмин подходит на шум и кряхтение придавленного воришки.",212725,null],[232047,"2026-09-23T15:05:29",20,"- Попался irrequieto! *Беатриче вытаскивает наручники*",232041,null],[232049,"2026-09-23T15:05:35",20,"/r d20+5",212725,null],[232051,"2026-09-23T15:05:44",20,"/удача",212725,null],[232053,"2026-09-23T15:06:18",20,"/застегивает наручники",212725,null],[232092,"2026-09-23T15:12:32",31,"Вроде все везунчики кончились?/",212725,null],[232095,"2026-09-23T15:13:01",31,"Гоблин затихает, смиряясь с судьбой заключённого",212725,null],[232106,"2026-09-23T15:14:53",20,"/ещё один",232092,null],[232109,"2026-09-23T15:15:35",20,"*Беатриче берет гоблина подмышку, направляясь к своим напарникам*\n\n- Хей! Я его поймала, что дальше?",232095,null],[232110,"2026-09-23T15:15:46",17,"Марко выходит из кузницы на шум, опирая главные ворота\n\nОн уже заранее провёл ритуал понимания языков, чтобы подслушать если вдруг гоблин бубнил бы себе под нос что то\n\nНа чистейшем гоблинском который слышат все рядом он спрашивает зеленокожего\n\n— Игры кончились. Бежать некуда. Единственная твоя надежда на спасение это всё рассказать нам. Я задаю вопросы - ты отвечаешь, и не приведи господь я почую, что соврал мне.",212725,null],[232111,"2026-09-23T15:16:10",17,"— С какой целью ты воруешь клещи?",212725,null],[232118,"2026-09-23T15:18:03",17,"Понимание языков не даёт в целом возможности говорить на незнакомом языке, только читать его и понимать написаное. Но у Марко был прикуплен по скидке на гоблинской ярмарке \"Гоблинско-общий\" словарик и пару гоблинских сказок для детей",212725,null],[232126,"2026-09-23T15:18:43",31,"- Для крабика...\n\nГоблин бурчит глядя на тебя",232111,null],[232130,"2026-09-23T15:19:07",17,"— Кто такой крабик четко, внятно поясни? Зачем ему клещи?",212725,null],[232131,"2026-09-23T15:19:13",20,"/🥺",232126,null],[232132,"2026-09-23T15:19:36",31,"- а как крабику без клещей?",232130,null],[232133,"2026-09-23T15:19:48",31,"- чтобы клац клац делать",212725,null],[232135,"2026-09-23T15:19:55",17,"/ Он на общем говорит?",212725,null],[232136,"2026-09-23T15:20:02",31,"Да/",232135,null],[232139,"2026-09-23T15:20:29",17,"— Сиоры, ваше слово. Помоему этот мелкий паршивец ломает комедию.",212725,null],[232143,"2026-09-23T15:20:44",20,"- Твой друг крабик лишился клещей? *Пытается понять Беатриче*",232132,null],[232144,"2026-09-23T15:20:52",22,"Ясмин тем временем смотрела прямо в глаза гоблину. \n\nЕсли гоблин присмотрится, то заметит, как ее глаз иногда двигается ассинхронно.",212725,null],[232147,"2026-09-23T15:21:06",17,"Марко слегка закрывает глаза ладонью\n\n\"Друг крабик, господи помилуй\"",212725,null],[232150,"2026-09-23T15:21:17",22,"/помощь на запугивание, кто кидать там будет",212725,null],[232152,"2026-09-23T15:21:27",20,"/знал с кем на дело шел)",232147,null],[232154,"2026-09-23T15:21:30",31,"- крабик не друг. Крабик помощник",232143,null],[232156,"2026-09-23T15:21:58",22,"//ладно я сама пропишу запугивание, ускорим процесс",212725,null],[232167,"2026-09-23T15:23:24",31,"Чую, сейчас гоблин жидкого даст/",212725,null],[232174,"2026-09-23T15:24:41",17,"/И получит преимущество на ускользание?",232167,null],[232177,"2026-09-23T15:25:29",31,"Видно опытного мастера. Я запишу это/",232174,null],[232186,"2026-09-23T15:27:21",22,"- Кожу бы живём содра-а-ать...\n- Душу разорва-а-ать\n- Крабика в суп\n- Карлика на вертел \n\nРазными голосами запела Ясмин.",212725,null],[232187,"2026-09-23T15:27:22",22,"/вуншпунш",212725,null],[232189,"2026-09-23T15:27:42",22,"//поэт из меня так себе, так что извиняйте",212725,null],[232190,"2026-09-23T15:28:18",22,"/r +1 злая девочка поёт странную песенку",212725,null],[232192,"2026-09-23T15:28:41",22,"У меня есть вдохновение? Мне не хватает вдохновений!/\nИли подпевайте/",212725,null],[232195,"2026-09-23T15:29:29",31,"Ну бог тобой, бери вдохновение/",232192,null],[232197,"2026-09-23T15:29:33",31,"На переброс/",212725,null],[232199,"2026-09-23T15:30:01",31,"Гоблин таки обгадился. Прямо на руки держащей его Беатриче",212725,null],[232200,"2026-09-23T15:30:08",22,"/от души🖤",212725,null],[232204,"2026-09-23T15:30:31",31,"- чиво вам надааааааа!???!!?",212725,null],[232207,"2026-09-23T15:30:45",31,"- отпустите!!!!!",212725,null],[232216,"2026-09-23T15:32:04",22,"- Нормально отвечай\n- Подробно\n- Не заставляй нас \n- Использовать эти клещи\n- На тебе\n- Пирожочек",212725,null],[232217,"2026-09-23T15:32:27",20,"- Уф... *Беатриче морщится, держа перепуганного обосранного гоблина теперь на вытянутых от себя руках*\n\n*Хоть бы предупреждали*",232199,null],[232219,"2026-09-23T15:32:54",17,"Марко внимательно прислушался к голосу Ясмин. Его самого пробрало до мурашек. Будто несколько страшных злых древних существа извергли проклятье на этого гоблина. \n\n\"Ничего себе. Тот самый Злой глаз в действии?\"\n\n— Что вы, сиора Ясмин. Карлика на вертел? Это совершенно незаконно. Сперва отсечение правой кисти. По протоколу. Потом уже казнь через повешанье на эшафоте. Спросите, зачем отсекать руку если всё равно казнить будут? Таков закон и бюрократические нюансы.",232186,null],[232220,"2026-09-23T15:33:21",31,"- я честно сказал! Я для крабика брал! Крабику нужны клещи! Чтобы делать клац-клаааааац....\n\nВой гоблина переходит в хрип",212725,null],[232221,"2026-09-23T15:33:32",17,"— Это мелкая пакость, останется между нами в тайне, сиора Беатриче.",232217,null],[232223,"2026-09-23T15:34:07",20,"*просто смотрит на Марко взглядом типа \"Ни. Слова\"*",232221,null],[232224,"2026-09-23T15:34:29",22,"Ясмин ничего не говорит. Она смотрит на гоблина. И медленно облизывается.",212725,null],[232225,"2026-09-23T15:34:37",17,"— Нам нужно, чтобы ты привёл нас к этому крабику. Быть может это твой единственный шанс на спасение. Подумай хорошенько.",212725,null],[232226,"2026-09-23T15:35:05",31,"- а, а вы не обидете крабика? Он хороший...",232225,null],[232234,"2026-09-23T15:36:27",17,"— Как вы думаете, сиоры? Способны ли МЫ обидеть маленького крабика, который всего то хотел делать клац клац?",212725,null],[232236,"2026-09-23T15:38:33",20,"- Что вы, синьор. Да мы и мухи не обидем *тянет Беатриче*\n- уж тем более маленького крабика, хотящего клац-клац",232234,null],[232237,"2026-09-23T15:38:48",17,"— Кстате приятель, а почему крабику нужны новые и новые клещи? ты же уже стащил их больше десятка я полагаю.",212725,null],[232242,"2026-09-23T15:42:32",31,"- они все плохо подходят. Нужно больше",232237,null],[232245,"2026-09-23T15:44:55",31,"- я отведу вас к крабику...\n\nГоблин выглядит сломленным",212725,null],[232256,"2026-09-23T15:51:02",22,"*шмыг шмыг*\n\nГлаза Ясмин округляются. Она смотрит на гоблина и Биатриче в ужасе.\n\nВ её голове раздается мерзкое хихиканье.\n\nДевушка побледнела и убежала за угол, где ее вывернуло.\n\nОпять. Вы ОПЯТЬ ЭТО СДЕЛАЛИ. Я против. Я не разрешаю. ЭТО МОЕ ТЕЛО.\n\nИхихи-хи-хи",212725,null],[232258,"2026-09-23T15:51:24",22,"Спустя пару минут Ясмин возвращается.\n\n- Это п-просто с-стресс.. И-извините...",212725,null],[232301,"2026-09-23T15:59:19",31,"Решайте что то по гоблину и маякните мне, я пока пойду ужин готовить/",212725,null],[232309,"2026-09-23T16:01:08",22,"//Ясмин готова идти, у нее просто очередной \"приход\"",212725,null],[232384,"2026-09-23T16:23:21",17,"— Я не привык совать нос в личное. Рад просто, что вы вернулись к нам, после всех невзгод. Поэтому, вот, попейте соку. Мои знакомые выжимают из свежих фруктов.\n\nМарко достал из сумки бутылку яблочного сока, полную и протянул Ясмин",232258,null],[232408,"2026-09-23T16:31:38",20,"- Есть и что покрепче, Сеньорита. Если вам нужно собраться с духом конечно *Беатриче кивает на свою фляжку с вином на поясе*\n\n- Хотя таким с непривычен лучше не злоупотреблять",212725,null],[232409,"2026-09-23T16:31:55",17,"Марко отошел в сторонку, заглянул в открытую бочку. Потом вернулся к Беатриче\n\n— Я подержу, сиора. Вон там есть в бочке вода и рядом тряпьё. Можете привести себя в порядок.\n\nПротянул руки чтобы ухватить гоблина",232245,null],[232410,"2026-09-23T16:32:38",17,"— Одну минутку, любезный. мы почти готовы пойти к вашему другу крабику.",212725,null],[232411,"2026-09-23T16:32:49",17,"— Надеюсь его знаменитый клац клац того стоит.",212725,null],[232412,"2026-09-23T16:34:55",20,"- А, Grazie. *Она с облегчением передает ему проникшего гоблина*\n\n- Думаю не обязательно его прям в захвате удерживать, вон он как поник. Просто держите его рядом и в наручниках\n\n/Не повторяй мою ошибку...\n\n*Она уходит к бочке привести себя в порядок. Стирать долго, поэтому просто стягивает с себя испачканную рубашку, оставаясь жилете бригантины на голове тело, не задерживаясь. Рубашку запасную потом сменит*",232409,null],[232426,"2026-09-23T16:48:03",22,"- С-спасибо. Большое. \n\nЯсмин в один залп осушает половину бутылки. \n\n- Н-нет. Больше н-никакого алкоголя!\n\nДевушка сильно раскраснелась, что было заметно даже на ее смуглой коже в сумерках.\n\nЧуть погодя она осушила оставшуюся половину.\n\n- Б-Беатриче. Простите что напугала. Этот к-казус из-за меня. Позвольте я дам вам свой анчал.\n\nДевушка снимает с себя самую крупную часть одежды, ту, что обмотана над топом.\n\n- Девушке же н-неприлично так ходить! - шепотом добавляет Ясмин.",232384,null],[232427,"2026-09-23T16:49:58",22,"А комариха то развратница!",212725,null],[232428,"2026-09-23T16:51:05",20,"- А, да все на так уж страшно, синьорита. Благодарю за заботу. *Беатриче вытирает капли воды, поправляя ремни на бригантине*\n\n- Главное на сам жилет не попало, без брони тут лучше не ходить  - остальное житейские мелочи. Новую завтра куплю.",212725,null],[232433,"2026-09-23T16:54:29",22,"- Ки душчар! \n\n/какое распутство!\n\nЯсмин покраснела еще сильнее и вернулась к гоблину, готовая двигаться дальше.",212725,null],[232436,"2026-09-23T16:57:31",17,"/ @QURTZZ готовы",212725,null],[232437,"2026-09-23T16:58:50",17,"Марко просто прокрутил в голове какие слухи могут пойти по городу, если кто-то увидит Беатриче Висконти в непристойном виде посреди ночи в компании, мужчины, иностранки и... гоблина.",212725,null],[232438,"2026-09-23T16:59:02",17,"И хихикнул тихонечко",212725,null],[232439,"2026-09-23T16:59:53",31,"Ее репутации не повредит походу)/",232437,null],[232440,"2026-09-23T17:00:04",31,"Как тащите гоблина, на привязи?/",212725,null],[232441,"2026-09-23T17:00:16",20,"/скорее репутации этих двоих👀",232439,null],[232442,"2026-09-23T17:00:50",31,"А уж как репутация гоблина упадет.../",212725,null],[232443,"2026-09-23T17:00:53",17,"Марко идёт рядом с гоблином удерживая цепь между наручниками в своей руке\n\n/ тоесть совершенно ненадёжно!)",212725,null],[232445,"2026-09-23T17:04:46",17,"/Погодите... Он же щас заставит нас в трубу канализационную нырять...",212725,null],[232446,"2026-09-23T17:06:29",31,"Гоблин понуро ведет вас темными переулками, которые, судя по запаху, днем выполняют роль общественных туалетов, он держится подальше от любых крупных улиц. Ведет вас он в район тех самых старых складов, о которых говорил страэник Отто. На удивление, вы не замечаете тут прмзгвклв жизни большой группы гоблинов. Видимо, слухи о из клдичесвте были несколько преувеличиены. \n\nГоблин доводит вас до самого дальнего склада, который смотрится крепче других. Там даже довольно приличная дверь, словно гоблин выбирал место для хранения сокровищ с особой тщательностью.\n\nДойдя до двери гоблин заговорил:\n\n- Крабик там, можете зайти",212725,null],[232448,"2026-09-23T17:08:12",31,"Гоблин отпирает дверь и приглашает вас в темноту",212725,null],[232449,"2026-09-23T17:12:07",20,"- Ну что, идём? *Беатриче оборачивается к союзникам*\n\n/0% подозрений, 100% готовности",212725,null],[232451,"2026-09-23T17:12:49",22,"Ясмин кивает",212725,null],[232452,"2026-09-23T17:13:17",31,"Ждем решения прожженого Марко/",212725,null],[232453,"2026-09-23T17:15:45",17,"\"Беглый анализ\"\n\nНейронные связи пробивает импульс тока\n\n\"Старый склад с большой дверью, совершенно не подозрительно, пока.\"\n\n— А у тебя есть с собой клещи? Не гоже как то с пустыми руками",212725,null],[232454,"2026-09-23T17:16:19",17,"Жнец слетает с карниза и ищет в крыше, в боковых стенах щель или окно чтобы заглянуть внутрь",212725,null],[232455,"2026-09-23T17:16:26",17,"/r +2 Внимание ворона",212725,null],[232458,"2026-09-23T17:17:16",31,"Ворон не находит способов заглянуть в склад",212725,null],[232459,"2026-09-23T17:17:36",17,"\"Глухо заколочен\"",212725,null],[232460,"2026-09-23T17:17:47",17,"— И кстате, что там внутри, кроме твоего друга?",212725,null],[232461,"2026-09-23T17:18:02",31,"- там мой дом",232460,null],[232466,"2026-09-23T17:21:47",31,"- Давайте я зажгу свет?",212725,null],[232468,"2026-09-23T17:23:47",20,"- А, да. Было бы неплохо *кивает Беатриче вспоминая, что не все тут видят в темноте*",232466,null],[232469,"2026-09-23T17:24:21",17,"— Давай зайдём как ты обычно заходишь, так что зажигай, зови своего друга. мы хотим познакомиться",212725,null],[232470,"2026-09-23T17:24:58",31,"- тогда снимите железки",212725,null],[232471,"2026-09-23T17:25:12",31,"Протягивает вам закованные руки",212725,null],[232477,"2026-09-23T17:29:05",17,"— Не так быстро. Но если тебе не совсем удобно, чтож.\n\nМарко открывает один наручник на правой руке гоблина ключом и тут же пристегивает себе на левую руку, так они с гоблино стали повязаны",212725,null],[232478,"2026-09-23T17:29:15",17,"— Теперь можешь делать всё практически как обычно",212725,null],[232479,"2026-09-23T17:29:18",17,"— Или что то мешает?",212725,null],[232480,"2026-09-23T17:37:23",31,"Гоблин недовольно кивает и тащит тебя в темноту. Там чем-то щёлкает и загорается факел у входа, а затем от его огня по принципу домино и какой то хитрой схемк загораются еще пара десятков факелов по всему периметру склада.\n\nВашему взору представляется довольно большое помещение склада, и оно похоже на... Склад? Гоблин стаскал сюда кучу железяк, тут и там валяются части каких то механизмов, у одной из стен стоит заваленный грязными бумагами и свитками стол.\n\nА прямо посреди склада стоит он. Крабик",212725,null],[232482,"2026-09-23T17:39:04",31,"Конструкция собранная из разных железя, вы видите тут в том числе и клещи, что воровались у дварфов и теперь стали составной частью клешен краба конструкта. Но самым неприятным элементом выглядит какой то посверкивающий кристалл внутри крабика. От него веет жутью",212725,null],[232484,"2026-09-23T17:40:05",17,"— Тааак. А крабик любит гостей?",212725,null],[232487,"2026-09-23T17:43:04",31,"Гоблин резко выворачивает закованную руку, его большой палец выворачивается под немыслимым углом и рука вылетает из наручника, он бросается к конструкту\n\n- опасность, защищай сеня Крабик!\n\nЗа вашими спинами грохочет замок. Склад закрыт. Похоже, гоблин как то создал систему закрывания дверей дистанционно. Гений механики, не иначе\n\nКрабик тем временем оживает. Пульсация кристалла усиливается. Он встречает своего создателя резким ударом клешни, который отбрасывает гоблина в сторону и впечатывает в стену. Зеленый сползает по стене, он в шоке и кричит: \n\n- Крабик, ты чего?!\n\nКрабик не обращает внимание на гоблина. Он заметил вас, и вы интересны ему больше.\n\nБросаем на инициативу",212725,null],[232488,"2026-09-23T17:43:57",31,"/roll d20+4 инициатива Крабика",212725,null],[232490,"2026-09-23T17:44:33",22,"/r +2",212725,null],[232492,"2026-09-23T17:44:56",22,"/довыпендривалась",212725,null],[232493,"2026-09-23T17:44:59",17,"/r +2 Инициатива Марко",212725,null],[232495,"2026-09-23T17:46:28",31,"Беатриче \nМарко\nЯсмин\nКрабик 40 урона, кристалл разбит, конструкт упал",212725,null],[232496,"2026-09-23T17:46:39",31,"@PaIIasCat инициатива",212725,null],[232498,"2026-09-23T17:47:54",20,"/r d20+3",232496,null],[232501,"2026-09-23T17:48:29",31,"Ща разберут на запчасти, демоны((",212725,null],[232502,"2026-09-23T17:48:47",31,"Ход Беатриче/",212725,null],[232503,"2026-09-23T17:51:09",20,"*Беатриче молниеносно выхватывает рапиру и кинжал*\n\n- Синьор, Синьорита, пробовали когда-нибудь грансеолу? Сейчас будет ее механическая версия *с этими словами она без капли сомнений к кидается в бой*",212725,null],[232504,"2026-09-23T17:51:38",20,"/r d20+5 удар рапирой\n/r d20+5 удар кинжалом",212725,null],[232506,"2026-09-23T17:51:56",31,"Кинжал попал",212725,null],[232507,"2026-09-23T17:52:01",20,"/r d4+3 урона",212725,null],[232509,"2026-09-23T17:52:08",31,"Колющий?/",212725,null],[232512,"2026-09-23T17:52:52",31,"Крабик не сильно пострадал, очевидно железяка не очень боится кольщий ударов",212725,null],[232513,"2026-09-23T17:53:09",31,"Это все?/",212725,null],[232515,"2026-09-23T17:53:21",20,"/да",212725,null],[232516,"2026-09-23T17:53:30",20,"/конец хода",212725,null],[232517,"2026-09-23T17:53:31",31,"Ход Марко",212725,null],[232518,"2026-09-23T17:59:14",17,"Марко поднял руку с наручниками и посмотрел на цепь потом он перевез взгляд на гоблина и взгляд этот был недобрый.\n\n— Могли обойтись без боли...\n\nОт факелом на пол отбрасывались длинная тень она начала изменяться вытянулась морда вытянулись уши по форме став шакалиными. \n\nДва золотых глаза загорелись в тени.\n\nИ она восстала вошла в Марко от чего на его собственное лицо было поглащено черной головой шакала.\n\nСледом был голос. Древний. Глубокий. Не человеческий. \n\nМарко указал пальцем на гоблина гордо выпрямив спину. На кончике пальца чернела магия. Холодная. Мертвая.\n\n— Отключи!\n\n/ Приказ спас мудрости СЛ 13",212725,null],[232519,"2026-09-23T18:00:20",31,"/roll -d20+3 сопротивление ч помехой так как сам гоблин тоже этого хочет",212725,null],[232521,"2026-09-23T18:00:58",17,"/ Ход",212725,null],[232522,"2026-09-23T18:01:41",31,"Гоблин орет:\n\n- Крабик, у нас отмена!\n\nКрабику абсолютно, совершенно, невероятно похеру ну слова гоблина. Он лишь щелкает жвалами\n\nПохоже, гоблин утратил власть над своим созданием",212725,null],[232523,"2026-09-23T18:02:15",31,"Ход Ясмин/",212725,null],[232524,"2026-09-23T18:02:19",20,"/Галя, отмена не прошла",212725,null],[232525,"2026-09-23T18:02:41",31,"Рад что отсылка понятна)/",232524,null],[232528,"2026-09-23T18:07:13",22,"Жалкий подражатель!\nПсина сутулая!\nХочу вырвать эти глаза!\n\n- Свет, защити меня! Священное пламя!\n\nСпас ловкость сл 14",212725,null],[232529,"2026-09-23T18:07:33",31,"/roll d20+4",232528,null],[232531,"2026-09-23T18:07:40",22,"/ход",212725,null],[232533,"2026-09-23T18:08:04",20,"/ну давай нападай",212725,null],[232534,"2026-09-23T18:08:19",31,"Я так понимаю, перед крабиком стоит Беатриче, а два жреца за ней? Конусом стоите?/",212725,null],[232539,"2026-09-23T18:09:29",31,"/roll d20+5 атака клешней по Беатриче, попытка поймать в захват и сжать",212725,null],[232541,"2026-09-23T18:09:51",31,"Ловкая дамамрша уворачивается и смеется",212725,null],[232543,"2026-09-23T18:10:27",31,"/roll d20+3 атака жвалами крабик бросается на девушку с желанием перекусить ее пополам",212725,null],[232545,"2026-09-23T18:10:39",31,"Видимо опять мимо",212725,null],[232547,"2026-09-23T18:10:45",20,"/кд 18",212725,null],[232548,"2026-09-23T18:11:11",31,"Крабик злобно стрекочет, кристалл на его спине наливается потусторонним светом",212725,null],[232549,"2026-09-23T18:11:13",31,"Ход/",212725,null],[232550,"2026-09-23T18:11:47",20,"/до кристалла рапирой никак не достать?",212725,null],[232551,"2026-09-23T18:12:33",31,"Если перепрыгнешь клешни и жвала. Проверкой акробатики 18+",232550,null],[232552,"2026-09-23T18:12:58",20,"/r d20+5 пробуем",232551,null],[232554,"2026-09-23T18:13:17",20,"/эх",212725,null],[232555,"2026-09-23T18:13:27",31,"Опиши как ударилась о крабика и потеряла один хит",212725,null],[232559,"2026-09-23T18:17:51",20,"*Беатриче смотрит на кристалл краба, понимая что походу щас чёт рванет. Подпрыгнув, она пытается запрыгнуть на клешню, чтоб потом перебраться на спину и вонзить рапиру прям в центр*\n\n*Не учитыват одно - металл сука скользкий*\n\n-AH, STRONZO! VAFFANCULO A TE E A TUTTA LA TUA FAMIGLIA NEL CONCHIGLIE! *С громкими ругательствами она больно приземляется задницей обратно на землю*",212725,null],[232564,"2026-09-23T18:19:08",20,"*Встаёт, раздражённо цокая языком. И снова вставая в стойку*\n\n- Цельтесь в эту штуку наверху...и лучше отойдите подальше\n\n/Уворот и конец хода",212725,null],[232567,"2026-09-23T18:20:56",31,"Ход Марко/",212725,null],[232582,"2026-09-23T18:26:22",17,"Марко поднимает обе руки вверх ладонями кверху\n\nИз воздуха слева и справа от краба материализуются черные лапы с когтями\n\nОдна уже устремилась на краба вторая на гоблина\n\nГлаза черного шакала светятся срким золотом.\n\nНо в последний момент левый глаз Марко тускнеет. \n\nСлышится тихое \n\n— Нет\n\nИз под черноты шакалиной морды появляется человеческий глаз следователя\n\nОн сжимает левую руку  и черная лапа около гоблина пропадает.\n\nНо с правой стороны лапа рвёт крабика.",212725,null],[232584,"2026-09-23T18:27:18",17,"/ Заговор ледяное прикосновение. Типо отыграл что из за способности Жнец у жреца смерти могу бить заговорами по двоим рядом. Но тут гоблина убивать не хочется.",212725,null],[232585,"2026-09-23T18:27:36",22,"//чую по описаниям у нас только Биатриче без ментальных проблем",212725,null],[232586,"2026-09-23T18:27:40",17,"/r +5 Попадание",212725,null],[232588,"2026-09-23T18:27:46",31,"Я разрешаю бить по крабу двумя руками/",212725,null],[232589,"2026-09-23T18:27:57",31,"Попал/",232587,null],[232590,"2026-09-23T18:28:10",31,"Но уже не в этот зод/",232588,null],[232591,"2026-09-23T18:28:33",17,"/r d8 Некротияечкой и краб не может восстанавливать здоровье до моего хода",212725,null],[232594,"2026-09-23T18:29:16",17,"/ Намного веселее создать себе внутреннюю борьбу, разве нет? Я думал все так делают )",232585,null],[232596,"2026-09-23T18:29:57",31,"Хмм. Я не прописывал крабу сопротивление от неуротике. Но он же не живой. Как быть?/",212725,null],[232597,"2026-09-23T18:30:06",22,"Ржаветь!/",232596,null],[232598,"2026-09-23T18:30:20",17,"/ Некротичекая магия не только заставляет плоть гнить но и металл ржаветь это магия увядания",212725,null],[232599,"2026-09-23T18:30:34",31,"Ок, принял. Тогда полный урон/",212725,null],[232600,"2026-09-23T18:30:38",20,"/в я чую что Беатриче их может скоро заработать в такой компании 👀",232585,null],[232602,"2026-09-23T18:31:03",22,"//я больше с золотых глаз офигела",232594,null],[232603,"2026-09-23T18:31:22",31,"Крабик принимает волну некротической энергии, и она ему не по вкусу. На его броне расцветают пятна ржавчины/",212725,null],[232604,"2026-09-23T18:31:36",31,"Это весь ход?/",212725,null],[232608,"2026-09-23T18:32:22",31,"Если да, то Ясмин ход/",212725,null],[232616,"2026-09-23T18:34:27",22,"Краб пугал девушку до ужаса. Ещё и эти глаза... золотые глаза.. появилась четвёртая пара...\n\n- Нет нет нет... - шептала Ясмин. Она зажмурилась и сложила руки в молитвенном жесте, призывая свет на помощь.\n\nСпал лвк 14 Священный свет",212725,null],[232619,"2026-09-23T18:34:47",22,"//кое кто не догадался взять нормальные заклинания, ход",212725,null],[232621,"2026-09-23T18:34:54",31,"/roll d20+4 краб уворачивается от света",212725,null],[232624,"2026-09-23T18:35:02",31,"Краб ловок",212725,null],[232625,"2026-09-23T18:35:19",22,"Краб ходит/",212725,null],[232626,"2026-09-23T18:35:40",31,"/roll d6 бросок на спецспособность",212725,null],[232628,"2026-09-23T18:35:45",31,"Не прошло/",212725,null],[232630,"2026-09-23T18:35:59",31,"/roll d20+5 атака клешнёй по Беатриче",212725,null],[232634,"2026-09-23T18:36:17",20,"/она уворачивается, с помехой)",212725,null],[232635,"2026-09-23T18:36:31",31,"От Крита?/",232634,null],[232640,"2026-09-23T18:36:54",31,"А хотя да, ты права, очерёдность должны быть",212725,null],[232643,"2026-09-23T18:37:22",20,"/клац клац был очень близко...",212725,null],[232644,"2026-09-23T18:37:24",31,"Клещня безуспешно щёлкает перед девушкой",212725,null],[232647,"2026-09-23T18:37:36",31,"/roll d20+3 атака жвалами",212725,null],[232649,"2026-09-23T18:37:50",31,"И жвала мимо, крабик тот еще мазила",212725,null],[232650,"2026-09-23T18:37:52",31,"Ход",212725,null],[232653,"2026-09-23T18:38:44",20,"/r d20+5 Беатриче упертая, снова пытается забраться на краба",212725,null],[232658,"2026-09-23T18:39:14",31,"Беатриче с гиканькм совершает невероятный по красоте прыжок и оказывается на башке крабика",212725,null],[232661,"2026-09-23T18:40:14",20,"*Оказавшись наверху она перехватывает рапиру поудобней и наносит удар прямо в этот крайне подозрительный кристалл*",212725,null],[232663,"2026-09-23T18:40:20",20,"/r d20+5",212725,null],[232666,"2026-09-23T18:40:28",31,"Попала",212725,null],[232668,"2026-09-23T18:40:35",20,"/r d8+3",212725,null],[232674,"2026-09-23T18:41:14",20,"/r d20+5 может хоть кинжалом получше пойдет",212725,null],[232679,"2026-09-23T18:41:23",20,"/реально пошло",212725,null],[232688,"2026-09-23T18:42:09",20,"/r 2d4+3 тыкаем в ядро с попеременным успехом",212725,null],[232692,"2026-09-23T18:42:35",20,"/конец хода",212725,null],[232697,"2026-09-23T18:42:55",31,"Краб пытается стихнуть девушку в конце ее хода",212725,null],[232698,"2026-09-23T18:43:10",31,"Соревнование атлетика от краба ловкость от тебя",212725,null],[232699,"2026-09-23T18:43:15",31,"/roll d20+5",212725,null],[232701,"2026-09-23T18:43:21",20,"/r d20+5",212725,null],[232707,"2026-09-23T18:43:32",31,"Ты удержалась на крабе",212725,null],[232708,"2026-09-23T18:43:38",31,"Ход Марко/",212725,null],[232710,"2026-09-23T18:44:04",20,"*Беатриче участвует в импровизированном родео. Выглядит довольной*",232707,null],[232717,"2026-09-23T18:46:25",31,"Ребята, был бы очень рад если бы уложились в течение часа следующего, чтобы на утро не переносить. Крьб лох, убивайте кго/",212725,null],[232733,"2026-09-23T18:53:45",17,"Марко сократил дистанцию. Молча. Быстро.\n\nОдна из его рук превратилась в черные когти и он пронзил из в металлическую оболочку краба",212725,null],[232734,"2026-09-23T18:53:51",17,"/r +5 Наносим раны",212725,null],[232737,"2026-09-23T18:54:22",17,"/ Так ну тут на откуп мастера Крит провал. Ход окончен",212725,null],[232738,"2026-09-23T18:54:53",31,"Реакция",212725,null],[232740,"2026-09-23T18:55:03",31,"/roll d20+3 жвалами",212725,null],[232742,"2026-09-23T18:55:08",31,"Попал?",212725,null],[232743,"2026-09-23T18:55:24",17,"/ Нет конечно три консервные банки по 18 КД",212725,null],[232744,"2026-09-23T18:55:38",31,"У сюка/",212725,null],[232745,"2026-09-23T18:55:43",31,"Ход Ясмин",212725,null],[232746,"2026-09-23T18:56:03",31,"@lady_godzilla",212725,null],[232755,"2026-09-23T19:05:42",22,"Свет покинул меня.. я сделала слишком много зла..",212725,null],[232756,"2026-09-23T19:05:49",22,"Яссмин достаёт арбалет",212725,null],[232757,"2026-09-23T19:06:05",22,"/r +4\n/r d8",212725,null],[232759,"2026-09-23T19:06:13",22,"/ход, сорри, только до дома дошла, постараемся закончить бой",212725,null],[232760,"2026-09-23T19:06:38",22,"@QURTZZ",212725,null],[232765,"2026-09-23T19:07:34",31,"/roll d6 на перезарядку способности",212725,null],[232767,"2026-09-23T19:07:39",31,"О, прошло",212725,null],[232770,"2026-09-23T19:08:59",31,"Крабик гудит, его мощная гидравлика в ногах включает турбо режим и он оббегает Марко без провоцированной атаки и нападёт на Ясмин",212725,null],[232772,"2026-09-23T19:09:10",22,"Вспышка",212725,null],[232773,"2026-09-23T19:09:12",31,"/roll d20+5 клешней",212725,null],[232775,"2026-09-23T19:09:30",31,"Это что?/",232772,null],[232780,"2026-09-23T19:10:14",22,"- Свет, защити меня!\n\nПеред Ясмин вспыхивает свет. Бросок атаки по ней с помехой.",212725,null],[232782,"2026-09-23T19:10:24",22,"Мимо",212725,null],[232785,"2026-09-23T19:10:40",31,"/roll d20+3 атака жвалами",212725,null],[232788,"2026-09-23T19:11:09",31,"/roll d8+3 крабик бросается на Ясмин в попытке перекусить ее пополам",212725,null],[232790,"2026-09-23T19:11:30",22,"Перекусил.\n\nЯсмин вскрикнула и упала без сознания.",212725,null],[232791,"2026-09-23T19:11:59",31,"Жаль, хотел выбить 9 и дать тебе возможность пройти спас мудрости и пробудить каргу/",212725,null],[232792,"2026-09-23T19:12:03",31,"Ход/",212725,null],[232793,"2026-09-23T19:12:14",22,"@PaIIasCat",212725,null],[232796,"2026-09-23T19:13:32",31,"Если поднимешься с 1хп, то что будешь спас мудрости кидать)/",232790,null],[232799,"2026-09-23T19:16:14",17,"/ Ясмин забыл свой щит и чешуйчатый доспех) Щас поднимем",212725,null],[232801,"2026-09-23T19:18:00",22,"/У меня арбалет же, щит нечем держать. А доспех такой не брала.. я билд чисто по ролеплею собирала, надеюсь, что не буду в итоге обузой😒",232799,null],[232802,"2026-09-23T19:18:17",31,"Уважаю такой подход/",232801,null],[232805,"2026-09-23T19:19:57",20,"- Ах ты Stronzo! *Беатриче в гневе из-за нападения на союзника снова бьёт по ядру*",232793,null],[232806,"2026-09-23T19:20:21",20,"/r d20+5 рапира\n/r d20+5 кинжал",212725,null],[232808,"2026-09-23T19:20:29",31,"Кинжал прошёл",212725,null],[232810,"2026-09-23T19:20:37",20,"/мда, не везёт рапире",212725,null],[232811,"2026-09-23T19:20:55",20,"/r d4+3",212725,null],[232814,"2026-09-23T19:21:16",31,"Опять соревнование атлетики и акробатики",212725,null],[232815,"2026-09-23T19:21:30",20,"/то что бью по ядру заметно хоть? Или это просто урон такой же как обычные атаки?",212725,null],[232816,"2026-09-23T19:21:38",31,"/roll d20+5 атлетика крабика",212725,null],[232818,"2026-09-23T19:21:39",20,"/r d20+5",232814,null],[232820,"2026-09-23T19:21:57",31,"Опишу после твоего хода/",232815,null],[232822,"2026-09-23T19:22:19",31,"Ты опять удержалось",212725,null],[232824,"2026-09-23T19:22:52",20,"/конец хода получается",212725,null],[232830,"2026-09-23T19:23:18",31,"Кристалл на спине крабика начинает покрываться сетью трещинок, го все ещё ярко горит. Пока что эти повреждения никак не сказываются на крабике",212725,null],[232832,"2026-09-23T19:23:44",31,"Ход Марко",212725,null],[232835,"2026-09-23T19:24:28",31,"У них общий хп, но у кристалла есть свое. Не знаю как еще объяснить/",232815,null],[232840,"2026-09-23T19:27:23",31,"@dunchev",212725,null],[232871,"2026-09-23T19:38:01",17,"/ Все замечательно)",232801,null],[232874,"2026-09-23T19:41:08",17,"/ А мы же 1 уровня. Ячеек на хил нету сори.",212725,null],[232875,"2026-09-23T19:41:48",17,"Марко разводит руки и хлопает в ладоши \n\nДве черные когтистые лапы сдавливают корпус краба с двух сторон",212725,null],[232876,"2026-09-23T19:42:05",17,"/r +5 q +5 q А попадание там одно",212725,null],[232878,"2026-09-23T19:42:18",17,"/r d8 Неуро",212725,null],[232880,"2026-09-23T19:42:39",22,"//ячейки потрачены на ролеплей, все отлично👍",232874,null],[232885,"2026-09-23T19:43:53",17,"/ Перепроверил. За способность Жнец. Попадание одно а цели может быть две в 5 футах друг от друга",212725,null],[232886,"2026-09-23T19:44:03",17,"/r d8 Вот ещё раз ты разрешил",212725,null],[232888,"2026-09-23T19:44:25",31,"крабик насмешливо скрипит/",212725,null],[232890,"2026-09-23T19:44:37",22,"/r Спас от смерти",212725,null],[232892,"2026-09-23T19:44:48",31,"Один провал/",212725,null],[232893,"2026-09-23T19:45:06",22,"/Понеслась душа в рай",212725,null],[232895,"2026-09-23T19:45:08",31,"/roll d20+5 клешней по Марко",212725,null],[232897,"2026-09-23T19:45:29",31,"Крит провал, разрешаю атаку реакций",212725,null],[232898,"2026-09-23T19:45:47",17,"/r +4 Атака реакцией",212725,null],[232900,"2026-09-23T19:45:48",31,"@dunchev",212725,null],[232901,"2026-09-23T19:45:53",31,"Мимо",212725,null],[232905,"2026-09-23T19:46:05",31,"/roll d20+3 жвала к бою",212725,null],[232907,"2026-09-23T19:46:13",31,"Ух бля/",212725,null],[232908,"2026-09-23T19:46:43",31,"/roll 2d8+3 ням ням",212725,null],[232911,"2026-09-23T19:46:50",17,"/ Я все",212725,null],[232914,"2026-09-23T19:47:24",31,"Крабик довольно скрежещет",212725,null],[232916,"2026-09-23T19:47:34",20,"/ой ой",212725,null],[232917,"2026-09-23T19:47:38",31,"/Беатриче",212725,null],[232919,"2026-09-23T19:48:21",20,"/ну чё, поднять никого я не могу - пробуем добить. В два раза яростней из за павших товарищей",212725,null],[232920,"2026-09-23T19:48:22",17,"Жвала пронзили грудь Марко и он рухнул неподалеку от Ясмин\n\nЧерная голова шкала схлынула с его головы и лица как будто дым",212725,null],[232921,"2026-09-23T19:48:37",31,"Жвала, не клешня/",232920,null],[232922,"2026-09-23T19:48:50",20,"/r d20+5 кинжал \n/r d20+5 рапира",212725,null],[232925,"2026-09-23T19:49:02",31,"Все мимо",212725,null],[232926,"2026-09-23T19:49:16",20,"/фига",212725,null],[232927,"2026-09-23T19:49:17",31,"Кажется, вам кабзда",212725,null],[232929,"2026-09-23T19:49:29",20,"/удача, пробую ещё раз ударить",212725,null],[232930,"2026-09-23T19:49:39",31,"Давай",212725,null],[232931,"2026-09-23T19:49:45",20,"/r d20+5 🙏",212725,null],[232934,"2026-09-23T19:49:58",20,"/ну чтож...",212725,null],[232935,"2026-09-23T19:50:02",20,"/бей",212725,null],[232936,"2026-09-23T19:50:08",31,"/roll d20+5 атлетика",212725,null],[232938,"2026-09-23T19:50:15",20,"/r d20+5",212725,null],[232939,"2026-09-23T19:50:15",31,"Кидай соревнование",212725,null],[232941,"2026-09-23T19:50:23",31,"Удержалась",212725,null],[232942,"2026-09-23T19:50:30",31,"Ход гоблина/",212725,null],[232943,"2026-09-23T19:51:03",31,"/roll +d20+3 в крабика летит кирпич",212725,null],[232945,"2026-09-23T19:51:18",31,"/roll d4+1",212725,null],[232948,"2026-09-23T19:51:41",31,"Гоблин орёт:\n\n- Крабик, мы же друзья, не надо так!",212725,null],[232952,"2026-09-23T19:52:06",31,"Крабик атакует гоблина",212725,null],[232954,"2026-09-23T19:52:14",31,"/roll d20+5",212725,null],[232957,"2026-09-23T19:52:26",20,"/гоблин живи",212725,null],[232958,"2026-09-23T19:52:27",31,"/roll d6+3",212725,null],[232961,"2026-09-23T19:52:41",31,"/roll d20+3 жвала по гоблину",212725,null],[232963,"2026-09-23T19:52:50",31,"/roll d8+3",212725,null],[232965,"2026-09-23T19:52:59",31,"И гоблин пал",212725,null],[232966,"2026-09-23T19:53:07",31,"Беатриче, ход",212725,null],[232972,"2026-09-23T19:53:33",31,"Одно хорошее попадание по кристаллу/",212725,null],[232975,"2026-09-23T19:53:48",20,"/r d20+5 кинжал \n/r d20+5 рапира, ДАВАЙ",212725,null],[232976,"2026-09-23T19:53:49",31,"Бля, спойлер",212725,null],[232979,"2026-09-23T19:54:02",31,"Рапра прошла",212725,null],[232980,"2026-09-23T19:54:11",20,"/r d8+3 ДАВАЙ",212725,null],[232982,"2026-09-23T19:54:29",31,"Описывай как разбился кристалл и упал конструкт",212725,null],[233000,"2026-09-23T20:01:33",20,"*Беатриче видит, на краю за пару ударов повергает ее товарищей и даже того бедного гоблина, что пытался в последний момент помочь*\n\n*Ярость застилает ей глаза, накрывая приливом адреналина. Так не должно было быть, она должна была защитить их!*\n\n- НИКТО ЗДЕСЬ СЕГОДНЯ НЕ УМРЕТ КРОМЕ ТЕБЯ, MERDA! *Она роняет кинжал, перехватывая рапиру обеими руками и со всей силы вонзает в кристалл, наваливаясь всем весом и вбивая ее по рукоять*\n\n*Краб начинает заваливаться, но дампир не тратит время на триумф победы или вытаскивание застрявшей рапиры. Она спрыгивает с падающего краба и бежит к товарищам, падая на колени рядом с Марком и начиная быстро рыться в его сумке. Ну же, ты ведь все это время был таким предусмотрительным сеньор...*",212725,null],[233001,"2026-09-23T20:01:43",20,"/комплект целителя есть?",212725,null],[233002,"2026-09-23T20:02:32",31,"/roll d20 спас гоблина от смерти",212725,null],[233005,"2026-09-23T20:03:07",31,"Внимание кинь",233001,null],[233006,"2026-09-23T20:03:18",20,"/r d20+3",233005,null],[233010,"2026-09-23T20:04:49",31,"Ты замечаешь поблизости осколок кристалла, который искрит. В твоей голове мелькает влсплминнет об опытах сиора Гальвани, что оживлял лягушек силой молнии\n Может и тут сработает?",212725,null],[233015,"2026-09-23T20:06:19",20,"/ща мы вас будем реанимировать)",233010,null],[233016,"2026-09-23T20:06:47",20,"/ну пробуем, почему нет",212725,null],[233017,"2026-09-23T20:06:54",31,"Проверка медицины с преимуществом от реанимации",212725,null],[233023,"2026-09-23T20:07:29",20,"/r +d20+1 реанимируем Ясмин",212725,null],[233027,"2026-09-23T20:07:42",31,"Ясмин открывает глаза",212725,null],[233028,"2026-09-23T20:07:50",20,"/r +d20+1 реанимируем Марко",212725,null],[233030,"2026-09-23T20:07:56",20,"/бля",212725,null],[233031,"2026-09-23T20:08:06",31,"Марко получает провал",212725,null],[233032,"2026-09-23T20:08:07",20,"/надеюсь ещё один ход есть",212725,null],[233033,"2026-09-23T20:08:21",31,"Еще один повал он переживет",212725,null],[233035,"2026-09-23T20:08:26",31,"Рискнёшь?",212725,null],[233036,"2026-09-23T20:08:43",31,"Тут еще и жр ца света есть",212725,null],[233037,"2026-09-23T20:08:56",20,"/у Ясмин остались ячейки? Лечи скорее!\n\n- Сеньорита, нужна помощь - скорее!",212725,null],[233039,"2026-09-23T20:09:43",31,"/roll d20 второй спас гоблина",212725,null],[233041,"2026-09-23T20:09:54",20,"/r +d20+1 реанимируем пока гоблина",212725,null],[233043,"2026-09-23T20:10:04",20,"/мда ...",212725,null],[233044,"2026-09-23T20:10:08",31,"Гоблин получает второй провал",212725,null],[233048,"2026-09-23T20:11:06",31,"@lady_godzilla спасай)/",212725,null],[233078,"2026-09-23T20:24:28",22,"/Ячеек нет, комплекта целителя тоже нет",212725,null],[233082,"2026-09-23T20:24:54",22,"/ладно, включаем воображение, требую у мастера характер ран",212725,null],[233083,"2026-09-23T20:25:01",20,"/Хватай осколок и с преимуществом медициной пробуй",233078,null],[233084,"2026-09-23T20:25:03",22,"/будем использовать, то что есть",212725,null],[233089,"2026-09-23T20:26:00",31,"Раны от сильного сдавливания рулной клетки, возможно перелом ребер, которые проткнули легкие или другие кю органы",233082,null],[233092,"2026-09-23T20:26:22",22,"/марко же лечим?",212725,null],[233093,"2026-09-23T20:26:35",31,"Да",212725,null],[233094,"2026-09-23T20:26:45",31,"Гоблин то хер с ним/",212725,null],[233095,"2026-09-23T20:27:00",20,"/Марко ещё один провал пережить может",212725,null],[233096,"2026-09-23T20:27:01",22,"на гоблина есть план, но позже, пишу пост/",233094,null],[233119,"2026-09-23T20:32:10",22,"Ясмин дрожа подползла на коленях к осколку и положила рядом с телом товарища. Потом она развернула свои инструменты ювелира и стала аккуратно вытаскивать осколки костей. \n\nТам, где вынуть инородные предметы не получалось, она с помощью инструментов плотника отпиливала лишнее.\n\nНет.. он не дышит..\n\nНеудачница!\nУбийца!\nМясник!\n\n- Живи, свет, умоляю, пусть он будет жить! \n\nЯсмин стояла на коленях и ревела, судорожно вытряхивая все из своей сумки. К ее ногам подкатилась ее флейта. Не думая ни секунды, она плотницким резаком заострила флейту и вонзила ее прямо в грудь Марко, который не мог дышать из-за сдавленной груди.\n\n\\\\у меня есть медицинское образование! Я смотрела все сезоны доктора Хауса, Хорошего доктора и дораму Призрачный доктор! Очень рассчитываю на автоуспех🙏\n\nЯ готовилась к этому испытанию всю жизнь!",212725,null],[233125,"2026-09-23T20:34:37",31,"Ну вообще надо не в шрудь, а в трахею. Но из уважения к образованию я принимаю это описание)) Марко стабилизироваг)",212725,null],[233128,"2026-09-23T20:35:02",31,"Гоблина спасаете?/",212725,null],[233132,"2026-09-23T20:35:39",20,"/спасаем, там заявка была у Ясмин тоже",233128,null],[233133,"2026-09-23T20:36:16",22,"Да, потом гоблина так же реанимируем, но без трубки, иначе Марко дышать не сможет/",212725,null],[233136,"2026-09-23T20:36:38",22,"/r +6 медицина на гоблина",212725,null],[233138,"2026-09-23T20:36:50",20,"/с преимуществом",212725,null],[233139,"2026-09-23T20:36:51",22,"/что и следовало доказать про мои броски",212725,null],[233142,"2026-09-23T20:37:22",20,"/сегодня было какое-то проклятие 9",212725,null],[233145,"2026-09-23T20:37:39",31,"Гоблин тяжело с присвистом дышит, но приходит в себя",212725,null],[233150,"2026-09-23T20:38:19",31,"- Крабик, почему?..\n\nПредательство друга едва не довело гоблина до слез",212725,null],[233155,"2026-09-23T20:39:10",31,"- вы меня спасли... Зачем? Я же вас в ловушку привел?",212725,null],[233159,"2026-09-23T20:40:16",22,"Ясмин не отвечает, доверив общение Беатрис.",212725,null],[233161,"2026-09-23T20:40:46",22,"Она трясущими руками продолжала аккуратно извлекать осколки из Марко.",212725,null],[233187,"2026-09-23T20:43:52",20,"- Мы следователи, а не палачи.\n\n*Бросает Беатриче, с тревогой наблюдая как Ясмин ухаживает за ранами Марко. Вроде жив - это главное*\n\n- Да и остались у нас к тебе вопросы.",233155,null],[233196,"2026-09-23T20:45:02",31,"- я все расскажу. Меня зовут Нак-Нак, кстати",212725,null],[233200,"2026-09-23T20:47:27",20,"/кто там",233196,null],[233206,"2026-09-23T20:48:08",31,"Ладно, завтра закончим, я уже спать хочу/",212725,null],[233251,"2026-09-23T20:57:19",17,"Первой его встретила старая подруга. Боль.\n\nИз флейты выплеснулось немного крови и Марко медленно начал снова дышать.\n\nОн открыл глаза, тонкие щели в которые ударил свет. Он ослеплял, поэтому следователь предпочел из сразу же зажмурить.\n\nОн чувствовал, что кто то тянет из него осколки.\n\nСил не осталось даже стонать. \n\nСтарая подруга приучила его к смирению.",212725,null],[233394,"2026-09-23T21:51:43",17,"Соленые слезы Ясмин капали в свежую рану на животе. \n\nМарко дрожащей рукой достал из внутреннего кармана свой платок. Тот самый с вышивкой. И протянул его Ясмин\n\n— Вы.. Вытри слезы, синьора... Жжется...\n\nТихо простонал он",212725,null],[233403,"2026-09-23T21:56:02",22,"- Я-я н-не реву-у-у!\n\nПроревела Ясмин, принимая, платок.",212725,null],[233408,"2026-09-23T22:00:02",22,"- Н-не шевелитесь! О-отдыхайте. \n\nЯсмин разорвала свое сари. Анчал она свернула и положила Марко под голову. А лоскуты из нижней юбки были использованы вместо бинтов.\n\n- Не шевелитесь. О-отдыхайте. Завтра б-будет легче.\n\nЯсмин была настолько встревожена чужой судьбой, что даже летающие золотые глаза, мерзкий хохот и мысли родственничков отошли на задний фон.",212725,null],[233414,"2026-09-23T22:08:07",20,"*Беатриче подходит чуть ближе, передавая Ясмин флягу - то самое L’Elisir dei Visconti. Хотя сейчас это явно был не знак рода или хорошее вино*\n\n- Вот, оно достаточно крепкое - подойдёт для обработки ран",233408,null],[233415,"2026-09-23T22:09:12",20,"*Девушка явно хотела помочь, но не знала как - не хватало познаний в медицине*\n\n- Возьмите мой плащ - еще повязки лишними не будут. Доверяю это вам, сеньорита",212725,null],[233416,"2026-09-23T22:11:40",22,"- Н-нет! Он крепкий мужчина. Он справится! П-прикройтесь п-пожалуйста. Вы же леди, ваша честь м-может пострадать!\n\nЯсмин приняла вино и продолжила обработку ран.",233415,null],[233419,"2026-09-23T22:23:00",17,"В голове Марко тишина. Все звуки заглушены.\n\nСердцебиение. \n\nДва громких удара по ушным перепонкам. \n\nБам\n\nБАМ\n\nНе его сердце.\n\nИ вечно усталый голос\n\n\"ГОБЛИН \n\nДОЛЖЕН \n\nУМЕРЕТЬ\"\n\nМысленный ответ\n\n\"Нет\"\n\n\"ТЫ СЛАБ\n\nЖАЛОК\n\nМИЛОСЕРДЕН\"\n\nСнова ответ\n\n\"Только последнее правда\"\n\n\"НЕ МЕШАЙ МНЕ\"\n\n\"У тебя нет власти надо мной\"\n\nТишина на мгновение, и тут же ее разбивает слова Ясмин\n\n\"Завтра будет легче?\"\n\nЛёгкая усмешка на лице искаженном болью\n\n\"Врятли\"",212725,null],[233420,"2026-09-23T22:23:45",17,"/ Думаю после этого перебинтованый я прихожу в себя.",212725,null],[233425,"2026-09-24T05:30:56",31,"Итак, раненые пришли в себя, больше никто не умирает. Нак-Нак смотрит на вас как на какое то чудо природы, что не стало оставлять гоблина на смерть и заявляет:\n\n- может, чайку?\n\nИ не дожидаясь ответа, принимается шерудить у очага. Откуда то достает чайник, на удивление чистый, сыпет туда из мешочка сухую заварку и дождавись кипятка в чайнике, заливает ее. Откуда то притаскивает пяток щербатых кружек и разливает напиток, предлагая его вам. По запаху вроде чай с какими то травами, судя по всему, с мятой или мелиссой. \n\nПока гоблин занят приготовлением чая, а Ясмин хлопочет над раненным Марко, Беатриче прохаживается по складу. Ее внимание привлекают остатки кристалла, что питал Крабика. Осколки продолжают вспыхивать инфернальным светом и искрить. Беатриче не очень понимает, что это вообще за дрянь, но решает что лучше бы её тут не оставлять. Да и Феллино, возможно, заинтересуется.\n\nОстанки Крабика, что был сварен из листов металла и дварфовских клещей, лежат грудой обломков. Похоже, чтобы вернуть Дварфам их имущество разом, вам потребуется повозка. Все таки с теми травмами, что получили Ясмин и Марко, не стоит таскать тяжести,\n\nТакже Беатриче понимает, что склад это не просто мусорная свалка и жилье гоблина. Это очень похоже на мастерскую механика, просто очень запущенную. Так бы мог жить и работать чудаковатый гном-изобретатель, что полностью игнорирует гигиену, а от гоблина такого ждать было бы сложно. Но грубоватые швы на металле все таки выдают - это работа гоблина, любой гном удавился бы от стыда из-за такой халтуры.\n\nНа рабочем столе лежит несколько свитков, похоже, Крабик собирался не по наитию, а по рассчетам и чертежам.",212725,null],[233498,"2026-09-24T08:26:38",22,"- Беатриче, как на счёт т-того, чтобы отдохнуть здесь, утром направимся  к Ф-феллино.. Я м-могу первая по д-дежурить, а ты меня потом с-сменишь. З-заодно вытащу ф-флейту из Марко, ему уже л-лучше.\n\nВиски пульсировали, а тремор становился все сильнее. Ясмин прижала трясущиеся конечности к груди, но меньше дрожать они не стали.",212725,null],[233521,"2026-09-24T08:32:54",20,"- Не стоит, Сеньорита. Пейте чай и ложитесь спать - я сама посторожу до утра. *Беатриче помогает расстелить спальник из своей сумки*\n\n- Вы и так многое пережили, чудо что сами все ещё на ногах. Утром как проснетесь я схожу за повозкой.",233498,null],[233574,"2026-09-24T09:16:40",31,"Гоблина будете о чем то спрашивать, или просто все на длогий отдых падаете? Что вообще будете делать с ним, ворюгой?/",212725,null],[233577,"2026-09-24T09:18:05",22,"Ясмин кивнула. Прежде она вытащила флейту и тела Марко, а после легла спать.\n\nСон был крайне неспокойный. Девушка периодически скулила и тихо вскрикивала.\n\n- Не надо.\n- Отпустите.\n- ПРОЧЬ!\n\nПоследнюю фразу она практически выкрикнула. Сев в спальнике, Ясмин тяжело дышала, а по ее лицу струился пот.\nПосмотрев на освещение, девушка поняла, что уже раннее утро. Она тихонько осмотрела Марко и, убедившись, что тот в порядке, решила разыскать вчерашнего гоблина и заодно осмотреть всю эту комнату.\n\n\n//я прописываю скип, тк Ясмин по идее уже совсем не але, тут как то не до разговоров",212725,null],[233604,"2026-09-24T09:30:20",17,"Марко пришел в себя только после долгого отдыха \n\nЯсмин спасла ему жизнь, Беатриче устранила угрозу. Он чувствовал себя обязаны обоим. \n\nПоднявшись с пола он первым делом прижал руку в перебинтованому животу\n\nЯсмин беспокойно спала гоблин тоже, а Беатриче он заметил на посту сидящую на стуле\n\nОн махнул ей рукой и выдавил улыбку в знак того то вс нормально\n\nПрижал ладонь к животу, она чуть начала пульсировать золотым сиянием. Вокруг поднялись будто бы песчинки ставшие блёстками\n\nВнутри кости восстанавливались, ткани сростались.\n\nИ после он наконец вздохнул глубоко. \n\nВстал и подошёл к дампиру\n\n— Что удалось понять пока я лежал в отключке, синьора? \n\nОн кивнул на чертежи и осколки камня искрящиеся на столе",212725,null],[233614,"2026-09-24T09:35:09",20,"- Лишь то, что что-то темное в этом кристалле, всю ночь напролет продолжал сиять этим инфернальным светом. Ну и током бьётся. *Отвечает Беатриче, косясь на кристалл*\n\n- Я в таком не особо разбираюсь, оставила вам как придёте в себя. За гоблином тоже присмотрела - вон он, не сбежал.",233604,null],[233622,"2026-09-24T09:37:02",20,"- Что планируете с этим делать, Синьор Марко? *Она указывает в целом на все - кристалл, клещи, гоблин...*\n\n- Я могла бы пойти за повозкой - переведем клещи дварфам. Кристалл тоже можно доставить на изучение синьору Феллино. Командуйте",212725,null],[233634,"2026-09-24T10:39:58",17,"— Никогда с таким не сталкивался. Думаю нам нужно отнести осколки сеньору Неро. Вместе с новостями по делу о воре клещей. \n\nМарко смотрит на чертежи и на криво спаяного но рабочего конструкта \n\n— Это все создал гоблин?",212725,null],[233636,"2026-09-24T10:57:30",17,"/ Давайте отвезем гоблина к Неро. Дварфам дадим адрес пусть сами заберут своё железо?",212725,null],[233640,"2026-09-24T11:12:35",20,"- Похоже на то - можем спросить его об этом по пути. Нужно узнать откуда он достал этот жуткий кристалл",233634,null],[233645,"2026-09-24T11:34:27",22,"Ясмин проснулась. Голова гудела, но в целом она чувствовала себя отдохнувшей. Настолько, насколько это вообще было возможно. \n\n- Чертежи.. Этот гоблин гениален.. П-по своему. Давайте прихватим кристалл, чертежи и самого мелкого и направимся к Него. А ж-железки, вы правы, пусть сами таскают.",212725,null],[233646,"2026-09-24T11:37:50",31,"итак, вы тащите гоблина к Неро, верно?/",212725,null],[233648,"2026-09-24T11:42:48",31,"Разбудив Нак-Нака и прихватив осколки кристалла вы отправились вместе с гоблином в контору сыщика. Также вы прихватили с собой следующее:\n\n— \"Накладные подошвы\" (свиток устройство изобретателя с заклинанием \"прыжок\")\n— \"Тонкая ниточка с колокольчиком\" (свиток устройство изобретателя с заклинанием \"сигнал тревоги\")\n\n//Напомню что изобретатель делая свитки в виде устройств дает возможность ипользовать их кому либо\n\n— Рецепт \"Искатель голоса\"\n— Рецепт \"Сфера направления\"\n— Рецепт \"Протез\"\n\nТакже вы нашли склянку с зельем, что пахло одновременно дохлой кошкой и палубным лаком. Нак-Нак пояснил, что это такой гоблински аналог Зелья бдительного отдыха",212725,null],[233649,"2026-09-24T11:43:13",31,"чутка лута вам/",212725,null],[233651,"2026-09-24T11:44:19",22,"//полезный парень. Будь мы в пф, я бы уже бежала за чертой, которая делает его подручным. Чтобы свитки клепал",212725,null],[233654,"2026-09-24T11:47:17",31,"Ваша пестрая компания не сильно выделялась на фоне народа, что курсировал по Вальдории в это утро. Никем не остановленные, вы добрались до конторы Неро. Сыщик принял вас, оценивающе глянул на гоблина, но сразу ничего не сказал о нем. Налив вам кофе, а себе любимого ликера, табакси обратился к вам:\n\n- итак, друзья мои, судя по вашему внешнему виду, дело оказалось не столь простым, как я предполагал? Или оно еще не закончено? Расскажите, я весь во внимание.",212725,null],[233659,"2026-09-24T11:48:32",31,"Ну на то и расчет был у меня. Но вы и без черты можете обойтись, чтобы с ним подружится/",233651,null],[233687,"2026-09-24T11:58:16",22,"Ясмин сбивчиво пересказывает информацию о гоблине, крабике, клещах и смотрит на товарищей, если они вдруг хотят что-то добавить о кристалле и чертежах.",233654,null],[233692,"2026-09-24T11:59:46",20,"- Кристалл бьётся током *дополняет Беатриче таким тоном, будто это критично важная информация*",233687,null],[233714,"2026-09-24T12:10:44",31,"- Кристалл бьётся током... Ага... Ну, я советую вам оставить самый большой из кусков себе, мало ли когда пригодится проводить реанимационные действия в будущем. А мелкие осколки давайте сюда. Есть у меня эксперт, что разберутся с происхождением этой штуки\n\n//вы получаете на группу:\n\nРеанимационный осколок кристалла - заряженный непонятной силой кристалл, что может быть током. При использовании проверки медицины вы получаете преимущество для поднятия павшего товарища. Один раз за долгий отдых//",212725,null],[233716,"2026-09-24T12:12:13",22,"//ура! Воскрешательный аппарат! Я буду кричать, \"Сестра, разряд!\"",233714,null],[233718,"2026-09-24T12:12:34",31,"- теперь, относительно тебя, гоблин...\n- Нак-Нак - гоблин не стесняется перебивать\n- хорошо, относительно тебя, Нак-Нак. Зачем тебе было создавать такую опасную штуку? И где ты взял кристалл для его запитки?",212725,null],[233784,"2026-09-24T12:30:21",31,"Гоблин смотрит на табакси с прищуром и выдает:\n\n- Крабик должен был защитить меня. Ты, большой кот, не знаешь, как живем мы, городские гоблины. Мы все время боимся, все время прячемся, нас гоняют как зверей и убивают ради забавы. Мы постоянно слышим голоса за спиной. Недобрые голоса. Вся моя община, та что жила рядом с моим складом... Их всех убили, одним днем. Просто пришли и убили, как лис на охоте, использовали как мишени для стрел и манекены для копий. Я выжил только потому, что в тот дегь ходил к гномам, хотел наняться на работу, я хотел честно зарабатывать, я умея мастерить лучше любого гоблина в городе. Да может и лучше гнома. А они посмеялись надо мной и выгнали, сказали что гоблину только крысоловки мастерить. Я вернулся домой и увидел что все мои друзья, соседи и родственники мертвы. Это было очень страшно. А еще страшнее было когда я побежал к страже и вместо помощи получил пинок в лицо и смех. Я вернулся и похоронил своих близких там же, за складом. В братской могиле. И там же я себе пообещал, что меня так просто не убьют, я найду способ защитить себя. И других гоблинов. И я начал думать, кто может защитить меня, маленького и слабого. И придумал Крабика. Крабик сильный, о защитит. Но Крабик сошел с ума, хотя и не было у него ума, он же железный. Я не знал чем заставить его работать, и камень этот светящийся попался мне в катакомбах под канализацией. Я его подобрал, понял что он искру дает, и ее хватает для питания Крабику. А потом Крабик сошел с ума. Хоть и нет у него ума. Вы же наверное не поняли, зачем я клещи брал? Я уже потом понял свою ошибку, я плохо читаю, знаю что у крабиков есть клешни, да не так прочитал и стал клещи таскать. Чтобы клац-клац мой Крабик умел делать",212725,null],[233802,"2026-09-24T12:35:26",31,"Неро смотрит на гоблина добрую минуту, выслушав его монолог, затем оборачивается к вам:\n\n- что же, кажется теперь все ясно. Это ваше дело, от начала и до конца разгадки. Вам и решать, как поступать",212725,null],[233807,"2026-09-24T12:45:45",22,"//жду решения товарищей. Как игрок я бы уже стала вербовать. \nНо у Ясмин в голове карнавал, так что ей точно не до этого",212725,null],[233810,"2026-09-24T12:48:24",31,"что то написал монолог гоблина, сам сижу глаза вытираю/",212725,null],[233827,"2026-09-24T12:59:02",20,"*Беатриче молчит, слушая историю этого маленького зелёного изобретателя*\n\n*В душе бушует праведный гнев - как кто-то посмел совершить подобное злодеяние против невинных? Как стража могла закрыть на это глаза?!*\n\n*Кража для нее уже отошла на второй план, сейчас она пылала  возмущением. И сочувствием - сама ведь недавно потеряла близкого человека*\n\n- В стремление защитить себя и близких нет ничего неправильного. Я не могу здесь судить. *отвечает она*\n- Конечно это не оправдывает воровство, но в этом случае я от своего имени буду просить о снисхождении к его судьбе.  Можно найти выход помимо сдачи страже.\n\n- Клещи всегда можно вернуть - а вот близких уже нет...",233802,null],[233847,"2026-09-24T13:09:32",31,"Неро хитро улыбается в усы:\n\n- ладно, я решу вопрос с дварфами, останки Крабика им доставят, пусть сами выковыривают из него свои клещи. Просто чтобы не скомпрометировать место жительства Нак-Нака. Что до тебя, Нак-Нак, тебе стоит прекратить промышлять воровством, тем более серийным. Если ты и правда так хорош, как механик, то я дам тебе возможность наращивать клиентскую базу, отправлю к тебе пару заказчиков, а ты уж постарайся не подставить меня и мое слово. Ну и думаю, справедливо будет, если твои услуги для моих агентов будут оплачиваться со скидкой. Ты согласен?\n\nГоблин кивает.\n\n- Вот и хорошо. Все живы, здоровы и при деле. Очень хорошо.\n\nОбращается к героям:\n\n- ну что же, вы успешно справились с заданием, я в вас и не сомневался. вот ваша награда, стандартная такса, по 50 золотых на каждого\n\n//вы получаете 50 золотых монет каждый. Первая арка закрыта. Вы получаете также по 800 очков опыта: 200 за стартовые мини-квесты, 300 за закрытие дела, 100 за победу в бою и 200 за отыгрыш персонажей.//\n\n//Нак-Нак теперь может мастерить что то для вас со скидкой, как вы уже поняли, его класс - изобретатель. Возможно в дальнейшем он сможет выдавать квесты//",233827,null],[233856,"2026-09-24T13:10:58",31,"//Все, закрыли арку, слава богу. Очень доволен, вы были великолепны в своих ролях и заявленных характерах. Надеюсь, вторая арка получится поинтереснее в плане загадок. Думаю, к ней приступим перез пару дней//",212725,null],[233859,"2026-09-24T13:11:29",31,"Неро на прощание говорит вам:\n\n- загляните ко мне завтра. Есть подвижки по делу Беатриче",212725,null],[233880,"2026-09-24T13:19:54",31,"лут из мастерской гоблина и реанимаионный кристалл сами разделите, кому что нужно//",212725,null],[233939,"2026-09-24T14:16:22",17,"— Нак нак. Коли ты теперь добропорядочный гражданин, подскажи мне пожалуйста. Тебе никогда не попадался вот такой черный песок?\n\nМарко достает стеклянную пробирку на дне которой небольшая горсточка черного песка. И демонстрирует гоблину.",212725,null],[234003,"2026-09-24T14:36:59",31,"Буду дома отвечу, отличный вопрос/",233939,null],[234113,"2026-09-24T15:18:41",31,"Нак-Нак протягивает руку, берет пробирку, смотрит ее на свет, поднимает на тебя недоуменный взгляд. \n\nЗатем открывает пробирку, высыпает содержимое себе на руку, катает между ладонями. Еще один недоуменный взгляд на тебя.\n\nНаконец он достает из кармана толстенную лупу и рассматривает содержимое пробирки под лупой. После чего поворачивается к тебе и говорит:\n\n- Это проверка какая то? Это же не песок, это земля. Странная какая то, но точно земля, вон, гляньте сами через лупу.\n\nТы подходишь, смотришь через лупу и понимаешь что гоблин прав. Песчинки были бы одинаковыми, а то что ты видишь имеет разную форму и размер. Это и впрямь не песок, как думал и ты, и Неро. Это земля",233939,null],[235245,"2026-09-25T02:38:00",31,"@dunchev Коля, как сможешь, добей эту тему с песком землёй, это будет выход на побочный квест. Я без этого не смогу продолжить/",212725,null],[235246,"2026-09-25T02:50:58",17,"— Значит земля. Должно быть необычная...",212725,null],[235247,"2026-09-25T02:52:38",31,"Нае-Нак:\n\n- я в земле не разбираюсь. Только чую, что пахнет старостью. Вы лучше спросить у кого нибудь, кто старый. Или к земле близкий там",235246,null],[235248,"2026-09-25T02:54:20",17,"— Хм... Поищу кого нибудь.",212725,null],[235249,"2026-09-25T02:56:08",31,"//начат побочный квест: Близко к земле//\n\n/Квест не обязательно бежать и выполнять сейчас, проще будет дождаться удобной ситуации по ходу основного сюжета. И не забывать задавать вопросы/",212725,null],[235250,"2026-09-25T02:58:42",31,"Может быть сегодня продолжим основную линию, я ее переделал от изначального плана чуток. Если нет, то вероятнее всего уже в понедельник. Хотя если будут запросы на небольшие личные дела в период между основными квестами - то заявки принимаются. Может встретится с кем, или поискать дополнительную работу/",212725,null],[235256,"2026-09-25T08:48:43",31,"@dunchev @lady_godzilla @PaIIasCat \n\nИтак, вы покинули контору Неро Феллино. Он ждет вас завтра, а сегодня у вас целый свободный день, который можно потратить на свои дела. Чем планируете заняться?\n\n/Коля, не забудь уровень поднять/",212725,null],[235257,"2026-09-25T09:53:19",22,"- Это б-был такой тяжелый день вчера... Е-если сегодня нет дел, то я б-бы погуляля немного...\n\nОй гляньте, день у нее тяжелый был\nНе надорвалась, болезная?",212725,null],[235258,"2026-09-25T09:53:24",20,"*Беатриче выходит вместе со всеми, потягиваясь и щурясь на утреннее солнышко*\n\n- Неплохое начало дня, molto bene \n\n*Она поворачивается к компаньонами.*\n\n- Знаете как сделать его ещё лучше? Завтрак, miei amici! Вчера нам так и не удалось из-за спешки, но сегодня я настаиваю все же принять мое приглашение в Il Leone di Velluto.\n\n- Нет ничего полезнее чем начать день с бокала лёгкого вина. А уж за качества вина я могу там поручиться. Да и frittata у них к утру просто восхитительна!\n\n*Она поправляет ворот свежей белоснежной рубашки, принимая вид истинной аристократки*\n- Я угощаю, конечно же.",212725,null],[235259,"2026-09-25T09:54:39",22,"- О-отличная идея.\n\n*шепотом под нос*\nМне правда очень тяжело!\nНет, сама ты такая! Я сильная!",212725,null],[235260,"2026-09-25T09:55:24",31,"девочки идут на бранч, я так понимаю? Просекко дегустировать?)/",212725,null],[235261,"2026-09-25T09:55:57",20,"/с утра только мальвазия ;)",235260,null],[235262,"2026-09-25T09:56:29",31,"Социальте пока, я вам потом что нибудь подкину, чтобы не расслаблялись)/",212725,null],[235263,"2026-09-25T09:56:38",31,"пока выберу/",212725,null],[235264,"2026-09-25T09:58:11",20,"- Прекрасно, в таком случае прошу за мной, сеньорита. Вы с нами сеньор Марко? *Беатриче вопросительно оборачивается к детективу*",235259,null],[235265,"2026-09-25T10:00:36",20,"/кстати в Вальдории нет городских каналов как в Венеции? На карте их не видно",212725,null],[235266,"2026-09-25T10:01:32",31,"боюсь, нет. я Ориентировался больше на Геную и ее стены/",235265,null],[235267,"2026-09-25T10:03:18",17,"Марко задумался о том к кому обратится за помощью в исследовании земли. Вопрос Беатриче выбил его из мыслей \n\n— Я... да, да. Пойдёмте позавтракаем.",212725,null],[235268,"2026-09-25T10:16:53",31,"/roll d6 на случайное событие",212725,null],[235270,"2026-09-25T10:17:21",31,"ок, номер 4. Жду от вас экспозиции и запущу/",212725,null],[235271,"2026-09-25T10:18:51",20,"*Беатриче ведёт вас в соседний район Старого города. Узкий переулок, куда вы приходите, еще погружен в глубокие тени, хотя вершины соседних палаццо уже окрашены золотисто-розовым светом восходящего солнца. В воздухе висит утренняя прохлада, смешанная с ароматами морской соли, старого дерева и свежевыпеченного хлеба из соседних пекарен.\n\nА вот и «Бархатный Лев» (Il Leone di Velluto). Это заведение располагается в перестроенном купеческом палаццо. Тяжелые дубовые двери с коваными ручками в виде львиных голов приоткрыты, выпуская на зябкий утренний воздух тепло. Стрельчатые окна забраны густым муранским стеклом, которое ловит солнечные блики, но надежно скрывает от зевак лица тех, кто завтракает внутри.\n\nПахнет свежей выпечкой, сладким миндальным молоком, корицей и едва уловимым шлейфом дорогих благовоний, которые жгли здесь всю ночь.\n\n- Ну, вот мы и на месте. Добро пожаловать в Il Leone di Velluto друзья. Лучшее место в городе для тех, кто ищет минуту передышки от суеты Вальдории.\n\nЧерез пару минут общения с швейцаром Беатриче проводит вас дальше и вы усаживаетесь на небольшом балконе, скрытом от основного зала за коваными узорами двери и портьерой - идеальное место спокойного завтрака. Или разговора без лишних ушей.",212725,null],[235275,"2026-09-25T10:21:44",31,"так вкусно написала что я захотел еще раз пообедать/",212725,null],[235278,"2026-09-25T10:32:21",22,"- Ого.. так р-роскошно!",235271,null],[235286,"2026-09-25T10:40:58",20,"- Все лучшее для сеньориты *Беатриче шутливо подмигивает, галантно отодвигая для Ясмин стул*\n\n- Присаживайтесь и просто постарайтесь расслабиться - вы и так вчера очень многое пережили, вон все ещё слегка трясетесь. Советую вам заказать помимо еды бокальчик  Malvasia. Не пьянит, но неплохо прочищает голову.",235278,null],[235287,"2026-09-25T10:45:11",22,"- Х-хорошо. \n\nЯсмин присела и погрузилась в свои мысли,  ожидая официанта",212725,null],[235289,"2026-09-25T10:53:20",22,"Когда официант приносит меню, пальцы Ясмин бегут по строчкам. \nКреветки. Треска. Моллюски. Говядина?!\n\nОна обращается к официанту.\n\n- Я возьму...\n\nМЯСО! \nСТЕЙК! \nС КРОВЬЮ!\n\n- Р-Рыбу с овощами.\n\nБери говядину, как все нормальные люди.\nОна же у нас нитакуся. \nВегетарианка точно.\nДа нет же, там другое слово было пас-ке-та-ри-ан-ка!\n\n- Рыбу с овощами, как у всех. Любую рыбу.",212725,null],[235290,"2026-09-25T10:54:39",22,"- И-и вино! \n\nКРАСНОЕ КАК КРОВЬ!\nСУХОЕ КАК ТВОЯ ДУША!\n\n- Красное, сухое... Т-только Лёгкое п-пожалуйста.",212725,null],[235292,"2026-09-25T11:01:35",31,"/стартует побочное задание/",212725,null],[235293,"2026-09-25T11:04:45",31,"Ясмин наслаждается принесенно пищей, легкое вино заглушает голоса матери и теток. Но вдруг в ее голове появляетс новый голос. Тоненький, жалкий. нечеловеческий.\n\n- ты... ты меня слышишь? Помоги, прошу...\n\nЯсмин оглядывается и видит на полу изможденную белую крысу. На животном она замечает ошейник с биркой, на бирке число 9\n\n- да, это я звала... помоги, прошу...",235290,null],[235299,"2026-09-25T11:23:10",22,"Ясмин поднимает крысу на руки и осматривает осторожно",212725,null],[235300,"2026-09-25T11:23:24",22,"/r +6",212725,null],[235302,"2026-09-25T11:24:50",31,"Животное измождено. На вид просто тощая белая крыса, шерсть клочками, только в глазах что то есть. Искра интеллекта. Это животное разумно? Похоже на то",235301,null],[235303,"2026-09-25T11:26:38",22,"Ясмин аккуратно гладит крысу и кормит кусочком рыбы.\n\n- Тише, тише. Отдохни. Поешь. П-потом расскажешь что с тобой случилось.",212725,null],[235304,"2026-09-25T11:31:01",31,"Крыса с жадностью накидывается на еду. Кусок рыбы пдпет в ее желудок за секунду. Ее впалый живот надувается на глазах. Ты вновь слышишь ее голос в голове. Уже не такой умирающий\n\n- спасибо. помоги. я сбежала. но другие еще там. их мучают. чтобы умнели. так нельзя. это больно. это страшно. мы не хотим. помоги",235303,null],[235306,"2026-09-25T11:34:41",22,"- Расскажи. Откуда ты сбежала, кто вас держит и что происходит?\n\nОпа подружку нашла\nТакую же крысу, как она сама\nИхихи-хи-хи \n\nНа глазах Ясмин навернулись слезы.",212725,null],[235307,"2026-09-25T11:36:32",31,"- Каспар. аптека. клетки. опыты. нож. искры. зелья. горько. больно. \n\nПохоже, полноценными предложениями крысе общатся все таки сложно",235306,null],[235308,"2026-09-25T11:38:09",22,"Ясмин осматривает крысу, чтобы убедиться, что та не больна и пытается разглядеть, какие опыты на той ставили.",235307,null],[235309,"2026-09-25T11:38:15",22,"/r +6 медицина",212725,null],[235311,"2026-09-25T11:38:57",22,"- Кушай, м-маленькая, отдыхай, я п-попробую тебе помочь.",212725,null],[235312,"2026-09-25T11:39:32",31,"ты замесчешь на крысе швы, в районе головы. так же ее шерстка в мескольких местах подпалена, словно бы ее били током или прижигали",235310,null],[235313,"2026-09-25T11:40:16",31,"взгляд крысы соловеет от еды и усталости, она засыпает в твоих руках",235311,null],[235314,"2026-09-25T11:48:11",31,"как остальные реагируют на разговор Ясмин с крысой?",212725,null],[235315,"2026-09-25T11:50:15",22,"- Бедная малышка. Я помогу тебе.\n\nЯсмин гладила маленькую крысу, а ее глаза были мокрые от слез.\n\nТолько не говори что ты реально пойдешь ее спасать\nСпасительница мусора и отребья\nОтвратительно\n\nЯсмин поднимает глаза на товарищей.\n\n- М-мы же поможем м-мышке? Она говорила со мной.. Аптекари, Каспар, издевались над ней. Не просто тестировали лекарства,  а занимались настоящим садизмом! \n\nЛицо девушки пылало возмущением и она даже перестала заикаться.",212725,null],[235316,"2026-09-25T11:50:18",20,"/а мы слышим что крыса говорит? Или это чисто у Ясмин в голове?",235314,null],[235317,"2026-09-25T11:50:41",22,"//кажется крыса к моему карнавалу присоединилась",235316,null],[235318,"2026-09-25T11:50:50",31,"ну голос крысы только в голове у Ясмин. Отвечает она голосос или нет я не знаю/",235316,null],[235319,"2026-09-25T11:51:02",22,"/вслух конечно.  Сидит бубнит",235318,null],[235320,"2026-09-25T11:57:01",20,"*Беатриче смотрит на этот разговор? с крысой, бокал вина завис у губ.*\n\n- Эээ...она говорила с вами, сеньорита? *Кидает взгляд на бокал Ясмин. Да не, вроде не настолько крепкое...*\n\n*Потом снова смотрит на белую спящую крыску. По расцветке действительно похоже на тех крыс которые держат для опытов, а не просто уличная. Возможно слова девушки не такой уж вымысел.*\n\n- Ну, если этой малышке действительно нужна помощь, то как мы можем остаться в стороне?",212725,null],[235321,"2026-09-25T12:04:42",22,"- С-спасибо! Ваше с-сердце так добро!\n\nГубы Ясмин задрожали, а пальцы выбивали нервную дрожь.\n\nДа сожрёт она твою новую подругу\nТочно сожрёт, крыса то еще и специями нафарширована\nФу ну это слишком низко, даже для кровосиси!\nСтавлю 3 левых глаза на то, что сожрёт!\nЛадно, ставлю глаз циклопа, что не сожрёт!\nТак вот у кого мой глаз циклопа?! Ах ты Ара-бха(шлёндра)!",212725,null],[235322,"2026-09-25T12:05:38",31,"ну кстати, дампиру кровь положено иногда пить))",212725,null],[235323,"2026-09-25T12:05:48",31,"крыса как консерва, ммм//",212725,null],[235324,"2026-09-25T12:10:38",31,"Решили помочь крысе? А куда идти и чего делать будете?",212725,null],[235325,"2026-09-25T12:11:09",20,"/сначала дозавтракаем и подождем реакции Марко",235324,null],[235326,"2026-09-25T12:11:41",31,"прикинь,Марко боится крыс и упадет в обморок)/",235325,null],[235327,"2026-09-25T12:15:17",20,"/это будет cinema",235326,null],[235372,"2026-09-25T13:34:55",31,"@dunchev загляни как будет время. Если что, можешь отойти по своим тесным делам, а девушки и вдвоем сгоняют крысам на помощь/",212725,null],[235403,"2026-09-25T13:47:10",17,"/Сори очередной загруженный день на работу прям не продохнуть \n\nЩас почитаю",212725,null],[235451,"2026-09-25T14:24:44",17,"— Салат Цезарь пожалуйста и того же вина, что и синьорите.\n\nЗадумчиво перечитывает старые записи в книге мертвых\n\nПотом он замечает как Ясмин подобрала крысу и будто бы.. общается с ней.\n\nОн вздыхает понимая женскую сердобольность. Но сам он относится к опытам над животными с холодным цинизмом. \n\n— Ясмин. Опыты на грызунах это обычное дело. Прогресс на месте не стоит исследования в областях медицины требуют живых подопытных. Простите меня за цинизм, но это действительно так. Если хотите, можете подлечить ее и держать как домашнего питомца. Но зачем пытаться нарушить обычный порядок в медицинском учреждении? Или крыса сказала вам что то иное?",235286,null],[235476,"2026-09-25T14:56:17",22,"- В-вы абсолютно правы. Разум говорит, что все так есть, но..\nВ руках Ясмин лежала крыса, руки девушки изулучали приятный тёплый свет, постепенно угасающий с каждым жёстким словом мужчины.\n\n- Они ведь живые.. Они думают, помнят, страдают.. Они кричат, когда их рвут на части. Они сидят там, запертые в клетки и ждут, когда умрут и смерть не будет легкой...\n\nПосмотри на себя. Ты думаешь, ты помнишь, ты страдаешь. Ещё вчера тебя рвали на части, тебе это понравилось?\n\nЭти крысы, они как мы, только меньше..тише..и их некому не жалко. Вспомни историю гоблина. Он тоже маленький и тихий и всем плевать на его судьбу.\n\nОбычное дело говоришь. Опыты на крысах, на кроликах,  на сиротах. На тех, кто мал и тих, верно?\n\nЯсмин прервалась, погладив крысу. Свет в ее руках погас.\n\n- А Найн не стала покорно ждать своей судьбы и взяла дело в свои лапки. Она смогла сбежать и теперь просит о помощи. Я помогу ей, я хочу этого, моё сердце этого хочет. \n\nЯсмин вновь умолкла. В голове снова был карнавал голосов, наперебой насмехавшихся над ней и ее чувствами.",235451,null],[235477,"2026-09-25T14:57:53",31,"Уже и кличку дала?) я вообще другое имя ей придумал, но пусть так)/",235476,null],[235479,"2026-09-25T14:58:10",22,"/ну девятка найн же, само напрашивается",235477,null],[235481,"2026-09-25T14:58:46",31,"Да, логично, не спорю/",235479,null],[235482,"2026-09-25T15:02:41",17,"— Я не собираюсь спорить на этой почве. В счёт благодарности за спасение своей жизни, помогу вам. С тем что вы задумали. Меня тут больше интересует вопрос как вышло, что крыса общалась с вами. Она не издавала писка, вы слышите ее в голове? Вот это действительно уникально.",212725,null],[235486,"2026-09-25T15:04:03",22,"Ясмин пожала плечами, что тут странного, она привыкла что в ее голове кто-то болтает.  Одним голосом больше, одним меньше, какая разница.",212725,null],[235488,"2026-09-25T15:06:23",22,"- Предлагаю п-поискать некого Каспара в ап-птекарском районе.\n\nГолоса в голове Ясмин стали невыносимы, девушка уже едва держалась, чтобы не закричать и ее голос снова начал дрожать.\n\n- Г-госпожа Беатриче нам поможет, я думаю.",212725,null],[235489,"2026-09-25T15:07:48",20,"- Хм, аптека Каспара... *Беатриче пытается припомнить, не слышала ли она чего об этом месте*",235488,null],[235490,"2026-09-25T15:07:56",20,"/r d20 на историю",212725,null],[235492,"2026-09-25T15:08:46",20,"- Нет, боюсь это место мне не знакомо. Но ничего не мешает нам его поискать *она делает глоток вина, явно готовая к новой авантюре*",212725,null],[235502,"2026-09-25T15:19:12",31,"Ну варианты выяснить направление есть всегда/",235492,null],[235565,"2026-09-25T15:43:23",17,"/r d20+5+d4 Слышал ли Марко о Каспаре",212725,null],[235574,"2026-09-25T15:45:24",31,"Марко вспоминает неприметную аптеку где то в Нижнем городе. На ее вывеске было написано Каспар и еще что-то вроде было",235566,null],[235610,"2026-09-25T15:57:32",17,"— Я знаю где находится аптека Каспара, хотя с ним самим лично не знаком. Покажу дорогу.\n\nМарко поднялся бросив взгляд на крысу\n\n\"А со мной не хочешь поговорить?\"\n\nПодумал он про себя глядя на крысу",212725,null],[235612,"2026-09-25T15:58:17",31,"А кинь спас мудрости, крыса попытается пробиться. Ясмин восприимчивая просто",235610,null],[235618,"2026-09-25T16:00:53",22,"- Отлично. В-ведите. П-почему вы так смотрите на Н-найн? Дать погладить? Н-но только с моих рук. В-вы меня немного пугаете.",235610,null],[235626,"2026-09-25T16:05:25",17,"/r +5 Спас",235612,null],[235629,"2026-09-25T16:06:00",17,"— Пытаюсь установить с ней ментальный контакт. Или это все таки ваша особенность, Ясмин? Может вам легко залезть в голову?",235618,null],[235632,"2026-09-25T16:08:25",20,"*Беатриче гладит крысу. Эх, сочная наверное...*",235618,null],[235633,"2026-09-25T16:08:30",20,"/шутка",212725,null],[235635,"2026-09-25T16:08:33",20,"/или нет",212725,null],[235637,"2026-09-25T16:08:52",22,"- Вы х-хотите попробовать влезть мне в голову? В-вам там не понравится...",235629,null],[235638,"2026-09-25T16:09:22",22,"Ясмин показалось или дампирша действительно облизнулась?\n\nНЕ ПОКАЗАЛОСЬ",212725,null],[235642,"2026-09-25T16:10:50",31,"/roll d20 крыса пробивает ментальный блок жреца",235627,null],[235644,"2026-09-25T16:10:58",31,"Крысе не хватило сил/",212725,null],[235645,"2026-09-25T16:11:37",31,"Крыса разводит лапки, ну типа я пыталась",212725,null],[235647,"2026-09-25T16:16:41",31,"Марко ведёт вас в трущобы Нижнего города. Не лучшее место, но он тут свой. И его нехорошего взгляда хватает чтобы отвалить местную шушеру криминального толка.\n\nАптека и правда выглядит затрапезно. Похоже, ее лучше дет не просто прошли, а скорее  всего и вовсе не начинались. Вы входите в здание. \n\nЗа прилавком вас встречает плюглявенький мужичок, что смешивает какой то порошок. Подняв на вас голову, он сияет как новая монетка\n\n- Клиенты? Чего изволите? Кчть прекрасная настойка для мужской силы, а еще...\n\nАптекарь затыкается, увидев тяжелый взгляд Марко\n\n- так чем могу помочь?",212725,null],[235649,"2026-09-25T16:19:34",17,"— Нет. Я хотел чтобы крыса попробовала со мной установить связь. Сам я не умею зализить никому в голову, тем более без разрешния сиоры. Будьте спокойны.",235637,null],[235650,"2026-09-25T16:21:03",17,"— Добрый день, синьор Каспар. я полагаю? \n\nМарко осматривается в поисках необычных лекарств.",235647,null],[235656,"2026-09-25T16:25:05",31,"- да, это я, вы правы, сиор. Что конкретное ищете? Клянусь, у меня лучший выбор в районе!",235650,null],[235794,"2026-09-25T17:38:22",31,"Короче, как будет возможность, пишите. Буду реагировать на заявки. На выходных скорее всего будет очень рваный онлайн у меня. Этот квест коротенький, буквально на часок неспешно отыграть. А нормальный будем играть уже в понедельник//",212725,null],[235799,"2026-09-25T17:39:37",17,"/ Да а что мы ему предъявим я чето чтоб туплю не знаю что сказать",212725,null],[235800,"2026-09-25T17:40:01",17,"/ В таких случая я всегда начинаю блефовать с харизмой -1 это весело будет)",212725,null],[235804,"2026-09-25T17:41:31",31,"Ну ты всегда можешь попробовать) вдруг проканает)",235800,null],[235819,"2026-09-25T17:49:42",22,"/я тоже очень туплю, мигрень одолела. Если оклемаюсь, то вечером что-то напишу",212725,null],[235822,"2026-09-25T17:51:50",31,"Не торопитесь, лениво пиракм квест. Лучше экономить силы на главный)) ну если хотите, могу и сюда прямо сейчас Экшена добавить, чтобы долго не трещать с аптекарем)/",212725,null],[235823,"2026-09-25T17:52:08",17,"— Марко Веньер. Пишу диссертацию на тему \"Использование грызунов для тестирования новейших медицинских препаратов\". Мне подсказали у вас есть опыт. Не могли поделиться, может быть продемонстрировать?",212725,null],[235824,"2026-09-25T17:52:22",31,"Проницательность кидай/",235823,null],[235825,"2026-09-25T17:52:32",20,"/ты блефуешь, я стою сзади и угрожающе зыркаю -> блеф через запугивание",235800,null],[235826,"2026-09-25T17:52:45",22,"//дайте мне пару часов до дома доползти и можно экшен. Сложно писать, когда перед глазами 2 экрана одновременно 🥲",235822,null],[235827,"2026-09-25T17:53:01",17,"/r d20+5+d4 Проницательность это да",212725,null],[235833,"2026-09-25T17:54:30",31,"Апткарь заявлет с легкой улыбкой: \n\n- рад видеть коллегу учёного, но боюсь, вы ошиблись, никогда я не имел дел с грызунами, со времён ученичества",235828,null],[235834,"2026-09-25T17:54:44",31,"Тебе кажется, он предельно честен",212725,null],[235840,"2026-09-25T17:57:14",17,"\"Может Ясмин ошиблась и вообще разговор с крысой плод ее воспалённой фантазии. Она в принципе странная.\"\n\n— Что ж. Видимо не правильно подсказали. А вы только продаете медикаменты, а новые не пытаетесь создать? Сейчас на основе яда змей исследуются новейшие успокоительные. Слышали?",212725,null],[235844,"2026-09-25T17:59:22",31,"- ну конечно исследовательская работа это основа моего дела. Насчет змеинного яда в успокоительных я слышал, го скептичен, с моей точки зрения это слишком сильное средство. Успокоиться можно, ха-ха, навсегда.\n\nИз задней комнаты раздается шум, можете бросить на восприятие/",235840,null],[235849,"2026-09-25T18:01:19",17,"/r d20+5+d4 Прислушивается",212725,null],[235856,"2026-09-25T18:08:07",31,"Ты слышь отчаянный писк десятка крысиных глоток.\n\nКрыса за пазухой у Ясмин нервно шебуршит, тоже что то чует\n\nХозяин меняется в лице и выдавливае вымученную улыбку и скороговоркой просит его подождать, ибо срочные дела, после чего устремляется в комнату позади.\n\nТут же из под одежды Ясмин выпрыгивает крыса и несётся следом за ним, едва не прищемив хвост, она успевает заскочить в комнату до закрытия двери за аптекарем.\n\nИз-за закрытой двери Марко продолжает слышать звуки. Громкий удар, словно кто то ударил палкой по прутьям клетки, а затем жуткий утробный вой",212725,null],[235905,"2026-09-25T18:43:54",17,"Марко переводит бесконечно усталый взгляд на Ясмин\n\n— Хотите пойти посмотреть, что же он там прячет?",212725,null],[235963,"2026-09-25T19:10:51",22,"- Да! Скорее! А ч-что если там не только м-маленькие крысы..\n\nРуки Ясмин начали наливаться светом.",235905,null],[236006,"2026-09-25T19:20:59",22,"//у меня бокал вина и я готова к экшену",235822,null],[236007,"2026-09-25T19:21:31",31,"Врывайся/",236006,null],[236009,"2026-09-25T19:22:37",22,"/после Беатриче только.. а то как влечу так и улечу",236007,null],[236010,"2026-09-25T19:22:45",17,"Марко выносит дверь с ноги",212725,null],[236012,"2026-09-25T19:23:27",31,"Мощный удар ноги от Марко срывет дверь с петель, вы забегаете в неожиданно большую комнату",212725,null],[236013,"2026-09-25T19:23:35",22,"Воинственная Ясмин выглядывает из-за его плеча.",236010,null],[236015,"2026-09-25T19:23:40",17,"— Каспар! Лжец! Показывай грызунов, диссертация сама себя не напишет!\n\nМарко смеялся от такой наглости на них спокойно могут на жаловаться властям и закроют на 15 суток",212725,null],[236020,"2026-09-25T19:25:08",31,"Вы видите что аптекарь лежит на полу, а над ним нависат чудовище, созданное из десятка крыс. Он кричит:\n\n- помогите! Монстр!\n\nВ то же время Ясмин слышит в голове голос крысы:\n\n- мы сами его накажем, не мешайте",212725,null],[236021,"2026-09-25T19:25:33",31,"Ваши действия?",212725,null],[236026,"2026-09-25T19:27:29",20,"*Запоздавшая Беатриче врывается в комнату вслед за Морко и в ахере смотрит на происходящее*\n\n*Переводит на Марко взгляд типа: \"во что мы блять опять ввязались\"*",212725,null],[236027,"2026-09-25T19:27:41",20,"/жду решения Ясмин короче",212725,null],[236029,"2026-09-25T19:27:55",22,"- НАЙН!\n\nГромко выкрикнула Ясмин, частично оглушая Марко.\n\n- Не смей. Ты ведь не такая! Не отвечай насилием на насилие! Я понимаю тебя.. п-правда понимаю. Но эта м-мразь не стоит твоих когтей.",212725,null],[236030,"2026-09-25T19:27:56",17,"Марко бежит защищать человека это уже не смешно\n\n— Каспар, ты чего тут сотворил!?\n\nОн подбегает и прикрывает собой Каспара",212725,null],[236032,"2026-09-25T19:28:31",22,"А крыска то явно лучше нашей клуши",212725,null],[236033,"2026-09-25T19:29:16",20,"*Беатриче бежит прикрывать Марко, уже вытаскивая рапиру и кинжал и становясь перед мужчинами.*\n\n- Ясмин, лучше отойди мне за спину.",212725,null],[236034,"2026-09-25T19:29:37",22,"Ясмин подбегает и обнимает крысу.\n\n- П-позволь мне разделить твою боль. Не делай этого..",212725,null],[236035,"2026-09-25T19:29:39",31,"Крысомонстр тебя не трогает, еюты не его цель. Но обойти не может",236030,null],[236036,"2026-09-25T19:29:48",31,"Большую?/",236034,null],[236037,"2026-09-25T19:29:52",22,"Да",212725,null],[236039,"2026-09-25T19:30:06",22,"//погоди я думала Найн выросла",212725,null],[236041,"2026-09-25T19:30:20",31,"Нет, она мелкая, рядом/",236039,null],[236042,"2026-09-25T19:30:34",31,"Это остальные собрались в монстра/",212725,null],[236043,"2026-09-25T19:30:35",22,"/значит большую. Ясмин добрая наивная душа. Как выживала я хз. Без тетушек не обошлось точно",212725,null],[236044,"2026-09-25T19:31:05",31,"/roll d20+3, крысомонстру не до нежностей",236043,null],[236046,"2026-09-25T19:31:19",31,"Цап, но мимо",212725,null],[236047,"2026-09-25T19:31:30",31,"Все, твари снесло крышу",212725,null],[236048,"2026-09-25T19:31:31",22,"/r +3 сила любви! Убеждение",212725,null],[236050,"2026-09-25T19:31:33",31,"Инициатива/",212725,null],[236051,"2026-09-25T19:31:54",22,"//да ладно тебе.. неужели я настолько плохо обнимаюсь 😭",212725,null],[236052,"2026-09-25T19:31:55",17,"/r +2 Продержимся",212725,null],[236055,"2026-09-25T19:32:03",22,"/r +2",212725,null],[236058,"2026-09-25T19:32:18",31,"Крыс не в настроении//",236051,null],[236059,"2026-09-25T19:32:30",31,"/roll d20+3 крыса монстр",212725,null],[236061,"2026-09-25T19:32:30",17,"— Обнимай кррепче Ясмин. Или пойду обниматься я",212725,null],[236062,"2026-09-25T19:32:54",22,"Ясмин грустно шмыгнула носом.",212725,null],[236063,"2026-09-25T19:33:46",20,"/r d20+3 инициатива",212725,null],[236065,"2026-09-25T19:33:56",31,"Голос в голове Ясмин:\n\n- зачем же вы полезли, теперь Стая убьет вас((( \n\nВ голосе слышна грусть",212725,null],[236069,"2026-09-25T19:34:31",31,"Беатриче\nМарко\nСтая\nЯсмин\nКаспар",212725,null],[236071,"2026-09-25T19:35:01",31,"Каспар:\n\n- да, убейте тварь",212725,null],[236072,"2026-09-25T19:35:07",17,"— Крыски, погодите! Давайте поговорим!",212725,null],[236075,"2026-09-25T19:35:49",31,"Убеждение/",236072,null],[236077,"2026-09-25T19:36:18",17,"/r d20+5+d4 Пошли обнимашки групповые",212725,null],[236079,"2026-09-25T19:37:09",31,"Большой монстр затих. Вы все слышите в голове голос мелкой крысы:\n\n- говори, мы слушаем",212725,null],[236080,"2026-09-25T19:37:16",22,"//тем временем Беатриче 😐😶🫥",212725,null],[236081,"2026-09-25T19:37:38",20,"/эх, а я хотела эпичную боевую позу принять",212725,null],[236083,"2026-09-25T19:37:53",31,"Свободное действие можешь на нее потратить/",236081,null],[236084,"2026-09-25T19:38:17",20,"/да как-то теперь неловко)",236083,null],[236086,"2026-09-25T19:38:29",31,"Мастер творит произвол, обьялает инициативу и сам нарушает, фу таким быть/",212725,null],[236094,"2026-09-25T19:39:35",31,"Крысы в ожидании/",212725,null],[236096,"2026-09-25T19:39:43",31,"Слюни капают/",212725,null],[236101,"2026-09-25T19:41:18",22,"- Месть не вернет вам то, что у вас отняли. Но м-милосердие хотя бы не позволит отнять у вас ещё и самих себя... Вы лишь продолжите эту цепь боли и с-страданий.. остановитесь!",212725,null],[236103,"2026-09-25T19:41:28",22,"нытик!",212725,null],[236107,"2026-09-25T19:41:42",31,"Ну попробуй тоже убеждение/",236101,null],[236110,"2026-09-25T19:42:10",22,"/r +3 Не гасите свет в своей душе!",212725,null],[236113,"2026-09-25T19:42:22",22,"/я уже говорила как ненавижу кубы?",212725,null],[236114,"2026-09-25T19:42:30",22,"/где там моя булава",212725,null],[236115,"2026-09-25T19:42:48",31,"Стая не убеждена\n\n- мы его сожрем! Живыыыыыым!!!",212725,null],[236116,"2026-09-25T19:42:55",31,"Беатриче, ход",212725,null],[236117,"2026-09-25T19:44:32",20,"*Беатриче кидается вперёд, хватая Ясмин за шкирку и оттаскивая от крысы себе за спину*\n\n- Il mio giusto Dio, оно же вас почти цапнуло! Говорите с дистанции!\n\n*Принимает позу парирования, блокируя стае подход к остальным - ладно, она выиграет напарникам ещё немного времени.*\n\n/Вывела Ясмин из досягаемости + уворот\n/Конец ходах",212725,null],[236119,"2026-09-25T19:44:54",31,"Марко ход/",212725,null],[236134,"2026-09-25T19:49:02",31,"@dunchev айда крыс бить/",212725,null],[236137,"2026-09-25T19:50:27",17,"— Ясмин. Извини. Они слишком опасны. Хоть и не виноваты в этом.",212725,null],[236138,"2026-09-25T19:51:30",17,"Марко коглатила черная маска шакала, его правая рука превратилась в когтистую лапу и он пробил острыми когтями брюхо монструозной стаи",212725,null],[236139,"2026-09-25T19:51:40",17,"/r +5 На попадание 3d10 Урон",212725,null],[236141,"2026-09-25T19:51:46",17,"/ Ясно. Ход",212725,null],[236142,"2026-09-25T19:51:48",31,"Мимо/",212725,null],[236143,"2026-09-25T19:52:07",17,"Шкура оказалась намного прочнее чем казалось на первый взгляд \n\n— Шайсе...",212725,null],[236145,"2026-09-25T19:52:42",31,"Стая уворачивается от удара человека ч шакальей головой и не обращая на него внимания оббежала и кинулась на Каспара",212725,null],[236146,"2026-09-25T19:52:50",31,"/roll d20+3 цап",212725,null],[236148,"2026-09-25T19:53:03",17,"/ Ну. Я технически стоял перед ним. Так что провоцирку могу?",212725,null],[236149,"2026-09-25T19:53:05",20,"/а провоцированная?",236145,null],[236150,"2026-09-25T19:53:18",31,"Давайте провоцирут, ок",212725,null],[236151,"2026-09-25T19:53:55",31,"Убейте крысу, не дайте свершится мести!/",212725,null],[236153,"2026-09-25T19:54:30",17,"/r +4 На попадание d8+2 Урон колющий",212725,null],[236155,"2026-09-25T19:54:31",20,"/заменяю атаку на захват",212725,null],[236156,"2026-09-25T19:54:41",17,"/r d8 Ещё колющего",212725,null],[236158,"2026-09-25T19:54:51",17,"/ Ну надо же!",212725,null],[236159,"2026-09-25T19:55:10",31,"Крыса сильно ранена, но продолжает свой путь к Каспару",212725,null],[236160,"2026-09-25T19:55:17",31,"Давай свой захват Катя/",212725,null],[236161,"2026-09-25T19:55:17",22,"/фига ты мощный",236158,null],[236162,"2026-09-25T19:55:25",20,"/r d20+1",212725,null],[236164,"2026-09-25T19:55:27",17,"Марко в спину сущестуву повторил атаку когтистой рукой и в этот раз разорвал слившеймч шов",212725,null],[236165,"2026-09-25T19:55:38",20,"/ну ладно, один раз удачу ещё",212725,null],[236168,"2026-09-25T19:56:05",20,"/Лол",212725,null],[236169,"2026-09-25T19:56:08",31,"Стая все твки дошла да Каспара и впилась в него зубами",212725,null],[236170,"2026-09-25T19:56:16",31,"/roll d6+3",212725,null],[236172,"2026-09-25T19:56:46",31,"/roll d20+1 спас тела от отравы для Каспара",212725,null],[236174,"2026-09-25T19:56:59",22,"ПЕЧЕНЬ МНЕ ОСТАВЬ",212725,null],[236175,"2026-09-25T19:57:08",31,"Провалил, упал, пена изо рта, Стая над ним, ход/",212725,null],[236176,"2026-09-25T19:57:13",31,"Ясмин/",212725,null],[236177,"2026-09-25T19:57:50",31,"Крыса в твоей голове:\n\n- теперь можно и умереть...",212725,null],[236179,"2026-09-25T19:58:03",22,"Ясмин дернулась, она не сразу поняла, что эти слова вылетели из ее рта и всхлипнула.\n\n- Эту боль.. ее нужно остановить. Мне очень очень жаль!\n\nСпас лвк 14",212725,null],[236180,"2026-09-25T19:58:25",31,"/roll d20+3",212725,null],[236182,"2026-09-25T19:58:34",22,"Ход/",212725,null],[236183,"2026-09-25T19:58:52",31,"/roll d20 Каспар спас от смерти",212725,null],[236185,"2026-09-25T19:58:59",31,"Живой, сука/",212725,null],[236186,"2026-09-25T19:59:03",31,"Беатриче",212725,null],[236188,"2026-09-25T20:01:51",31,"@PaIIasCat",212725,null],[236189,"2026-09-25T20:02:05",31,"Сорян что тегаю, просто уже спать собираюсь и хочу добить/",212725,null],[236191,"2026-09-25T20:03:47",22,"/можем завтра закончить, не мучай себя\nКак хорошо то после винца эх",212725,null],[236192,"2026-09-25T20:04:04",31,"Я не мучаю)/",236191,null],[236194,"2026-09-25T20:04:18",31,"Да и осталось пару ходов/",212725,null],[236195,"2026-09-25T20:04:20",20,"/r d20+5 рапира\n/r d20+5 кинжал",212725,null],[236197,"2026-09-25T20:04:34",31,"Кинжал попал/",212725,null],[236199,"2026-09-25T20:04:44",20,"/мда, не везёт рапире от слова совсем",212725,null],[236200,"2026-09-25T20:04:49",20,"/r d20+3",212725,null],[236203,"2026-09-25T20:05:09",20,"/это не то, извините",212725,null],[236205,"2026-09-25T20:05:23",20,"/r d4+3",212725,null],[236207,"2026-09-25T20:06:12",17,"Марко снова вонзает когти Аннубиса в спину существу",212725,null],[236208,"2026-09-25T20:06:27",17,"/r +5 На попадание\n\n 3d10 Неуро урон",212725,null],[236210,"2026-09-25T20:06:27",31,"Наповал. Точный удар кинжала в крысо монстра убил его. Но Монстр успел свести счёты со своим врагом, позоронив кго под своей мёртвой тушей",212725,null],[236211,"2026-09-25T20:06:39",17,"/ Nine!",212725,null],[236212,"2026-09-25T20:06:56",31,"Марко уже глумился рад трупом/",236211,null],[236213,"2026-09-25T20:07:48",31,"Мысли маленькой крысы в ваших головах:\n\n- Стая сделала что была должна. Пора и мне догнать стаю",212725,null],[236215,"2026-09-25T20:08:18",17,"— Беатриче помоги достать его!",212725,null],[236216,"2026-09-25T20:08:25",17,"/r -1 Атлетика зашкаливает",212725,null],[236220,"2026-09-25T20:08:53",31,"Хочешь Каспара вытащить?/",212725,null],[236221,"2026-09-25T20:09:07",31,"Ну хотя бы 12 атлетики дайте/",212725,null],[236223,"2026-09-25T20:09:23",20,"*Беатриче бежит помогать Марко оттащить тушу с человека*",212725,null],[236224,"2026-09-25T20:09:28",20,"/r d20+1",212725,null],[236226,"2026-09-25T20:09:36",31,"Хе-хе/",212725,null],[236227,"2026-09-25T20:09:38",20,"/ахаха",212725,null],[236229,"2026-09-25T20:09:58",20,"/чё, ещё разочек?",212725,null],[236230,"2026-09-25T20:10:05",31,"Дело твое/",212725,null],[236233,"2026-09-25T20:10:26",20,"/r +d20+1 давай помогай Марко",212725,null],[236236,"2026-09-25T20:10:50",17,"/ Ладно получилось я уже писал про чудотвортсво",212725,null],[236237,"2026-09-25T20:10:54",31,"Совместными усилися вы скинули тушу",212725,null],[236238,"2026-09-25T20:10:56",20,"/а в бою где такие кубы блин",212725,null],[236240,"2026-09-25T20:11:36",31,"Каспар лежит при смерти",212725,null],[236241,"2026-09-25T20:11:43",31,"Но благо вы в аптеке",212725,null],[236242,"2026-09-25T20:11:54",31,"Если конечно хотите его спасти/",212725,null],[236243,"2026-09-25T20:12:23",31,"Крыса в аштз головах:\n\n- пусь умрёт. Стая не могла умереть просто так",212725,null],[236244,"2026-09-25T20:13:32",22,"- Насилием отвечать на насилие неправильно. \n\nЯсмин села к Найн и стала объяснять суть бытия.",212725,null],[236245,"2026-09-25T20:15:30",31,"- может у людей и так. А мы крысы. Мы живём проще. Кусаем в ответ. Он мучил нас, он терзал нас. Кому то повезло как мне, я стала умнее от его зелий. Врочем, без зелий я наверняка стану такой как была ранее. А кто то потерял себя и стал Стаей.",236244,null],[236246,"2026-09-25T20:17:04",22,"- Ты очень умная девочка, ты поймёшь. Пойдем, покажешь, какие зелья ты принимала. Ты хочешь и дальше быть умной или хочешь в-вернуться к прежней жизни?\n\nСама этих зелий попей\nВот тебе они явно нужны, дуреха",212725,null],[236250,"2026-09-25T20:18:18",31,"- нет, я не прикоснусь к этой дряни! Лучше быть просто крысой и не уметь думать. Так проще жить и спокойнее",236246,null],[236255,"2026-09-25T20:19:18",31,"Суровая версия Элджернона вышла, да//",212725,null],[236256,"2026-09-25T20:19:18",20,"/r +d20+1 где-то на заднем плане звуки \"Разряд! БЖЖЖ!\"",212725,null],[236258,"2026-09-25T20:19:29",31,"Оклемался/",236257,null],[236260,"2026-09-25T20:20:41",31,"Каспар поднимается, видит труп Стаи\n\n- вы убили тварь? Спасибо вам герои! Она хотела меня сожрать, откуда только взялась, тварь такая!",212725,null],[236261,"2026-09-25T20:24:01",20,"*Беатриче бросает на него очень тяжёлый и говорящий взгляд типа - 'не пизди нам тут'*\n\n*Поворачивается к Марко*\n\n- Сеньор сыщик, не так хорошо разбираюсь в законах, но тут явно есть по вашей части \n\n*Ее рука все ещё крепко сжимает плече Каспара. Не сбежит*",236260,null],[236266,"2026-09-25T20:31:09",31,"Если позволите, я отвечу за Марко\n\n- тут налицо жестокое обращение с животными, но ж о мелкая статья, так, будет штраф\n\nКаспар победно улыбается\n\n- ну и вивисекция и создание химер без лицензии. А это уже каторга. Или отрубание рук. На выбор. Думаю, суд выберет каторгу",212725,null],[236267,"2026-09-25T20:32:39",22,"Видишь, дуреха, даже крысе это понятно. А ты все бежишь да бежишь.\nОт себя не убежишь, дорогая. Однажды твоя дорога заведёт тебя в тупик.\n\nНЕТ!\n\n- Н-нет.. я понимаю тебя. Я п-принимаю твой выбор. Н-надеюсь, что ты б-будешь счастлива.",236250,null],[236269,"2026-09-25T20:35:41",31,"Через некоторое время сюда явилась стража и знакомый Марко следователь Беппо. Они забрали и Каспара и остнки Стаи. Аптека была опечатана, однако вам удалось кое что вытащить на память\n\n+ 2 зелья лечения\n+ 1 зелье алхимического огня\n+ страничка из дневника исследований Каспара, на которой сказано, что объект LJ-9 проявил существенные паранормальные способности и это эксперимент следует продолжить. Так вы узнали имя тоф крысы, что Ясмин называла Найн. Она тоже пропала, скрывшись где то в городском коллекторе. Надеюсь, она будет счастлива",212725,null],[236273,"2026-09-25T20:37:12",31,"// сторонний квест завершен. Опыт за него вы получите в конце арки. Надеюсь, он вам хоть чуток зашёл. Это моя аллюзия на Цветы для Элджернона, но думаю вы и сами это поняли//",212725,null],[236279,"2026-09-25T20:39:02",20,"/будь счастлива, маленькая крыска...",212725,null],[236283,"2026-09-25T20:47:36",31,"//на выходных я ничего вести тут не смогу, я имею ввиду из квестов. Если будут заявки, то постараюсь их обработать. В понедельник начнем сюжетный квест, на него у меня большие надежды//",212725,null],[239982,"2026-09-28T06:12:35",31,"@lady_godzilla @dunchev @PaIIasCat \n\nЗаявок на выходных я не получал, так что предположу, что после истории с крысой вы разошлись по домам или по делам. На следующее утро вы прибыли в контору Феллино. Хозяин встретил вас как всегда радушно, напоил кофе и соверешив все необходимые по этикету реверансы, перешел к делу.\n\n- Беатриче, как я уже говорил вчера, у нас есть подвижки по вашему делу. Точнее, у нас появилась возможность найти информацию из, так сказать, первых уст. Мои агенты, как вы помните, разработали версию о вампире-гастролере, шли стандартным путем, через сравнение списков въехавших в город, опроса капитанов и стражников и так далее. Это не принесло успеха, к сожалению. Но привлекло кое чье внимание.\n\nСтарый табакси протягивает Беатриче письмо. Явно дорогая бумага, ярко-красные чернила, почерк с завитками. Сломанная сургучная печать представляет собой оттиск перстня-печатки с изображением чаши. Ты достаешь письмо из кончарта и читаешь:\n\n\"Многоуважаемый сиор Феллино. Ваши действия по поиску заезжих ночных хищников привлекли мое внимание. Уведомляю вас, что никто из них не посмел бы явиться в город без моего на то дозволения. Кроме пары исключений. Я готов назвать вам эти имена, но в обмен на услугу, которую, к моему глубокому сожалению, клан не может решить сам. Жду вас, либо ваших доверенных агентов в резиденции клана Сангвини. Не приходите в ранние часы, солнце для меня неприятно. Искренне ваш, Энрико Сангвини\"\n\nТы поднимаешь глаза на сыщика. Ты знаешь, кто такие Сангвини. Но предпочитаешь чтобы сам Неро рассказал о них и их интересе.\n\n- Что же, я не ожидал что наше расследование выведет нас на встречу с главой вампирского клана Вальдории. Мне доводилось пересекаться с ними, не скажу что это было приятное общение, но это цивилизованные.... люди. Сиор Энрико Сангвини, патриарх клана, держит руку на пульсе ситуаций с любыми вампирами города, он тут теневой лидер. Граф Ночи, если желаете, но сам он себя так не называет. И если он заинтересован нашими поисками, то возможно дело серьезнее, чем я думал. Он предлагает информацию, это хорошо. Но не бесплатно, нам нужно будет отплатить услугой. Не знаю уж, с чем там не может справится клан, но думаю, стоит как минимум узнать об этом предложении. \n\nНеро смотртт на вас, ожидая ваших реакций",212725,null],[239991,"2026-09-28T08:55:13",17,"Марко напрягся от известий главы вампирского клана\n\n— Беатриче, позволите?\n\nОн взял письмо и прочитал его внимательно\n\n— Значит Энрико Сангвини снимает ответственность со своих людей, если их можно называть людьми. Если все так, как по вашему рассказу Неро, эти несколько \"исключений\" скорее всего очень сильные вампиры. \n\nОн передал письмо Ясмин\n\n— Что ж предлагаю пойти на встречу. Только нужно учитывать, что граф ночи врятли примет отказ, даже если его просьба нам не понравится.",212725,null],[239992,"2026-09-28T08:56:18",31,"- Верно, Энрико мягко стелет, но вряд ли приемлет отказ",239991,null],[239993,"2026-09-28T09:12:52",20,"- Связываться с вампирами... *Беатриче морщится, уже представляя какая услуга могла понадобится Сангвини. Марко прав, просьба им явно не понравится. Но им нужна эта информация. Ей нужна - хотя бы ради Кристины.*\n\n- Чтож, синьоры и сеньорита, похоже нас ждёт крайне насыщенная ночь.",212725,null],[239998,"2026-09-28T09:23:11",22,"- Лезть к хищнику п-прямо в логово? \n\nЯсмин поежилась.\n\nПравильно, девочке, он очень опасный\nОчень страшный\nЗабейся в угол, мышка, и дрожи от страха!\n\n- З-значит так и поступим. Мы ему н-нужны, значит сразу нас не будут у-убивать. Н-наверное...",212725,null],[240006,"2026-09-28T09:29:32",17,"— Он не станет просто убивать нас, это потеря репутации, которую он строил веками",212725,null],[240007,"2026-09-28T09:30:15",31,"- не думаю что вас хотят или захотят убить. В Вальдории даже вампиры стали торговцами, принцип \"Ты мне - я тебе\" работает и у них. Другое дело, что честность и ревность услуг они могут понимать очень спецефично и всегда в свою пользу",212725,null],[240008,"2026-09-28T09:31:33",31,"- ну чтоже, раз вы решили навестить этого \"клиента\", то я напишу ему и скажу, что вы, как мои представители, прибудете после заката, я полагаю, около 8 часов вечера",212725,null],[240009,"2026-09-28T09:33:40",17,"— Возможно он что-то знает о черной земле с мест преступлений. На сколько мне известно вампиры по ночам вынуждены спать в могильной земле внутри гроба. Если это, конечно не сказки.",212725,null],[240012,"2026-09-28T09:36:09",31,"- ну, спросить его вы сможете. А захочет ли он отвечать...\n\nНеро пожимает плечами",240009,null],[240013,"2026-09-28T09:36:49",20,"- Или потребует за это дополнительную услугу *кивает Беатриче*",212725,null],[240017,"2026-09-28T09:46:11",31,"- Видно дитя Вальдории",240013,null],[240021,"2026-09-28T09:48:24",17,"— Волков бояться в лес не ходить. У меня обратной дороги нет, сеньор Неро, попробуйте закинуть удочки ан счет изучения земли через свои связи. Даже если граф ночи откажется помогать, можем вам улыбнётся удача.\n\nПотом к спутницам\n\n— Сиоры, я готов отправляться. У вас есть еще дела или сомнения?",212725,null],[240022,"2026-09-28T09:49:30",31,"- уже работаю, Марко, уже работаю.",240021,null],[240024,"2026-09-28T09:51:32",20,"- Никаких сомнений, сеньор Марко. Разве что то, что пока не стемнело нас ждать не будут *Беатриче помешивает кофе, делая небольшой глоток*\n\n- Так что стоит подумать чем заняться до заката. Может как раз походим порасспрашивает о той самой черной земле?",240021,null],[240026,"2026-09-28T09:54:22",20,"/ну или сразу таймскип",212725,null],[240028,"2026-09-28T09:55:47",31,"Решайте втроём и вперед)/",212725,null],[240037,"2026-09-28T10:08:20",22,"- Черная земля.. К-конечно можно поспрашивать, но к-кого? В-врядли торговцы о ней слышали, но с-судачить о наших вопросах т-точно будут.",212725,null],[240038,"2026-09-28T10:08:21",17,"— Хороший сон днём, чтобы не клевать носом ночью. Мне необходим. \n\n\nСмотрит на бледную кожу Беатриче\n\n— А вы вообще спите, сиора, Беатриче?",212725,null],[240042,"2026-09-28T10:13:27",22,"- Я тоже за х-хороший отдых перед в-визитом.\n\nИ бокальчику для храбрости\nИхихи-хи-хи",212725,null],[240043,"2026-09-28T10:15:17",20,"- Не с кем *Отвечает Беатриче не задумываясь, потом хлопает себя по лбу*\n\n- А, вы про сон, сеньор. Да, конечно сплю - дампирам отдых нужен не меньше чем людям.",240038,null],[240045,"2026-09-28T10:27:14",17,"— Неро, запишите адрес по которому нам нужно прийти к вечеру пожалуйста. Мы пойдём на эту встречу и узнаем, что могло понадобиться графу ночи от вашего сыскного агентства.",212725,null],[240047,"2026-09-28T10:42:07",31,"Неро передает тебе рекомендательное письмо от своего имени, и та отдельном листе адрес, судя по нему, вас ждут в самом дорогом районе города - Палаццо",240045,null],[240054,"2026-09-28T10:52:09",17,"— Что ж. Предлагаю передохнуть до вечера. Неро, вы можете подсказать, что можно прихватить с собой для самообороны? Чеснок, осиновый кол? Это работает или выдумка?",212725,null],[240057,"2026-09-28T11:02:37",31,"- Марко, вы же разумный человек. Вы идете в дом сильнейшего вампира города, подозреваю остальные лишь его \"дети\". При всем уважении, но даже снарядись вы до зубов, шансов даже поцарапать его у вас не будет. Скорее всего не будет. А что до уязвимостей вампиров... Чеснок им неприятен, но не опасен. Первейшее средство от вампира - кол в сердце, но там есть ограничения, он не убьет вампира, а лишь пригвоздит его к гробу. Они не любят солнца, проточной воды и серебра, не могут зайти без приглашения в чужой дом. А, ну и огонь из тоже жжет неплохо. Но учтите, мои знания о вампирах это не практика, а только теория, сам я к счастью не охотился на них даже в молодости.",240054,null],[240058,"2026-09-28T11:04:11",17,"— Конечно, я только в рамках самообороны, чтобы иметь чуть выше нуля шанс спастись. Если вдруг не найдём общий язык.",240057,null],[240060,"2026-09-28T11:06:59",31,"- возьмите святой воды в храме тогда. Недалеко от дома Сангвини Собор стоит же. Не думаю, что это вас бы спасло от желания хозяина вас прикончить, но если для собственного спокойствия...",240058,null],[240062,"2026-09-28T11:09:00",20,"- Эх, это все бесполезно против толпы, только если мы не приведем за собой само солнце *пожимает плечами Беатриче*\n\n- вроде заклинания дневной свет? *Она хмурится, что-то как будто припоминая*\n- матушка о чем то таком упомянала.",212725,null],[240071,"2026-09-28T11:29:21",31,"К маме в гости хочешь?)/",240062,null],[240072,"2026-09-28T11:31:45",20,"/ага, забегу на пару минут попить воды и спросить про вампиров и на улицу меня потом не выпустят...",240071,null],[240073,"2026-09-28T11:33:51",17,"Марко открыл свой кошель и грустно закрыл\n\n— Пойдёмте в церковь, попросим флакон святой воды, мне было бы так чуть спокойнее.",212725,null],[240074,"2026-09-28T11:35:06",22,"- Давайте в-все же зайдём в храм. В-вода лишней не будет.\n\nА еще там тишина.\n\nА что, мы тебе надоели?\n...\nДа да, так и скажи, что мы тебя утомили.\nТы действительно желаешь нашего исчезновения, дорогая?",240062,null],[240075,"2026-09-28T11:36:14",20,"- Ну чтож, храм так храм *Соглашается Беатриче*\n\n/let's go",212725,null],[240076,"2026-09-28T11:37:54",31,"Чуть позже отпишу, пока занят/",212725,null],[240164,"2026-09-28T14:14:58",31,"//не нравится мне как рисует Гемини, а ГПТ еще не откатился, так что без Арта Собора//\n\nВ самом центре Старого города вы находите величественный Собор. Посвящённый Аскелатору, он выше любых зданий Вальдории. \n\nСегодня будний день, и службы нет, поэтому площадь перед Собором не сильно забита народом, так, несколько старушек богомолиц, художников из местной академии искуств, что занимаются зарисовками и колорирые нищие. Ваше внимание привлекает слепой старец, у ног которого стоит кружка для пожертвования и табличка с кривоватой надписью: \"дай слепому 5 монет, он вернет тебе совет\".\n\nВорота Собора открыты, вы без проблем можете войти внутрь и попросить местных жрецов о святой воде или чем бы то ни было еще",212725,null],[240201,"2026-09-28T14:27:07",20,"*Беатриче подходит и кидает в стакан старцу 5 серебряных монет. Какого-то шибко ценного совета она не ждёт (не ешь жёлтый снег?), но благородный статус обязывает проявлять милосердие и участвовать в благотворительности*",212725,null],[240222,"2026-09-28T14:34:43",31,"Старик поднимает на Беатриче взор, укрытый повязкой и скрипит:\n\n- не верь тому, кто в собственной боли ищет наслаждение и ответ",240201,null],[240225,"2026-09-28T14:37:10",22,"Ясмин подходит к старцу.  Она даёт ему мясной пирог, 5 серебряных и плед.\n\n// -1 паек, -5 серебра, -1 тёплая ткань(осталось 2)",240164,null],[240228,"2026-09-28T14:41:35",31,"Старик переводит слепоцтвзор на Ясмин, его ноздри раздуваются от запаха пирога:\n\n- Помни что Свет бывает жесток не только ко Тьме. Тех, кто носит Свет в себе, он тоже не щадит",240225,null],[240230,"2026-09-28T14:42:32",20,"*Беатриче глубокомысленно кивает, будто старик это мог увидеть, и уступает место Ясмин.*\n\n\"Тот кто ищет в боли ответ и наслаждение? Что бы это могло значить?\"\n\n/Так и запишем - мазохистам не доверяем",240222,null],[240239,"2026-09-28T14:51:03",17,"— Вот уж нашли у кого советы получать. \n\nМарко проходит мимо услышав два бесплатных совета он им не придал внимания. Отправляется внутрь чтобы найти жреца и поговорить на счет святой воды.",212725,null],[240258,"2026-09-28T14:55:26",31,"Ты слышишь в спину голос старика, какие то весьма посредственные вирши:\n\nИ без монеты дам совет\nИщи в корнях, там твой ответ",240239,null],[240278,"2026-09-28T15:05:44",22,"//мы две типичные женщины, которые встретили загадочную гадалку-таролога-хироманта",212725,null],[240292,"2026-09-28T15:11:04",31,"Внутри Собора ты почти сразу встречаешь молодого священника, что услышав о твоей нужде в святой воде, тут же предложил тебе фляжку за символические 15 золотых монет",240239,null],[240321,"2026-09-28T15:21:20",17,"Марко подошел и склонил голову перед Падре выказывая благоговение\n\n— Благословите меня, отче. Расследование страшных преступлений против человечности привело нас к сиору Энрико Сангвини. Нам нужно подготовиться, падре. Три флакона святой воды и ваше доброе наставление нужны нам как воздух.",212725,null],[240322,"2026-09-28T15:21:26",22,"Ясмин смотрит исподлобья на священника. Она сжимает руки и упирается пальцами в ладони.\n\nВ ее голове стало тише.\n\n- П-пятнадцать золотых.. за мертвую в-воду..Но в-едь святая вода она в источниках, в земле! А вот фляге.. в металле.. она задыхается.. она с-слабеет. \n\n(Торг?)",212725,null],[240323,"2026-09-28T15:21:37",22,"//опять синхронность капец!",212725,null],[240324,"2026-09-28T15:21:38",17,"/ Мёртвая вода)))",212725,null],[240326,"2026-09-28T15:21:49",22,"Торг!/",240324,null],[240327,"2026-09-28T15:21:55",17,"/ Это когда я провожу ритуал Церемонии и Аннубис освящает воду )))",212725,null],[240328,"2026-09-28T15:22:13",17,"/ Но Ритуал такой стоит 25 Золотых",212725,null],[240329,"2026-09-28T15:22:20",22,"/я тоже подумала, что дома освятим!",240327,null],[240333,"2026-09-28T15:22:45",17,"/ Так что тут выгодно!",212725,null],[240334,"2026-09-28T15:22:46",22,"/я думала бесплатно.. молись там усерднее, все дела..",212725,null],[240336,"2026-09-28T15:22:57",17,"/ Неа ( Компоненты: В, С, М (порошок серебра стоимостью 25 зм, расходуемый заклинанием)",212725,null],[240340,"2026-09-28T15:23:14",22,"/давай еще выгоднее, если мастер разрешит",240333,null],[240350,"2026-09-28T15:29:15",31,"Не наглейте/",212725,null],[240351,"2026-09-28T15:29:23",31,"И так скидка есть)",212725,null],[240352,"2026-09-28T15:29:42",31,"Просто падре очень приглянулся Марко, священники они такие, знаете ли))/",212725,null],[240353,"2026-09-28T15:30:35",31,"А если честно я просто забыл сколько это стоит)/",212725,null],[240354,"2026-09-28T15:31:06",17,"Марко улыбнулся слыша речи иностранки",212725,null],[240356,"2026-09-28T15:32:52",22,"Ясмин перехватила игривый взгляд падре в сторону Марко, побледнела и покинула храм, бурча себе под нос\n\n- Патит Брахмин! (Падший священник)",212725,null],[240357,"2026-09-28T15:33:17",31,"- Сиор Сангвини в чем то подозревается? Ну, учитывая что я никогда не видел его на службе, не могу сказать что это меня удивляет\n\nПередаёт тебе 3 фляжки со святой водой и забирает 45 золота",240321,null],[240359,"2026-09-28T15:34:10",20,"*Где-то на улице Беатриче рассматривает работы художников с живым интересом.*\n\n- Ах, Вальдория да в мазках на холсте ... Che bellezza!",212725,null],[240362,"2026-09-28T15:34:51",31,"Тебе на плечо опускается тяжелая рука",240359,null],[240363,"2026-09-28T15:35:21",31,"Обернувшись, ты видишь одного из братьев Кристины",212725,null],[240365,"2026-09-28T15:35:51",22,"- С-сеньора.. а у вас все с-святые отцы столько с-свободных нравов?\n\nШокированная Ясмин рассказала Беатриче о похотливом священнике.",240359,null],[240366,"2026-09-28T15:35:55",31,"- явилась, убийца? Дай хоть похоронить сестру по людски, не позорь ее после смерти",212725,null],[240368,"2026-09-28T15:37:21",17,"— Мы пока не знаем. Сиор Неро Феллино поручил нам отправиться к Сангвини и разведать.",240357,null],[240369,"2026-09-28T15:38:52",20,"- Убийца?! *Беатриче резко поворачивается к нему, явно пылая праведным гневом*\n\n- Как ты смеешь обвинять меня тут, пока я все эти дни ищу тварь, что посмела ее погубить? Или думаешь в ту ночь только ты потерял дорого человека?!",240366,null],[240371,"2026-09-28T15:39:06",31,"- Сиор Феллино тоже не частый гость наших служб. Но он частый жертвователь, этого не отнять",240368,null],[240373,"2026-09-28T15:39:31",20,"*К рапире не тянется, это всё-таки родственник ее возлюбленной.*",240369,null],[240377,"2026-09-28T15:42:06",31,"Он набычился:\n\n- если бы в ночь ее смерти я не видел тебя бухающей в таверне, я бы уже сейчас открутил твою голову. Но я тебя видел и поэтому знаю, что это не ты. Но если ты была рядом с ней, то защитила бы. А еще лучше, если бы ты не была с ней знакома. Тогда никакая клыкастая тварь не нашла бы к ней дорогу. Может, ты и не убивала Кристину. Но не будь тебя в ее жизни, она бы жила",240369,null],[240401,"2026-09-28T15:50:59",20,"- А где были вы, ее братья?! Почему так ревностно вставали на моем пути, но не оказались рядом когда она действительно нуждалась в вас?! Почему?! *Она взвилась ещё больше, явно подавленная в эти дни горечь снова дала о себе знать. В глубине она злится не только на них. Но и на себя.*\n\n- И нет у меня в знакомых никаких тварей, способных на такое. Иначе я бы не искала сейчас убийцу, а уже наведалась свести с ними счеты! \n\n*Она резко отступает назад, возвращаясь себе самообладание. Нельзя показывать такую слабину, ещё и перед ее спутниками*\n\n- Можешь винить меня сколько душе угодно. Но пока ты этим занят я буду идти по следу этого ублюдка. И когда я это сделаю он заплатит кровь за то что посмел совершить и за все жизни, которые отнял.",240377,null],[240413,"2026-09-28T15:54:56",31,"В его лице ты прочла, что он и сам себе это говорил сотню раз. Он не извинился, и ничего более не сказал. Развернулся и ушел в Собор",240401,null],[240418,"2026-09-28T15:55:58",31,"Не ищите тут смысла, просто мне захотелось добавить штришок к миру. И тем более третий день после смерти Кристины, похороны же должны быть//",212725,null],[240436,"2026-09-28T16:00:03",31,"Итак, Марко купил святую воду, Беатриче встретила человека из недавнего прошлого, а Ясмин узнала о вольных нравах священников Вальдории. Жду ваших дальнейших заявок или планов//",212725,null],[240443,"2026-09-28T16:06:47",17,"Марко вернулся с тремя флаконами святой воды и раздал её спутницам\n\n— Священик толком ничего не знает о Сангвини. Что же, сиоры, идём прямо в пасть ко льву и сами разузнаем.\n\nВидя Беатриче на взводе\n\n— Что-то случилось? Чувствуется сильное напряжение в воздухе",212725,null],[240444,"2026-09-28T16:08:18",20,"- Ах...ничего, просто встретила кое-кого знакомого, сеньор. \n\n*Беатриче встряхивает головой, окончательно беря себя в руки и бросая тоскливый взгляд на храм. Похороны ...да, прошло уже три дня. Она хочет пойти...но понимает что ее присутствие может лишь вылиться в конфликт. Не хочется лишать их ещё и возможности мирно проводить дочь и сестру.*",240365,null],[240461,"2026-09-28T16:33:36",22,"- Спасибо. Я п-просто продолжаю удивляться различным к-культурам. Пообедаем или у вас с-свои планы?",212725,null],[240467,"2026-09-28T16:36:55",17,"— Разыгрался аппетит? Что ж. До вечера еще полно времени, можем зайти и пообедать. Какое блюдо, на ваш вкус приглянулось из местной кухни, сиора Ясмин?",240461,null],[240496,"2026-09-28T16:45:29",22,"- Креветки. С-с чесноком.\n\nЯсмин покосилась на Биатриче и шепотом спросила. \n\n- Или это слишком грубо?",240467,null],[240532,"2026-09-28T16:53:33",20,"- Ох нет, вам нужно кушать больше, сеньорита. Не стесняйтесь. В Вальдории по истине потрясающая кухня, которую стоит пробовать и пробовать *Беатриче все ещё смотрит на собор*\n\n- Прошу меня простить, я что-то не очень голодная. Сеньор Марко, пожалуйста - позаботьтесь о даме. Встретимся вечером\n\n*Он делает немного резкий поклон, быстрым шагом скрываясь за собором. Она не может подойти близко, но и уйти сердце не даёт...так хоть будет присутствовать издалека*",240496,null],[240719,"2026-09-28T17:46:47",22,"- Тогда пообедаем в-вдвоем?",212725,null],[240733,"2026-09-28T17:52:08",17,"— Да, дадим Беатриче время. Тут за углом есть местечко. Прошу \n\nМарко показал Ясмин дорогу до ближайшего заведение где они и присели он первым решил начать разговор. \n\n— Простите за бестактность. Меня пожирает любопытство. Могу я задать вопрос касаемо вашего золотого глаза, синьорита?",212725,null],[240740,"2026-09-28T17:54:00",22,"Ясмин задумчиво коснулась глаза. \n\nЧто произошло, почему она перестала его прятать.\n\nПотому что это лучшее, что в тебе есть, дорогуша!\n\n- И-извините, я сейчас его с-спрячу.",212725,null],[240742,"2026-09-28T17:54:53",17,"— Нет нет, я не хотел обидеть вас.",212725,null],[240750,"2026-09-28T17:56:12",22,"- В-все в порядке. Я знаю, что он с-страшный.\n\nЯсмин опустила голову. Небольшое свечение и глаз снова \"нормальный \".\n\n- Я не хотела в-вас пугать, мне жаль. С-совсем забылась.",212725,null],[240751,"2026-09-28T17:56:20",17,"— Мне просто крайне любопытно, почему вы называете его злым глазом Я видел свет ваших ладонях разве это зло?",212725,null],[240755,"2026-09-28T18:00:38",22,"- Так люди говорят. С детства. Везде. Мол посмотрю я \"неправильно\" и то молоки скиснет, то корова сдохнет. Как будто я правда в этом виновата.\n\nА кто еще?\nА кто себе под нос бубнел, когда буренка боднула?\nВрушка!\n\nЯсмин повела плечами.\n\n- Еще я с-слышала, в путешествиях, как матери обнимали с-своих детей и говорили не смотреть мне в глаза. Особенно в \"злой глаз\". П-понимаете? Двухметровые говорящие з-звери для них м-милые, а зло! И в-все из-за этого шайтанового глаза.\n\nЯсмин закусила губу и опустила взгляд вниз.",212725,null],[240760,"2026-09-28T18:12:40",17,"Марко некоторое время молчал, крутя чашку за ручку.\n\n— Значит доказательство против вашего глаза следующее. Кто то посмотрел на него, потом скисло молоко. Или умерла корова.\n\nОн слегка нахмурился.\n\n— Слабовато.\n\nМарко поднял взгляд на Ясмин.\n\n— Сколько раз люди смотрели вам в глаза и после этого не происходило ничего? Полагаю, никто не считал.\n\nОн отпил из чашки.\n\n— Люди вообще любят сначала назначить виновного, а потом подтянуть любые доказательства. Я много лет наблюдал эту привычку профессионально.\n\nМарко немного помолчал.\n\n— Допустим даже они правы. Допустим ваш глаз действительно способен приносить несчастье. Я видел достаточно проклятий чтобы не отбрасывать такую возможность только потому, что она звучит странно.\n\n— Тогда это всё ещё не делает его злым.\n\n— Яд убивает. Огонь обжигает. Некоторые заклинания делают вещи похуже. Но зло требует намерения.\n\nМарко посмотрел на её уже изменившийся глаз.\n\n— Вы желали смерти тем коровам?\n\nОтвет был очевиден, поэтому ждать его он не стал.\n\n— Вот и я так думаю.\n\nНесколько секунд он разглядывал Ясмин, уже скорее как загадку чем как что то пугающее.\n\n— Если однажды захотите узнать правду, а не то что о вас решили чужие люди, можно проверить ваш глаз.\n\nЧуть пожал плечами.\n\n— Наблюдать. Записывать. Сравнивать. Как любое другое необычное явление. Я в этом разбираюсь. Это уже серьезный подход будет, а не просто слухи. \n\n\n— Хотите я займусь вами и вашим глазом серьезно, сиора?",212725,null],[240781,"2026-09-28T18:25:33",22,"- Я.. \n\nНу давай. Начни заливать, что корове зла не желала\nИ в молоко то не плевала\n\n- Я буду рада у-узнать о нем правду.\n\nВ голове Ясмин раздается булько-хлюпающий звук и кашель, будто кто-то подавился.\n\nАХАХАХАХАХА\n\nДевушка помирилась, будто от головной боли.\n\n- С-спасибо вам. Вы очень доб..любезны.\n\nЯсмин слабо улыбнулась и подняла взгляд на Марко.",212725,null],[240833,"2026-09-28T18:42:07",31,"Чутка Лора персов? Очень хорошо/",212725,null],[240850,"2026-09-28T18:47:59",17,"Марко заметил слабую улыбку и сам едва заметно улыбнулся в ответ\n\n— Тогда договорились. Будем считать это новым расследованием.\n\n— Правда есть одна сложность. Для наблюдений объект исследования желательно держать поблизости. Так, что хочу извиниться если вам покажется то вам не кажется, что я слишком пристально разглядываю ваше лицо, сиора. Заранее извиняюсь, иначе никак.\n\nМарко на секунду задержал на ней взгляд, потом совершенно спокойно продолжил\n\n— Вы говорили что много путешествовали. Было хоть одно место откуда вам не хотелось уезжать?",240781,null],[240923,"2026-09-28T19:21:07",22,"Ясмин смутилась и неосознанно провела ладонью от локтя к запястью, словно пытаясь успокоиться.\n\nДома, конечно же\nВерно. И чего только бежала?\nТихо, не отвлекайте, а то опять НАЛАЖАЕТ\nИ-хи-хи-хи\n\n- Был один монастырь...\n\nВ ее руках ритмично застучали перебираемые четки.\n\n- Это было очень д-давно и очень далеко. Глухая деревня, к-куда я попала по ошибке, в-ведь я тогда плохо знала язык. Но это было п-прекрасное место. Он был словно посреди цветущего с-сада. Я провела там три года, д-дольше, чем где-либо еще. Именно там я узнала, что мой с-свет можно развить, что я могу д-дарить людям излечение. Моя н-наставница была доброй женщиной. Она не б-боялась меня.\n\nДевушка прикрыла глаза, погрузившись в воспоминания. Прекрасные белые цветы, похожие на белые звездочки, тонкий аромат ванили, сменились раскатами грома и стеной дождя. Ясмин сжала зубы и попыталась открыть глаза.\n\nКуда собралась, дуреха?\nТы правда думала, что просто вспомнишь свои цветочки и ванильки?\nНачала вспоминать, так вспоминай ДО КОНЦА\n\n- Б-буря. Сильная буря, которую не видели н-никогда раньше, она уничтожила все.\n\nПродолжила говорить девушка не открывая глаз. Четки в были зажаты в кулаке настолько сильно, что костяшки побелели.\n\n- Я н-не смогла им помочь. Я не с-смогла их спасти.\n\nПо ее щеке потекла слеза.\n\n- Я с-смогла лишь СБЕЖАТЬ!\n\nВыкрикнула она и резко дернула головой. С шумным вдохом девушка отвернулась к стене и спрятала свое лицо в руках, пытаясь выровнять дыхание.",212725,null],[240962,"2026-09-28T19:34:00",17,"/ Можно ли понять что Ясмин испытывает чувство вины? Будто она это навлекла?",212725,null],[240999,"2026-09-28T19:42:50",22,"/думаю да, она постоянно себя во всех бедах вокруг винит",212725,null],[241014,"2026-09-28T19:45:45",31,"Я это потом обыграю, если что. Сегодня с утра придумал как/",212725,null],[241033,"2026-09-28T19:50:57",31,"Даже немного природу сил кастомных южных карг Полины придумал)/",212725,null],[241053,"2026-09-28T19:57:39",17,"Марко не стал сразу отвечать. Подвинул к ней стакан воды и дождался пока дыхание станет хоть немного ровнее.\n\n— Вполне возможно.\n\nОн сказал это спокойно\n\n— Возможно буря действительно была связана с вами. С глазом. С чем то ещё, чего вы не понимаете\n\nМарко достал Книгу мертвых \n\n— Я слишком давно занимаюсь странными смертями чтобы говорить человеку \"это просто совпадение\" когда у меня нет доказтельств\n\nПеро заскользило по странице\n\n\"Ясмин. Монастырь. Три года без происшествий\"\n\n\"Аномальная буря. Причина неизвестна. Возможная связь с золотым глазом. Злым глазом.\"\n\nОн немного подумал и добавил ещё строчку.\n\n\"У нее самой злого умысла явно не было\"\n\nМарко поднял на неё глаза\n\n— Вот это важн. Если ваш глаз вызвал ту бурю, я хочу понять как. Почему именно тогда. Почему не раньше. Можно ли было её остановить.\n\nМарко посмотрел на сжатые в кулаке чётки\n\n— Следствие обычно работает именно в таком порядке. Сначала факты. Потом приговор\n\nИ чуть тише добавил\n\n— Люди почему то очень любят делать наоборот. Не приговаривайте себя, Ясмин. Давайте разберемся. Докопаемся до сути.",212725,null],[241077,"2026-09-28T20:03:14",22,"/если честно, вдохновениями выступали стат блоки этих леди\nЛеди 1\nЛеди 2\nЛеди 3",241033,null],[241097,"2026-09-28T20:06:24",22,"Ясмин делала глоток за глотком, успокаивая эмоции.\n\n- С-спасибо. Правда спасибо.\n\nОна дотронулась было до руки Марко, но быстро ее одернула, звякнув браслетами.",212725,null],[241104,"2026-09-28T20:07:26",31,"Это статы для Ясмин, или ковена?/",241077,null],[241116,"2026-09-28T20:08:36",22,"/ковен. Спелы там огонь\nПоследняя хага чисто из моего первого ваншота. Я ей вдохновлялась.\nЭх, кто-то любит единорогов и фей, а я хаг🥲",241104,null],[241118,"2026-09-28T20:09:04",31,"Это хорошо, это может пригодится)/",241116,null],[241157,"2026-09-28T20:14:44",17,"— Я благодарен. Правда. За вашу откровенность. Хочу ответить тем же. А вы хотите задать мне какой то вопрос? Обещаю ответить честно \n\nТень всколыхнулась шакалиный бог, или те отголоски, что от него остались, не любил когда его упоминали.",212725,null],[241188,"2026-09-28T20:19:23",22,"- К-конечно. В вашей голове тоже живёт кове..к-карнавал? Ну..\n\nЯсмин замялась.\n\n- Я видела ваши.. или не ваши.. лапы. И странную тень. С золотыми глазами..",241157,null],[241280,"2026-09-28T20:36:35",17,"Марко на несколько секунд замолчал.\n\n— Нет. Не карнавал\n\nОн посмотрел на собственную тень\n\n— По крайней мере я очень на это надеюсь\n\nМарко чуть откинулся на спинку стула.\n\n— Его звали Анубис. Когда то давно его почитали как проводника мёртвых. Хранителя границы между теми кто ещё дышит и теми кому уже пора в загробный мир\n\nМарко пролистывает быстрое нигу мертвых \n\n— Теперь он мёртв\n\n— В книге мертвых я нашёл его погребальные обряды. Решил провести один\n\nМарко усмехнулся одним уголком рта\n\n— Из профессионального любопытства\n\nОн продолжил уже серьёзнее.\n\n— Во время ритуала моя тень стала похожа на шакала, потом слилась со мной, пропала на время\n\nМарко постучал пальцем по груди\n\n— Думаю от самого бога давно ничего не осталось...\n\nЗадумался на пару секунд\n\n— Скорее лишь эта тень, отголосок былой силы\n\n— Иногда я чувствую его. От этого и воплощения на голове и руках. Иногда он спасает мне жизнь... А иногда разговаривает, чаще ругается \n\nМарко нахмурился\n\n— Обычно когда я почти умер. Сообщает что я слаб, глуп и разочаровываю его своим нежеланием умирать достойно, а ещё когда не добиваю противников",241188,null],[241316,"2026-09-28T20:43:38",17,"/ Наверное я всех утомил своими полотнами) стараюсь облегчать текст. но вижу что не совсем выходит))",212725,null],[241478,"2026-09-28T21:08:49",22,"/мне нравятся твои полотна, не надо ничего облегчать",241316,null],[241514,"2026-09-28T21:14:07",22,"- Как.. К-как ты пришел к нему? \n\nЯсмин наморщила лоб и закусила губу.\n\n- Я видела д-других жрецов смерти, но все они были.. Будто уже одной ногой с-стоят в могиле и им точно было п-плевать на проблемы ж-живых людей.\n\nБог смерти мертв?\nВот же неудачник!\n\n- С-слаб и глуп.. Ха! Тебя так называет тот, кто умудрился п-потерять собственное царство? \n\nНИЧТОЖЕСТВО!\n\n- Я-я хотела с-сказать, что он н-неправ. В-вы очень сильны, я в-видела.\n\nДевушка активнее перебирала четки, заметно нервничая.",241280,null],[241593,"2026-09-28T21:33:59",17,"— Главное расследование моей жизни привело меня сначала к владельцу этой книги. А уже через него к Анубису.\n\nМарко тяжело выдохнул и на несколько секунд задержал взгляд на книге мертвых. Обложка кованая металлом инкрустирована мертвым хризолитом. Жёлтым мутным камнем.\n\n— Но о самом расследовании я, пожалуй, расскажу вам в другой раз.\n\nОн посмотрел на Ясмин с какой то теплотой\n\n— На сегодня нам обоим хватит откровений\n\nОн снова берет вилку и нож. Нужен ещё разделаться со стейком\n\n— И всё же… благодарю вас, Ясмин. Я вижу вы - загадка, совсем не чудовище и не зло. Если позволите. я продолжу искать разгадку. Ведь мне по настоящему стало интересно. \n\nМарко начинает нарезать кусок прожаренного мяса\n\n— А сейчас предлагаю просто пообедать. От такой интересной беседы у меня сильно разыгрался аппетит",241514,null],[241641,"2026-09-28T21:51:07",22,"Ясмин кивнула и приступила к своему чесночно-креветочной пасте.",212725,null],[242117,"2026-09-29T02:51:45",31,"Относительно больших полотен текста -; видимо это фишка этой кампании) графоманы собрались)) но вроде никто не страдает)/",212725,null],[242121,"2026-09-29T05:11:59",31,"Ладно, думаю хватит филлеров, делаем таймскип до вечера//",212725,null],[242122,"2026-09-29T05:20:01",31,"Солнце над Вальдорией начало заходить около 7 вечера, для вас троих это стало сигналом, что пора идти на встречу с клиентом. \n\nРайон Палаццо существенно отличался от остальных частей города. Тут чисто, тихо, нет разбитых фонарей и некоторые дома потрясают воображение своей роскошью. Стража на улицах без перегара и внимательна. Кажется, тут не может произойти ничего плохого.\n\nНужный вам дом находится на Юго-Востоке района, и не является самым большим и роскошным, го все же примечателен. Вы не понимаете, откуда у вампиров столько денег, но может сказывается то, что им как минимум на еду и лекарства тратится не нужно? Позубаскалив (ха-ха) на эту тему, вы подходите к двери Графа Ночи.",212725,null],[242128,"2026-09-29T06:32:38",17,"Марко кивает спутницам и берется за дверной молоточек. Отлитый из олова в форме бутона розы. Он пару раз уреренно стучит им в дверь.",212725,null],[242129,"2026-09-29T06:50:22",31,"Спустя несколько секунд дверь открывается. Перед вами стоит высокий бледный человек в строгом черном костюме:\n\n- вы от сиора Феллини? Проходите, господин ожидает вас\n\nДворецкий ведет вас по зданию,  тут темновато, шторы почти везде задернуты. Вы минуете коридор, гостиную, еще один коридор и заходите в рабочий кабинет.",242128,null],[242130,"2026-09-29T07:02:04",31,"В кабинете вы видите хозяина, Энрико Сангвини. Он выглядит моложаво, но глаза выдают возраст, они слишком неправильно выглядят на вечно юном лице.\n\nЗаметив вас, и  задержав внимательный взгляд на Беатриче, он поднялся с бокалом чего  то красного в руках и поприветствовал вас\n\n- Добро пожаловать в мой дом, сиор и сиоры. Я ожидал вас и вижу, что не ошибался в ожидании.\n\nСмотрит на Ясмин:\n\n- думаю, не ошибусь, если скажу что вы тут эксперт по проклятиям. Это хорошо. Люблю профессионалов своего дела.\n\nСмотрит на Беатриче:\n\n- В вас я чувствую... родство, пожалуй. Мы обсудим это. Позже\n\nСмотрит на Марко:\n\n- Вы, сиор, видимо за старшего в группе? Разумный выбор.\n\nЭнирико садится и приглашает сесть вас.\n\n- присаживайтесь, мне есть что сказать. Может, хотите что то выпить? У меня есть прекрасное, но довольно терпкое вино, не всем оно по вкусу...\n\nПроизнося последние слова он смотрит в основном на Беатриче, похоже ему важно, чего хочет выпить дампирша.",212725,null],[242134,"2026-09-29T08:11:48",22,"/вот поросюшка. Ну хоть понятно, почему жабо бордовое🙈",212725,null],[242135,"2026-09-29T08:13:50",22,"Ясмин аккуратно присела и ожидала реакции Беатриче. \n\nПравильно, рот не открывай.\nЧесноком смердит так, что даже мы слышим.\nОй а парень то ничего. Наверняка наш ровесник.",212725,null],[242166,"2026-09-29T09:54:51",17,"— Благодарю за радушный приём, сеньор Сангвини. Уверяю вас, что наша группа специалистов отлично обходится без лидера. Неро Феллини передаёт привет отправил нас по вашему приглашению, дабы помочь вам и вот мы здесь. Надеемся сможем быть полезны.\n\nМарко присел к вину не притронулся",212725,null],[242167,"2026-09-29T10:02:55",31,"Энрико отводит изучающий взгляд от Беатриче и смотрит на Марко:\n\n- Надеюсь, что будете. Что же, к делам, время ведь и правда не ждет. Некоторое время назад, около недели, мы столкнулись с проблемой, которую сами решить не можем. Представители моей семьи стали страдать от сильных солнечных ожогов. Это, конечно, не удивительно для вас, ведь вы и сами видите, какая у Сангвини белая кожа, солнце для нас вредно. Но удивительно тут то, что мои дети получают ожоги во время сна. То есть они буквально ложаться спать, никак не контактруют с солнцем, разве что во сне его видят, а прсыпаются солнечными ожогами разной степени тяжести. Я подозреваю проклятие, но не понимаю ни того, кто бы его наложил, ни того, как это было бы сделано. Поэтому и обратился к сиору Феллино, тем более, мне есть чем отплдатить кроме банальных денег. Впрочем, и их я готов платить",242166,null],[242174,"2026-09-29T10:09:26",17,"— К сожалению это, что то новое никогда в своей практике с таким не сталкивался. \n\nМарко листает книгу мёртвых\n\n— Можете назвать имена пострадавших?\n\n\"Быть может их имена проявятся в книге\"\n\n— Еще нам нужно осмотреть их.  Сиора Ямин смыслит в проклятьях.",212725,null],[242184,"2026-09-29T10:14:11",31,"- пока пострадали четверо, но не погиб никто. Стефано, Рокко, Базиль и Роман. Все они Сангвини, разумеется",242174,null],[242185,"2026-09-29T10:14:20",20,"- Благодарю за радушный прием, синьор Сангвини.\n\n*Беатриче делает лёгкий поклон, проходя за остальными в кабинет. Вампиры...она раньше не сталкивалась с ними так близко. В ней сейчас смесь осторожности и любопытства.*\n\n*На слова о вине она приподнимает бровь. Интересно что там за сорт вина - первая положительная? Немного подумав она кивает, когда природное любопытство берет верх.*\n\n- Было бы очень любезно с вашей стороны. Versalo, signore.\n\n*После этого начинает внимательно слушать, как Марко ведёт расспрос - хорошо когда с ними есть профессионал своего дела*",242130,null],[242191,"2026-09-29T10:18:37",31,"Вино на вкус и впрямь терпкое. И с привкусом железа. Похоже, оно хорошо сдобрено кровью\n\n//Катя, а твой персонаж вообще кровь ранее пил? По идее, дампиру это не нужно на постоянной основе, но Жажда все равно должна быть\n\nГолод дампира\nКаждый дампир знает, что жажду могут утолить лишь живые. Те, кто злоупотребляют, утоляя свой голод, рискуют потерять контроль и навсегда видеть в других лишь добычу. Те же, кто сопротивляется, могут обнаружить неординарные способы контролировать свои желания или подавлять их с помощью постоянного воздержания вплоть до зубного скрежета. В любом случае, искушение преследует дампиров, и обстоятельства постоянно складываются таким образом, чтобы давать им бесконечные поводы для искушения.\nХотя большинство дампиров жаждет живой крови, ваш персонаж может утолять иной голод. Совершите бросок или выберите самостоятельно один из вариантов таблицы «Голод дампира», чтобы определить, что именно привлекает вашего персонажа в качестве пищи.\nГолод дампира\nк6\nГолод\n1\nКровь\n2\nПлоть или сырое мясо\n3\nСпинномозговая жидкость\n4\nПсихическая энергия\n5\nСны\n6\nЖизненная сила\n\nБудь добра, опиши реакцию на кровь в вине. ну или скажи, чем ты ранее утоляла Жажду//",242185,null],[242194,"2026-09-29T10:19:07",20,"/Беатриче по классике - кровь\n/Так что пила, просто не у людей",212725,null],[242195,"2026-09-29T10:19:29",31,"- Осмотреть можно, Роман сейчас тут, дома, остальных я отосла под защитой в резиденцию за городом",242174,null],[242197,"2026-09-29T10:19:53",31,"ну тут человечья/",242194,null],[242218,"2026-09-29T10:28:08",20,"*Беатриче делает небольшой глоток и задерживает во рту, чтобы по привычке оценить вкус вина как учил отец. Замирает*\n\n*Кровь. Точно привкус крови, но...вкуснее всего что она когда либо пробовала. Совсем не такая, как у животных. Неужели человеческая? Madore Santa...*\n\n- Какой...насыщенный букет. Синьор похоже ценитель необычных сортов. *Говорит она, делая ещё один невольный глоток. Нет, нельзя слишком к этому пристращаться - матушка всегда говорила что до добра это не доведёт...*\n\n- Хотя моим спутникам вряд ли подойдёт, слишком уж крепкое для не искушённых.",242191,null],[242223,"2026-09-29T10:31:55",31,"Энрике поощрительно улыбается.\n\n- рад такой заботе о друзьях. И рад что вы оценили букет, по глазам вижу что вы не ценитель... излишеств\n\nВпервые выпитая человеческая кровь обострила твои чувства, ты получаешь временный бонус +1 к проверкам восприятия и анализа. И ты сразу замечаешь, что хозяин дома рад твоей реакции, похоже для него важно, что ты не безумная кровопийца",242218,null],[242227,"2026-09-29T10:35:46",22,"- Позволите осмотреть комнаты д-детей? А в-взорслые как спят? Т-тоже возникают ож-жоги?\n\nСжигает всех своей красотой\nТочно\n\nЯсмин помассировала висок. Ей явно хотелось уйти подальше от этого отвратительно-смазливого мужчины, на которого тетушки явно пустили слюну.",212725,null],[242234,"2026-09-29T10:38:43",31,"- все мои дети уже взрослые. малышей у нас нет\n\nЭнрико забавляет эта мысль\n\n- пойдемте, я провожу вас к Роману",242227,null],[242243,"2026-09-29T10:50:29",31,"Энрико встает из за стола, гибкий, хищный, опасный. Тетушки в голове Ясмин восхищенно-насмешливо заохали.\n\nХозяин ведет вас темными коридорами в роскошно обставленую спальню. Вы видете в ней кровать под балдахином, на кторой полулежит мужчина, замотаный в бинты. Запах железа и какой то гнили стоит в комнате. В руках мужчины бокал того же вина, что пил Энрико, бутылка с ним стоит початая на столике у кровати\n\n- Роман, эти люди здесь, чтобы разобраться с проклятием. Я был бы очень благодарен тебе, если бы ты помог им\n\nРаненый вампир склоняет голову\n\n- Конечно, отец. Спрашивайте, я постараюсь на все вопросы отвтеить",212725,null],[242245,"2026-09-29T10:54:40",9,"//Её руки и сюда добрались",212725,null],[242246,"2026-09-29T10:54:57",31,"согласовано/",242245,null],[242247,"2026-09-29T10:55:21",22,"//ты параноик! Все бдишь!",242245,null],[242306,"2026-09-29T13:44:46",17,"/ Такс все ждут следователя видимо) Щааааас",212725,null],[242307,"2026-09-29T13:48:58",22,"//блин простите меня хард сбил. Я поржала и забыла, что пост уже есть от мастера 😅\nНо предложение Коли мне нравится",212725,null],[242309,"2026-09-29T13:50:42",31,"Не торопитесь, я на часок примерно отойду",212725,null],[242314,"2026-09-29T14:00:30",17,"Марко подходит к кровати ближе, на секунду задержав взгляд на бинтах\n\nМарко пододвинул стул и сел. Достал записную книжку\n\n— Доброго вечера, Роман. Начнем с простого. \n\nКогда вы легли спать и когда обнаружили ожоги? \n\nПроснулись во время сна от боли? \n\nГде именно появились первые ожоги? На каких участках?\n\nМожет быть видели сон?\n\nМарко переводит взгляд на Энрико\n\n— Что общего у четверых кроме фамилии?\n\nОн снова смотрит на Романа\n\n— После опишите пожалуйста несколько дней до первого ожога.\n\n— И пока рассказывайте, разрешите сиоре, Ясмин, размотать бинты чтобы осмотреть ожоги детальнее",212725,null],[242319,"2026-09-29T14:06:50",22,"Ясмин тихо подошла к Роману и стала осматривать его раны с помощью медицины.",212725,null],[242320,"2026-09-29T14:07:00",22,"/r +d20+6",212725,null],[242327,"2026-09-29T14:30:02",20,"*Беатриче остаётся чуть в стороне, она ведь не следователь и не врач, помочь особо не может, но тоже осматривает мужчину на предмет каких-то травм, странных меток или запаха помимо ожогов. Вдруг что-то тоже заметит*",212725,null],[242328,"2026-09-29T14:30:15",20,"/r d20+3+1 внимание",212725,null],[242383,"2026-09-29T15:21:15",31,"- Мы вчетвером вернулись с бала Магистрата, наверное около 4 часов утра, распили по бокалу вина и отправились по \"постелям\". \n\n//ты понимаешь что под постелью тут точно не эта кровать с балдахином имеется ввиду//\n\n- да, сон я видел, что странно, я не вижу снов уже много лет. Это был восход солнца, чего я тоже много лет не видел и даже не думал, что помню его. Во сне я почувствовал дикую боль на коже, запах паленого мяса ударил в ноздри, от этого я и проснулся. Думаю, проспи я еще немного, то уже бы не смог проснуться. Очнувшись, я увидел что на моих руках, груди, голове были кровоточащие ожоги, ровно в тех местах, что и во сне. Я слышал крики своих братьев из других комнат, уже потом межне рассказали что все мы видели одно и тоже, но пострадали по разному, Рокко пострадал сильнее всех, видимо, выпил больше нас и никак не мог проснуться. Отец отправил их в загородный дом, остался что проклятие в доме висит. Меня оставил как самого здорового.\n\nЭнрико вступает в разговор:\n\n- мои сыновья, помимо фамилии, могут похвастаться разчк что тесной семейной связью, они все очень дружны, и проводят время в компании друг друга обычно. Если конечно не заняты семейными делами. Разве что слишком любят развлекаться на балах и вечеринках, но что уж там, это дело молодое.\n\n//у тебя мелькает мысль, а что для вечно живущих вампиров молодость? Первые 300 лет после обращения?//\n\nРоман продолжает:\n\n- на следующий день кошмар повторился, и день спустя тоже. Моя жизнь сейчас превратилась в череду кошмаров и регенерации. За ночь я лечусь - он поболтал в воздухе бокалом - днем опять горю во сне и так по кругу. И у братьев за городом тоже самое.\n\nОн помолчал, собрался с мыслями и продолжил:\n\n- что до наших дел до этой проблемы... Ничего не обычного, все как всегда. На мне в плане лежит обязановиься следить за делами наших торговых лавок с антиквариатом, другие братья тоже отвечают за иные направления семейного дела. Я не припомню чего то необычного",242314,null],[242384,"2026-09-29T15:22:12",31,"Ты видишь солнечные ожоги. Тебе, южанке, они хорошо знакомы. Судя по всему, организм вампира регенерирует, но уже на пределе, даже его способности не безграничны",242321,null],[242387,"2026-09-29T15:23:20",31,"- твои обостреные чувства говорят о том, что Роман пьет какое то иное вино, не то же что ты пробовала у Энрико. Неужели патриарх экономит на детях?",242329,null],[242473,"2026-09-29T15:33:42",20,"*Беатриче задумчиво хмурится. Вряд ли это экономия, скорее всего в вине есть что-то способствующее регенерации, а не просто кровь для утоления голода*",242387,null],[242514,"2026-09-29T15:50:31",22,"Ясмин аккуратно продолжает осмотр. \n\n- Расскажите, как прошёл бал? Может с кем-то п-повздорили? Что именно в-вы пили? Какое оно было на вкус и отличалось ли от в-выших обычных напитков?\n\nЯсмин проводит рукой по лбу мужчины(горячий?)",212725,null],[242515,"2026-09-29T15:50:59",22,"/r +6 внимательный поиск проклятия по визуалу",212725,null],[242517,"2026-09-29T15:51:17",22,"//парень облапан✅",212725,null],[242529,"2026-09-29T15:55:47",31,"Это на что бросок? Восприятие, магия или то?/",242516,null],[242539,"2026-09-29T16:01:16",31,"- ну что вы, сиора, какой же бал без пары вызовов на дуэль? Хотя нас с братьями не задирают, отвыкли уже от таких глупостей. Что пили? Да не припомню, если честно. Что то легкое и сладкое. Ну и дома еще перед сном по бокалу нашего семейного купажа\n\nКивает оа бутылку\n\nТы слушаешь его в полуха, занимаясь осмотром. Твоя внимательность в осмотре ран оправдалась, ты поняла что ожоги эти магического происхождения, это явное проклятие. И ты понимаешь, что уже что то подобное видела, на корабле, что привез тебя сюда. Похоже, тут тоже сработал подклад",242514,null],[242541,"2026-09-29T16:02:34",22,"//Восприятие, я текстом писала про внимание. На знания Ясмин тупая(-1). Так что по факту просто потискала парня.. капец",242529,null],[242552,"2026-09-29T16:06:08",31,"День прошел не зря, мама и тетуи довольны/",242541,null],[242553,"2026-09-29T16:06:35",22,"/точно, а Ясмин красная как рак. Второй раз бросок 20 на осмотр полуголого мужика",242552,null],[242554,"2026-09-29T16:06:53",31,"Ну может это знак судьбы?)/",242553,null],[242555,"2026-09-29T16:07:55",22,"/фе этот парень точно не для меня. Слишком смазливый. Забирайте обратно",242554,null],[242557,"2026-09-29T16:08:26",31,"Его сердце разбито, он засыпает и сгорает/",242555,null],[242561,"2026-09-29T16:10:47",22,"/Очень вас жаль, мужчина. Держитесь там. Алоэ мажтесь 🤝",242557,null],[242624,"2026-09-29T18:36:05",17,"— Ясмин. Что то необычное обнаружила?",212725,null],[242625,"2026-09-29T18:37:44",22,"- Я..Я... \n\nЯсмин густо покраснела. Она видела всякое, но что именно зацепило ее взгляд сильнее всего. \n\nКасаемо возможного проклятия,  конечно же\n\n@QURTZZ",212725,null],[242626,"2026-09-29T18:38:38",31,"Я просто в одном посте все написал, мой косяк/",212725,null],[242627,"2026-09-29T18:39:01",17,"/ Дам наводочку подводочку мне нужно узнать что это подклад",212725,null],[242628,"2026-09-29T18:39:05",31,"Вот",242539,null],[242629,"2026-09-29T18:39:44",22,"/ща пропишу, попробую одной рукой. А то в метро можно только голосовым. Но боюсь мои наигранные заикания не поймут😅",212725,null],[242630,"2026-09-29T18:40:08",17,"/ Отыгрыш голосом в метро!",242629,null],[242631,"2026-09-29T18:40:23",17,"/ Ещё и с интонациями))",212725,null],[242632,"2026-09-29T18:40:57",17,"/ Вообще ещё кружок записать! Чтобы мимика была видна!)",212725,null],[242634,"2026-09-29T18:41:47",17,"/ Санитары врываются в вагон))",212725,null],[242635,"2026-09-29T18:42:20",22,"///тут толпа, я звездой стою. Куда толпа, на той станции и я выйду🥲",242634,null],[242637,"2026-09-29T18:46:52",22,"/шрифт не могу исправить, там курсив крч",212725,null],[242639,"2026-09-29T18:52:08",17,"Марко перестал писать и посмотрел на Ясмин\n\n— Подклад?\n\nОн на секунду задумался, после чего перевёл взгляд на Романа и бутылку\n\n\"За городом у братьев продолжается. Значит не дом\"\n\n— Если я правильно понял сиору Ясмин, проклятие должно быть привязано к чему то материальному. Предмету, который находится рядом с жертвой\n\nМарко постучал карандашом по краю записной книжки\n\n— Или внутри неё... Вы же... Пили что то на балу.\n\nОн посмотрел на Ясмин\n\n— Такое возможно? Что то достаточно мелкое. Пыль, песок, металлическая крошка. То что можно проглотить и даже не заметить в осадке напитка?\n\nМарко постучал пером по пергаменту ещё раз и сильнее\n\n— На балу вы пили разное. Но дома... Дома вы пили одно и тоже. Та бутылка семейного купажа осталась?",212725,null],[242640,"2026-09-29T18:56:52",31,"Роман в растерянности:\n\n- бутылка? Д-да, мы пили из одной. Просто взяли из ящика. И вот эту - показывает на ту что стоит на столике - мне тоже тд того же ящика принесли...",242639,null],[242641,"2026-09-29T18:57:26",31,"Я ответил на заявку Марко, так как она продолжает заявку Ясмин/",212725,null],[242644,"2026-09-29T18:59:03",17,"— Дайте пожалуйста изучу. Возможно что то есть.\n\nМарко сперва колец палец совершенно забыл что он в окружении вампиров. Кровь выступает и он выводит глиф око Анубиса в книге мертвых. Перамент поглощает кровь. А остаток он выбирает быстренько своим расшитым красивым платком. \n\n/ Ритуал обнаружение магии чтобы посмотреть на бутылку и на вино в бокале Романа",212725,null],[242647,"2026-09-29T18:59:53",31,"На это нужно кидать проверку?/",242644,null],[242648,"2026-09-29T19:00:41",17,"/ Нет если там есть наложенное заклинание я вижу свечение и могу определить школу магии. Например некромантия",212725,null],[242649,"2026-09-29T19:06:07",31,"Твой ритуал показывает, что вино в бокале Романа светится магической аурой, что то вроде смеси школ Очарования и Некромантии, но конкретное заклинание ты определить не можешь. Бутылка, а точнее ее содержимое, фонит еще сильнее",242644,null],[242650,"2026-09-29T19:10:48",17,"Золотое свечение из глаз Марко светится сильнее и вокруг в воздух поднимается песчинки они парят около ресниц\n\n— Определено вино затронуто магией. Школы очарования и некромантии. Давайте разбираться. Может это обычная практика подвергать семейный купаж магическим заклинаниям или это злой умысел.",212725,null],[242651,"2026-09-29T19:11:47",31,"Это вопрос? Кому?/",242650,null],[242652,"2026-09-29T19:12:21",17,"/ Всем",212725,null],[242653,"2026-09-29T19:12:32",17,"/ Сангвини тут патриарх пусть даст реакцию",212725,null],[242654,"2026-09-29T19:12:36",17,"/ Это его вино",212725,null],[242655,"2026-09-29T19:13:47",31,"Энрике:\n\n- нет, мы не зачаровываем свое вино. Это просто купаж сухого красного и донорской крови, не более того",212725,null],[242656,"2026-09-29T19:15:17",20,"/r d20+2 проницательность?",242655,null],[242658,"2026-09-29T19:15:29",31,"- мы ведь в обществе живём, и нам не пристало охотится как зверям. Мы разбавляем кровь вином, чтобы она дольше сохранялась и не сворачивалась. Ну и из любви к виру, конечно",212725,null],[242659,"2026-09-29T19:16:04",31,"По лицу Энрике ничего не скажешь, маску он держит хорошо. Но и голос вроде не выдает лжи",242656,null],[242660,"2026-09-29T19:22:30",20,"*Беатриче переглядывается с Марко, дескать вроде не лож, но что-то в этом странное есть?*",212725,null],[242661,"2026-09-29T19:23:06",20,"/может вино для контроля над отродиями",212725,null],[242662,"2026-09-29T19:23:21",20,"/но наверное мы об этом не можем знать",212725,null],[242663,"2026-09-29T19:23:34",17,"/r d20+5+d4 Проницательность продженого следака",242655,null],[242665,"2026-09-29T19:24:48",17,"— Тогда цепляемся за эту ниточку, господин Сангвини. И начинаем распутывать. Откуда коробка. Где разливалось, кто причастен. И лучше делать это быстро, скоро день и новый болезненный сон для ваших сыновей.",212725,null],[242666,"2026-09-29T19:26:17",31,"Энрике говорит правду о назначении вина, он и правда поит им своих детей чтобы те не слетали с катушек от поглощения живой крови. Судя по всему, наличие чар в вине для него стало шоком, но он не выдаёт это лицом и сейчас старается понять как это вышло и как скоро он найдет виноватых. И в глубине души (или что там у него) кого то подозревает",242664,null],[242667,"2026-09-29T19:29:35",31,"Энрике хмурится\n\n- Вино с наших виноградников, там же и погреба, там же оно и купажируется в специальном помещении. Но разве жидкость можно проклясть? Вы же говорили о подкладе, я не эксперт в таком, но разве это не какой то физический предмет?",242665,null],[242668,"2026-09-29T19:29:36",17,"— Я вижу. Вижу вы уже представили виновного. Опишите его нам. Назовите его имя. Кого вы первого подозреваете, пусть и неосознанно, но он предстал перед вами.",212725,null],[242669,"2026-09-29T19:30:30",17,"— Можно добавить серебряный порошок в воду и произнести молитву\n\nМарко демонстрирует флакон святой воды. Вода слегка светится \n\n— И вот что будет",242667,null],[242670,"2026-09-29T19:31:28",17,"/ Да все. Я уже раскусил тебя мастер сдавайся!",242667,null],[242671,"2026-09-29T19:31:46",31,"- Марко, вам случалось иметь заклятых друзей? Таких о которых вы всегда думаете в опасной ситуации и которых готовы обвинить в своих бедах? У меня такие есть. И никого из них нет в городе, я слежу за этим. Тщательно",242668,null],[242672,"2026-09-29T19:33:10",31,"- святая вода? Насколько я знаю, она не заставляет видеть сны, что сбываются наяву",242669,null],[242673,"2026-09-29T19:33:56",31,"Ага. Излагай/",242670,null],[242674,"2026-09-29T19:34:24",17,"— Вам виднее, сеньор. Я лишь хочу помочь вам и спасти ваших сыновей как можно быстрее. \n\nУбирает флакон святой воды\n\n— Я скорее показал, что серебряный порошок в воде делает ее магической. Тут может быть добавлен такой же материальный очень мелкий проклятый песок или вроде того. Роман, на зубах ничего не скрежетало?",212725,null],[242675,"2026-09-29T19:36:28",31,"- нет. И вкус был обычный. Погодите ка\n\nРоман берет бутылку, переворачивает ее и выливает содержимое просто на стол. Винно-кровавая лужа быстро увеличивается в размере и наконец в самый ее центр падает небольшой чёрный камешен",242674,null],[242676,"2026-09-29T19:37:17",22,"/r +6 Внимание на камешек",212725,null],[242678,"2026-09-29T19:37:39",22,"//я жгу! ура! рак кубов! он покину меня! Урааа! все спускаем на бесполезные проверки!",212725,null],[242679,"2026-09-29T19:37:44",20,"- Синьора, это и есть тот проклятый предмет о которых вы говорили? *Беатриче с опаской смотрит на камешек*",212725,null],[242680,"2026-09-29T19:38:00",22,"/я честно на камень смотрю, не на мужика",212725,null],[242681,"2026-09-29T19:38:11",31,"Вот и подклад нашелся. Ты ощущаешь проклятый предмет, это работа карги, совершенно точно",242677,null],[242682,"2026-09-29T19:38:21",31,"Может камень тоже мужик?/",242680,null],[242683,"2026-09-29T19:40:12",22,"Ясмин вскакивает и  шипит на камень, словно кошка.\n\n- Г-где эти погреба!? Эту мерзость нужно уничтожить!",212725,null],[242684,"2026-09-29T19:43:30",17,"— Пол дела сделано. У остальных сыновей изъять бутылки проклятого вина.",212725,null],[242685,"2026-09-29T19:47:00",22,"- И найти этот ис-сточник! Что за мраз-зь это с-сделала.",212725,null],[242686,"2026-09-29T19:50:41",20,"/надо воспользоваться случаем и семейное вино прорекламировать\n/Заказывайте вино Висконти - и никаких проклятых камней",212725,null],[242687,"2026-09-29T19:51:23",31,"Энрико смотрит на камешек\n\n- и что, в каждой бутылке может быть эта дрянь? Проверю. А что до виноградника, я дам вам его адрес, вы же сможете найти там другие проклятые камни, если они есть? Я просто не ощущаю от камня какой-либо опасности, поэтому сам явно не найду, осленно если они спрятаны",212725,null],[242688,"2026-09-29T19:51:31",31,"Ты это вслух сказала?/",242686,null],[242689,"2026-09-29T19:52:10",22,"/надеюсь",242688,null],[242691,"2026-09-29T19:53:28",20,"/надо бы как будет уходить)",242688,null],[242692,"2026-09-29T19:53:56",31,"Ну это в характере персонажа, да/",242691,null],[242693,"2026-09-29T19:55:00",22,"/потом маме будешь объяснять про странные заказы от странных господ",242691,null],[242694,"2026-09-29T19:56:06",31,"/не буду спойлерить. С мамой Беатриче мы ещё не встречались/",212725,null],[242695,"2026-09-29T19:59:02",31,"В общем, Энрике просит вас посетить винодельню и поискать там проклятые предметы, ибо сам он не ощущает ничего от камешков. Вампир ждет вашего решения/",212725,null],[242696,"2026-09-29T19:59:55",22,"Ясмин на низком старте",212725,null],[242697,"2026-09-29T20:01:30",20,"/там явно будет какая-то Una splendida matrona",242694,null],[242698,"2026-09-29T20:01:57",22,"- И с-список. Кто мог  это с-сделать.\n\nОй расшипелась то\nАй ай ай нас хотят найти\nКакие мы злые",212725,null],[242699,"2026-09-29T20:11:22",31,"- если бы у меня был готовый список, я бы уже шёл по нему и открывал головы...\n\nСлова Энрике, до того бывшего спокойным, сейчас звучали зло. В его глазах мелькает что то очень опасное\n\n- все кто мог бы туда попасть, сейчас не в городе. Точно. Кто то новый? Возможно... Или нет?\n\nСмотрит на Беатриче, затем выдыхает и успокаивается. \n\n- найдите мне имя того, кто это устроил. Если я сам начну этим заниматься, то я сорвусь раньше времени, и это не закончится ничем хорошим для моей семьи. Найдите виновника и я буду вашим должником. Мне нужно только имя, дальше я справлюсь сам\n\nУлыбается. Только глаза мертвые, как у акулы",242698,null],[242700,"2026-09-29T20:16:43",22,"//у акул глаза нормальные...\n\nпростите, я просто обожаю акул, у меня с ними тонна книг, игрушек, пижама в виде гигантской акулы и постельное белье... Не могу оставить этот произвол",242699,null],[242701,"2026-09-29T20:17:28",31,"Нормально для акул как рыб. На человеческом лице они покажутся неподходящими)/",242700,null],[242702,"2026-09-29T20:18:34",22,"//скину я тебе один арт, буквально на днях его нашла, он так в тему😄",242701,null],[242703,"2026-09-29T20:21:03",31,"Ладно, завтра продолжим. Если вам принципиально, то можете считать камешек песчинкой, которую вы разглядели только потому что онасиякт аурой. В вот почему ее вампиры не разглядели раньше - это будет загадкой)/",212725,null],[242704,"2026-09-29T20:21:05",17,"— Не медля ни секунды мы отправимся туда.",212725,null],[242712,"2026-09-29T21:13:10",20,"*Беатриче снова следует за спутниками, готовая отправится куда угодно если это приблизит их к той самой информации, которую Сангвини обещал за помощь. Но для начала...*\n\n*Он немного тормозит рядом с Энрике*\n\n- Signor Сангвини, полагаю сейчас вы на время откажитесь от вина с вашей винодельни *кидает взгляд на стол, где все ещё разлита багровая жидкость* в виду очевидных причин. А ведь вино это лучшее лекарство души в минуты ansia e rabbia.\n\n*Она делает отработанный жест, в лёгком поклоне, одна рука за спиной а другой вытаскивая визитную карточку - небольшую, но явно из качественной бумаги, с гербом и изящно выведенными в ручную буквами:*\n\n\"𝖁𝖎𝖓𝖎 𝖊𝖉 𝖊𝖘𝖘𝖊𝖓𝖟𝖊 𝖁𝖎𝖘𝖈𝖔𝖓𝖙𝖎\" \n\n(а также адрес дома в старом районе)\n\n- Семья Висконти всегда готова предоставить высшее качество по неизменным традициям лучших вин Вальдории. И гарант отсутствия каких либо spiacevole sorpresa, конечно.\n\n*Отдав карточку она кивает на прощание, скрываясь за дверью  следом за спутниками.*\n\n*Алый плащ развивается за спиной с чувством выполненного долга*\n/\u003c⁠(⁠￣⁠︶⁠￣⁠)⁠>",212725,null],[242713,"2026-09-29T21:16:32",22,"//лучшая!",242712,null],[242714,"2026-09-29T21:19:08",17,"Когда они вышли из особняка Сангвини, Марко листал свою записную книжку\n\n— Ваше предложение, сиора Беатриче, натолкнуло меня на мысль о подставе. Возможно другой винный дом захотел забрать такого клиента как Сангвини и специально подстроил проклятье вина их давних поставщиков? Такую версию пока отбрасывать нельзя",212725,null],[242715,"2026-09-29T21:20:06",17,"— Какие виннодельни в городе могли бы рискнуть своим именем и пойти на такую авантюру?",212725,null],[242716,"2026-09-29T21:20:23",22,"- Главное, чтобы это н-не был очередной \"крабик\".. только крово-винный",242714,null],[242717,"2026-09-29T21:21:33",20,"- Хм...сеньор Сангвини упоминал, что эта винодельня и так принадлежит его семье. Кто был бы настолько безумен чтобы пробраться на территорию, где скорее всего полно вампиров?",242714,null],[242719,"2026-09-29T21:22:25",20,"- Скорее всего тоже вампир или кто-то сравнимой силы. Или имеющий туда прямой доступ",212725,null],[242720,"2026-09-29T21:22:29",17,"— Семье, да. Видимо я был невнимателен. Спасибо, сиора. Теперь можно такую версию отбросить. Не думаю что в семье пошли бы на такое",242717,null],[242721,"2026-09-29T21:25:24",22,"- Они же г-говорили что очень горячие г-головы. Могли обидеть не того, к-кого стоило обижать.. Это же я-явно дело рук в-ведьмы.\n\nВ голове Ясмин тем временем было подозрительно тихо.",212725,null],[242722,"2026-09-29T21:28:04",17,"— Хм... Да. Звучит правдоподобно. Сынки Сангвини заносчивые, дерзкие. Помните как этот Роман сказал \"Какой же бал без дуэли\" будто он может легко умереть бессмертный ублюдок.",212725,null],[242723,"2026-09-29T21:28:32",17,"Марко не ожидал сам от себя таких слов. Вампиров он на дух не переносил.",212725,null],[242724,"2026-09-29T21:28:44",17,"И кажется тень удлинилась",212725,null],[242725,"2026-09-29T21:28:50",20,"- Ваша правда, Синьора. *Кивает Беатриче*\n- Я могу поверить, что это мог быть кто-то кто затаил на них обиду. А уж мстить в Вальдории любят с размахом - от дуэлей до вот таких вот подлых проклятий. \n\n- Эх, жаль что все эти горячие головы сейчас прикованы к постелям. Каково было бы с ними посоревноваться в фехтовании... *Слегка мечтательно тянет Беатриче - явно горит желанием проверить собственные силы против таких оппонентов*",212725,null],[242726,"2026-09-29T21:29:17",17,"\"МЕРТВЫЕ ДОЛЖНЫ НАХОДИТСЯ В ЗАГРОБНОМ МИРЕ… СМЕРТНЫЙ\"",212725,null],[242727,"2026-09-29T21:29:41",20,"- Ну будет вам, синьор Марко. Балы без дуэлей и правда скука смертная",242722,null],[242728,"2026-09-29T21:30:19",17,"— Скука смертная... \n\nТихо повторил Марко",212725,null],[242729,"2026-09-29T21:32:17",20,"/в такой компашке главное тоже голосом в голове не заразиться",212725,null],[242730,"2026-09-29T21:34:16",22,"/извините, я просто маску носить перестала и вот началось",212725,null],[242742,"2026-09-30T03:17:27",31,"Ты этого уже не видишь, но Энрико читает фамилию на карточке и хмурится, словно что то вспоминает",242712,null],[242746,"2026-09-30T06:34:19",31,"@dunchev @lady_godzilla @PaIIasCat \n\nИтак, покинув дом Сангвини, вы, движимые желанием помочь несчастным вампирам, заработать денег, раскрыть секрет, свой вариант (нужное подчеркнуть), отправляетесь на их семейную винокурню с  наглым названием \"Preziosissimo Sangue\". Она расположена за стенами города, на северо-востоке. Энрико снабдил вас грамотой, что открыла ворота города, обычно запираемые на ночь. Стражи ворот при виде этих бумаг стали относится к вам с опаской и не спорили с вашим правом покинуть город в неурочное время. Они же предоставили вам лошадей, так как на своих двоих вы бы добрались на винодельню только к утру.\n\nЧерез пару часов вы увидели перед собой виноградные поля, посреди которых находилась довольно большая винокурня со складом и дистиляционными комнатами. похоже, вино купажируют кровью именно там. На удивление, вы не видите никакой охраны, винокурня словно вымерла. Хотя сейчас уже заполночь, может просто все работники просто мирно спят?",212725,null],[242761,"2026-09-30T07:29:50",22,"Содрать бы шкуру с этих бездельников\n\nВ темноте возникли недовольные глаза.\n\nСекси мальчиков совсем не уважают.\n\nЯсмин нахмурилась и осмотрелась повнимательнее. Отсутствие хоть какой либо охраны выглядело очень странно.\n\n- Н-неужели у них даже нет \n*шепотом*\n- Особых ночных сотрудников? Подозрительно.",212725,null],[242762,"2026-09-30T07:29:56",22,"/r +6 внимание",212725,null],[242764,"2026-09-30T07:33:17",31,"темновато видать, ты ничего подозрительного не заметила",242763,null],[243009,"2026-09-30T12:13:25",20,"/r d20+4 внимание, присоединяюсь к осмотру местности",212725,null],[243046,"2026-09-30T12:43:00",17,"Марко практически ничего не мог разглядеть в темноте поэтому просто держался рядом.\n\n— Нам нужно проверить как минимум цех где разливают виноп о бутылкам и цех где его кцпажирубт кровью. \n\nОн захлопнул книгу и его глаза вновь заблестели золотом, чтобы видеть магические ауры\n\n/ ритуал обнаружение магии \n\n— Предлагаю сперва в цех.",212725,null],[243059,"2026-09-30T12:47:06",20,"- Может зажечь факел, сеньор Марко? *Предлагает Беатриче, вспоминая что люди не так хорошо видят в темноте*",212725,null],[243078,"2026-09-30T12:51:42",17,"— Если никого нет и нас не встречают. Не проверяют наши бумаги. Лучше не привлекать внимания. Что то тут не так, подозрительно, сиора. Будьте на чеку",243059,null],[243136,"2026-09-30T13:10:09",31,"Ты замечаешь множество следов тяжёлых сапог перед зданием. Большая часть следов ведут внутрь",243010,null],[243248,"2026-09-30T13:31:32",20,"- Тут довольно много следов *Беатриче указывает на это своим спутникам*\n\n- Как думаете, нас опередили?",243136,null],[243261,"2026-09-30T13:33:41",22,"- Я м-могу зажечь свет, если н-нужно. \n\nЯсмин замялась. И тихо добавила, покосившись в сторону посмеивающихся глаз.\n\n- Но мне и так все видно... когда никто не отвлекает",212725,null],[243262,"2026-09-30T13:33:50",17,"— У виноделов собрание. Что то обсуждают или решают...",243248,null],[243353,"2026-09-30T13:50:10",22,"- П-попробуем подслушать?",212725,null],[243370,"2026-09-30T13:52:11",20,"- Можно попробовать *Беатриче поправляет бригантину. Ну, это будет непросто...*\n\n- К окну или к двери?",212725,null],[243384,"2026-09-30T13:55:19",22,"- Окно наверное будет лучше",212725,null],[243445,"2026-09-30T14:04:34",17,"Откуда то прилетает черный ворон и садится на плечо Марко\n\n— Если ничего не увидим или не будет слышно, можно попробовать этого пернатого проныру внутрь запустить",212725,null],[243608,"2026-09-30T14:37:49",17,"Что ж троица скрытно идёт к окну, чтобы аккуратно заглянуть внутрь в здание и подслушать разговоры, если это возможно",212725,null],[243656,"2026-09-30T15:19:33",31,"Бросайте восприятие, скрытность вам зачту и так/",212725,null],[243658,"2026-09-30T15:26:59",17,"/r +d20+5+d4 Восприятие ворон помогает",212725,null],[243660,"2026-09-30T15:28:41",22,"//так я разгребла работу и отправила любимым коллегушкам обратно все переделывать, теперь смогу поучаствовать нормально",212725,null],[243661,"2026-09-30T15:28:54",22,"/r +6",212725,null],[243663,"2026-09-30T15:29:28",22,"/r d4",243662,null],[243665,"2026-09-30T15:29:44",22,"/21 результат, забываю добавлять",212725,null],[243669,"2026-09-30T15:33:10",31,"Фига вы чувствительные. Ща распишу/",212725,null],[243674,"2026-09-30T15:43:12",31,"Подкравшись к окнам незамеченными, и прислушавшись к происходящему внутри, вы услышали в первую очередь звуки глухих ударов, словно кто то пытался выбить крепкую дверь. \n\n- Навались, бараны! И так задержались! \n\nЭтот голос принадлежит очевидно крупному мужчине, который ощущает себя в праве отдавать приказы. Ответом ему служат матюки еще пары мужиков.\n\n- Быстрее, сукины дети! Иначе дон накрутит ваши кишки на забор!\n\nВорон смотрит в окно и передаёт Марко картинку:\n\nТрое дюжих мужиков при оружии пытаются выбить одну из внутренних дверей, синхронно ударяясь о нее плечами. За ними наблюдает еще более огромный мужик с арбалетом за плечами. Видимо за этой дверью хранится что то важное. Или кто то",212725,null],[243678,"2026-09-30T15:47:42",22,"Ясмин нервно дергала косу и прикусывала губы.\n\nТак и будешь молчать?\nИли снова боишься?\nБоишься быть собой\n\n- Я... У-у меня есть одна и-идея... в общем я могу п-притвориться доном.. н-ну если надо... вот..\n\n//закл Маскировка",212725,null],[243679,"2026-09-30T15:48:07",31,"А ты знаешь как выглядит Дон?/",243678,null],[243687,"2026-09-30T15:53:45",22,"/я предположила, что это наш заказчик",243679,null],[243691,"2026-09-30T15:55:46",31,"Хм-м-м. Ну я тебе не запрещаю это отыграть)/",243687,null],[243707,"2026-09-30T16:00:15",22,"/ я советуюсь с более умными товарищами!",243691,null],[244185,"2026-09-30T18:30:23",20,"- К Сангвини вряд ли бы обратились Дон. *тихо говорит Беатриче*\n- Да и люди в его подчинение явно отличаются большим...эм, изяществом? Ну, вы поняли.\n\n- Обычно это обращение к влиятельным людям вроде глав преступных синдикатов или мафии. Во всяком случае в Вальдории. Так что похоже мы наткнулись на незваных гостей, решивших воспользоваться отвлечением хозяина винодельни...",212725,null],[246341,"2026-10-01T08:11:58",31,"@PaIIasCat @dunchev @lady_godzilla \n\nБлижайшие часа 4 я тут. Жду ваших действий/",212725,null],[246342,"2026-10-01T08:16:26",17,"— Они пытаются вломиться в комнату, скорее всего там кто-то есть. Забаррикадировался от этих, сеньоров...\n\n— Беатриче права. У них там арбалет наготове, нужно действовать аккуратно\n\nМарко осматривает что над мужчинами, можно ли использовать окружение чтобы обезвредить их\n\n— Ищите варианты как не вступая в отрытое противостояние обезвредить их. Или же предложите кем нам представиться? Помоему мы сразу же получим тут болт в грудь.",243678,null],[246343,"2026-10-01T08:17:13",17,"/r d20+5+d4 Анализирую окружение, может что то можно было бы уронить на них или толкнуть чтобы получить преимущество",212725,null],[246346,"2026-10-01T08:31:23",31,"Ты видишь, что единственное, что можно уронить на мужиков - это люстра со свечами. Можно попробовать как то перерубить веревку, на которой она висит, но если она упадет неудачно, может и пожар начаться пожалуй. В самом здании куча бочек, за которые можно прятаться, но пожалуй покатить бочку вряд-ли выйдет - они тяжелые и незаметно вы ее не сможете толкнуть.",246344,null],[246350,"2026-10-01T08:43:42",20,"- Может просто внезапно ворвемся и хорошенько отделаем их? Так всего-то четверо... *Беатриче разглядывает обстановка из окна*\n\n /Ых, стратегия сложна",212725,null],[246365,"2026-10-01T08:53:40",22,"- О-обезвредить.. но как?\n\nПравильно, девочка, милосердие для слабых\nСПАЛИ ТУТ ВСЕ ДО ТЛА\n\nЯсмин поджала губы.\n\n- Б-боюсь, если я с-стану Энрико, то меня б-бытро раскроют.. а других и-идей у меня нет.",212725,null],[246366,"2026-10-01T08:54:06",22,"/на улицу только вывести бы",246350,null],[246367,"2026-10-01T08:54:47",17,"— Отличный план сперва люстра, потом ваш выход на бис, сиора. Я поддержу",246350,null],[246369,"2026-10-01T08:56:23",17,"Марко входит первым \n\nКак только мысль требует использования сил бога смерти, тень сливается с ним и черная голова шакала закрывает лицо\n\nОн создаёт две черные лапищи около цепи на которой держится люстра и срубает её",212725,null],[246370,"2026-10-01T08:56:27",17,"/ Что кинуть?",212725,null],[246371,"2026-10-01T08:56:49",17,"\"Приветствия и любезностей не будет\"",212725,null],[246372,"2026-10-01T08:57:35",31,"да просто попадание, кд люстры пусть будет 10/",246370,null],[246373,"2026-10-01T08:57:48",17,"/r +5 Попадание",212725,null],[246375,"2026-10-01T08:58:49",31,"Черные лапы, созданые силой Анубиса, легко сбивают зажженую люстру на головы четверых мужчин",212725,null],[246377,"2026-10-01T08:59:33",31,"/roll 4d20+1 на ловкость от них",212725,null],[246379,"2026-10-01T09:00:53",31,"Двое увернулись, в том числе и главарь с арбалетом, еще один получает урон от падения, четвртый словил люстру самым темечком, неудачник",212725,null],[246380,"2026-10-01T09:02:00",31,"/roll d6 урона по третьему",212725,null],[246382,"2026-10-01T09:02:54",31,"Увернувщиеся и частично пострадвшие мужики разворачиваются для отражения атаки, бросаем инициативу",212725,null],[246383,"2026-10-01T09:04:02",22,"/r +2",212725,null],[246385,"2026-10-01T09:05:43",31,"/roll d20+1 Бандит со скимитаром\n/roll d20+1 Бандит с алхимическим огнем\n/roll d20+2 Головорез с арбалетом\n/roll d20-19 Бандит без сознания\n\n/roll d2 если единица то пожар",212725,null],[246387,"2026-10-01T09:07:05",31,"Бандит с алхимическим огнем и арбалетчик успели спрятатся за бочки, бандит со скимитаром, оглушенный падением люстры не успед укрытся",212725,null],[246388,"2026-10-01T09:08:09",17,"/r +2 Инициатива Марко",212725,null],[246390,"2026-10-01T09:09:07",22,"/они кучей же стоят? В 15фт?",212725,null],[246391,"2026-10-01T09:09:55",31,"Ясмин\nБандит со скимитаром 16 урона, мертв\nМарко\nБеатриче\nГоловорез с арбалетом 36 урона, мертв\nБандит с алхимическим огнем 11 урона в отключке\nПолудохлый бандит мертв",212725,null],[246392,"2026-10-01T09:10:06",31,"@PaIIasCat инициатива/",212725,null],[246394,"2026-10-01T09:10:59",31,"конусом, один впереди, двое по бокам за ним, ну радиус 15 футов гдетто, да",246390,null],[246395,"2026-10-01T09:12:02",20,"/r d20+3",246392,null],[246398,"2026-10-01T09:12:47",31,"Ясмин, ультуй/",212725,null],[246399,"2026-10-01T09:13:47",22,"- Я-я не хочу делать вам больно! С-сдавайтесь!\n\nСпас лвк 14, успех - половина урона",212725,null],[246400,"2026-10-01T09:13:56",22,"/r 3d6 огненные ладошки",212725,null],[246402,"2026-10-01T09:14:10",31,"всем? даже тем кто за бочками?/",246399,null],[246403,"2026-10-01T09:14:18",22,"И отшагнуть назад",212725,null],[246404,"2026-10-01T09:14:53",22,"//ну думаю что тем, кто спрятался ничего не будет. Пламя не сквозное же",212725,null],[246405,"2026-10-01T09:15:39",22,"/Излечит любые амбиции, Священный костёр инквизиции ☺️",212725,null],[246406,"2026-10-01T09:16:02",31,"погуглил, те что за бочками  получат +5 к спасу/",246404,null],[246407,"2026-10-01T09:17:08",31,"/roll d20+1 Бандит со скимитаром\n/roll d20+6 Бандит с алхимическим огнем\n/roll d20+7 Арбалетчик",212725,null],[246409,"2026-10-01T09:17:35",22,"Успех - половина /",212725,null],[246410,"2026-10-01T09:18:35",31,"Арбалет помешал головорезу увернутся от огня, его довольно сильно опалило. ДВа его подчиненных пострадали меньше",212725,null],[246411,"2026-10-01T09:19:19",31,"это весь ход Ясмин?/",212725,null],[246412,"2026-10-01T09:20:03",31,"как вы стоите? Ясмин отошла насколько я понял/",212725,null],[246413,"2026-10-01T09:20:51",22,"Я думаю, что треугольником. Я подошла, отжарила, отошла. Беатриче первая/",246412,null],[246415,"2026-10-01T09:22:10",31,"ок, ход бандита со скимитаром",212725,null],[246418,"2026-10-01T09:23:31",31,"/roll +d20+3 ударенный люстрой и обожженый Ясмин мужик с предсмертным кпиком нападает на Беатриче. Получает преимущество как за безрассудную атаку, он уже понимает что не выживет",212725,null],[246421,"2026-10-01T09:23:58",31,"Дампирша вситречает его короткинм ударом эфеса рапиры в зубы",212725,null],[246422,"2026-10-01T09:24:41",31,"следующая атака по нему будет с преимуществом/",212725,null],[246423,"2026-10-01T09:24:51",31,"ход Марко/",212725,null],[246424,"2026-10-01T09:27:37",31,"@dunchev",212725,null],[246425,"2026-10-01T09:29:43",17,"/Арбалетчик и бандит с алхимическим огнём рядом друг с другом в 5 футах? есть ли 2 цели такие ?",212725,null],[246426,"2026-10-01T09:29:55",17,"/Мне нужно потому что заговор может ударить по двоим если они в 5 футах",212725,null],[246427,"2026-10-01T09:30:37",31,"больше 5 футов между ними/",246426,null],[246428,"2026-10-01T09:34:04",17,"Рука превращенная в черную лапу ложится на голову наглецу смеющему напасть на сиору Беатриче\n\n/Погребальный звон спас мудрости СЛ 13",212725,null],[246429,"2026-10-01T09:34:13",17,"/r d12 Урон если провал",212725,null],[246431,"2026-10-01T09:34:35",17,"/Ход",212725,null],[246432,"2026-10-01T09:34:46",22,"//мне так смешно, я если честно только так это представляю",212725,null],[246435,"2026-10-01T09:35:05",22,"//простите😅",212725,null],[246436,"2026-10-01T09:39:43",31,"котик тьмы)/",212725,null],[246437,"2026-10-01T09:40:12",31,"/roll d20 мудрость",246428,null],[246439,"2026-10-01T09:40:41",31,"бандит упал с разорванными перепонками, уши сочатся кровью, на лице маска ужаса",212725,null],[246440,"2026-10-01T09:40:47",31,"/Беатриче",212725,null],[246441,"2026-10-01T09:41:51",31,"@PaIIasCat",212725,null],[246442,"2026-10-01T10:32:08",20,"*Беатриче смотрит на бандита перед ней. Черт, она надеется что Марко его хотя бы просто оглушил, а не убил*\n\n*Сама кидается на того, у которого замечает в руках алхимический огонь*",212725,null],[246443,"2026-10-01T10:32:38",20,"/r d20+5 кинжал\n/r d20+5 рапира",212725,null],[246445,"2026-10-01T10:32:55",20,"/хоть что-то попало?",212725,null],[246446,"2026-10-01T10:34:15",17,"/ Если позволишь мастер, ворон летит и отвлекает одного из вражин давая Беатриче преимущество помощью на одну атаку",212725,null],[246447,"2026-10-01T10:34:58",31,"не позволю, мне и та кэтих бомжей жалко. В свой ход объявляй хотя бы/",246446,null],[246448,"2026-10-01T10:35:10",31,"кинжал прошел",246444,null],[246449,"2026-10-01T10:35:33",20,"/r d4+3 урон не смертельно",212725,null],[246451,"2026-10-01T10:36:01",20,"/ну и пусть будет всплеск действий",212725,null],[246452,"2026-10-01T10:36:17",20,"/r d20+5 рапира ДАВАЙ",212725,null],[246454,"2026-10-01T10:36:36",31,"опишир как уложила, урон не нужен/",212725,null],[246455,"2026-10-01T10:39:39",20,"*Беатриче с размаху бьёт бандита эфесом, перехватывая падующее бессознательное тело второй рукой как в танце. Толи чтобы плавно опустить на пол, толи чтобы не допустить детонацию алхимического огня*\n\n- Buonanotte.\n\n*После этого она оборачивается и подбегает к бандиту с арбалетом, вовлекая в ближний бой чтобы загородить союзников*",212725,null],[246456,"2026-10-01T10:41:12",20,"/конец хода, да",212725,null],[246457,"2026-10-01T10:41:53",31,"ход Головореза. Увидев что Беатриче мешает ему стрелять, он бросает арбалет и всидывает булаву, ударом которой встречает Беатриче",212725,null],[246458,"2026-10-01T10:41:59",31,"/roll d20+4",212725,null],[246460,"2026-10-01T10:42:09",20,"/попал",212725,null],[246461,"2026-10-01T10:42:18",31,"/roll d6+4",212725,null],[246463,"2026-10-01T10:43:46",31,"удар приходится дампирше в плечо, заставляя пошатнутся и потерять ее из виду. Головорез отходит в глубину, прихватя арбалет и пытаясь скрытся",212725,null],[246464,"2026-10-01T10:44:00",31,"/roll d20+5 скрытность",212725,null],[246466,"2026-10-01T10:44:10",31,"херов получилось спрятатся",212725,null],[246467,"2026-10-01T10:44:33",31,"/roll d20 спас от смерти четвертого баднита",212725,null],[246469,"2026-10-01T10:44:51",31,"восстал с одним хп, едва соображает",212725,null],[246470,"2026-10-01T10:44:59",31,"/Ход Ясмин",212725,null],[246471,"2026-10-01T10:55:46",22,"- У-у вас еще есть шанс сдаться! О-одумайтесь!\n\n/лвк 14, успех-половина",212725,null],[246472,"2026-10-01T10:56:06",22,"/r 3d6 ладошки",212725,null],[246474,"2026-10-01T10:56:24",22,"/стараюсь задеть максимум разбойников. Не Беатриче",212725,null],[246475,"2026-10-01T10:56:40",31,"тот что только восставл с одним хп упал снова",212725,null],[246476,"2026-10-01T10:57:02",31,"/roll d20+7 спас головореза",212725,null],[246478,"2026-10-01T10:57:12",31,"5 хп долой",212725,null],[246479,"2026-10-01T10:57:50",31,"/Марко",212725,null],[246484,"2026-10-01T11:56:11",22,"@dunchev",212725,null],[246485,"2026-10-01T11:57:49",17,"Марко медленно движется к ближайшему живому противнику\n\nИз ноздрей теневой головы шакала появляется дымка\n\nЗаносит лапу (лапку) и рвёт когтями",212725,null],[246486,"2026-10-01T11:58:18",17,"Ворон тут же срывается с карниза и мешает обзору этого противника",212725,null],[246487,"2026-10-01T11:58:30",17,"/r +d20+5 Нанесение ран с помощью от ворона",212725,null],[246489,"2026-10-01T11:58:38",17,"/r 3d10 Некро урон",212725,null],[246491,"2026-10-01T11:58:49",17,"/Ход",212725,null],[246492,"2026-10-01T11:59:21",31,"описывай смерть. по другому некроурон я не воспринимаю)",212725,null],[246493,"2026-10-01T12:00:53",17,"/ Нелетально нельзя",212725,null],[246494,"2026-10-01T12:00:59",17,"/ Sadness",212725,null],[246495,"2026-10-01T12:01:19",17,"/ Может через спас мудрости? у меня по квенте надо бороться с силой Аннубиса которая хоронит",212725,null],[246496,"2026-10-01T12:01:24",31,"у вас есть нелетальный если что/",212725,null],[246497,"2026-10-01T12:01:41",31,"ладно, давай спас",212725,null],[246498,"2026-10-01T12:01:48",17,"/r +5 Голый спас",212725,null],[246500,"2026-10-01T12:01:49",31,"сколько нужно пробить?/",212725,null],[246501,"2026-10-01T12:02:04",17,"/ 10 я думаю было бы достаточно, ок развитие пошло по злой ветке",212725,null],[246502,"2026-10-01T12:02:08",17,"/ Тоже не плохо",212725,null],[246503,"2026-10-01T12:02:31",31,"тем интереснее/",246501,null],[246504,"2026-10-01T12:04:11",17,"Марко поглощен силой и могуществом мёртвого бога\n\nОна пульсирует в его груди, в его руках\n\nОн не сопротивляется заносит когтистую лапу и разрывая грудную клетку обычного парня сжимает его сердце внутри вырывая из тела\n\nОно с чавкающим звуком падает к ногам кровавые брызги заливают плащ и костюм, штанины и ботинки.\n\nМарко не обращает внимание, сегодня он отдался этой силе, сегодня он принимает её без сопротивления",212725,null],[246505,"2026-10-01T12:04:38",31,"спасибо, было омерзительно/",212725,null],[246506,"2026-10-01T12:05:12",31,"итак, перед вами три трупа, и один бандит в отключке. А аткэе вы видиете дверь, что они пытались вскрыть",212725,null],[246507,"2026-10-01T12:09:22",20,"*Беатриче в шоке смотрит на то, как ее союзники буквально убивали людей в простой потасовке*\n\n- Che cazzo...\n\n*Она спешит к телам, проверяя есть ли всё-таки кто живой*\n\n/Так вроде кто-то был не мертв, а не стабилизирован",212725,null],[246508,"2026-10-01T12:10:04",31,"жив тот, кого ты оглушила. Остальные мертвы",246507,null],[246509,"2026-10-01T12:14:22",20,"*Она медленно поднимается, не найдя ни у кото из троих пульса. Потом резко поворачивается к спутникам*\n\n- КАКОГО ЧЕРТА?! ОГОНЬ?! ЧЕРТОВЫ ТЕНЕВЫЕ КОГТИ?! ЭТО БЫЛИ ОБЫЧНЫЕ ЛЮДИ!!!\n\n*Она в ярости*\n\n- Мы даже не знаем, что они здесь делали, виноваты ли они хоть в чем-то! Perché diavolo li hai uccisi?!",212725,null],[246510,"2026-10-01T12:15:13",31,"вдохновение тебе. Так их, жрецов-убийц)",246509,null],[246511,"2026-10-01T12:16:51",17,"Приходит осознание. Тень возвращается на место, с головы слезает медленно перетекая в неё шакалиная маска\nКажется в голове слышен удаляющийся грубый смех и отголоски\n\n\"УЖЕ... СКОРО...\"\n\nМарко поднял руки и посмотрел на ладони. Кровь стекала между пальцами. Сейчас она была не ритуальная для дела.\nСейчас он просто убил человека.\n\nМарко долго смотрел на собственные руки, будто осматривал улику на месте преступления\n\n\"Я мог остановиться?\"\n\n\"Нет... Хуже...\"\n\n\"Я не хотел останавливаться\"\n\nПальцы дрогнули. Марко медленно вытер ладонь о плащ и нащупал во внутреннем кармане небольшой сложенный платок\nМарко сжал платок в кулаке\n\nПеред глазами на мгновение не кровь\nМаленькие пальцы, коробка с морскими стёклами, булочка в меду\nДевочка которая боялась грозы\n\n\"Лючия\"\n\nИмя прозвучало внутри тихо, но достаточно громко\nМарко закрыл глаза\n\n\"Я ещё не нашёл тебя\"\n\nПальцы сильнее сжали ткань\n\n\"Значит я ещё не имею права исчезнуть\"\n\nОн медленно вдохнул\nСмех Анубиса уже почти растворился\nОн убрал платок обратно во внутренний карман\n\n\"Это был ты. Не смей обманывать себя. Это был слабый ты, Марко\"\nТихо прокрутил он у себя в голове\n\nМарко наклонился, поднял выпавшее сердце и положил рядом с телом\nПосле чего закрыл погибшему глаза и положил на них две золотые монеты. Еще одному рядом сделал тоже. И начал обряд упокоения мёртвых.",212725,null],[246512,"2026-10-01T12:17:45",17,"На это он лишь молча слегка кивнул закрыв глаза\n\nВ знак того, что Беатриче во всём права",246509,null],[246513,"2026-10-01T12:17:48",22,"О-о-о а пёсик то не плох\nСердечко красиво полетело\nЖаль, что не к моим ногам\nДа куда тебе еще, старая?\nЭто я то старая?!\n\nВ голове у Ясмин началась какафония. Девушка с ужасом смотрела на Марко, упиыающегося насилием, на людей, что предпочли смерть плену. На три пары золотых глаз, которые кружили вокруг нее, будто сражаясь друг с другом.\n\nДевушка прижалась к стене, закрыла глаза и начала читать про себя мантру. Ее тело била мелкая дрожь, а мантра то и дело срывалась.",212725,null],[246514,"2026-10-01T12:18:22",17,"/ Один всё же жив",246509,null],[246515,"2026-10-01T12:21:33",31,"Живой бандит начинает стонать и поднимает голову",212725,null],[246516,"2026-10-01T12:23:24",17,"— И так. Сейчас тебе нужно ответить на вопросы, мы вызовем помощь и сохраним твою жизнь. От кого мы здесь ты сам, думаю понимаешь. \n\nМарко присел к нему и посмотрел угрюмо, потом снял очки и протёр кровь с линз краем его костюма\n\n— Теперь скажи нам, кто вас послал сюда и зачем?",212725,null],[246517,"2026-10-01T12:23:45",20,"*Беатриче переводит взгляд с Марко на Ясмин, оба выглядят как будто не в себе. Che cazzo...*\n\n*Кое-как подавив бушующий в груди гнев, она поворачивается к бандиту. Нет, не время и не место сейчас устраивать разборки*\n\n*Она подходит, защелкивая на бандите наручники, пристегнув их к ближайшей балке. Чтобы не сбежал? Скорее чтобы не дать повода этим двоим прикончить и его*",212725,null],[246519,"2026-10-01T12:25:05",22,"//я все жду, когда Беатриче под предлогом похода в кафешку, отвезёт нас в помещение с мягкими белыми стенами и рубашками-обнимашками",212725,null],[246520,"2026-10-01T12:25:53",20,"/к серединеи кампании вероятность этого явно возрастёт 👀",246519,null],[246521,"2026-10-01T12:26:00",22,"//я честно думала, что только я буду самая отбитая. Но явно недооценила изощренность Николая",212725,null],[246522,"2026-10-01T12:29:07",22,"Немного придя в себя, Ясмин протянула руку, чтобы коснуться плеча Марко, но взгляд упал на окровавленный пол и она шагнула назад.\n\n- М-мне жаль.. Я-я правда не хотела н-навредить... \n\nЯсмин встала за спиной Биатриче и посмотрела на бандита. Ее золотой глаз ярко сиял.",212725,null],[246523,"2026-10-01T12:29:41",31,"человек в ужасе смотрит на тебя, покрытого кровью его бригадира, на всю обстановку вокруг. Он дрожит крупной дрожью и выдавливает:\n\n- м-мы люди Дона Треви... Капо сказал, что нужно тут что то забрать... клянусь, я не знаю о чем речь, спросите у капо... \n\nуказывает пальцем на останки арбалетчика, потом понимает что тот уже не ответит и начинает жалобно скулить",246516,null],[246524,"2026-10-01T12:31:20",20,"/r d20 Беатриче пытается припомнить что-то о доне треви",212725,null],[246526,"2026-10-01T12:32:11",31,"что то царапает твою подкорку, но что?",246525,null],[246527,"2026-10-01T12:37:26",20,"*Беатриче вздвхает, слегка хлопнув по его плечу. Черт, как же все так быстро скатилось в это...*\n\n- Хватит дрожать. Тебя не убьют, даю свое слово. \n\n*Бросает она. Да, возможно убить его и избавиться от свидетеля было бы логичнее - Дон Треви явно не простит убийство его людей, если это кто-то из криминальных авторитетов. Но убить этого парня ей не позволит честь - и дьявол с ними, с этими последствиями*\n\n- Кто такой этот твой Дон?",246523,null],[246529,"2026-10-01T12:38:22",22,"/r -1 Может Ясмин что-то о нем слышала",212725,null],[246531,"2026-10-01T12:40:31",31,"ты вспоминешаь, что слышала это имя краем уха, за ужином в таверне где ты живешь. Ты не вслушивалась, но вроде как о нем говорили довольно темные личности и говорили с уважением",246530,null],[246532,"2026-10-01T12:42:13",17,"/r d20+5+d4 марко помнит о Треви не переживайте",212725,null],[246534,"2026-10-01T12:42:40",17,"/ Или нет...",212725,null],[246536,"2026-10-01T12:43:11",31,"ты помнишь о нем как о криминальном воротиле и главе семьи Треви. Без подробностей, его дела с твоими не пересекались никогда",246533,null],[246540,"2026-10-01T12:46:36",31,"Мужик подуспокоился, млова Беатриче его проняли. Он поверил в себя.\n\n- Ну, Дон Треви это Дрн Треви, большой босс, кормилец. Все знают дона\n\nОчевидно, он верит в свои слова. В его картине мира Дон - это всем известная величина, даром что сам он явно не знал дона лично, а может и не видел его никогда",246527,null],[246546,"2026-10-01T13:06:13",20,"- Среди нас тут есть и приезжие - расскажи о Доне Треви поподробнее.",246540,null],[246547,"2026-10-01T13:10:08",31,"Просто хлопает глазами в ответ. Но понимая, что его жизнь и здоровье висят на волоске, начинает что то усиленно вспоминать\n\n- Дон, ну Дон это тот кто приказы раздаёт и зарплату платит, и вдовам солдат помогает, если дон говорит делать, мы делаем и не спрашиваем зачем. \n\nОпускает голову, смиряясь с неизбежным:\n\n- я про Дона только это знаю, я его не видел никогда сам...",246546,null],[246549,"2026-10-01T13:26:39",20,"*Беатриче смотрит на Марко и Ясмин, дескать есть ли у них ещё вопросы*",212725,null],[246556,"2026-10-01T14:18:48",22,"Ясмин лишь тяжело вздохнула.\n\n-- Н-надо его придушить, ч-чтобы не ударил в спину и осмотреться. Ч-что они хотели выкрасть.. \n\nДа добивай его, чего мелочиться?",212725,null],[246557,"2026-10-01T14:19:25",22,"/Ясмин предлагает в нелетал негодяя и осмотреть тела наёмников + понять, что они хотели забрать",212725,null],[246558,"2026-10-01T14:20:11",31,"Посчитаю это заявкой от всей группы//",246557,null],[246559,"2026-10-01T14:23:16",17,"Марко подходит к закрытой двери и сперва стучит\n\n— Кх кх\n\n— Господин Сангвини послал нас. Там кто нибудь есть?",212725,null],[246560,"2026-10-01T14:23:46",31,"Ударив несчастного бандюгана по голове ещё разок и отправив его в сон, в после к лекарю с сотрясением мозга, вы начинаете обшаривать телв и то что от них осталось. Ваше добычей стали:\n\n- тяжелый арбалет и 12 болтов к нему\n- скимитар\n- короткий меч\n- булава\n- два флакона с алхимическим огнем\n- 12 золотых и 5 серебряные монет\n- тяжёлый ключ с гравировкой \"67\"",212725,null],[246561,"2026-10-01T14:23:51",20,"- Я за ним пересмотрю, не надо его больше трогать *Тут же реагирует Беатриче*\n\n- Хватит на сегодня смертей",246556,null],[246562,"2026-10-01T14:24:34",20,"/блин, уже успели ушатать беднягу (",212725,null],[246563,"2026-10-01T14:25:07",31,"Оттуда раздаётся неуверенный голос:\n\n- Сиор Сангвини послал вас? Хвала небесам! Сейчас отро... Стойте, в чем вы докажите что от хозяина пришли?",246559,null],[246564,"2026-10-01T14:25:32",31,"Тут не дробят, тут темное фентози/",246562,null],[246565,"2026-10-01T14:27:55",22,"//я легонько булавой приложила, погладила",246562,null],[246566,"2026-10-01T14:29:25",31,"Кстати, еще к луту булава, точго",212725,null],[246567,"2026-10-01T14:33:49",20,"/Беатриче запомнила сорт и название того вина которым ее угостили?",246563,null],[246568,"2026-10-01T14:35:31",31,"Да, можешь сама придумать, потому что я поленился прописать)/",246567,null],[246569,"2026-10-01T14:42:57",20,"- Elegia sanguinaria, урожай позапрошлого года со здешних виноградников. Цвет если брать на свет -  carminio intenso. *Через дверь говорит Беатриче, прислонившись плечом к стене*\n- Едвали кто-то в городе смог бы угостить нас данным сортом кроме самого Сеньора Сангвини.\n\n- Ну что, достаточно убедительный пароль?",246563,null],[246570,"2026-10-01T14:48:01",31,"Голос оттуда раздаётся уже спокойный. \n\n- и впрямь. Разве что вы прочитали название на бочке рядом. Но про цвет там не написано. \n\nДверь отворяется со скрипом. Оттуда появляется небольшого росточка старик, что смотрит на вас как на ангелов небесных, что выдернули его из пасти дракона",212725,null],[246571,"2026-10-01T14:48:37",31,"Молодец что про цвет ввернула, я уже хотел язвить и заставлять проходить проверку убеждения/",212725,null],[246572,"2026-10-01T14:51:07",17,"Марко поть поклонился\n\n— Господин послал нас совершенно по другому поводу. Но мы все понимаем на виноградников проблем хоть отбавляй. Что ж, сперва...\n\n— Что хотели люди Дона Треви, что они требовали или искали тут?",212725,null],[246573,"2026-10-01T14:58:46",31,"Старик мрачнеет.\n\n- эти ублюдки явились сюда около недели назад. Их было много. И сильные. Они убили Джеронимо, члена клана что охранял нас. Принесли какую то дрянь, мелкие камушки и заставили нас закидывать их в бутылки. Это кропотливая работа, она затянулась на несколько дней, но первые партии вина с камнями уехали от нас почти сразу, наши обычные курьеры и не спрашивали ни о чем, просто приехали и забрали. А нас заставили добавить камеи во все бутылки. И когда мы закончили, сегодня вечером, почти все из них уехали, оставили только этих...\n\nПоказывает пальцем на трупы ваших жертв\n\n- они начали зачистку, почти всех убили, я понял что единственный шанс выжить это спрятаться за дверью, он из мощного дуба. Но на сле несчастья тут же лежал мешочек с оставшимися камнями, и без него они уходить не пожелали",212725,null],[246574,"2026-10-01T15:03:49",22,"Ясмин смотрит на старика. Есть ли у него признаки проклятия? Он ведь напрямую трогал эту дрянь.",212725,null],[246575,"2026-10-01T15:04:59",22,"- Изменилось ли в-ваше здоровье с тем пор, к-как вы начали этим заниматься?\n\nЯсмин буквально выплюнула последние слова.\n\n- И почему вы целую н-неделю никому не говорили?",212725,null],[246576,"2026-10-01T15:05:03",22,"/r +6",212725,null],[246578,"2026-10-01T15:05:16",22,"//медицина",246577,null],[246579,"2026-10-01T15:05:32",31,"Старик выглядит здоровым для своих лет. Никаких признаков проклятия.",212725,null],[246580,"2026-10-01T15:07:26",31,"- а мы и не могли сказать, сиора. Тут за нами был приглядывать бандитов, а от имени Джеронимо они письма слали в резиденцию клана, дескать все в порядке. Сиор Джеронимо тут давно жил, и за нами приглядывал. Но и на него нашлась управа\n\nНа последних словах голос старика дрогнул. Видимо, силы что дал ему эмоциональный подъём уже начали заканчиваться",246575,null],[246581,"2026-10-01T15:08:45",31,"- зато я знаю, откуда они эти камни проклятые притащили. Где то в порту их хранили, я по ящику понял. Только не знаю, где именно они там лежали",212725,null],[246582,"2026-10-01T15:09:15",17,"— Где тело Джеронимо? А так же разрешите забрать камни на анализ, мы сюда за ними и прибыли.",212725,null],[246583,"2026-10-01T15:11:11",31,"- не осталось тела, сиор. Они его на солнце вытащили. Так и сгорел Джеронимо, в пыль обратился. А камни забирайте, мне они не нужны, проклятые",246582,null],[246584,"2026-10-01T15:13:14",31,"- надо сиору Энрике сообщить обо всем, срочно отправлюсь в город",212725,null],[246585,"2026-10-01T15:16:27",17,"— Порт значит... Где базируется сам Дон Треви не известно, может игорный дом или стриптиз?",212725,null],[246586,"2026-10-01T15:17:00",31,"- я не знаю, сиор. Откуда мне о бандитах знать?",246585,null],[246588,"2026-10-01T15:32:12",22,"Ясмин осматривает камни, пытаясь понять, кто их сделал и какой магией.",212725,null],[246589,"2026-10-01T15:32:16",22,"/r +6",212725,null],[246591,"2026-10-01T15:32:25",22,"/сожрала один🙈\nЛибо торкнуло",212725,null],[246592,"2026-10-01T15:33:22",31,"Разрешаю один сожрать для анализа. Пусть мама и тети тебе скажут что это работа карги)) но минус к хп будет до долго отдыха)))/",246591,null],[246593,"2026-10-01T15:34:11",31,"Я без шуток кстати предлагаю. Даже описание дам)/",212725,null],[246594,"2026-10-01T15:35:40",31,"Могу в личку скинуть описание, чтобы ты расписала в речи карг в голове//",212725,null],[246595,"2026-10-01T15:36:39",22,"Ясмин смотрит на камни, но ничего не понимает.\n\nОна берет один из них в руку и подносит поближе, чтобы рассмотреть. \n\nВнезапно, ее рот сам собой открывается, а рука закидывает туда камень. Из глаз девушки брызнули слезы, а из горла вырвалось настрающее хихиканье. \n\nИхихи-хи-хи",212725,null],[246596,"2026-10-01T15:36:45",22,"Описывай тут)/",246594,null],[246597,"2026-10-01T15:41:24",31,"Твои внутренние карги помогают тебе определить, что эти камешки - это подклады, созданные Ночной Каргой. Они сделаны очень хитро, проклятие основано на крови Сангвини, и не причиняют вреда другим людям, кровь это биологический маркер. Скорее всего, для создания использовалась кровь одного из Сангвини. Камешки постепенно насыщали вино, которое пьют члены клана и навязывало им кошмары, что прорывались в реальность",246596,null],[246598,"2026-10-01T15:42:07",31,"/roll d6 это минус к твоему максимальному ХП до долгого отдыха",212725,null],[246600,"2026-10-01T15:42:15",31,"Несерьёзно вышло(",212725,null],[246603,"2026-10-01T15:52:23",22,"Находясь в припадке, с закатанными глазами, Ясмин сбивчиво пояснила эту информацию. \n\nКогда она закончила, ее лицо побледнело, а одна прядь волос поседела.",246597,null],[246604,"2026-10-01T15:59:57",20,"*Беатриче наблюдает за всем этим в культурном шоке. С кем она вообще работает...*\n\n- Вы...в порядке синьора? *Осторожно спрашивает она, протягивая ей фляжку воды*",212725,null],[246605,"2026-10-01T16:05:47",22,"Ясмин кивнула и выпила воды, приходя в себя.\n\n- И-извините. У меня п-просто свои о-особенности.",212725,null],[246628,"2026-10-01T18:25:36",31,"Ещё заявки сегодня планируются?/",212725,null],[246629,"2026-10-01T18:26:29",20,"/подождем что скажет Марко на инфу о карге, у меня просто перс вообще не шарит чё это",246628,null],[246635,"2026-10-01T18:53:44",17,"Марко дернулся к Ясмин, но опоздал\n\n— Ясмин, какого...\n\nКамень уже исчез во рту\nОн перехватил её за запястье, второй рукой придержал за плечо, не давая упасть когда глаза девушки закатились\nХихиканье ему не понравилось совсем\nМарко молча слушал сбивчивые слова, запоминая каждую деталь\n\n\"Ночная Карга. \nКровь Сангвини\nНе отравляет вино а просто проводник\nСон прорывается наружу...\"\n\nКогда припадок закончился, Марко ещё несколько секунд не отпускал её руку\nВзгляд остановился на побелевшей пряди\n\n— Это тоже ваша... особенность?\n\nОн не дожидался ответа и сразу отпустил.\nДостал записную книжку и записал увиденное в подробностях. В личное дело Ясмин. \nПосле посмотрел на оставшиеся камни\n\n— Значит нам нужна кровь Сангвини, которую использовали для изготовления. Кто её дал, добровольно или нет, может привести к самой Карге\n\nМарко достал кошель из кожи, вытряхнул из него в карман скудные запасы монет  и очень осторожно, не касаясь кожей руки, забрал в него один из оставшихся камней\n\nПосмотрел на Ясмин\n— Сиора, я беспокоюсь о вас. Давайте договоримся больше не есть проклятые предметы. Хотя вам, кончно в этом деле виднее. \n\nМарко снова открыл записную книжку\n\n— Вы узнали больше чем мы смогли бы узнать здесь за сутки. Благодарю\n\nОн повернулся к старику\n\n— Теперь о ящиках. Вспоминайте всё что на них было. Может цифры? Может клеймо или название судна. Какой был цвет краски. Что угодно, что позволит найти нужный склад в порту",212725,null],[246645,"2026-10-01T18:58:32",31,"Старик чешет голову\n\n- ну ящики были с маркировкой, там был номер склада, он точно был двузначный. Шестерка вроде, и еще что то. Да, точно, шестьдесят какой то склад. \n\nСтарик продолжает думать:\n\n- помню, что когда главный этих бандитов уходил, он тем, кто остался сказал чтобы они все обратно на склад везли, к птичке",246635,null],[246646,"2026-10-01T18:59:08",17,"Марко подошёл и чернилами на стене написал 61 \n\n— Посмотрите наглядность помогает вспомнить",212725,null],[246647,"2026-10-01T18:59:20",17,"В стороне написал крупно 62",212725,null],[246648,"2026-10-01T18:59:25",17,"/ у нас всего 9 вариантов",212725,null],[246649,"2026-10-01T18:59:40",17,"Марко продолжал писать с паузами смотря на старика",212725,null],[246650,"2026-10-01T18:59:48",20,"- К птичке ... может это какой-то опознавательный знак у склада? Вроде статут или рисунка?",212725,null],[246651,"2026-10-01T19:00:08",17,"— Может есть Стелла или статуя птицы?",212725,null],[246652,"2026-10-01T19:00:22",17,"/r d20+5+d4 Вспоминаем",212725,null],[246654,"2026-10-01T19:00:27",20,"- Не припомнить ничего такого в Районе доков, сеньор?\n\n/Помощь",212725,null],[246656,"2026-10-01T19:00:50",31,"Старик всматривается, и когда доходит до номера 67, делает какие то странные движения руками, словно поднимает по очереди два арбуза.\n\n- точно, 67!",212725,null],[246660,"2026-10-01T19:01:23",31,"Стараемся в молодёжные отсылки/",212725,null],[246669,"2026-10-01T19:03:05",17,"— У нас есть ключ\n\nМарко достает ключ с гравировкой 67. \n\n— Значит он от склада.",212725,null],[246670,"2026-10-01T19:03:13",31,"Ты вспоминаешь, что в порту вообще полно птичьей тематики. Там и куча кораблей с птичьими именами, и всяки мелкие изображения юурескстников, альбатросов и прочих пернатых. Да буквально шагу не ступить, чтобы не наткнуться на матроса с попугаем на плече. Нереально проверить",246653,null],[246672,"2026-10-01T19:03:16",17,"— Что ж. Не будем медлить, сиоры!",212725,null],[246674,"2026-10-01T19:03:47",17,"— По номеру склада спросим дорогу у местных работников портового района.",212725,null],[246679,"2026-10-01T19:04:31",20,"- А с этим что? *Кивает на бессознательное тело*\n\n- Отправим к синьору Сангвини?",212725,null],[246685,"2026-10-01T19:11:03",31,"Решайте что делать с бандосом и что будете делать дальше. Напомню, на улице ночь, около 3 часов. До города в принципе можете добраться к рассвету",212725,null],[246696,"2026-10-01T19:15:59",17,"— Да. Отправим Сангвини. Он просил живого. Вот он. \n\n\nСмотрит на Беатриче открыто\n\n— Да, это жестоко, сиора. Но вы слышали. Они убивали всех здесь по приказу.",246679,null],[246697,"2026-10-01T19:16:34",17,"— Если не хватает духу вынести приговор, когда доказательства уже собраны. \n\nОчки Марко поймали блик\n\n— Я вынесу его сам.",212725,null],[246698,"2026-10-01T19:17:15",31,"Сами на склад идете?",212725,null],[246699,"2026-10-01T19:18:13",17,"— Идём в район доков. Склад 67 ждёт.",212725,null],[246714,"2026-10-01T19:25:59",31,"Расположив пленника на лошадях и прихватив старика, что назвался Клеменце, вы к рассвету были у городских ворот. Там ваши дороги разошлись, Клменце с пленником отправился к поместью Сангвини с отчетом, а ваша дорога вела к портовым складам.\n\nБез особых проблем вы выяснили направление у местных докеров, и вот вы уже стоите перед складом номер 67. Внешне он ничем не выделяется на фоне других, разве что перед ним не толчется народ. Большие ворота склада закрыты, но ключи от небольшой двери у вас есть. Вы можете зайти внутрь, если хотите",212725,null],[246717,"2026-10-01T19:27:26",17,"Ворон облетает склад по кругу\n\nПросто в поиске щелей и окон",212725,null],[246719,"2026-10-01T19:27:40",17,"\"Ну что там, Жнец?\"",212725,null],[246722,"2026-10-01T19:29:25",31,"Окна на складе ечть, под самой крышей, они нужны только для того, чтобы внутрь мог проникать солнечный свет. Заглянуть в гид можно, но что происходит на полу здания не видно",212725,null],[246739,"2026-10-01T19:38:21",22,"Ясмин потрогала свою седую прядь. \n\n- Да, так.. бывает. Иногда.. потом приходит. Оно в-всегда п-проходит...\n\nДевушка бросила взгляд на пленника и отвернулась. \n\nОн сам выбрал свою судьбу.\n\nКонечно сам, остальных то ты прожарила\nКак тебе на вкус камушек?\nДуреха. Хватит тянуть в рот всякую гадость!",212725,null],[246748,"2026-10-01T19:45:50",20,"*Беатриче пробует прислушаться, есть так какая возня на складе*",212725,null],[246750,"2026-10-01T19:46:00",20,"/r d20+4",212725,null],[246754,"2026-10-01T19:46:12",20,"/тиш да гладь...",212725,null],[246766,"2026-10-01T19:50:02",22,"/r +6 Ясмин тоже прислушивается",212725,null],[246769,"2026-10-01T19:50:15",22,"*звуки сверчков*",212725,null],[246780,"2026-10-01T19:55:08",17,"/r +d20+5+d4 Марко смотрит глазами в Ориона внутрь через окошко",212725,null],[246782,"2026-10-01T19:55:14",31,"Ясмин слышит только скрип досок дв шуршанье крыс. Беатриче не слышит и этого.",212725,null],[246783,"2026-10-01T19:55:24",17,"\"Дай ка я сам взгляну\"",212725,null],[246784,"2026-10-01T19:57:30",31,"Марко видит густо заставленный склад и замечает одинокую человеческую фигуру, что сидит посреди склада на одном из ящиков и болтает ногами. Судя по всему это очередной бандит, возможно как раз тот, что ждет возвращения чистильщиков с проклятыми камнями",212725,null],[246791,"2026-10-01T20:00:27",17,"— Сиора Ясмин. Станьте тем командиром бандитов.  Кажется вы предлагали такой хитрый ход. Думаю сейчас самое время реализовать этот козырь.",212725,null],[246793,"2026-10-01T20:00:36",17,"Марко протягивает Ясмин ключ",212725,null],[246797,"2026-10-01T20:01:16",17,"— Внутри один. Вы зайдёте и заболтаете его. А мы зайдём после вас. И поддержим в случае проблем.",212725,null],[246800,"2026-10-01T20:01:52",20,"- Может ещё камни для убедительности с собой взять? Ну так, на всякий случай",246793,null],[246819,"2026-10-01T20:05:53",17,"— У меня один. Остальные кажется у вас, да?",212725,null],[246821,"2026-10-01T20:05:56",22,"--Мы же хотим п-проследить за ним и у-узнать, что п-происходит, верно?\n\nЯсмин замялась.\n\n- У меня е-есть еще о-одна идея.",212725,null],[246823,"2026-10-01T20:06:17",22,"//дайте время я придумаю как это описать адекватнт",212725,null],[246825,"2026-10-01T20:06:23",17,"— Достаньте из него информацию. Что хочет Дон. Зачем он пошел войной на Сангвини.",246821,null],[246826,"2026-10-01T20:06:44",17,"— Сделай вид что все сделано в лучшем виде. Парни уже напиваются в баре и лапают проституток.",212725,null],[246831,"2026-10-01T20:07:24",17,"— Конечно, это все не более чем советы с моей стороны. Как угодно сеньора, так и развяжите ему язык",212725,null],[246835,"2026-10-01T20:08:04",20,"- Хм, тот бандит с арбалетом был не простой, а Капо. Возможно так на складе вообще один из его подчинённых? Тогда ещё и авторитетом сможете надавить",212725,null],[246836,"2026-10-01T20:08:14",22,"//я пока подумаю как это нарративно описать, игромеханически предложу тут, мб у вас будут идеи\n\nУдалённое наблюдение. Если вы находитесь в пределах 10 миль от сувенира, вы можете действием войти в транс. Транс длится 1 минуту, но заканчивается раньше, если вы выйдете из него (действие не требуется) или окажетесь недееспособны. Во время этого транса вы можете видеть и слышать происходящее вокруг сувенира, как если бы вы лично находились там. Пока вы используете свои органы чувств в месте нахождения сувенира, вы ослеплены и глухи для окружающей вас среды. Когда транс заканчивается, сувенир уничтожается без каких-либо последствий.\n\n\nХочу реализовать вот это. Думаю тут должно зайти.\n\n\nЧерез полчаса-час напишу",212725,null],[246847,"2026-10-01T20:11:33",17,"/ Ну может маскировку на Бетариче сама камень как сувенир и наблюдаешь куда тебя отнесут. Мб так. Я снаружи жопу поморожу. Ваша сцена я в тени. Тем более щас занят)",212725,null],[246860,"2026-10-01T20:14:03",31,"Обсуждайте короче, и решайте что будете делать. Как решите, отпишитесь. Я уже утром отреагирую/",212725,null],[246870,"2026-10-01T20:16:06",31,"Мне очень сильно нравится планирование и фишка с личинами. Прям вкусно./",212725,null],[246928,"2026-10-01T20:32:06",22,"Ясмин чуть сгорбилась и тихо начала объяснять.\n\n— Я-я не только могу принять облик Капо(лидер бандюганов) но и...\n\nДевушка закусила губу, практически до крови.\n\nДавай, малышка, сделай это!\nВидишь, когда надо, твоя кровь может быть тебе полезной\nШабаш не только требует\nШабаш еще и дает...\n\n— Я могу подкинуть им предмет, через который буду видеть и слышать все что происходит вокруг носителя предмета!\n\nБыстро выпалила девушка и испуганно вжала голову в плечи.",212725,null],[246929,"2026-10-01T20:32:39",22,"Получив подтверждение товарищей, девушка стала действовать.",212725,null],[246943,"2026-10-01T20:38:58",22,"Ясмин взяла мешочек с камнями, потом она отошла от товарищей чуть подальше и постаралась сделать так, чтобы они этого не увидели.\n\nДевушка протянула руку перед собой. Ее пальцы стали изменяться, они покрылись морщинами и скрючились. Ногти удлиннились и стали больше напоминать когти. Зажмурившись, девушка шумно вдохнула и сунула пальцы себе в рот.\n\nХруст. Резкая боль. Скрежет когтей.\n\nВ руке у девушки был ее зуб. Рука же постепенно возвращала свой первоначальный внешний вид.\n\nЯсмин достала один из своих платков и наскоро обтерла от крови зуб, руки и свой рот.\n\nПосле чего, девушка достала свой ювелирный набор и наскоро обтесала зуб так, чтобы тот стал больше напоминать один из камней. \n\nУбедившись в качестве проделанной работы, Ясмин кинула свой зуб в мешок, к другим камням и обратилась Капо(лидером бандитов).",212725,null],[246947,"2026-10-01T20:39:19",22,"/r +2 Скрытное вырывание зуба",212725,null],[246953,"2026-10-01T20:39:45",22,"//как человек, которому удаляли все 4 зуба мудрости, я не представляю, как это можно сделать скрытно и с покер фейсом",212725,null],[246977,"2026-10-01T20:49:15",22,"Ясмин-Капо подходит к тому мужику и откидывается спиной на один из ящиков. Она говорит тихо, но будто ни к кому не обращается.\n\n— Дело сделано, Сангвини больше не проблема. Мои ребята уже празднуют в кабаке, девок щупают да эль глушат, заслужили. А теперь к делу, мы свою часть выполнили, но попотеть пришлось изрядно, если ты понимаешь о чем я.\n\nЯсмин поворачивается к мужику и делает жест рукой, будто пересчитывает стопку монет.\n\nПосле чего, Ясмин подходит вплотную, но смотрит в другую сторону. Ее рука передает мешок с камнями.\n\n— Слушай, между нами... Сангвини - ребята не простые.. у них связи везде. Дон точно уверен, что вывезет эту войну? Что за комар его укусил, зачем он вообще на них пошел? Мы подставили свои шеи, и я хочу быть уверен, что у Дона есть четкий план, а не просто личная обида. Что конкретно он хочет с них поиметь?",212725,null],[246985,"2026-10-01T20:50:48",22,"//а можно мне каркающую ворону в помощь?",212725,null],[246999,"2026-10-01T20:54:36",17,"/ И щас он такой девок щупают.... Мммм, а они все педики были......",212725,null],[247002,"2026-10-01T20:55:27",22,"//Ох уж этот гордый городок..",246999,null],[247985,"2026-10-02T02:58:04",31,"Хватит читать мои заметки!/",246999,null],[247989,"2026-10-02T03:05:02",31,"//Ребята, скажу сразу. Мне невероятно жаль ломать вашу идею об колено сейчас. Может быть в середине этого квеста я бы еще поменял что то и дал вам поиграть в шпионов, но тут я уже сюжетку завязал на другое. Оставим это для другого квеста, тем более у меня появилась одна смутная идея для квеста где будет возможность поработать под прикрытием. А пока будет кое что другое//",212725,null],[247990,"2026-10-02T03:09:47",31,"Мужик смотрит на Ясмин-Капо и вместо ответа улыбается, сверкнув длинными клыками.\n\n- Хорошо говоришь, но торопишься, все сразу хочешь вызнать. Капо бы так не чумел,. Да т пахнешь ты по другому, лицо его, а кровь не та. Я это чую. Не зря Хозяин сказал, что может прийти кто то любопытный. Не обманул, как всегда. А еще он мне сказал, что тот кто придет с вопросами - это мой бонус.",212725,null],[247991,"2026-10-02T03:12:30",31,"@lady_godzilla \n\nИтак, перед тобой вампирское отродье, которое считает тебя бонусом за отлично проведенную работу. И он готовится тебя выпить. Но пока он вальяжен, у тебя есть возможность совершить какое либо действие, может напапасть первой, или попытаться сбежать или позвать на помощь. Или начать плакать. Выбирай.",212725,null],[247995,"2026-10-02T06:49:17",22,"Хребет об колено конечно же.\n\nБежим.. эх",247991,null],[247996,"2026-10-02T07:09:23",31,"Жаль что он все таки не тормоз. Рывком догоняет тебя, отбрасывает внутрь склада и плотоядно облизываясь, приближается. \n\nДиспозиция Ясмин посадки склада, перед ней в 30 футах вампир, за ним в 20 футах дверь в склад.\n\n@dunchev @PaIIasCat вы на улице слышите шум и понимаете что надо вмешаться. Вы входите. Перед вами спина отродья в 20 футах, он вас не заметил, слишком сосредоточен на своей \"награде\". Разрешаю вам по одному действию неожиданности, с преимуществом, затем бросаем инициативу",247995,null],[247997,"2026-10-02T07:14:03",31,"Вы ведь сразу поняли, что придется драться с вампиром, верно?) ну не мог же я такой случай упустить) удачи, ребята/",212725,null],[247998,"2026-10-02T07:30:27",22,"//да это ожидаемо было",212725,null],[248004,"2026-10-02T08:35:33",20,"/так, ладно насколько толстая крыша склада?\n/Можно ли ее пробить?",212725,null],[248005,"2026-10-02T08:35:42",31,"Если что, враг кастомный. Вроде должен быть проще обычного))/",212725,null],[248006,"2026-10-02T08:41:21",20,"/на улице уже солнышко ведь?",248005,null],[248014,"2026-10-02T09:11:00",22,"/судя по описаниям да, предположу что 4-5 утра",248006,null],[248017,"2026-10-02T09:20:50",31,"Около 5 утра, рассвет близко, но ещё не наступил. Дверь через которую вы вошли с южной строны",212725,null],[248115,"2026-10-02T10:48:23",31,"Ребята, если есть возможность, давайте завалим вампира в ближайщие пару часов? Просто у меня статблок его на рабочем компе и нужные по сюжету арты тоже, а через 2,5 часа я свалю на выходные)//",212725,null],[248116,"2026-10-02T10:48:33",17,"/ Щас сделаем",212725,null],[248120,"2026-10-02T10:50:13",20,"/так ладно, тактику оставляю на умного Марко и врываюсь танковать тогда",212725,null],[248139,"2026-10-02T10:53:19",17,"/ Умный марко предложил наложить маскировку на Беатриче!)",212725,null],[248141,"2026-10-02T10:53:44",17,"/ А млин она на себя только, пон",212725,null],[248143,"2026-10-02T10:54:02",31,"Насколько я могу судить, Маскировка это особенность карги-кукушки/",212725,null],[248145,"2026-10-02T10:54:07",17,"/ Тогда отзываем статус умного!",212725,null],[248147,"2026-10-02T10:54:20",22,"//да бейте его! Там моя дама в беде.\nСильная и независимая. Слабая и зависимая.",212725,null],[248155,"2026-10-02T10:57:12",20,"- Надеюсь вы что-нибудь быстро придумаете, Сеньор Марко. Я пойду пока возьму удар на себя *шепчет она ему, прежде чем сорваться с места*\n\n*Беатриче ногой выбивает дверь на склад, выхватывая рапиру и кинжал.*\n\n*Видит кто перед ней и хищно усмехается. Вампир? Похоже зря она расстраивалась - ей всё-таки удастся сразится с подобным противником*\n\n- Обижать даму, что не может ответить? Che schifo. Теперь твой противник - Беатриче Висконти да Вальдрио!\n\n*Она делает жест, будто танцор приглашающий на танец. Или дуэль, что в целом для нее одно и тоже*\n\n- Моя сталь жаждет танца, а вы выглядите как сносный партнер на один вечер. Не разочаруйте меня, signore\n\n/Стойка уклонения + открытая провокация\n/Ну и ждёт когда этот зубастый тоже представится по правилам чести😤",212725,null],[248156,"2026-10-02T10:57:22",17,"— Черт, план провалился!",212725,null],[248157,"2026-10-02T10:57:43",17,"Марко влетает внутрь за Беатриче ворон пикирует разбивая оконное стекло",212725,null],[248158,"2026-10-02T10:57:51",17,"/r +2 Инициатива Марко и ворон",212725,null],[248160,"2026-10-02T10:58:16",31,"Ну давайте все инициативу, я то думал вы его подло в спину ударите))",212725,null],[248162,"2026-10-02T10:58:43",31,"/roll d20+3 Инииатива вампира",212725,null],[248164,"2026-10-02T10:58:48",20,"/да за кого ты нас держишь! (Оскорблённые аристократические звуки)",248160,null],[248165,"2026-10-02T10:58:58",20,"/r d20+3",212725,null],[248168,"2026-10-02T10:59:51",31,"ну хоть зашла красиво/",248166,null],[248170,"2026-10-02T11:00:34",20,"/хорошо что не атаку а уклонение выбрала\n/Главное чтобы он теперь на это клюнул, а не пошел делать Ясмин кусь)",248168,null],[248173,"2026-10-02T11:01:33",31,"@lady_godzilla Инициативу/",212725,null],[248176,"2026-10-02T11:03:03",31,"Марко\nВампир 33 урона, помеха\nЯсмин\nБеатриче",212725,null],[248179,"2026-10-02T11:03:44",22,"/r +2",212725,null],[248182,"2026-10-02T11:04:22",31,"Марко может ходить/",212725,null],[248183,"2026-10-02T11:04:33",17,"\"ПАДАЙ\"",212725,null],[248184,"2026-10-02T11:04:42",17,"/Спас мудрости СЛ13",212725,null],[248185,"2026-10-02T11:04:51",22,"//будь моя воля, я бы давала вампирами бафы/дебафы в зависимости от того какую дрянь они кусают",212725,null],[248187,"2026-10-02T11:05:13",31,"хватит читать мои заметки!!!!",248185,null],[248188,"2026-10-02T11:05:42",31,"/roll d20+1 мудрость",248184,null],[248190,"2026-10-02T11:06:06",31,"упал, хуле/",212725,null],[248191,"2026-10-02T11:06:30",31,"Опиши что с ним и что ему делать в свой ход?/",212725,null],[248197,"2026-10-02T11:07:57",31,"о как/",212725,null],[248199,"2026-10-02T11:08:11",31,"так что он просто ржет тебе в лицо\n\n- ты мне не Хозяин!",212725,null],[248200,"2026-10-02T11:09:19",17,"\"ГЛУПЕЦ, ОН ЖИВОЙ ТРУП! МЕНЯ СЛУШАЮТСЯ ТОЛЬКО ЖИВЫЕ ИЛИ ПО НАСТОЯЩЕМУ МЁРТВЫЕ, МАРКО! ТЫ ОСЁЛ!\"",212725,null],[248203,"2026-10-02T11:13:42",31,"- трое на одного значит... не честно как-то...\n\nНарочитым движением достает из кармана табакерку, откидывает крышку и достает оттуда щемотку белого порошка. Вы видите что этот порошок обжигает его пальцы, но вампира это не смущает. он подносит ладонь к носу и резко втягивает носом порошок. \n\nРеакция наступает незамедлительно. Вены на его теле вздуваються, и начинают гореть серебристым сиянием, а глаза напротив, наливаются чернотой. Что бы он не вдохнул, это явно не что то полезное для хдоровья. Но похоже, он стал опаснее.\n\nБонусным действием он перемещается к Марко и пытается впится в его шею. Ты успеваешь рассдышать:\n\n- зря ты решил мне приказывать...",212725,null],[248204,"2026-10-02T11:13:53",31,"/roll d20+5 укус",212725,null],[248206,"2026-10-02T11:14:07",31,"лох, разрешаю атаку реакцией/",212725,null],[248207,"2026-10-02T11:14:13",31,"от Марко/",212725,null],[248209,"2026-10-02T11:16:50",17,"/r +4 Пошла атака!",212725,null],[248210,"2026-10-02T11:16:50",22,"//нет, пусть кусает. Хочу посмотреть, как у него пена пойдёт изо рта от \"вкусняшки\" Марко",212725,null],[248212,"2026-10-02T11:17:13",17,"/r d8+2 РУбящий",212725,null],[248216,"2026-10-02T11:17:42",17,"РУка покрылась темными тенями и превратилась в готи которыми Марко резанул по вампиру на реакции после уклонения",212725,null],[248217,"2026-10-02T11:17:52",31,"половинка урона, если не магический/",212725,null],[248218,"2026-10-02T11:18:25",31,"Ход Ясмин/",212725,null],[248222,"2026-10-02T11:23:00",17,"\"ДОСТАВАЙТЕ ФЛАКОНЫ С ВОДОЙ, СМЕРТНЫЕ\"",212725,null],[248224,"2026-10-02T11:24:21",31,"//Ребята, сорян, всех попросил сыгратьт, а сам работать убегаю, кто же знал что придеется. Попробую быстро все сделать и вернусь//",212725,null],[248227,"2026-10-02T11:30:09",17,"/ Да не парься, Полина вероятно тоже работает, и скажу по секрету мы с Катей тоже жестко пашем прямо щас! Да, Кать?)",248224,null],[248229,"2026-10-02T11:30:29",17,"/ \"Вбил задачу в нейронку - пишет пост в другой теме\"))",212725,null],[248236,"2026-10-02T11:39:23",22,"//работаю. Вот такие вот гении навбивали в нейронку задач, а я потом не понимаю, с херали у нас по бумагам все локомотивы идеально отремонтированы, а по факту вместо того что нужно, на них впендюрили то, что по чертежам стоять физически не может\n\nИзвините, горит",248229,null],[248254,"2026-10-02T12:18:20",31,"Вернулся. Жду по возможности ход Полины/",212725,null],[248271,"2026-10-02T12:33:08",22,"Ясмин шипит, как змея, а после стреляет вампиру в спину из арбалета.\n\nБонус Сглаз сл 14 ловкость\nДействие атака из арбалета",212725,null],[248273,"2026-10-02T12:33:43",22,"/r +4\n/r d8+1d6 стрела и некротика",212725,null],[248276,"2026-10-02T12:34:00",22,"@PaIIasCat",212725,null],[248278,"2026-10-02T12:34:27",31,"некротика имунн/",248274,null],[248279,"2026-10-02T12:34:49",31,"/roll d20+5 ловкость",248271,null],[248281,"2026-10-02T12:35:07",31,"что там от сглаза?/",212725,null],[248282,"2026-10-02T12:35:27",22,"Помеха на все спасибо ловкость/",248281,null],[248283,"2026-10-02T12:35:55",22,"Напомните, в днд лечение ран - нежить ранит? Или просто не действует?/",212725,null],[248284,"2026-10-02T12:36:33",31,"никак/",212725,null],[248294,"2026-10-02T12:41:22",31,"Вампир, что так борзо выглядел вначале, уже успел отхватить люлей от Марко контратакой, словить стрелу от Ясмин и сглаз от нее же. Он немного обескуражен, но все еще верит в свою непобедеимость.\n\n@PaIIasCat поддай ушлепку//",212725,null],[248299,"2026-10-02T12:44:29",20,"- Хей, да как ты смеешь игнорировать саму Беатриче Висконти! *Беатриче кидается на него, отталкивая Марко в сторону и загораживая его собой*",248294,null],[248300,"2026-10-02T12:44:49",20,"/r d20+5 рапира\n/r d20+5 кинжал",212725,null],[248302,"2026-10-02T12:45:04",20,"/одну удачу на рапиру",212725,null],[248303,"2026-10-02T12:45:10",20,"/r d20+5",212725,null],[248305,"2026-10-02T12:45:37",20,"/r d8+3 урон рапиры\n/r d4+3 и кинжала",212725,null],[248307,"2026-10-02T12:45:52",20,"/моя рапира проклята, я поняла",212725,null],[248308,"2026-10-02T12:46:06",20,"/нужно нести осящать в храм",212725,null],[248309,"2026-10-02T12:46:30",31,"иттго 5 урона",212725,null],[248310,"2026-10-02T12:46:48",20,"- Давай, нападай на меня, черт возьми! *Возмущается она*\n\n/Конец хода",212725,null],[248311,"2026-10-02T12:47:17",20,"/ну все, после этого я коплю 100 золотых и покрываю рапиру серебром...",248309,null],[248312,"2026-10-02T12:47:28",31,"Вампир получил два укола но смотрит на тебя странно, словно не хочет атаковать",248310,null],[248316,"2026-10-02T12:50:44",31,"/Марко",212725,null],[248322,"2026-10-02T12:56:17",17,"Марко выхватил бутылку святой воды и с размаху пытается забить ее о лицо вампирского отродья",212725,null],[248324,"2026-10-02T12:57:12",17,"/r +2 Ну.. Да",212725,null],[248326,"2026-10-02T12:57:48",31,"бутылка летит мимо и разбивается об пол, оставляя лужу",212725,null],[248327,"2026-10-02T12:58:06",31,"Это весь ход?/",212725,null],[248328,"2026-10-02T12:59:47",17,"Ворон толкает своей тушкой с воздуха вампира в спину под летящий флакон",212725,null],[248331,"2026-10-02T12:59:58",17,"/Ход",212725,null],[248332,"2026-10-02T13:00:24",31,"Вампир ловким движением отбрасывет ворона в полете куда то в сторону",212725,null],[248333,"2026-10-02T13:00:33",31,"и улыбается",212725,null],[248337,"2026-10-02T13:01:39",31,"вы видите что одна из его ран затягивается, ублюдок регенерирует",212725,null],[248339,"2026-10-02T13:02:17",31,"не обращая внимания на Беатриче, он вновь атакует Марко, оббегая девушку на высокой скорости (без провоцирки)",212725,null],[248340,"2026-10-02T13:03:03",31,"/roll d20+5 когти по Марко\n/roll d20+5 клыки по Марко",212725,null],[248342,"2026-10-02T13:03:45",17,"Волна черной энергии не даёт приблизится вампиру",212725,null],[248343,"2026-10-02T13:04:16",31,"Похоже, вампир еще слишком неопытен в своем теле, его атаки опасны, но неуклюжи, он промахивается. Сейчас он стоит перед Марко, а позади у него за спиой Бестриче, чуть дальше за спиной Ясмин",212725,null],[248344,"2026-10-02T13:04:18",31,"ход/",212725,null],[248345,"2026-10-02T13:04:32",31,"Ясмин ходит/",212725,null],[248347,"2026-10-02T13:05:29",31,"Беатриче в бешенсте, эта мразь ее игнорирует",248346,null],[248349,"2026-10-02T13:12:47",22,"//Беатриче, я твой отец 😈",248312,null],[248350,"2026-10-02T13:13:39",31,"твой мать/",248349,null],[248351,"2026-10-02T13:13:49",22,"-- Свет, помоги мне!\n\nСпасибо лвк 14 с помехой",212725,null],[248352,"2026-10-02T13:14:03",22,"/r d8 если провал",212725,null],[248354,"2026-10-02T13:14:06",31,"/roll -d20+3",248351,null],[248356,"2026-10-02T13:14:17",22,"Ход @PaIIasCat",212725,null],[248357,"2026-10-02T13:14:31",31,"этот урон огнем?",212725,null],[248358,"2026-10-02T13:14:39",22,"Лучистый",248357,null],[248359,"2026-10-02T13:14:55",31,"ок, значит минус реген на следущий ход/",212725,null],[248362,"2026-10-02T13:18:06",20,"- Эй,какого черта ты смеешь игнорировать мой вызов?! *Беатриче снова оказывается прямо перед лицом вампира, оскаливаясь*\n\n- Я бросила тебе вызов, так имей честь принять его! Давай, назовись кто ты и бей!",212725,null],[248363,"2026-10-02T13:18:14",20,"/обе атаки захват",212725,null],[248364,"2026-10-02T13:18:28",31,"обниматся лезешь?/",248363,null],[248365,"2026-10-02T13:20:20",20,"/ну куда ж без этого",212725,null],[248367,"2026-10-02T13:20:46",20,"/r d20+1 вроде атлетика нужна\n/r d20+1",212725,null],[248369,"2026-10-02T13:21:01",31,"мне что кидать, ловкость?/",212725,null],[248370,"2026-10-02T13:21:07",31,"акробатику?/",212725,null],[248372,"2026-10-02T13:21:54",17,"/Акробатика или атлетика",212725,null],[248373,"2026-10-02T13:22:10",31,"/roll -d20+5 акробатика от первого захватп\n/roll -d20+5 акробатика от второго",212725,null],[248375,"2026-10-02T13:22:20",31,"опа, поймала",212725,null],[248376,"2026-10-02T13:22:25",31,"обняла как родного/",212725,null],[248377,"2026-10-02T13:23:10",31,"описывай что делаешь и ход Марко/",212725,null],[248378,"2026-10-02T13:25:40",22,"//это я удачно сглазила",212725,null],[248379,"2026-10-02T13:25:59",31,"сглаз долго работает?/",248378,null],[248380,"2026-10-02T13:26:21",17,"/ Да, долго",212725,null],[248381,"2026-10-02T13:26:30",38,"// очень",248379,null],[248382,"2026-10-02T13:26:39",20,"*Беатриче ловит вырывающегося вампира в клещи, крепко обнимаю со спины и прижимая его руки к туловищу*\n\n/Не уйдет, собака",212725,null],[248383,"2026-10-02T13:26:52",17,"Марко рвёт когтями схваченого",212725,null],[248384,"2026-10-02T13:27:13",17,"/r +d20+4 Опля ворон помогает",212725,null],[248386,"2026-10-02T13:27:19",31,"попал",212725,null],[248387,"2026-10-02T13:27:21",17,"/ Это если че рескин атаки рапирой",212725,null],[248388,"2026-10-02T13:27:27",17,"/r d8+2 Урон",212725,null],[248390,"2026-10-02T13:27:32",17,"/ 5 колющего",212725,null],[248391,"2026-10-02T13:28:19",31,"когти Марко Вонзаются в мертвую плоть",212725,null],[248392,"2026-10-02T13:28:55",31,"ход Вампира, пытается вырваться. какой спас пробить нужно чтобы вырваться?",212725,null],[248393,"2026-10-02T13:29:24",20,"/встречная проверка опять",212725,null],[248394,"2026-10-02T13:29:27",31,"/roll d20+5 Акробатика, вампиры пытается вырваться и отступить",212725,null],[248396,"2026-10-02T13:29:28",20,"/акробатика",212725,null],[248398,"2026-10-02T13:29:41",20,"/r d20+1 aтлетика",212725,null],[248400,"2026-10-02T13:29:43",31,"14 выьил с помехой",212725,null],[248401,"2026-10-02T13:29:58",20,"/не, не вырвался",212725,null],[248402,"2026-10-02T13:30:22",31,"Вампир орет:\n\n- отпусти, дура, не посмотрю кто ты такая, порву!",212725,null],[248403,"2026-10-02T13:30:25",31,"ход/",212725,null],[248404,"2026-10-02T13:30:31",31,"Ясмин/",212725,null],[248405,"2026-10-02T13:30:51",31,"пиздят вампира бессовестно/",212725,null],[248406,"2026-10-02T13:31:35",17,"\"КТО ДАЛ КРОВЬ СЕМЬИ САНГВИНИ! ТЫ?\"",212725,null],[248408,"2026-10-02T13:31:55",17,"Марко утробным звуком басисто рычит эти слова ему в ухо",212725,null],[248409,"2026-10-02T13:32:16",31,"- я что, похож на этих ублюдков! ха!",212725,null],[248410,"2026-10-02T13:32:35",31,"- тебя я тоже порву, шакалоголовый",212725,null],[248411,"2026-10-02T13:32:42",31,"- всех порву!",212725,null],[248412,"2026-10-02T13:32:58",22,"Лвк 14, с помехой",212725,null],[248413,"2026-10-02T13:33:14",22,"Ясмин пускает лучи света в злую кровосиську.",212725,null],[248414,"2026-10-02T13:33:21",22,"/r d8",212725,null],[248418,"2026-10-02T13:34:46",31,"/roll -d20+3",212725,null],[248420,"2026-10-02T13:35:20",31,"-аррргх, ты тоже сдохнешь!",212725,null],[248421,"2026-10-02T13:35:34",31,"Беатриче/",212725,null],[248422,"2026-10-02T13:35:54",20,"- Ну и кто я, а?! Я Висконти! *Шипит она в ответ*\n\n/Ну чё, он в захвате, сковываю его в кандалы)",248402,null],[248424,"2026-10-02T13:37:17",31,"И достаю плетку.../",248422,null],[248425,"2026-10-02T13:37:43",22,"//погоди.. вы взяли 2е наручников. Нормальные и пушистые? Нормальные вы потратили..",248422,null],[248426,"2026-10-02T13:37:58",17,"/Не, мы их не брали)\n\nне брали же...?",248425,null],[248428,"2026-10-02T13:38:22",22,"Я помню что брали//\nЖду арт на вампира в пушистых наручниках",212725,null],[248429,"2026-10-02T13:39:25",20,"/r d20+5 одеваем наручники (с розовым мехом)",212725,null],[248431,"2026-10-02T13:39:49",20,"/добро пожаловать в deep dark fantasy сладкий",212725,null],[248432,"2026-10-02T13:39:50",31,"Смерть от кринжа/",212725,null],[248433,"2026-10-02T13:40:35",31,"Ну ход Марко видимо/",212725,null],[248434,"2026-10-02T13:41:16",17,"/Опутан?",212725,null],[248435,"2026-10-02T13:41:34",31,"Ну да",212725,null],[248437,"2026-10-02T13:42:02",22,"//расчехляю свой разращенный жпт",212725,null],[248438,"2026-10-02T13:42:39",31,"Хорошая картинка, потом после его хода дополнишь, хорошо?/",248436,null],[248475,"2026-10-02T14:23:23",31,"@dunchev будешь глумится над вампиром? Твой ход",212725,null],[248482,"2026-10-02T14:25:50",17,"/Сори щас",212725,null],[248483,"2026-10-02T14:26:21",17,"Марко осматривается в поисках осинового кола",212725,null],[248484,"2026-10-02T14:26:29",17,"Есть ли факел или жаровня с огнём?",212725,null],[248506,"2026-10-02T14:33:48",17,"Не найдя ничего марко рвёт его по горлу когтями",212725,null],[248507,"2026-10-02T14:34:09",17,"/r +d20+4 Удар d8+2 Урон",212725,null],[248509,"2026-10-02T14:34:14",17,"/Ход",212725,null],[248520,"2026-10-02T14:39:10",31,"Я вам на кой черт давал алхимический огонь в луте?) три раза вроде)",248484,null],[248522,"2026-10-02T14:39:30",17,"/Брат этими бутылками попасть с +2 да ну нахер",248520,null],[248523,"2026-10-02T14:39:40",17,"/Тем более взрыв 10 футов",212725,null],[248531,"2026-10-02T14:41:04",31,"Ладно, ход вампира",212725,null],[248533,"2026-10-02T14:42:40",22,"//это на потом. Пусть лежит.",248520,null],[248540,"2026-10-02T14:46:34",31,"Получив удар в горло вампир насмешливо говорит Марко:\n\n- и это все? Слабый червяк. Ничтожество. Сейчас ты увидишь боль...\n\nЕго речь прерывается. Серебристое свечение в жилах сменяется на черно зеленое, он одним движением вырывается из захвата Беатриче и бросается на Марко. Похоже, та дрянь что он вдохнул в начале боя, наконец дала ему полную силу",212725,null],[248542,"2026-10-02T14:47:04",31,"/roll d20+5 когти по Марко\n/roll d20+5 клыки по Марко",212725,null],[248544,"2026-10-02T14:48:39",31,"Не попав по Марко вампир в  ярости ревёт и бонусным действием отходит вглубь склада",212725,null],[248545,"2026-10-02T14:49:06",31,"Теперь вампир в середине склада, неподалёку от Ясмин",212725,null],[248546,"2026-10-02T14:49:10",31,"Ход/",212725,null],[248549,"2026-10-02T14:51:41",31,"Ясмин, вампир рядом, твой ход/",212725,null],[248551,"2026-10-02T14:55:42",22,"Спас телосложение 14",212725,null],[248553,"2026-10-02T14:56:31",22,"Ясмин громко взвизгнула и накрыла голову руками. Вокруг нее начало расходиться сияние.",212725,null],[248556,"2026-10-02T14:56:52",22,"/r 2d10+2 Сияние рассвета",212725,null],[248558,"2026-10-02T14:57:00",22,"...",212725,null],[248560,"2026-10-02T14:57:15",22,"@PaIIasCat ходи, а я плакать",212725,null],[248563,"2026-10-02T14:58:14",31,"/roll d20+3",248551,null],[248566,"2026-10-02T14:58:31",31,"Прошёл даже с помехой",212725,null],[248568,"2026-10-02T14:58:52",22,"//2 урона лучистым. Ори от боли, пожалуйста 🥲",248566,null],[248572,"2026-10-02T15:00:16",31,"- сссука сссветлая",212725,null],[248573,"2026-10-02T15:01:01",20,"/а в скольких футах от вампира Ясмин?",212725,null],[248575,"2026-10-02T15:02:11",31,"10",248573,null],[248581,"2026-10-02T15:03:44",20,"*Беатриче бежит за вампиром, нанося два удара. Даже не столько для урона, понимая что он мало что ему сделает, а чтобы тот уже обратил внимание наконец-то!*",212725,null],[248582,"2026-10-02T15:04:11",31,"Выброси крит единицу, оьратит/",248581,null],[248583,"2026-10-02T15:04:12",20,"/r d20 +5 кинжал \n/r d20+5 рапира",212725,null],[248585,"2026-10-02T15:04:22",20,"/ну почти",212725,null],[248586,"2026-10-02T15:04:22",31,"Киндаж прошёл)",212725,null],[248587,"2026-10-02T15:04:40",20,"/r d4+3",212725,null],[248590,"2026-10-02T15:05:09",31,"Вампри защищается ладонью, но ты ее пропарываешь",212725,null],[248593,"2026-10-02T15:06:02",20,"- Почему ты не дерешься со мной?! Что, кровь Висконти для тебя не достаточно хорошо?!",212725,null],[248595,"2026-10-02T15:07:06",20,"/конец хода",212725,null],[248597,"2026-10-02T15:07:48",31,"Он насмешливо: \n\n- Висконти?!",248593,null],[248599,"2026-10-02T15:08:24",20,"- Да, Висконти! ВИСКОНТИ ДА ВАЛЬДРИО!!!",248597,null],[248600,"2026-10-02T15:08:50",31,"- ну если ты настаиваешь...",212725,null],[248601,"2026-10-02T15:09:05",20,"/кажется я знаю что ты собираешься сделать...💀",248597,null],[248603,"2026-10-02T15:09:48",31,"/я предсказуемый, да. Но погоди. Если выживешь, будет интересно. Наверное/",248601,null],[248604,"2026-10-02T15:10:08",31,"@dunchev ходи",212725,null],[248605,"2026-10-02T15:10:25",20,"/к маме все больше и больше вопросов👀",248603,null],[248607,"2026-10-02T15:11:05",31,"/мама знает почти все. Реально стоит с ней потрещать/",248605,null],[248619,"2026-10-02T15:17:02",22,"//ты домой хоть иногда возвращайся",248605,null],[248622,"2026-10-02T15:17:19",20,"/да надо бы",248619,null],[248629,"2026-10-02T15:23:26",31,"Ну я надеюсь дать сюжетный пинок ей по итогам этого квеста. Вампир такой лох конечно получился) или это мой рак кубов все//",212725,null],[248631,"2026-10-02T15:24:02",22,"//ой не тебе возмущаться! Две единицы на топовом спелле",248629,null],[248634,"2026-10-02T15:24:51",17,"\"Порошок...\"",212725,null],[248635,"2026-10-02T15:25:00",17,"МОгу я схватить шкатулку с порошком?",212725,null],[248637,"2026-10-02T15:25:19",17,"/Табакерку",212725,null],[248638,"2026-10-02T15:25:26",20,"/тоже хочешь занюхнуть?",248635,null],[248640,"2026-10-02T15:25:37",31,"Можешь. Ловкость рук 18",248637,null],[248642,"2026-10-02T15:25:54",17,"/ Бля когда он был скован было бы попроще, но хорошая мысля приходит...",212725,null],[248643,"2026-10-02T15:26:01",17,"/r +2 Ловкость рук",212725,null],[248646,"2026-10-02T15:26:10",17,"Ворон тоже рядом цепляется",212725,null],[248649,"2026-10-02T15:26:26",31,"Ворон выхватил табакерку из кармана вампира",212725,null],[248650,"2026-10-02T15:26:38",31,"- стой, курица ебаная, верни!",212725,null],[248651,"2026-10-02T15:27:09",17,"\"Сюда\"\n\nВорон кидает ее марко в ладонь и тот занюхивает порошок",212725,null],[248652,"2026-10-02T15:27:24",31,"Ой бляяяяя/",248651,null],[248656,"2026-10-02T15:27:43",31,"/roll d10 лучистого урона по Марко",212725,null],[248659,"2026-10-02T15:28:15",31,"Вы ребята ебвнутые, жрете всякую херню))//",212725,null],[248660,"2026-10-02T15:28:33",22,"//Это Марко повторюшка!",248659,null],[248664,"2026-10-02T15:30:02",31,"Затянувший понюшкой порошка из табакерки вампира, Марко получил дикий удар по мозгам и огонь в легких. Ты получаешь +2 урону и +15 к скорости на следующие три хода, затем будет плохо",212725,null],[248666,"2026-10-02T15:30:13",31,"Ход вампира",212725,null],[248669,"2026-10-02T15:30:20",17,"/ О да, я сбегу!",212725,null],[248670,"2026-10-02T15:30:23",17,"/ ))))))",212725,null],[248672,"2026-10-02T15:31:10",31,"Вампир, у которого отняли нямку, а дозу хочется, кидается на Марко с утробным вокс. Нарик сраный",212725,null],[248676,"2026-10-02T15:31:41",20,"/он рядом, захват провоцированной",212725,null],[248678,"2026-10-02T15:31:47",20,"/r d20+1",212725,null],[248681,"2026-10-02T15:32:05",31,"/roll d20+5 удар когтями\n/roll d20+5 проверка ловкости рук на вернуть табакерку",212725,null],[248684,"2026-10-02T15:32:17",31,"Чмошник",212725,null],[248687,"2026-10-02T15:32:32",31,"Не работает, он под дурью слишком быстрый/",248676,null],[248688,"2026-10-02T15:32:36",17,"Марко не просто стал быстрее человеческий глаз перестал замечать его молниеносные скачки",212725,null],[248692,"2026-10-02T15:33:00",31,"/Ясмин",212725,null],[248693,"2026-10-02T15:33:06",22,"Лвк 14 от вампира, с помехой",212725,null],[248697,"2026-10-02T15:33:23",20,"/команда шизов и нариков, кайф",212725,null],[248698,"2026-10-02T15:33:24",22,"Ясмин сквозь слезы, пытается направить луч света на вампира",212725,null],[248699,"2026-10-02T15:33:34",22,"/r d8",212725,null],[248708,"2026-10-02T15:34:24",31,"/roll -d20+3",248693,null],[248710,"2026-10-02T15:34:40",22,"7 лучистого, ход @PaIIasCat",212725,null],[248714,"2026-10-02T15:35:03",31,"- уээээ\n\nРечь вампира уже не похожа на человеческую",212725,null],[248719,"2026-10-02T15:37:00",20,"*Беатриче берет подмышку обдолбавшкгося Марко, оттаскивая его от вампира*\n\n*С тяжёлым вздохом берет алхимический огонь и бросает в гада*\n\n- Мда, дуэль как-то вообще не задалась...",212725,null],[248720,"2026-10-02T15:37:10",20,"/r d20+5",212725,null],[248724,"2026-10-02T15:37:56",31,"Урон можешь не кидать",212725,null],[248728,"2026-10-02T15:41:16",31,"Вампир вспыхивает как спичка, и сгорает за секунды. Непонятно что его доконало, огонь или все таки приход от его порошка. Или все вместе, что более вероятно. Вы пока не знаете, что это было, но явно не что то хорошее и пригодное для употребления",212725,null],[248730,"2026-10-02T15:41:49",20,"/хорошо хоть образец этой дури остался",212725,null],[248733,"2026-10-02T15:42:48",17,"/МАРКО ЕЩЕ НЕ ДОНЮХАЛ ВСЁ ДО КРУПИНКИ",248730,null],[248738,"2026-10-02T15:43:57",22,"- Марко! Марко! Приди в себя!\n\nЯсмин подбежала к мужчине и стала хлопать его по щекам.",212725,null],[248742,"2026-10-02T15:44:14",31,"Проверка медицины",248738,null],[248743,"2026-10-02T15:44:24",22,"/r +d20+6",248742,null],[248746,"2026-10-02T15:44:46",20,"*Беатриче просто на всякий случай придерживает его, а то мало ли*",212725,null],[248748,"2026-10-02T15:45:18",31,"Ты в лишь у Марко признаки отравления металлической пылью. Похоже, он занюхнул... Толчёное серебро?",248744,null],[248750,"2026-10-02T15:46:10",31,"Ты понимаешь, что это вряд ли вызовет привыкание, но легкие нужно очищать",212725,null],[248751,"2026-10-02T15:46:20",22,"-- Кяа пагал хаа?!\n(Ну что за дурак)",212725,null],[248754,"2026-10-02T15:46:54",20,"/опа",248748,null],[248755,"2026-10-02T15:47:17",22,"--  Нужно будет делать и-ингаляции. Иначе б-будете кашлять к-кровью.",212725,null],[248756,"2026-10-02T15:48:11",20,"- Инга...что? Типа прокашляться дать?",248755,null],[248761,"2026-10-02T15:48:59",22,"-- К-кальян. Н-на травах. П-простите, в этой стране знают о к-кальянах?",248756,null],[248771,"2026-10-02T15:51:14",31,"Шакал, что курит кальян/",212725,null],[248774,"2026-10-02T15:51:54",20,"-Эээ... да, но как ему поможет пахнуть пару раз? *Все ещё не до конца понимает что хочет Ясмин*\n\n- Ну можем отвести его в такое место,если хотите",248761,null],[248777,"2026-10-02T15:52:20",31,"/осмотритесь хоть/",212725,null],[248778,"2026-10-02T15:52:56",31,"/а то попиздовали в кальянную уже/",212725,null],[248784,"2026-10-02T15:53:27",17,"\"ДАЛЬШЕ Я САМ, МАРКО, СПИ, СМЕРТНЫЙ\"\n\nМарко пытается схватить Ясмин за горло и поднять над землёй с утробным рыком\n\n— ВЕДЬМА!",212725,null],[248785,"2026-10-02T15:53:35",17,"/r -1 Атлетика!)))",212725,null],[248792,"2026-10-02T15:54:12",17,"/r +5 Спас мудрости марко сопротивляется",212725,null],[248794,"2026-10-02T15:54:23",22,"/r +4 ну допустим акробатика",212725,null],[248796,"2026-10-02T15:54:24",17,"/ СЛ заклинаний 14 Нормал",212725,null],[248797,"2026-10-02T15:54:58",17,"Резким рывком Черная лапища шакала поднимает Ясмин над землёй\n\nЕё ножки болтаются а руки мышинально хватаются за плотную тьму",212725,null],[248798,"2026-10-02T15:55:10",17,"/ Постик пишу",212725,null],[248838,"2026-10-02T16:05:36",17,"Голос выходит из горла Марко, но голос не его. Внутри всё ещё ревёт серебро, сердце колотится слишком быстро, мышцы требуют движения, чужая сила распирает тело будто пытается разорвать его изнутри\n\nА поверх всего этого - Анубис. Огромный. Холодный. Уверенный что сопротивляться уже некому\n\n\"СЛАБЫЙ\"\n\nПальцы на горле Ясмин сжимаются сильнее. Марко видит её лицо будто через мутное стекло\n\n\"Нет\"\n\nЛапа не слушается\n\n\"ОНА ТРОГАЕТ ТО ЧТО ПРИНАДЛЕЖИТ МЁРТВЫМ\"\n\n\"Нет\"\n\nНа мгновение перед глазами возникает другое лицо. Не Ясмин. Девять лет, растрёпанные волосы\n\n\"Папа, смотри. Ещё одна звезда\"\n\nОн будто держит свою девятилетнюю дочь за шею\nЧто-то внутри Марко дёрнулось. Память.\n\n\"Лючия\"\n\nТень шакала дёрнулась\n\n\"СПИ\"\n\n\"Лючия Веньер\"\n\nПальцы на шее Ясмин разжимаются едва заметно\n\n\"ТЫ МОЙ\"\n\n\"НЕТ!\"\n\nМарко наконец шевелит уже своей рукой. Очень медленно, будто вытаскивает её из глубокого зыбучего песка\n\nТень начинает дрожать. Челюсти шакала раскрываются в беззвучном рыке\nМарко резко втягивает воздух\n\n— Отпусти... её\n\nГолос ещё двойной. Человеческий и что-то древнее под ним. Лапа сопротивляется\nМарко сжимает зубы так сильно что во рту появляется вкус крови\n\n— Я сказал. Отпусти\n\nПальцы разжимаются. Тьма резко срывается с руки. Теневая голова шакала ещё секунду висит поверх его собственной, потом начинает медленно сползать с лица, \n\nЯсмин падает вниз. \n\nМарко отшатывается на несколько шагов и хватается рукой за стену, тяжело дышит. Серебряная пыль всё ещё жжёт внутри, руки дрожат\nОн смотрит на Ясмин, потом на собственную ладонь которой секунду назад держал её за горло\n\n— Ясмин. Дыши. И прости, если сможешь...",212725,null],[248842,"2026-10-02T16:07:04",31,"Как вам посты писать, вы меня в плане пафоса на световые годы обходите//",212725,null],[248853,"2026-10-02T16:09:37",17,"/Так побочки накатили еще сверху",212725,null],[248854,"2026-10-02T16:09:40",17,"/Что получается?",212725,null],[248862,"2026-10-02T16:11:50",31,"Как тебе сказать. Это не наркотик. Это в прямом смысле металлическая пыль. Пока не уберёшь ее из организма, будешь проходить спас тела. Каждый раз он будет повышаться. Подходить будешь каждый отдых или каждый день. При провале -д10 хп",212725,null],[248864,"2026-10-02T16:12:07",31,"Я вообще не ебу как ты кго уберёшь из легких",212725,null],[248865,"2026-10-02T16:12:18",31,"И дв, баффы были на три хода/",212725,null],[248872,"2026-10-02T16:13:02",31,"Так что проходи спас тела, первый до следующего отдыха. СЛ 10 для начала",212725,null],[248879,"2026-10-02T16:15:14",31,"Когда спас дойдет до 16, начнется не только отток хп, но и снижение максимума здоровья перманентно, как у хроника",212725,null],[248894,"2026-10-02T16:16:39",31,"Да, все время забываю про это дерьмо/",248880,null],[248898,"2026-10-02T16:17:08",17,"/Снятие проклятья пускай типо, до 5 лвла никак или за 250 ЗМ которых нет",212725,null],[248906,"2026-10-02T16:18:23",22,"//я тебе варианты предложила, так то нарративно мы лечили путем долгого отдыха(3 дня в постельке=1 автоспас) \nИ да, у меня один персонаж так попал",248864,null],[248913,"2026-10-02T16:19:46",17,"/ Ясмин не будет лечить путём смачного удара по шарам с ноги?",248906,null],[248914,"2026-10-02T16:20:02",17,"/ Всё зряяяя",212725,null],[248917,"2026-10-02T16:20:34",17,"/Если че, мне на дебаф ультра пофиг, это даже прикольно, курильщик астматик",212725,null],[248921,"2026-10-02T16:22:16",31,"Давай уже спас тела, хочу тебе хп снять, раз уж вампиром не вышло)",212725,null],[248936,"2026-10-02T16:24:42",17,"/r +3 Спас тела",212725,null],[248939,"2026-10-02T16:24:54",22,"Ясмин упала на землю. Девушка вся тряслась. Из горла вырывался хрип-стон, а внутри все саднило.\n\nДевушка отползла в уголок и зажалась там, стиснув в кулаке кинжал.\n\nМожет все же пора домой?\n\nИз темноты посмотрели золотые глаза.\n\nЕще не насмотрелась на этих мразей?\n\nЕщё одна пара появилась над телом вампира.\n\nА ведь он выглядел таким нормальным\nТаким смелым, какой тебе никогда не быть\nТаким сильным, какой ты никогда не станешь\nТаким очаровательным, в отличие от тебя\n\nЯсмин почувствовала, будто кто-то стоял совсем рядом с ней, ей показалось, что ее щеки дотронулось могильное дыхание матери.\n\nТы слабая. Бестолковая. Маленькая негодница. Обучись ты моему ремеслу, тебе бы не было равных! Я все еще жду тебя дочка.\n\nЯсмин попыталась закричать, но их горла вырвалось лишь хрипение.",248838,null],[248941,"2026-10-02T16:25:35",31,"/roll d10 лучистый урон",248937,null],[248944,"2026-10-02T16:25:54",22,"//Ясмин нет. Не все же у меня бой-бабы :)",248913,null],[248946,"2026-10-02T16:26:23",17,"/ Схватить в следующий раз Беатриче ✍️",212725,null],[248949,"2026-10-02T16:26:48",31,"Придется стать со временем)/",248944,null],[248952,"2026-10-02T16:27:03",22,"//сделаем тебе кальян, когда Яс мозги на место немного вправит",212725,null],[248959,"2026-10-02T16:27:43",17,"Марко поднял руки в примирительном жесте ладонями к Ясмин двинуться в её сторону не смел. Он видел что было, что он сделал\nХотел было что что еще сказать\n\nНо серебро осевшее на лёгких дало о себе знать. Тяжелый приступ кашля повалил его на пол",212725,null],[248967,"2026-10-02T16:31:01",22,"Добей!\nДобей!\nДобей!",212725,null],[248981,"2026-10-02T16:33:26",31,"Ладно, как посициалите, пишите. Можете провести обыск/",212725,null],[248985,"2026-10-02T16:34:05",17,"/ @PaIIasCat какая реакция Беатриче?",212725,null],[249001,"2026-10-02T16:37:04",22,"Ясмин стиснула в руках кинжал и, пошатываясь подошла к Марко.\n\nНет.\n\nЯ не стану такой же. Я выше этого. Я не отвечу насилием на насилие...\n\nБандитам тем заливать будешь, которые танцевали, пока ты их поливала огнем.\n\nЯсмин мотнула головой.\n\nОна присела рядом с Марко. В одной руке был кинжал. А в другой у нее разгорался свет.\n\nПоджав губы, девушка разжала руку с кинжалом. Со звонким звуком он упал на камни.\n\nЯсмин погладила Марко по спине, из её руки исходило свечение и тепло. \n\n--Это пройдёт. Все проходит. Нужно время.\n\nПросипела она.",212725,null],[249003,"2026-10-02T16:37:14",22,"/r d8+4 лечим Марко",212725,null],[249013,"2026-10-02T16:41:30",17,"/ Ударами кулака!))",249001,null],[249041,"2026-10-02T16:47:50",17,"Марко ещё несколько раз тяжело кашлянул, но от руки Ясмин не отстранился\nОн молча смотрел в камни перед собой\n\n— Я чуть тебя не убил. А ты меня лечишь\n\nМарко поднял на неё взгляд\n\n— Благодарю, Ясмин",212725,null],[249074,"2026-10-02T16:56:29",22,"//мастер, а в этом городе есть хоть один нормальный гетросексуальный мужчина без странных наклонностей? \n\nСпросила шизичка🙈",249013,null],[249075,"2026-10-02T16:56:50",17,"/ Была парочка",212725,null],[249076,"2026-10-02T16:56:55",17,"/ Их на винокурне сожгли",212725,null],[249078,"2026-10-02T16:57:07",22,"//они сгорели в огне своих амбиций",249075,null],[249081,"2026-10-02T16:58:01",22,"Ясмин молча кивнула.\n\nПотом девушка перевела взгляд на Биатриче. \n\n-- Нужно осмотреться.\n\nПросипела она.",249041,null],[249083,"2026-10-02T16:58:12",22,"/r +6 внимание",212725,null],[249086,"2026-10-02T16:59:14",22,"//Ну да да конечно. Это же на мужика голого смотреть! Да что со мной не так?!\n\nПросто 2 крайности:\nПосмотреть на голого мужика = 20 на кубе\nПосмотреть что происходит вокруг = 1 на кубе",212725,null],[249093,"2026-10-02T17:00:06",17,"/Схватить тимейта за шею для сцены Крит 20 👌",212725,null],[249096,"2026-10-02T17:00:29",17,"[ДАННЫЕ УДАЛЕНЫ]",212725,null],[249110,"2026-10-02T17:05:54",20,"/пиздец, что я пропустила",212725,null],[249111,"2026-10-02T17:06:03",20,"/читаю",212725,null],[249112,"2026-10-02T17:06:30",22,"//ты все пропустила!",249110,null],[249114,"2026-10-02T17:07:17",31,"Ну Феллино вроде норм мужик/",249074,null],[249115,"2026-10-02T17:07:46",22,"//Ясмин вместо того, чтобы осматриваться, слюну на Марко пустила плачет сидит. \nМарко валяется на камнях, с астмой",212725,null],[249116,"2026-10-02T17:08:15",22,"//он слишком эм.. пушистый для меня😅",249114,null],[249118,"2026-10-02T17:09:04",31,"Зато у него ликёра до хрена/",249116,null],[249121,"2026-10-02T17:09:45",31,"У Беатриче отец мировой мужик, пятерых детей настрогал, жену правда любит, зараза такая//",212725,null],[249123,"2026-10-02T17:10:12",31,"Четверых детей*",212725,null],[249126,"2026-10-02T17:13:14",20,"/короче я не знаю стоит ли мне реакцией как-то на эту сцену вкидывать(\n/Будто уже поздновато чтобы нормально отреагировать, а не что-то вроде - \"стоит наблюдает за всем в афиге\"",249115,null],[249128,"2026-10-02T17:14:09",31,"Как в Ассасине же, у Эцио был старший брат, сестра и младший брат. Четверо)",249123,null],[249131,"2026-10-02T17:15:33",20,"/а, я уж думал ты Беатриче из списка уже вычеркнул",249128,null],[249134,"2026-10-02T17:16:30",31,"Сомневайся, сомневайся)",249131,null],[249136,"2026-10-02T17:17:02",31,"Позвольте я чуток мастерского произвола произведу?/",212725,null],[249143,"2026-10-02T17:20:29",31,"Беатриче, пребывая в легком шоке от поведения своих напарников, не стала слушать их объяснения друг перед другом и занялась более полезным делом - осмотром склада. И почти сразу она обнаружила сумку вампира, она валялась неподалёку от того места где он сидел, болтал по детски ногами и ждал их прихода.\n\nВ сумке Беатриче обнаружила немного денег (9 золотых и 7 медных), ещё один ключ от склада с номером 67, а также письмо. Вскрыв конверт, дампирша прочитала короткую записку",212725,null],[249155,"2026-10-02T17:25:11",20,"/ого, он себе даже герб Анти-Сангвини сделал",212725,null],[249156,"2026-10-02T17:25:31",31,"Рад что ты заметила/",249155,null],[249157,"2026-10-02T17:26:19",31,"Кажется, вы нашли имя, как и просил заказчик/",212725,null],[249159,"2026-10-02T17:27:34",20,"*Беатриче вчитывается в письмо. А вот похоже и ответ на все, что произошло*\n\n*Она снова оборачивается на спутников, заставая как раз тот момент, когда Ясмин пытается помочь, исцеляя Марко. Кажется, как бы странно порой эти двое себя не вели, некая связь помогающая держаться вместе у них все же есть...*",212725,null],[249160,"2026-10-02T17:28:01",31,"Созависимый токсичные отношения, милота/",249159,null],[249161,"2026-10-02T17:28:28",20,"/какие персонажи такая и связь",249160,null],[249165,"2026-10-02T17:29:28",31,"Бля, видимо зря я Ведьмака скачал, я теперь отсылки вижу. Это же Геральт и Йентфер, у них даже Циои своя есть, Лючия)",212725,null],[249168,"2026-10-02T17:30:21",17,"/Бля вот осёл, подписал письмо своим именем",212725,null],[249169,"2026-10-02T17:30:36",20,"/да у Марко скорее отеческие чувства к Ясмин",212725,null],[249171,"2026-10-02T17:30:45",20,"/со стороны во всяком случае",212725,null],[249173,"2026-10-02T17:34:06",17,"/Чувство голода у Анубиса. В остальном просто беседовали 1 раз. Развитие отношений запланировано у меня в заметках примерно на 20 сессий",212725,null],[249174,"2026-10-02T17:36:24",20,"*Беатриче подходит ближе, чувствуя себя немного неловко вторгаясь в эту странную сцену*\n\n- Синьор, Синьора, не хотела вас прерывать, но кажется я нашла информацию, за которой мы пришли.\n\n*Показывает им письмом*\n\n- Похоже наш противник был одним из людей дона, которого обратил в отродье некий Эдриан и отправил сюда на зачистку. Подозреваю это один из отступников семьи Сангвини - видите фамилию и печать? Печать чаши как на гербе Сангвини, но расколота.",212725,null],[249175,"2026-10-02T17:36:43",22,"//расслабьтесь, мы просто два больных человека. Все нормально.  Какие отношения хоспаде",249169,null],[249176,"2026-10-02T17:37:19",31,"Мы с Беатриче, как психически стабильные, просто обсуждаем двух психов, все нормально/",249175,null],[249177,"2026-10-02T17:39:24",22,"Хоть кто-то занимается делом\nБестолочь\nТолько и можешь, что ныть, да мужиков сжигать\nОй ну вылитая тётка Сара\nТочно! А я все думаю, кого она мне напоминает...\n\nВ голове Ясмин опять было бурное обсуждение. Но девушка усиленно пыталась сфокусироваться на том, что говорит Биатриче.",212725,null],[249179,"2026-10-02T17:40:49",22,"- П-похоже на то. Ж-жаль, что пришлось убить этого м-мужчину, но он был слишком о-опасен, чтобы тащить его в к-кандалах через полгорода.",249174,null],[249201,"2026-10-02T17:51:40",20,"- Да, к сожалению... *Беатриче кивает, видно что ей тоже не по душе то, что пришлось сделать. Возможно даже не столько факт убийства, как его способ. Она хотела сразить противника в честном бою, а вышло...ну, как вышло.*\n\n*Надо нанести на рапиру серебро - в любом случае понадобится при охоте на убийцу Кристины*",249179,null],[249202,"2026-10-02T17:51:50",17,"Марко смотрит на тело вампира\n\n— У нас есть всё, что просил Сангвини. Дальше не наша война. Но кажется, этот вампир новообращенный. И возможно Эдриан причастен к убийству Кристины. Нужно это расследовать перед тем как отец с ним расправится.\n\nМельком взглянул на Беатриче",212725,null],[249204,"2026-10-02T17:52:35",20,"/он разве не полностью сгорел?",212725,null],[249206,"2026-10-02T17:52:59",17,"/ Видимо отвлёкся на ведьму простите!",212725,null],[249208,"2026-10-02T18:03:31",17,"/ Что ж следователи с найдеными уликами возвращаются в резиденцию господина Сангвини",212725,null],[249209,"2026-10-02T18:04:03",31,"Ох, это же теперь лонгрид писать/",212725,null],[249210,"2026-10-02T18:06:03",22,"/я кат сцены обычно пишу заранее и нормально их оформляю с компа и просто на канале сохраняю с картинками. \nПотом по факту их запуска-простт пересылаю",249209,null],[249216,"2026-10-02T18:15:12",17,"/Я тоже",249210,null],[249217,"2026-10-02T18:15:20",17,"/ Я угадываю 90% как игроки будут играть",212725,null],[249218,"2026-10-02T18:15:24",17,"/ Но эти 10%..",212725,null],[249221,"2026-10-02T18:17:04",31,"Вы возвращаетесь в резиденцию Сангвини. Уже ярко светит солнце и порядочному вампиру положено спать. Но он ждет вас в комнате с плотно задернутыми шторами.\n\nВыслушав ваш рассказ, он кивает, когда вы говорите о ситуации на винодельне, очевидно, сопоставляя ваши слова со свидетельствами Клеменце.\n\nНо когда вы рассказываете о встрече на складе, он подбирается, информация о неизвестном ему отродье очевидно раздражает Патриарха, помешанного оа которое. Контрольным выстрелом в его голову становится письмо, подписанное Эдрианом Сангвини.\n\nУслышав это имя Энрике ругнулся, упомянув имена каких то демонов, о которых даже Марко не слышал. \n\n- Значит, он все таки вернулся... Чертов братец снова в Вальдории...\n\nЭнрике нервно ходит из стороны в сторону, и наконец приняв решение, он опускается в кресло и смотрит на вас.\n\n- думаю, мне нужно кое что объяснить. Во первых, несмотря на фамилию Сангвини, Эдриан давно не часть клана. Во вторых, думаю, это именно его и искал ваш работодатель, думаю, вам он то и нужен. В принципе, Феллино действовал правильно, когда искал гастролёра обычными путями. Вот только Эдриан необычный. Он истинный вампир, равный мне по силе. Попасть в город он мог абсолютно незаметно. \n\nПомолчав, Энрике встает и говорит вам:\n\n- пойдемте, я покажу вам его портрет. Хоть будете знать его в лицо",212725,null],[249227,"2026-10-02T18:19:33",31,"Энрике ведёт вас в катинную галерею дома, на большинстве картин изображены члены клана, все они в той или иной степени похожи на Энрике, тонкие, смуглые, темноволосые. Кроме одного портрета, на котором изображен человек с точёными скулами и светлыми волосами. И кажется, это лицо вам и правда неплохо знакомо",212725,null],[249228,"2026-10-02T18:20:17",31,"@PaIIasCat реакцию пожалуйста и продолжим",212725,null],[249234,"2026-10-02T18:28:10",22,"//оооо какие красивые кисти рук",249227,null],[249237,"2026-10-02T18:30:32",20,"*Беатриче замирает перед портретом со странным выражением лица.*\n\n*Она не была глупа, по крайней мере не настолько. Все эти странные слова матери с самого детства, теперь же слова Энрике о 'чувстве родства' в первую встречу, странное поведение того отродья, который избегал ударов по ней, его насмешка над фамилией...*\n\n*Она не может объяснить ту бурю эмоций, которая бушует в ее душе. И страх, страх что ее главные долг и гордость - имя Висконти, может ей никогда и не принадлежало полностью. Это хуже и больнее любой раны в бою...*",249227,null],[249243,"2026-10-02T18:34:19",31,"Энрике смотрит тебя с сочувствием. \n\n- думаю, теперь вы понимаете, почему я смотрел на вас с таким удивлением? Вы слишком похожи на Эдриана, словно родная дочь. Но это невозможно, физиологически невозможно. Видите ли, мой брат Эдриан - кастрат. Это произошло с ним ещё до обращения. У него не может быть детей, во всяком случае, естественным путем. Я не учитываю моменты обращений, это все таки немного не то",249237,null],[249254,"2026-10-02T18:36:37",20,"/эх, у Ясмин ещё минус один потенциальный мужик в городе)",212725,null],[249256,"2026-10-02T18:37:08",31,"- Но как бы то ни было, вы явно как то связаны с ним. Да и с Сангвини тоже. А значит, вправе знать о нём. Присядем, это долгая история",212725,null],[249257,"2026-10-02T18:37:44",22,"//мне только кисти рук зашли, моськой увы, не вышел 😅",249254,null],[249258,"2026-10-02T18:40:14",22,"-- И-извините.. но ведь в этом мире.. з-зачатие возможно даже и у.. б-ббездетных.\n\nЯсмин нервно трепала локон своих волос, вспоминая одну из родственниц, которая как раз на этом специализировалась.",212725,null],[249259,"2026-10-02T18:40:27",20,"*Беатриче кивает, все ещё пытаясь переварить все, что на нее сейчас вывалилось*\n\n-...конечно, давайте присядем.\n\n*Единственное что помогает ей сейчас сохранять спокойствие и не сорваться, так это то что худшая вероятность из всех - прямое кровное родство, сейчас противоречива. Возможно есть другое объяснение, обязательно должно быть...*",249256,null],[249260,"2026-10-02T18:40:59",20,"/Святым духом что-ли?)",249258,null],[249261,"2026-10-02T18:41:11",22,"//карги, это прям лорный факт",249260,null],[249276,"2026-10-02T18:56:15",31,"- Когда то давно, около 250 лет назад, я познакомился с Эдрианом. Я называю его братом, но технически наше братство не по родителям, что произвели нас на свет, а по обратившему нас отцу, прежнему Патриарху Сангвини, Томаззо. Он был... Жесток. Но и город тогда был другим. Основанный совсем недавно, он представлял собой арену постоянных столкновений. И Томаззо боролся за власть. Кровь лилась рекой и в какой то момент мы оказались в безвыходном положении. Нам с Эдрианом поступило предложение, которое бы спасло клан - нам нужно было убить отца. Двум отродьям, представляете? Но мы справились. Подкараулили пока отец лёг отдыхать, и Эдриан пронзил его грудь колом. А после мы приняли его кровь, стали Истинными и свободными, и смогли добить отца...\n\nТак мы стали во главе клана. Я отвечал за политику, Эдриан за силу. И наше превращение оставило на нас следы. Я начал работать над тем, чтобы наш клан  больше не был на грани смерти, разработал систему донорского полученят крови. Эдриан, в свою очередь, оставался без дела. И он начал сходить с ума. Он искал развлечения в алкоголе, наркотиках, сомнительных развлечениях. И ничего его не брало. И тогда он открыл для себя новую страсть - саморазрушение. Уверовав в свою силу и исключительность, решив что ему море по колено, он решил экспериментировать с тем, что смертельно для нашей природы. С серебром.\n\nЯ не знаю как он дошёл до мысли что толченое серебро можно вдыхать. Я не знаю в чем прелесть дикой боли, в затем ломки. Но Эдриан что то в этом нашёл. И это стало разрушать его личность. Со времени он потерял любые моральные ориентиры. Под действием серебра он творил зверства, резвл людей как скот, у него начиналось какие то припадки паранойи, которые сменялись периодами великодушия и желания одарить всех встречных градом даров. \n\nОколо 18 лет назад он устроил особо запоминающююся резню, где то в Нижнем городе. Погибло несколько сотен человек. Тогда я и понял, что если не остановлю его сейчас, то придут за всеми нами. Я не мог рисковать семьёй. И лично вышвырнул брата из города. Это было сложно, он конечно наркоман и псих, но он сильнее меня как боец. Я справился только потому что мне помогли дети, которым тоже осточертело его поведение. Тогда я потерял троих. А ему велел больше не появляться в Вальдории, мне не хватило духу его убить. А теперь он вернулся. И судя по этому письму, у его есть како ттсумачшедший план",212725,null],[249279,"2026-10-02T19:19:03",20,"- То есть сейчас в город вернулся одержимый кровопролитием и местью вампир. С зависимостью от серебра. И как показало происшествие на складе - способный обращать других в своих не менее сумасшедших слуг подобий.\n\n*суммирует Беатриче, понимая какой катастрофой это может стать для города. Уже начало становится - похоже именно Эдриан или его отродье и убили Кристину. И кто знает сколько ещё людей.*",212725,null],[249280,"2026-10-02T19:22:11",31,"- да, именно так. Я постараюсь его найти, но это будет непросто. Полагаю, он как то сговорился с этим самым Доном Треви, и нашел у него приют и поддержку.",249279,null],[249281,"2026-10-02T19:22:51",31,"- не знаю, будете ли его искать вы, но думаю, он вами заинтересуется, когда до него дойдут разговоры о вашем схдстве, сиора Висконти",212725,null],[249282,"2026-10-02T19:29:46",20,"- Если наши догадки верны и именно он стоит за убийством Кристины, я сама его найду. Рано или поздно... *Кидает тяжёлый взгляд на свою рапиру*\n\n*Сейчас она думает даже не столько о мести, а о том как защитить семью, если этот ублюдок о ней прознает. Как не потерять ещё и их...*\n\n- Можете рассчитывать на мою помощь в этом деле, синьор Сангвини. За своих спутников говорит не в праве, но за свой клинок слово буду нести до конца.",249281,null],[249283,"2026-10-02T19:31:50",31,"Энрике улыбается.\n\n- кровь старой Вальдории... Я свяжусь с вами если что то узнаю. А теперь думаю вам следует отчитаться перед начальством. А меня ждет бессонный день",249282,null],[249284,"2026-10-02T19:35:54",31,"Скип до конторы Феллино",212725,null],[249285,"2026-10-02T19:37:55",31,"Старый табакси выслушал вас, что то записал и похоже загрузился новыми обстоятельствами. После чего выдал вам вашу награду и попросил оставить его одного, общея связаться с вами через несколько дней\n\nПолучено 150 золота на каждого",212725,null],[249288,"2026-10-02T19:40:44",31,"Вторая сюжетная арка завершена. Вы получаете \n- 100 опыта за мини квест с крысами\n- 300 опыта за квест с расследованием\n- 700 опыта за боевые сцены\n- 200 опыта за отыгрыш\nИтого, + 1400 опыта. Все награды золотом, расходниками и прочим лутом также остались при вас, делите как хотите.",212725,null],[249299,"2026-10-02T19:43:07",31,"Следующая именно сюжетная арка пока в разработке. Пока будем исследовать город и проходить сторонние квесты. Буду на вас тренироваться делать сколько нибудь интересную боевку, сегодняшней я не доволен. Недоволен со своей стороны, к вам претензий у меня нет, вы супер/",212725,null],[249301,"2026-10-02T19:43:48",31,"Отзывы как всегда оставляйте в обсуждении квесты. Любая конс руктивная критика будет принята/",212725,null],[254137,"2026-10-05T06:43:27",31,"@PaIIasCat @dunchev @lady_godzilla \n\n//Сейчас у нас что то вроде интерлюдии, основной сюжет пока будет двигаться как беременная черепаха, следующий сюжетный квест начнется только после возвращения \"Серой Цапли\" - корабля на котором приплыла Ясмин, он должен привезти свидетеля покушения на капитана Карло Беати. По моим подсчетам до этого еще почти неделя, мы займем это место несколькими сторонними квестами. Опишу стартовую локацию (внезапно: таверна) и можем начинать. Ну или проигнорировать))//",212725,null],[254138,"2026-10-05T07:06:58",31,"Покинув контору Феллино, вы не нашли лучшего занятия, как посещения таверны. Выбор пал на \"Золотого Нарвала\", где квартирует Ясмин. \n\nС комфортом расположившись за столом и заказав поздний завтрак (или ранний обед) вы принялись что-то обсуждать. Разговор, впрочем, не особо клеился, сказывалась и бессонная ночь, да и мысли каждого были заняты своими проблемами. \n\nМарко с присвистом дышал, думая о том, не приведет ли его авантюра с вдыханием неизвестного порошка, оказавшегося толченым серебром, к преждевременному отходу в царство Анубиса, а ведь еще и тут дела остались. \n\nЯсмин как всегда слышала издевки своих теток и матери, которые продолжали веселиться за счет ее психики и намекая что в этом городе еще полно народу, которых можно весело сжечь. И где то на задворках сознания мелькала мысль о Ночной карге, которая накладывала проклятия как на вампиров, так и на капитана. Что их связывало? И при чем тут какой то Дон Треви?\n\nБеатриче тоже пыталась разобраться в своих чувствах. Она, несмотря на свой взрывной характер, дурой не была, и всегда знала, что отличается от членов своей семьи. Но теперь выяснилось, ч то у нее есть и еще одна, правда родство там непонятное. Надо бы с этим разобраться, прижать родителей к стенке. Фигурально, конечно, ведь Беатрече же не ненормальная, чтобы применять физическую силу к родителям? Мама говорила, что все расскажет, когда дочь станет достаточно взрослой. Может, время пришло?\n\nТаверна тем временем жила своей жизнью. Тут одуряюще вкусно пахло, публика собиралась не самая нищая и гомон толпы был по большей части ровным и спокойным. Однако, выделялись и некоторые голоса. Вот, например, за соседним столом вы услышали взволнованный голос молодого человека, что обращался к мужчине средних лет:\n\n- Наставник, поверьте, ну не приснилось мне! Я точно слышал этот шепот от линзы! Только разобрать не смог, он словно на другом языке говорил...\n\n- А я тебе говорю, не неси чушь. Я на этом маяке работаю уже 38 лет, и ничего там не шепчет, я бы уж наверное услышал хоть раз. Прекращал бы ты слушать всяких заезжих менестрелей и их сказки, уж больно впечатлительный ты стал.\n\n- Но, наставник! Вы же не можете отрицать, что на маяке что то не так? Трещинки в фундаменте, откужда они взялись пару дней назад? И запах тухлой рыбы, его же не было...\n\n- Окстись, маяку больше 400 лет. Трещинки это вообще ерунда, для такого старого здания. Но заявку в Магистрат сделать, конечно, не помешает, да. А что до запаха рыбы - так маяк на острове стоит, а вокруг море. Ну сдохла селедка, вот и воняет.\n\n- Там по запаху целая акула сдохла. Или кто побольше. А что, если это какое то проклятие?\n\n- Ты совсем одурел? Какое проклятие? Проклятие вонючего воздуха? Даже если бя я тебе поверил и сделал заявку в Магистрат, что бы я там написал? Прошу прислать мага, что умеет проклятия распознать, а то воняет сильно? Ну и уехал бы я лечебницу для душевнобольных. Так что не глупи, нет там проклятия. А если и есть, нам один черт нечем платить за проверку.",212725,null],[254180,"2026-10-05T09:36:52",20,"*Беатриче невольно подслушивает разговор этих двоих, запивая вином. Любопытно, любопытно...*\n\n- Синьорита Ясмин, мне кажется или это дело по вашей части? *Заговорчески шепчет она наклонившись к ней чуть ближе*\n- Таинственные проклятия, безвозмездная помощь...ну,вы поняли.",254138,null],[254181,"2026-10-05T09:42:43",22,"Ясмин испуганно сглотнула и приложила руку к своей шее.\n\n- К-как-то слишком м-много проклятий в последнее в-время, вам так не к-кажется?\n\nХоть бы не ковен.\n\nА то что?\nНе хочешь конкурентов?\n\n- Н-надо проверить, с-согласна. \n\nЯсмин перешла на шепот.\n\n- Т-то что мы нашли, дело р-рук ночной.. их же с-ситуация звучит, как м-морская.. Остается л-лишь молиться, чтобы еще и з-зеленая не дала о себе з-знать.",212725,null],[254185,"2026-10-05T09:45:24",20,"- Значит карг бывает много? *Удивлённо спрашивает Беатриче. Для нее явно слово карга это как и для многих общее понятие для просто всех таких ведьм*",254181,null],[254186,"2026-10-05T09:47:56",22,"Ясмин кивнула и показала три пальца.\n\n- Ковен. В-высшее зло.\n\nДевушка испуганно оглянулась, проверяя, смотрит ли кто на нее, однако никого, кроме трех пар ненавистных глаз.\n\n- Ковен м-может то, что не подвластно о-одной. Но я не п-понимаю, что им надо, п-просто так к-ковен не собирается. К-карги ненавидят друг друга.",254185,null],[254194,"2026-10-05T09:57:16",20,"*Беатриче глубокомысленно кивает, даже что-то понимая из этого объяснения*\n\n- Ага...значит это что-то вроде встречи противных дальних родственников которые ненавидят друг друга, но вынуждены иногда терпеть друг друга, потому что больше родни они ненавидят всех остальных вокруг.",254186,null],[254203,"2026-10-05T10:14:21",31,"Парень, заслышив ваши слова, встрепенуся и повернулся к вам с робкой надеждой:\n\n- вы разбираетесь в таких вещах? Можете проверить? этот шепот, он пугает...\n\n- не досаждай сиорам, Бродерик. Прошу прощения за моего ученика, он излишне впечатлителен",212725,null],[254232,"2026-10-05T10:56:12",20,"- О, не стоит сеньор. *Беатриче машет рукой*\n- Поверьте, мы достаточно сталкивались с странностями и тайнами этого города за последнее время, чтобы не списывать все на простые выдумки. И признаться честно - вы задели наше любопытство. \n\n- Расскажете подробнее что происходит? Возможно мы даже сможем помочь.",254203,null],[254245,"2026-10-05T11:19:42",31,"Парень, довольны твоим интересом, гачинает говорить:\n\n- Мы с сиором Родриго рабаотем на маяке. Ну, он работает, а я на подхвате. И вот а днях начались какие то странности. Настваник приказал мнее протереть линзу, через которую направляется свет маяка, ну я и ношел протирать. И в какой то моент понял, что динза говорит. Точнее, шепчет. Что то неразборчивое, но мне стало страшно и  убежал к наставнику. Он обругал меня лодырем и идиотом, и когдя вернулся, то уже ниччего не слышал в тот день. А на следющий вечер, заливая масло в фонарь, я снова услышал шепот. А еще через пару дней я стал замечать что в фундаменте башни появились мелкие трещинки, на осровке стало вонять дохлой рыбой. Густой такой запах, но иточника я не нашел, вот... И с тех пор я каждый вечер, как начинает смеркаться, слышу шепот. Не разбираю что он там говорит, но страшно, ужас. А наставник не верит мне",254232,null],[254252,"2026-10-05T11:23:25",20,"- Мда, звучит реально жутковато. Что-то поселилось под маяком? *Беатриче смотрит на спутников, может им что-то из этого знакомо?*\n\n- Что думаете? Я помимо огромного потустороннего мотылька мало что могу представить в такой ситуации.",254245,null],[254253,"2026-10-05T11:25:12",17,"Марко оторвался из собственных мыслей и внутрених самокопаний и поднял глаза от книги мёртвых\n\n— Поможем им. Пока сиор Фелино наводит справки о нашем гастролёре лучше не терять хватку. А если это снова подарочек от ковена, нам обязательно нужно им помешать. Уверен, если срывать их планы раз за разом ведьмы сами на нас выйдут...",212725,null],[254261,"2026-10-05T11:48:08",31,"Бородатый сиор Родриго смотрит на вас с подозрением:\n\n- Сиоры, я не особо привык доверять случайным ьлюдям. Какая вам выгода то? Нам нечем платить вам, да и не уверен я что опасность какая то есть",212725,null],[254266,"2026-10-05T11:56:17",22,"Ясмин посмотрела на сиора Родриго, а ее золотой глаз вспыхнул.\n\n- Когда в последний раз вы помогали тому, кто действительно в этом нуждался? Есть вещи, в которые...\n\nОй, у кого-то тут голосок прорезался\nЗапищала наша крыска\n\nНЕ ЛЕЗЬ!\n\n- Кхм. Мне будет достаточно того, что однажды вы поможете нуждающимся просто по зову сердца. От лишней буханки хлеба да теплой тряпки еще никто не обеднел, а кому-то эта доброта может стать лучом надежды, а возможно и вернёт веру.. в человечность.\n\nЯсмин чуть наклонила голову, пристально смотря на мужчину.",212725,null],[254269,"2026-10-05T11:57:54",22,"Дождавшись его реакции, девушка отвернулась и быстро замотала свою ладонь, вытирая проступившую от собственных когтей кровь. \n\nЯсмин слишком сильно сжала свою руку в кулак, пытаясь обуздать эмоции.",212725,null],[254272,"2026-10-05T12:05:05",31,"Родриго улыбается краем рта:\n\n- ну, так то да. Ну раз вы такие добрые и отзывчивые то кто же я такой, чтобы вам не позволить себе помочь. У нас с Бродериком еще есть дела, нужно кое что закупить для маяка, но ближе к сумеркам ждём вас на нашем островке. Он недалеко от порта, возьмете там лодку из тез что помечены буквой М - это Маяк значит, и плывите к нам. Все одно эта хрень по словам Бродермув только в темноте шепчет. Ладно, пошли, парень, у нас еще дела есть\n\nСмотритель маяка с учеником покидают таверну. А у вас до посещения острова с маяком есть еще несколько часов",212725,null],[254283,"2026-10-05T12:11:45",17,"— Новое дело, новая зацепка. Кажется, что так или иначе всё в городе связано. И Карги и Сангвини и Дон Треви",212725,null],[254284,"2026-10-05T12:12:47",17,"— Беатриче... Ввиду новых подробностей о вашем возможном происхождении, сиора, не хотите поговорить с семьёй? Мы можем подождать вас, до вечера еще порядочно времени",212725,null],[254289,"2026-10-05T12:25:07",20,"- Как раз думала о том, чтобы покинуть вас на время до сумерек ради этого *Кивает Беатриче, вставая*\n- Благодарю за понимание, Синьор",254284,null],[254290,"2026-10-05T12:26:02",17,"— Если потребуется помощь или компания на вечер мы будем неподалёку, сиора.",212725,null],[254293,"2026-10-05T12:26:37",17,"/ @QURTZZ @lady_godzilla я думаю логично сцену встречи с матерью дальше дать Беатриче, как думаете?",212725,null],[254297,"2026-10-05T12:31:01",31,"да легко вообще, я под нее время и оставлял/",254293,null],[254298,"2026-10-05T12:31:56",20,"/тогда Беатриче спешит домой",212725,null],[254315,"2026-10-05T12:41:19",17,"Марко кивнул легонько в спину девушке и достал записную книжку\n\n— И так, Ясмин, наш анализ продолжается.\n\nОн поднял глаза от книги и посмотрел на девушку\n\n— И я завёл еще одного \"пациента\" которого рассматриваю и записываю его поведение\n\n— Себя...",212725,null],[254317,"2026-10-05T12:42:05",20,"/удивительно что только сейчас",254315,null],[254318,"2026-10-05T12:42:16",31,"Беатриче, проговаривая про себя вопросы, что следует задать матери, покинула таверну и отправилась в родной дом. Она знала что в это время дома будет только мать, отец со старшим братом в лавке, сестра-погодка Беатриче, та еще вертихвостка наверняка убежала по своим амурным делам, а младший брат страдал от скуки в школе.\n\nНебольшой двухэтажный домик в самом центре Старого города мог похвастаться семейным гербом над воротами, прекрасным винным погребом и историей. Хоть нынче семья Висконти и не была на первых ролях в городской политике, но оставалась одним из старейших и уважаемых семейств, одним из основателей Вальдории более 300 лет назад.\n\nБеатриче нашла свою мать, на кухне. Время близилось к обеду, скоро явится отец и братья, и сиора Мария Висконти готовила, а точнее священнодейстовала над соусом. Заметив Беатриче, она отложила деревянную ложку и подбежала к дочери:\n\n- Милая, наконец то ты дома. Где же ты была? Три дня пропадала, и не появилась на похоронах?",254289,null],[254328,"2026-10-05T12:49:08",20,"- Madre... *Беатриче подходит ближе, утыкаясь в плечо матери лбом, зажмурившись. Дома, наконец-то дома...*\n- Я была на похоронах, просто...не смогла подойти ближе... Пока не найду этого ублюдка не думаю что смогу без вины подойти к могиле Кристины.\n\n*Она стоит так какое-то время, успокаиваясь, как ребенок ищущий утешения в объятиях матери. Что в целом так и было. После снова поднимает лицо.*\n\n- Я хотела спросить кое-что важное, мadre. В детстве ты сказала, что придет время и ты расскажешь мне почему я так отличаюсь от вас. Это время пришло.\n\n*Она смотрит на мать с решимостью*\n\n- Расскажи мне про Эдриана Сангвини. Я должна знать.",254318,null],[254359,"2026-10-05T13:17:58",31,"- ох, откуда...\n\nМария выдыхает, она не ждала этого имени. Молча открыв шкаф и достав оттуда бутылку вина, она плеснула его в бокал, слишком щедро, даже развлив жидкость. Тебе она не предложила, просто залпом выпила алкоголь. После чего сел а стол и жестом пригласила и тебя\n\n- я так надеялась, что ты не услышишь его имя. Хотя и глупо это, лицо то у вас одно. Прежде всего ты должна знать - нет, он не твой отец. Твоего зовут Джованни Висконти, и других мужчин у меня не было. Что до Эдриана... Он появился в нашей жизни чуть больше 20 лет назад. Тогда мы были молоды, у нас был только малыш Федерико и совсем не было денег. \n\nЭдриан пришел к нам, долго рассыпался в комплиментах, он чертовски обаятелен, когда хочет того. Мы не знали тогда, кто он есть, ну Сангвини и Сангвини, их немало, большая семья. Он предложил нам идею нового купажа, сам он назвал его \"Серебряная кровь\". Ты наверное не знаешь, но у Висконти была небольшая серебряная шахта, она давно истощилась. Так вот Эдриан предложил нам превратить ее в виноградник, чтобы, как он сказал, \"вино обрело благородный блеск\". Твой отец ухватился за эту идею, он ведь знает что богачи покупают даже не вкус, а историю. И мы согласились.\n\nДва года ушло на вызревание и купажирование. Вино и впрямь обрело серебряный блеск. И когда Эдриан пришел к нам снимать пробу, он оказался в восторге. Он говорил что это вино горит на его губах. А потом его глаза потемнели. Это было очень страшно...\n\nМария замирает, вспоминая\n\n- тогда он взрезал свою ладонь и кровь его, цветом т блеском неотличимая от вина, брызнула в бокал. Он приказал мне и Джованни выпить вино с его кровью. И мы не смогли отказать его воле. И его жутким клыкам. Мы выпили. Это было так мерзко. А он заявил, что дарует нам свою милость в обмен на мастерство Джованни и оставляет нам жизнь. Он ушел, а мы рыдали от ужаса, обнявшись вот тут, на этой кухне. А через три дня я поняла, что была уже беременна тобой в этот момент...\n\nЭдриан забрал весь запас вина тогда и не появлялся в нашей жизни более. Но когда родилась ты, и я увидела что твое лицо было копией его... Тогда Джованни взял меч и ушел в дом Сангвини. Я думала, он не вернется. Но его привезли ночью люди, или кто они там, что служили Эдриану. Он был изрезан и с тех пор подвижность его левой руки так и не восстановилась. Не знаю почему Эдриан не убил его, может потому что обещал в тот день, когда поил нас своей кровью. А может просто решил что это забавно.\n\nЧерез год примерно, ты уже подросла и начала ходить, у тебя выросли первые зубы, это были клыки, мы узнали что Эдриан больше нет в городе. Его семья изгнала его из Вальдории. Мы выдохнули. И решили, что тебе лучше не знать о нем. Хотя я и понимала, что у тебя будут вопросы, но трусливо решила, что лучше пододать. И похоже, зря. Я боюсь, чо именно Эдриан убил Кристину. У вас одно лицо, и она наверное просто перепутала вас во тьме и пригласила войти. а он...",212725,null],[254368,"2026-10-05T13:20:50",31,"Мария рыдает",212725,null],[254380,"2026-10-05T13:34:02",20,"*Беатриче бросается и обнимает мать, прижимая ее к себе в гости попытке утешить*\n\n- Мама...я не виню вас ни в чем, никогда не буду. То, что я не связана с этим монстром прямым кровным родством лучшая новость за сегодня, пусть тебе и пришлось рассказать мне горькую правду.\n\n- Во мне течет в первую очередь ваша с отцом кровь. Кровь Висконти - и это для меня самое главное. Моё существование не пятнает вашу честь,  я всё ещё могу нести его с гордостью как ваша дочь. Это все, на что я надеялась, спрашивая об этом *искренне говорит они, успокаивая мать*\n\n- В ту ночь...вашей вины нет. И если ты когда нибудь сможем, то смотри на меня и мое тронутое кровью ночи существование не как на проклятие, а как на клинок отмщения этому ублюдку. Потому что я клянусь что настигну его и заставлю заплатить за все, что он сделал с вами и Кристиной.",254368,null],[254383,"2026-10-05T13:35:40",31,"- я боюсь, что он пришел за тобой...",212725,null],[254384,"2026-10-05T13:36:28",31,"//Блин, я то какого хрена плачу сейчас?)//",212725,null],[254385,"2026-10-05T13:37:33",20,"/тоже блин, ещё сделал ее семью похожей на мою по составу\n/Вот и сиди теперь переживай как за реальных(",254384,null],[254389,"2026-10-05T13:39:29",20,"- Отлично, потому что это значит что мне самой не придётся искать его *она сжимает ее ладони в своих, пытаясь передать ту уверенность, что горит в сердце самой Беатриче*\n\n- Мама... возможно моя кровь это тот дар, что создан бросить ему вызов и покончить с этим. Я клянусь что стану сильнее ради вас. Я защищу тебя, отца, сестру, братьев...Я справлюсь.",254383,null],[254390,"2026-10-05T13:41:18",31,"- я знаю милая, я знаю. Дождись отца, не убегай. Ему тоже будет что сказать",254389,null],[254392,"2026-10-05T13:43:27",20,"*Она кивает, оставаясь сидеть рядом с матерью. Правда успокоила терзавшие ее душу сомнения. И даже ещё больше разожгла решимость*",254390,null],[254393,"2026-10-05T13:43:57",31,"Чуть позже пропишу сцену с отцом, пока занят/",212725,null],[254489,"2026-10-05T15:25:07",31,"Мать и дочь сидели в тишине, просто наслаждаясь покоем дома и теплотой близкого человека рядом. Вы и не заметили, как вошли отец, Джованни и Федерико, старший брат Беатриче. Они пришли на обед домой, как и было заведено в вашей семье.\n\nОтец, увидев вас вдвоем, заплаканых, но улыбающихся, кажется, что то понял и обратился к тебе\n\n- Здравствуй, малышка. Мы волновались.\n\nПривычные слова отца, ты их слышала лет с 13, когда начала пропадать на улицах Вальдории без присмотра. Тебя затопила волна нежности. И немного страха. Ты никогда не думала о том, почему у отца почти не работает левая рука, папа всегда был сильным и надёжным. В теперь и он, и мама, и Федерико казались такими хрупкими. Ты пообещала себе, что до них мерзкий кровосос не доберётся. Никогда.\n\nОтец продолжил:\n\n- Вижу, мать поделилась с тобой историей. Давно пора. Я тоже кое чем поделюсь. Пойдем в кабинет. Федерико, ты тоже иди.\n\nВ кабинете отца вы с братом часто играли в прятки в детстве и ты была уверена, что знаешь его в совершенстве. Ты ошиблась. Отец вскрыл тайник под столом и достал оттуда старый кожаный футляр.\n\n- открой, Беатриче\n\nТы открываешь футляр и видишь там рапиру. Но она какая то странная, словно и не металлическая вовсе.\n\n- это Шепот Зари. Наследие нашего рода с тех пор как мы были не виноделами, а воинами. Он передаётся в семье к первенцу и, если честно, давно не пускался в ход. Я взял его в ту ночь, когда пошел к Сангвини. Смог его ранить. Но не убить. Мне хватало сил, но не хватало скорости. И у Федерико не хватит. А у тебя хватит. Только у тебя и хватит. Возьми его. Федерико, ты не против?\n\nТвой обычно смешливый и саркастичный братец балагур, в этот момент выглядит очень взрослым. Ты и не думала что он так похож на отца. Разве что шрамов нет и седых волос.\n\n- нет отец, я не против. Пусть оружием пользуется тот, кто умеет это делать.",254392,null],[254491,"2026-10-05T15:25:53",17,"/ КОоооооооол!",212725,null],[254492,"2026-10-05T15:26:15",31,"@PaIIasCat ты получаешь новое оружие, фамильный меч Висконти. Он словно судбой предназначен быть твоим и упокоить мерзкую тварь. Будь достойна",212725,null],[254518,"2026-10-05T15:36:35",22,"// @dunchev напомни, а какое зло нам эта милая девочка Биатриче из хорошей семьи сделала? Что мы таскаем ее по злачным местам и заставляем делать всякое...",212725,null],[254520,"2026-10-05T15:37:29",31,"Это все махинации кошака Феллино. Что то он там понапророчил/",254518,null],[254524,"2026-10-05T15:38:55",20,"*Беатриче теряется к рапире с благоговении. Оружие рода...могла ли она когда либо представить, что будет достойна такой вещи? Нет, в ее глазах она всё ещё недостойна - это не награда, а обещание, которое ей только предстоит исполнить*\n\n- Grazie per l'onore, padre. *Тихо говорит она, впервые поднимая клинок и ощущая его вес в своей руке. Вес во всех смыслах*\n\n- Клянусь, что закончу то, что ты начал в ту ночь. Он заплати за то, что посмел принести горе в дом Висконти.",254489,null],[254527,"2026-10-05T15:39:58",31,"- не сомневаюсь. Но помни что ты не обязана все делать одна. Семья всегда придёт на помощь, не стесняйся попросить",212725,null],[254528,"2026-10-05T15:42:53",20,"*Она бережно притягивает ножны с рапирой на пояс. А потом просто молча обнимает отца и брата*\n\n*Она знает, что они будут готовы защитить ее даже ценой собственных жизней. Но не хочет, чтобы они хоть как-то подвергались опасности. Нет,  она обязательно их защитит. Теперь ее очередь.*\n\n*Ну а знаю что ее будут всегда ждать дома...она и так никогда не будет одна*",254527,null],[254529,"2026-10-05T15:43:22",20,"/все, я всплакнула)",212725,null],[254533,"2026-10-05T15:45:33",31,"Такая же фигня/",254529,null],[254534,"2026-10-05T15:45:45",31,"Что то я слишком сентиментален стал/",212725,null],[254581,"2026-10-05T16:04:16",31,"Оставим Беатриче до вечера в кругу семьи. У остальных заявок нет?/",212725,null],[254606,"2026-10-05T16:13:43",22,"- Как н-на счёт того, чтобы прогуляться по м-местным лавкам, пока Беатриче занята?\n\n//Ясмин предлагает заняться сбором слухов по маяку",254284,null],[254622,"2026-10-05T16:17:18",17,"Марко кивает. \n\n— Разумно. \n\nОн встаёт и касается плеча девушки легонько и медленно, чтобы не напугать, после того случая..\n\n— Вы альтруист, Ясмин и этого уже не исправить...\n\nРука марко наполняется теплом бледным светом, а девушка чувствует прилив решимости\n\n/Заклинание героин героизм. Чтобы не заикалась",254606,null],[254623,"2026-10-05T16:17:34",17,"Чуть отстронять Марко забирает свой плащ и тут его скручивает приступ кашля",212725,null],[254624,"2026-10-05T16:17:40",17,"/r d10 Минус максимальное хп",212725,null],[254629,"2026-10-05T16:18:04",17,"— Я... Я готов идти.\n\nМашет он рукой после приступа",212725,null],[254668,"2026-10-05T16:27:48",20,"/вам не за слухами, вам лёгкие прочищать надо идти, а то Марко не доживёт до следующей сюжетной арки (",212725,null],[254670,"2026-10-05T16:27:52",22,"Ясмин уверенно повела Марко в квартал, откуда тянулся горький травяной запах.\n\n- С..Спасибо. Тогда начнем с табачной.",212725,null],[254674,"2026-10-05T16:28:15",22,"// а я как раз хочу описать, как мы слухи собираем в кальянной",254668,null],[254675,"2026-10-05T16:28:15",31,"Правильно, Марко кашляет недостаточно/",254670,null],[254677,"2026-10-05T16:28:31",20,"/хитро",254674,null],[254679,"2026-10-05T16:28:54",31,"Описывайте свою кальянную, я включусь если нужно будет с НПС потрещать/",212725,null],[254680,"2026-10-05T16:29:23",17,"— И правда, сигареты кончаются\n\nМарко закурил",254670,null],[254694,"2026-10-05T16:31:37",31,"Помрешь, надо будет тебе перса на замену делать. Два варианта, либо станешь возрожденным, либо расскажи как мне, где мать Лючии?) моё предположение - после смерти дочери попала в дурку)/",254680,null],[254705,"2026-10-05T16:33:13",17,"/ Всему своё время. Я еще не мёртв",254694,null],[254706,"2026-10-05T16:33:31",20,"/Беатриче может тебя покусать - тоже дышать не надо будет :3",254694,null],[254713,"2026-10-05T16:34:01",31,"Дампир вроде не может обращать людей в нежить)/",254706,null],[254717,"2026-10-05T16:34:55",17,"/ Романтическая линия с Беатриче еще не разблокирована, посмотрим какие события произойдут далее",254706,null],[254783,"2026-10-05T16:53:04",31,"- а, и до вас дошли слухи? Это пацан, что там работает, болтает о шепотках от линзы. Как по мне, дурь. Может курит чего. Но у меня не покупал, точно вам говорю",254764,null],[254848,"2026-10-05T17:04:45",22,"-- Да кто ж знает. Интересно все равно, вдруг...\n\nЯсмин приблизилась.\n\n- Скрывают что...",254783,null],[254855,"2026-10-05T17:05:51",31,"Продавец наклоняется к Ясмин и понижая голос, говорит:\n\n- а вообще, если вам нужно что то в темноте разглядеть, то не маяку нужно идти. Лучше носить свой маяк с собой. Бывает полезно... Ксть тут у меня одна штука, чертеж, я сам в них не очень понимаю, но тот кто мне заложил, говорил что эта штука может огнем плеваться, что ручной дракон",212725,null],[254904,"2026-10-05T17:16:05",31,"- готов вам отдать за сущие копейки, 100 золотых монет",212725,null],[254915,"2026-10-05T17:18:08",22,"-- О... (возбужденно)\n\nЯсмин уже потянула руки.\n\n\nДА КУДА ТЫ БЕЗ ТОРГОВЛИ, ТУПИЦА\n\n- Ооо... (наигранно растроенно).",254904,null],[254923,"2026-10-05T17:18:53",22,"- Это же так дорого, может договоримся о скидке? Все же я у вас.. \n\nЯсмин покосилась на Марко и тише добавила\n\n- частый гость.",212725,null],[254926,"2026-10-05T17:19:13",31,"Давай убеждёние/",254923,null],[254928,"2026-10-05T17:19:14",22,"/r +3 Убеждение",254923,null],[254934,"2026-10-05T17:20:02",22,"Ясмин пихает локтем в бок Марко, от чего бедный мужчина заходится в кашле.",212725,null],[254936,"2026-10-05T17:20:12",22,"- Вы только посмотрите, как ему плохо!",212725,null],[254937,"2026-10-05T17:20:33",31,"- ну только из за ваших прекрасных глаз и жалости к вашему спутнику я готов отдать чертеж за 90, но только если вы пообщевете потратить 10 на его лекарства",212725,null],[254941,"2026-10-05T17:20:44",22,"- О горе нам, горе! Скидка бы очень помогла, ведь на лекарства еще так много придётся потратить.",212725,null],[254942,"2026-10-05T17:21:04",22,"//помощь от Марко кидать не надо?",212725,null],[254944,"2026-10-05T17:21:24",31,"Можно, если он убеждение выслке кинет или выступление/",212725,null],[254946,"2026-10-05T17:21:29",31,"Закашляется картинно/",212725,null],[254947,"2026-10-05T17:21:40",22,"//я могу его ткнуть побольнее",212725,null],[254954,"2026-10-05T17:22:51",31,"Тогда выступление будет с преимуществом/",254947,null],[254955,"2026-10-05T17:23:01",31,"Но он получит 1д4 урона/",212725,null],[254960,"2026-10-05T17:24:04",22,"/жаль конечно, но таков его путь, потом по спинке поглажу(подлечу)",254955,null],[254965,"2026-10-05T17:25:07",31,"@dunchev иди, тебя будут бить ради скидки/",212725,null],[254987,"2026-10-05T17:28:24",17,"— Сиора.. Что... КХА КХА\n\nМарко наиграно кивает",212725,null],[254994,"2026-10-05T17:29:15",31,"Выступление или обман кинь/",254987,null],[254995,"2026-10-05T17:29:21",22,"/r d4 с преимуществом",254987,null],[254997,"2026-10-05T17:29:43",31,"/roll d4 урон по Марко от удара локтес Ясмин",212725,null],[255003,"2026-10-05T17:31:02",17,"/r +d20-1+3 От ясмин",254994,null],[255008,"2026-10-05T17:31:49",9,"//Актёры погорелого театра",212725,null],[255015,"2026-10-05T17:32:19",31,"- хмм, кажется ваш кашель не так и силён. 90 последняя цена",212725,null],[255029,"2026-10-05T17:35:20",22,"//можно еще раз пнуть Марко?\n\nЛадно ладно я любя \u003c3",212725,null],[255031,"2026-10-05T17:35:51",22,"Ясмин передала деньги.\n\n100 зол\nЧертеж\nТравы для лечения на 2 недели \nПоходный кальян",212725,null],[255056,"2026-10-05T17:38:51",31,"Развернув чертёж ты поняла тл ко что тут изображена какая то трубка, банка для алхимического огня, какие тт мелкие проволчуи и куча формул. Все это введо тебя в состояние дешклй паники. Заткнулись даже тетушки, из жизненного опыта не хватило чтобы что понять и съязвить",255031,null],[255070,"2026-10-05T17:41:02",22,"В глазах Ясмин буквально стало разгораться пламя. \n\nВыглядит бобически!",212725,null],[255074,"2026-10-05T17:41:26",22,"Ясмин свернула чертеж и спрятала в сумку, так Марко, теперь пойдём лечиться.",212725,null],[255088,"2026-10-05T17:44:22",17,"Марко пожал плечами\n\n— Мне пачку Вальдорских красных",212725,null],[255089,"2026-10-05T17:44:37",17,"Расплатившись за сигареты вышел за Ясмин",212725,null],[255092,"2026-10-05T17:44:46",17,"— Зачем тебе этот чертёж?",212725,null],[255096,"2026-10-05T17:45:26",31,"Продавец внутри:\n\n- наконец то слил это дерьмо...",212725,null],[255114,"2026-10-05T17:48:52",31,"Я когда студентом был, лет в 18-19, со мной снимал хату бывший одноклассник, лютель кальяна. Вот он примерно также его описывал, а я видел только пару столбом в кухне и чихал от этого/",212725,null],[255119,"2026-10-05T17:50:27",22,"// у меня была одногрупница еврейка. Лучшая кальянщица потока👌",255114,null],[255165,"2026-10-05T17:56:42",17,"/\"Лечимся\"",212725,null],[255171,"2026-10-05T17:57:54",22,"- Выглядит очень... Амбициозно! Представляешь, что наш гоблин сможет построить? Если он свое создание сделал буквально их одних клещей, то что получится, если ему удастся это?! \n\nКажется сжигание людей заживо на нее хорошо влияет.\nУ нас определённо был неверный подход к ее воспитанию.",255092,null],[255173,"2026-10-05T17:58:20",22,"//Яс доктор, ей виднее 👌",255165,null],[255188,"2026-10-05T18:01:00",17,"— За то, что сохранили ему жизнь и свободу он и впрямь должен нам. Как так вышло, что гоблин такой головастый?",255171,null],[255190,"2026-10-05T18:01:02",31,"Главное - верить что течение помогает/",212725,null],[255222,"2026-10-05T18:17:22",17,"Марко удобно уселся и на минуту забыл о той ситуации в которой они оказались. О гастролёре, о болезни, о вампирских кланах, о стрессе и ранах полученных ранее\n\n— Знаешь... Здесь спокойно. Я давно не был в таком месте, давно просто не отдыхал. \n\nМарко сделал глубокую затяжку дымом кальяна с травами\n\nВкус был мягкий, пряный, обволакивающий и запах был крайне приятный. \n\n— Хотелось бы так отдыхать чаще.\n\nДобавил он тише в конце",255108,null],[255272,"2026-10-05T18:34:40",22,"- Если отдыхать часто, то это станет обыденностью и перестанет приносить удовлетворение.\n\nЯсмин вытянулась на подушках и посмотрела в потолок.\n\nГоловастый гоблин. Звучит как шутка! Ихихи-хи-хи\n\n- Умный гоблин. Это даже звучит нелепо. Однако.. помнишь ту крысу? Не думаю, что эксперименты некоторых личностей останавливаются лишь на крысах. Вспомни, как тут относятся к отребью. Не удивлюсь, если и над ним проводили нечто подобное. \n\nЯмин нахмурилась и села. Она взяла в руку чашку, та задрожала и девушка перехватила ее другой рукой, чтобы унять тремор. \n\n- Он умное создание, как ты отметил. Вряд-ли он бы стал болтать о том, откуда у него эти.. знания.\n\nДевушка сделала глубокий глоток янтарной жидкости и прикрыла глаза.",212725,null],[255295,"2026-10-05T18:42:33",17,"Закрыв глаза следователь прокрутил вспышками сцены из недавних событий \n\n— Я вспоминаю рой крыс который превратили в чудовищного монстра. а также одну из них научили телепатическим способностям.\n\nМарко нахмурился \n\n— Может быть и над гоблином кто-то постарался. Вдруг это, исскуственно усиленный интеллект.",212725,null],[255473,"2026-10-05T19:48:58",17,"Марко ещё раз затянулся, выдул вверх дым и некоторое время молча смотрел как он улетучивается вверх\n\n— Забавно. Запах немного напоминает курильницы которые используют при погребальных обрядах\n\nОн чуть повернул голову к Ясмин\n\n— Иногда задумываюсь почему именно Анубис?\nЕго часто называют богом смерти. Это не совсем верно. Смерть ему не принадлежала. Он следил за тем, что происходит после неё\n\n— Подготовить тело. Проводить душу. Взвесить сердце. Убедиться что мёртвый оказался там, где ему положено быть\n\nСледователь сделал ещё одну затяжку \n\n— Мне это всегда казалось... правильным. Даже смерть должна соблюдать порядок\nНо одна проблема все же имеется\n\nМарко посмотрел на тлеющие угли\n\n— Анубис мёртв. Я проводил его обряд ожидая в лучшем случае найти старую молитву или очередную бесполезную легенду. Вместо этого моя тень стала похожа на шакала\n\nМарко едва заметно усмехнулся\n\n— А потом что-то ответило. Вдруг это не Аннубис? Другой темный бог, кто ещё жив. Узурпировал его вотчину...\n\nМарко постучал пальцем по трубке кальяна\n\n— Но дарованная волшебная сила у меня есть. Значит что-то от него осталось\n\nМарко заглянул в мутную чашу кальяна \n\n— Возможно этого смертному должно быть достаточно",255327,null],[255869,"2026-10-05T22:25:34",22,"- Как это возможно? Смерть, которая мертва. Завабно.\n\nПсина сдохла\nБудка осталась\n\n- Интересно...\n\nБесхозная сила?\nТакое бывает?\nЯ хочу ее!\n__И я! Дай!\nДай!\n\nДАЙ!!\n\n- те... пожалуйста.. мне нужно немного прочистить разум.. Я.. не железная. \n\nЯсмин делает глубокую затяжку и даже не закашливается. Чуть задержавшись, она выпускает дым носом и отдаёт трубку Марко. В голове стало ощутимо тише.\n\n- Разве можно украсть силу бога? Это так.. амбициозно. Хотелось бы узнать, что за существо способно на такое!\n\nЯсмин была взбудоражена этой мыслью. Ее взгляд бегал из стороны в сторону, а кисти то сжимались, то разжимались.\n\nДевушка сделала глубокий вздох и стала нервно теребить волосы.\n\n- И-извините,  не п-понимаю, что на меня н-нашло.",212725,null],[255904,"2026-10-05T22:42:37",17,"/ Что ж ты такая прикольная и нервозная... Надо пост прмдумать",212725,null],[255908,"2026-10-05T22:44:09",22,"// Она шизоид! Такие не должны нравится, остановись, подумай!",255904,null],[255924,"2026-10-05T22:48:46",20,"/поздно, курс на романтическую ветку уже взят...",255908,null],[255934,"2026-10-05T22:49:55",22,"/да не, не опошляй, Коля не такой. Наверное",255924,null],[255982,"2026-10-05T23:04:15",17,"Марко несколько секунд смотрел на её дрожащие пальцы, а потом спокойно забрал руку Ясмин от волос и остановил своей. Взяв ладонь в ладонь \n\n— Не извиняйся\n\nБольшим пальцем он медленно провёл по её костяшкам, скорее успокаивая, снимая дрлж, чем лаская\n\n— Огонь это наглядный пример силы, Ясмин. Огонь можно украсть. Поднести свечу к чужому пламени и унести его с собой. Огонь не спросит кто ты. Ему всё равно в чьих руках гореть\n\nМарко посмотрел на неё наклонив голову на бок. Очки поймали блик огня небольших резных фонариков на стенах\n\n— С силой Анубиса не так. Иногда она приходит. Иногда нет. Я задаю вопрос, отвечает а иногда молчит. Она будто... выбирает когда проявится\n\nОн чуть сжал её ладонь\n\n— Поэтому меня терзают вопросы, кто сумел украсть силу мёртвого бога?\n\n— почему если он украл ее, ведёт себя как мертвый бог, использует его облик, его символы?\n\nМарко перевёл взгляд на их сцепленные руки\n\n— Если Анубис действительно мёртв... тогда кто и главное зачем отвечает мне?\n\n— Такие вот у меня загадки \n\nОн медленно отпускает ее руку в конце улыбаясь краем губ",212725,null],[256063,"2026-10-05T23:35:32",17,"— Да, может быть Аннубис был лишь проводником этой силы, он погиб, значит был слаб и она нашла себе другого. А может он и не погиб вовсе. Как это выяснить? Идей нет никаких... \n\nМарко ещё раз глубоко затянулся кальянные дымом и выдул его перед собой. Его глаза блеснули золотым песком сквозь развивающуюся дымку \n\n— Но для меня не это главная загадка миросдания. Я говорил с мертвыми, задавал сотнями погибших и находящимся в загробном мире один вопрос. \n\nОн опустил взгляд. Сгорбившись положил руки на колени и тяжело вздохнул\n\n— Как там моя дочь. Как с ней поговорить. Я.. я... \n\nЕго голос задрожал\n\n— Хочу сказать ей, как сильно люблю её. Что помню о ней. И никогда\n\nГолос сломался\n\n— не забуду...\n\nДолгая пауза. Кажется тянется вечность \n\n— Но её там нет. Она не попала в загробный мир. Я держал ее мертвое тело на руках. Но душа ее исчезла. И никто не знает где она. \n\nМарко выверенным движением достает из внутреннего кармана жилетки пробирку с мелкой черной землёй. \n\n— У нее под ногтями была эта земля, больше ничего. За пять лет... \n\nЕщё более тяжёлый вздох\n\n— Я не сдамся, Ясмин... Есть новая зацепка. Недавно два трупа мясников, такой же песок. Неро сказал были ещё в этом году и в прошлых. Количество жертв растет. И я найду кто стоит за этим... \n\nЕго собственные руки задрожали\n\nОн откинулся в конце на спинку мягкого диванчика и приложил руки к лицу. Он не плакал, слез не осталось давно.",212725,null],[256093,"2026-10-06T00:02:47",17,"Марко не сразу убрал руки от лица. Потом посмотрел на Ясмин\n\n— Спасибо, правда, я благодарен \n\nОн снова наклонил голову чуть на бок\n\n— И за лечение. За это все...\n\nОн чуть махнул рукой в на кальян и окружение\n\n— И за то что выслушала...\n\nСам не понял как засмотрелся в глаза Ясмин. Злой глаз, и обычный казались ему парой озёр. Потом наконец моргнул и сам осознал что смотрел дольше обычного. Чуть встряхнул головой \n\n— Я давно никому этого не рассказывал. И почему-то рад, что рассказал именно тебе\n\n— Мне как то... Легче стало.",256072,null],[256108,"2026-10-06T00:08:46",22,"Ясмин кивнула. \n\n- Тогда пойдем, нужно встретить Беатриче.",212725,null],[256110,"2026-10-06T00:10:08",17,"— Пойдём.",256108,null],[257404,"2026-10-06T06:45:42",31,"@dunchev @lady_godzilla @PaIIasCat \n\nХорошенько отдохнув до вечера, вы таки вспоминаете, что хотели посетить маяк и поискать следы проклятия. В назначенный час вы втроем собрались в районе порта около небольшого лодочного причала с лодками, принадлежавшими маяку.\n\n@lady_godzilla вы с Марко по дороге заглянули к гоблину и отдали ему чертеж, от чего тот пришел в крайнее возбуждение, что то восхищенно пропищал и закопался в расчеты, веля вам зайти завтра, чтобы он дал вам список необходимых ему запчастей для создания огнемета",212725,null],[257633,"2026-10-06T10:21:39",22,"/мы наверное завязку от @PaIIasCat ждем",212725,null],[257635,"2026-10-06T10:22:36",31,"не ильно торопитесь, я сегодня прокрастинирую как тварь. пытаюсь себя заставить начать рабоать уже ама полтора/",212725,null],[257641,"2026-10-06T10:26:39",20,"*Беатриче ждала спутников, сидя на карнизе какого-то здания. Завидев Марко и Ясмин она махнула им рукой, спрыгивая на землю и спеша к ним. На ее лице приветственная улыбка, да и в целом она выглядит намного расслабленной чем утром. Похоже разговор с семьёй сильно помог ей*\n\n- Синьор Марко, Синьорита Ясмин. Выглядите отдохнувшим. *Она хитро переводит взгляд с одного на другого. Кажется Ясмин всё-таки воплотила свой план с этой, как ее...'ингаляцией'*\n\n- Ну что, готовы поохотится на То-Что-Живет-Под-Маяком?",257404,null],[257646,"2026-10-06T10:35:14",17,"— Нетерпиться столкнуться с мистическим и потусторонним? Понимаю, эта работа затягивает. Согласен полностью.",212725,null],[257647,"2026-10-06T10:36:38",22,"- Как м-мама?",257641,null],[257648,"2026-10-06T10:41:40",20,"- Она... справилась, хотя начать говорить ей было тяжело *Беатриче слегка улыбается, поправляя эфес рапиры*\n\n- Она ведь Висконти, какой-то вампирский ублюдок не сломит ее дух. Да и рядом с ней отец с братьями и сестра. \n\n*Она немного задумывается*\n\n- А вообще вы в праве знать то, что мне рассказали - это ведь связано с нашим делом, да и я вам вполне доверяю.",257647,null],[257649,"2026-10-06T10:53:10",20,"- Насчёт крови - этот bastardo действительно не мой отец и никак не запятнал в этом плане честь Висконти. Однако раньше он вел одно дело с мой семьёй - предложил выращивать виноград на земле, где раньше добывали серебро - думаю вы и сами поняли почему. После того как он забрал партию вина, получившуюся из этого винограда, то заставил родителей винить это вино, смешанное с его кровью. Назвал это своей 'милостью' *Беатриче огрызается на этом слове, вспыхнув на секунду яростью за пережитое родителями*\n- Похоже та кровь и повлияла на то, что я родилась такой.\n\n- О моем существование он пока не знает, так как Энрико выгнал его из города почти сразу после этого события. Но это не надолго *рука на эфесе сжимается*\n- Потому что вопрос лишь в том, кто кого первее найдет - он меня или мой клинок его сердце.",212725,null],[257657,"2026-10-06T11:10:02",22,"Ямин приложила руки к сердцу.\n\n- Это очень.. очень жестокое злодеяние! \n\nГубы девушки чуть дрогнули и она продолжила \n\n- Мне очень жаль, что вы так.. пострадали из-за этого и.. И одновременно мне очень радостно, п-простите, но действительно радостно осознавать, что ведьмы не прикладывали к этому свои руки.\n\nЩеки Ясмин вспыхнули и она спрятала лицо в ладонях.\n\n- Прошу простите мне мой эгоизм, он т-так неуместен! Маяк, да, давайте н-направимя туда.\n\nДевушка опустила взгляд вниз и быстро зашагала вперед.\n\nСмотри, тот шакаленок еще живой\nНе добили его твои травки курильные\n\nПотом она резко остановилась, будто что-то вспомнила и обернулась к Марко.\n\n- Ваше горло, как оно?",212725,null],[257658,"2026-10-06T11:10:37",22,"//я совсем вчера забыла прописать Использование Малого восстановления. Можем зачесть, пожалуйста?",212725,null],[257659,"2026-10-06T11:10:52",31,"Да, конечно/",257658,null],[257660,"2026-10-06T11:14:20",31,"Я вам в целом могу засчитать долгий отдых, вы весь день чиллили/",212725,null],[257672,"2026-10-06T12:05:30",31,"Ладно, поехали на маяк//",212725,null],[257676,"2026-10-06T12:09:29",31,"Беатриче, ожидая товарищей, уже успела найти лодку с буквой М. Погрузившись в нее и налагая на весла, вы отправились к каменистому островку, на котором громоздился маяк.\n\nМоре сегодня было беспокойно. Не шторм еще, но до него недолго, ветер уже становился резким, порывистым. Свет на маяке уже горел, но было в нем что то странное. Стоит приглядется.\n\nВосприятие бросьте",212725,null],[257677,"2026-10-06T12:12:51",17,"/r +d20+5+d4 Марко глазами ворона осматривается с высоты птичьего полёта",212725,null],[257679,"2026-10-06T12:15:24",31,"Ворон передает тебе, что за горизонтом идет довольно большой галеон, он должен прибыть в порт примерно через час. Но похоже маяк ведет его не в порт, а куда то восточнее. Ворон видит там рифы. Если маяк не изменит направление света, то галеон напорется на рифы и может потонуть",212725,null],[257680,"2026-10-06T12:22:35",17,"— Маяк ведёт корабль на рифы, у нас всего час!\n\nМарко хватает весло и налегает на вёсла",212725,null],[257682,"2026-10-06T12:25:19",20,"*Беатриче налегает на весла, помогая Марко*\n\n- Сеньор, может вы сможете послать ворога предупредить их заранее?!",212725,null],[257684,"2026-10-06T12:26:28",31,"Усилия Марко с веслом ускорили ваше передвижение, и через 15 минут вы добрались до маяка.\n\n45 минут до кораблекрушения\n\nВыскочив из лодки, и подбежав к двери маяка, вы увидели, что его уже заливает высокими волнами воды, похоже, на ером этаже вас ждет немало воды",212725,null],[257686,"2026-10-06T12:27:07",31,"Дверь заперта",212725,null],[257687,"2026-10-06T12:28:46",20,"/есть окна?",212725,null],[257688,"2026-10-06T12:30:01",31,"есть, разбитое окно, чере которое заливается вода от высоких волн. Можно туда пролезть. СЛ 18 на акробатику, иначе будут раны от порезов стеклом",257687,null],[257689,"2026-10-06T12:33:01",20,"- Я попробую открыть дверь изнутри!\n\n*Беатриче бежит к окну.*",212725,null],[257690,"2026-10-06T12:33:13",20,"/r d20+5",212725,null],[257692,"2026-10-06T12:33:29",20,"/-удача",212725,null],[257693,"2026-10-06T12:33:35",20,"/r d20+5",212725,null],[257695,"2026-10-06T12:33:48",20,"/осталось 2",212725,null],[257696,"2026-10-06T12:35:58",17,"— Хорошая идея, немедленно \n\n\"Лети, Жнец. Произнеси громко около капитана \"МАЯК ВЕДЁТ ВАС НА РИФЫ\"\"\n\nВорон издаёт протяжный КАААААР и летит прямиком на капитанскую палубу",257682,null],[257697,"2026-10-06T12:36:44",31,"Беатриче словно тень проскочила сквозь разбитое окно и оказалась на первом этаже старого маяка, по колено в воде. Она видит переж собой круглую комнату, слева в 30 футах дверь на улицу, справа в 30 футах винтовая лестница наверх. А прямо посреди комнаты, в 20 футах от нее огромная вонючая туша дохлой акулы. Похоже, когда Бродерик говорил что воняет не селедка, он был прав",212725,null],[257698,"2026-10-06T12:36:58",31,"а он умеет говорить по человечески?/",257696,null],[257699,"2026-10-06T12:37:15",17,"/КОнечно навык \"Подражание\"",212725,null],[257700,"2026-10-06T12:37:27",17,"/ Подражание. Ворон может подражать простым звукам, которые когда-либо слышал, таким как чей-то шепот, плач ребенка или звуки животных. Существо, слышащее эти звуки, может понять, что это подражание, если совершит успешную проверку Мудрости (Проницательность) Сл 10.",212725,null],[257701,"2026-10-06T12:37:36",31,"нунадеюсь навык убеждения у него хороший/",257699,null],[257702,"2026-10-06T12:38:38",31,"ок, ворону лететь 10 минут, напомните мне потом прокинуть за капитана галеона проверку мудрости/",212725,null],[257703,"2026-10-06T12:38:52",31,"у вас осталось 43 минуты/",212725,null],[257705,"2026-10-06T12:40:32",20,"*Беатриче бежит к двери, чтобы открыть ее для спутников*",257697,null],[257707,"2026-10-06T12:41:38",31,"и заодно бросает проверку ловкости, СЛ 13. Местность пересеченая, ьскорость режется вдвое/",257705,null],[257708,"2026-10-06T12:43:28",20,"/на меня это вроде не действует, если не магия",212725,null],[257709,"2026-10-06T12:43:51",31,"ок, ты бежишь быстро. Но спас ловкости не для этого)/",257708,null],[257710,"2026-10-06T12:44:03",20,"/r d20+5 спас",212725,null],[257712,"2026-10-06T12:44:12",20,"/ну ладно, давай",212725,null],[257713,"2026-10-06T12:44:42",20,"/фигач",212725,null],[257714,"2026-10-06T12:45:07",31,"ты не добежала, со стороны мертвой акулы в тебя прилетело щупальце и обвило тебя",212725,null],[257715,"2026-10-06T12:45:17",31,"ты схвачена, но без урона. пока",212725,null],[257719,"2026-10-06T12:46:06",31,"Оглнявушсь, ты видишь что акула, хоть и дохлая, но уж больно аткивная, да еще и с тентаклями",212725,null],[257720,"2026-10-06T12:46:25",31,"Бросай инициативу",212725,null],[257721,"2026-10-06T12:46:33",20,"/r d20+3",212725,null],[257723,"2026-10-06T12:46:53",31,"/roll d20+1 акула",212725,null],[257725,"2026-10-06T12:47:31",31,"дверь все еще закрыта, ты в щупальце, твои друзья снаружи. \n\n42 минуты",212725,null],[257726,"2026-10-06T12:47:39",31,"ход Беатриче",212725,null],[257727,"2026-10-06T12:48:05",31,"Инициатива\n\nБеатриче\nМарко\nАкула 45 урона, убита\nЯсмин",212725,null],[257730,"2026-10-06T12:48:54",31,"если бы порезалась об окно, аула бы напала раньше)/",212725,null],[257731,"2026-10-06T12:49:49",20,"/что нужно чтобы вырваться из захвата?",212725,null],[257732,"2026-10-06T12:50:02",20,"/проверка или действие и проверка?",212725,null],[257733,"2026-10-06T12:50:23",31,"соревнование аробатики против атлетики акулы. у акулы преимущество по атлетике/",212725,null],[257734,"2026-10-06T12:50:37",20,"/r d20+5",212725,null],[257736,"2026-10-06T12:50:48",31,"/roll +d20+3",212725,null],[257738,"2026-10-06T12:51:00",31,"ты вырвалась",212725,null],[257739,"2026-10-06T12:51:38",20,"/тогда все ещё пробую открыть для других дверь",212725,null],[257740,"2026-10-06T12:52:12",31,"ну тут без проверок, просто открываешь засов",212725,null],[257741,"2026-10-06T12:52:43",31,"Марко и Ясмин бросают на инициативу, но начнут уже в новый круг. а пока ход акулы",212725,null],[257742,"2026-10-06T12:53:11",20,"- Осторожней, тут морепродукты разбушевались! *Перекрикивая шторм сообщает Беатриче, а потом снова встаёт перед акулой, чтобы взять удар на себя*",212725,null],[257743,"2026-10-06T12:53:34",31,"Акула подплвает к беатриче, дохлая, но сука, опсаная, и делает кусь",212725,null],[257744,"2026-10-06T12:53:46",31,"/roll d20+5",212725,null],[257746,"2026-10-06T12:54:04",31,"кусь-хуюсь/",212725,null],[257747,"2026-10-06T12:54:11",31,"рак кубов, ты задолбал/",212725,null],[257748,"2026-10-06T12:54:36",31,"и мультиатаку я ей не дал",212725,null],[257749,"2026-10-06T12:54:40",31,"ход/",212725,null],[257750,"2026-10-06T12:54:50",31,"инициатива Марко и Ясмин",212725,null],[257751,"2026-10-06T12:55:02",31,"41 минута",212725,null],[257753,"2026-10-06T12:56:43",17,"/r +2 Марко ини",257741,null],[257759,"2026-10-06T13:11:33",31,"@lady_godzilla инициативу",212725,null],[257803,"2026-10-06T13:57:56",22,"//простите, теперь я тут",212725,null],[257804,"2026-10-06T13:58:00",22,"/r +2",257759,null],[257836,"2026-10-06T14:21:33",31,"Беатриче ходит. \n\nОна ближе всех к акуле, Марко и Ясмин позади\n\n41 минуты до кораблекрушения",212725,null],[257857,"2026-10-06T14:40:10",20,"*Беатриче выхватывает рапиру и кинжал, нанося два удара по пасте прямо перед ней*",257836,null],[257858,"2026-10-06T14:40:35",20,"/r d20+6 рапира\n/r d20+5 кинжал",212725,null],[257866,"2026-10-06T14:41:19",20,"/ну ладно, стоим дальше танчим",212725,null],[257867,"2026-10-06T14:41:59",20,"/конец хода получается",212725,null],[257871,"2026-10-06T14:43:19",17,"Марко не церемонясь входит в здание\n\nЧерная голова Шакала снова проявляется и атакует ужасного монстра когтистой лапой вонзая когти поглубже\n\nНад Акулой из темноты вихрем формируется голова черного шакала с острыми клыками, а глаза горят золотым\n\nОна тоже кусает акулу пытаясь разорвать",212725,null],[257873,"2026-10-06T14:43:56",17,"/r +4 Обычный удар +5 Удар божественным оружием\n\nd8+2 q\nd8+3 q",212725,null],[257877,"2026-10-06T14:44:52",17,"В момент когда клыки парящей головы шакала вонзились в акулу в пасти загорелся золотой свет \n\n/Божественный канал",212725,null],[257879,"2026-10-06T14:45:22",17,"/ Акула получает еще 11 Урона нектротикой",212725,null],[257880,"2026-10-06T14:45:27",17,"/ БОЖЕСТВЕННЫЙ КАНАЛ: КАСАНИЕ СМЕРТИ\n2-й уровень, умение домена смерти\nВы можете использовать «Божественный канал» для уничтожения касанием чужой жизненной силы.\nКогда вы попадаете по существу рукопашной атакой, вы можете использовать «Божественный канал», чтобы нанести цели дополнительный урон некротической энергией, равный 5 + ваш удвоенный уровень Жреца.",212725,null],[257886,"2026-10-06T14:47:06",31,"Сколько ты выдал бедной акуле? Все прошло",212725,null],[257901,"2026-10-06T14:52:23",17,"/ Колющий 6\nСиловое поле 11\nНекротика 11\n\nИтого 28",257886,null],[257909,"2026-10-06T14:54:38",31,"Акуле бо-бо. Но еще может делать кусь/",212725,null],[257915,"2026-10-06T14:56:35",31,"/roll d20+5 акула выбрасывает щупальце чтобы ударить им Беатриче",212725,null],[257917,"2026-10-06T14:56:45",31,"Сучий рак кубов/",212725,null],[257919,"2026-10-06T14:56:51",31,"Ход/",212725,null],[257921,"2026-10-06T14:57:07",31,"Ладно, акула это разминка/",212725,null],[257922,"2026-10-06T14:57:13",31,"Ясмин",212725,null],[257925,"2026-10-06T14:58:51",22,"Ясмин опасливо смотрит на бедное создание.\n\nКакая красивая рыбка\nЕе бы да мне в озеро\nО да, славная вышла бы зверушка\n\n- Такое неестественное создание не должно существовать.. не должно страдать. Я помогу тебе.\n\nСпас лвк 14",212725,null],[257926,"2026-10-06T14:59:02",22,"/r 3d6 ОГОНЬ",212725,null],[257928,"2026-10-06T14:59:13",22,"Ход/",212725,null],[257930,"2026-10-06T14:59:41",31,"/roll d20+1 ловкость мёртвой акулы",212725,null],[257934,"2026-10-06T15:01:04",31,"Акула подгорает от огня, но из за того что находится в воде, получает только половину урона. А еще теперь из за испарения воды образовался водяной пар. Следующий раунд пройдёт в плохой видимости, всем кроме акулы помехи на атаку\n\nОсталось 40 минут",212725,null],[257936,"2026-10-06T15:01:30",31,"Беатриче",212725,null],[257944,"2026-10-06T15:02:51",20,"/r d20+6 пробуем ещё раз\n/r d20+5",212725,null],[257946,"2026-10-06T15:03:08",31,"Я для кого помещу писал?",212725,null],[257947,"2026-10-06T15:03:09",20,"/ура, я не только мясной щит",212725,null],[257950,"2026-10-06T15:03:21",20,"/а, сейчас",212725,null],[257952,"2026-10-06T15:03:35",31,"Оба прошли, да бля",212725,null],[257954,"2026-10-06T15:04:08",20,"/r d8+4\n/r d4+3",212725,null],[257956,"2026-10-06T15:04:41",31,"Описывай процесс нарезания сашими из акулы, ровно весь хп добила",212725,null],[257957,"2026-10-06T15:06:25",20,"*Беатриче пытается рассеять пар, махая рапирой. Попадает по акуле. Каким-то образом?*\n\n*Когда туман рассеивается, вы видите отплевывающуюся от воды дампиршу и свежие акульи суши с щупальцами*\n\n- Э...уже все закончилось? *Она оглядывается*",212725,null],[257958,"2026-10-06T15:06:57",31,"39 минут осталось",212725,null],[257964,"2026-10-06T15:09:13",20,"- Поспешим наверх *она не убирает рапиру, оставаясь на готове - мало ли кто ещё вроде этой акулы встретиться*\n\n- Я пойду вперёд, вдруг наверху очередной сюрприз с щупальцами\n\n/Беатриче готова двигаться наверх",212725,null],[257966,"2026-10-06T15:09:20",20,"/погнали",212725,null],[257972,"2026-10-06T15:11:32",17,"— Бежим",212725,null],[257973,"2026-10-06T15:11:37",17,"Тем временем ворон...",212725,null],[257975,"2026-10-06T15:12:26",31,"Потравила ещё пару минут, вы добрались до лестницы на второй этаж. Поднявшись на верх, вы увидели жилое помещение, тут то видимо и жил смотретьель с учеником. И смотриктель тоже тут. Точнее, тут то, что от него осталось. Сильный крупный мужчина сидит за столом. На его груди вы видите следы от ударов ножом, на рубахе запёкшаяся кровь. Но вот глаза не мертвы. Один из них выглядит как рыбий и смотрит на вас в упор.\n\nСпас мудрости, сл 14",212725,null],[257978,"2026-10-06T15:12:55",17,"/r +5 Спас",257975,null],[257980,"2026-10-06T15:12:58",22,"Ясмин поспешно следует за остальными. Пытаясь вспомнить, какие цветовые маркеры использовали маяки, чтобы предупредить корабль о скалах.\n\n\n//Ясмин скорее всего этого не знает, но я помню, что иногда маяки красным светом подсвечивают то, где есть рифы/скалы и понимаю, что Ясмин магией в принципе может это сделать",212725,null],[257983,"2026-10-06T15:13:06",31,"Не долетел еще, вы быстро идёте. Оа 32 минутах будет у корабля",257973,null],[257984,"2026-10-06T15:13:33",22,"/r +6 мудрость",257975,null],[257986,"2026-10-06T15:13:49",22,"/r -1 память Яс",257980,null],[257988,"2026-10-06T15:15:17",20,"/r d20+1 🫡",212725,null],[257990,"2026-10-06T15:16:01",31,"/roll 2d6+3 психический урон по Беатриче",212725,null],[257992,"2026-10-06T15:16:47",22,"@QURTZZ сбей бота. Иди в бросках кинь 50д20 и 50д6 там/",212725,null],[257993,"2026-10-06T15:18:36",31,"Смотритель открывает рот. Его голос совсем не тот, что вы слышали в таверне. Сейчас с вами говорит нечто чужеродное, нечеловеческое\n\n- вы пришли, как и обещали этому мешку с костями. И пока вам везет. Но лучше уйдите, так всем будет лучше. Я заберу кровь тех кто пдыве на корабле, а вы можете забрать то, что везёт корабль",212725,null],[257994,"2026-10-06T15:18:47",31,"/roll d20+3 убеждение",212725,null],[257997,"2026-10-06T15:20:05",31,"Можете попытаться перебить спасом мудрости. Марко не нужно, я засчитаю его прошлый Крит. Если не пройдете и решите атаковать, то будете под нерешительностью атаковать с помехой",212725,null],[257999,"2026-10-06T15:20:59",20,"/r d20+1 хуя он стелит, мне честь не позволяет так людей бросать",212725,null],[258001,"2026-10-06T15:21:13",20,"/пох, с помехой так с помехой",212725,null],[258002,"2026-10-06T15:21:56",22,"/r +6",212725,null],[258004,"2026-10-06T15:22:45",22,"- Нет! Нет! НЕ СМЕЙ ЛЕЗТЬ КО МНЕ В ГОЛОВУ! \n\nЯсмин обхватилась руками за голову и усиленно отводила взгляд от мёртвой твари.",212725,null],[258005,"2026-10-06T15:24:04",17,"Марко подбегает к трупу его книга Мёртвых покрывается золотым светом \n\n— Exorcizo te, omnis spiritus immunde!\n\n/Изгнание нежити",212725,null],[258006,"2026-10-06T15:24:12",17,"/ Вы Действием демонстрируете свой священный символ и читаете молитву, изгоняющую нежить. Вся нежить, которая может видеть или слышать вас в пределах 30 футов, должна совершить спасбросок Мудрости. Если существо провалило спасбросок, оно изгоняется на 1 минуту, или пока не получит урон.\nИзгнанное существо должно тратить свои ходы, пытаясь уйти от вас как можно дальше, и не может добровольно переместиться в пространство, находящееся в пределах 30 футов от вас. Оно также не может совершать реакции. В качестве действия существо может использовать только Рывок или пытаться освободиться от эффекта, препятствующего его передвижению. Если двигаться некуда, существо может использовать действие Уклонение.",212725,null],[258007,"2026-10-06T15:24:22",17,"/ СЛ 14",212725,null],[258008,"2026-10-06T15:24:27",20,"- Мне не нужна чертова удача, чтобы надрать тебе задницу *Беатриче оскаливается, готовая к бою*",257993,null],[258009,"2026-10-06T15:25:07",31,"/roll d20+3",258006,null],[258015,"2026-10-06T15:27:38",31,"Смотритель встает из за стола, но не знает куда ему идти. Мимо тебя ниж он полти не может, наверх его что то не пускает. Он завис.\n\n/ка долго он будет тупить?",258011,null],[258016,"2026-10-06T15:28:17",17,"/ оно изгоняется на 1 минуту",212725,null],[258017,"2026-10-06T15:28:38",17,"/ Он изнан в принципе из материального мира",212725,null],[258018,"2026-10-06T15:28:47",17,"/ Как заклинание изгнание",212725,null],[258019,"2026-10-06T15:28:59",17,"— Наверх!",212725,null],[258020,"2026-10-06T15:29:03",17,"И все бегут выше",212725,null],[258021,"2026-10-06T15:32:00",31,"Осталось 34 минуты",212725,null],[258022,"2026-10-06T15:32:23",31,"Ворон почти долетел",212725,null],[258029,"2026-10-06T15:38:13",31,"На верхнем этаже вас встретил потусторонний синий свет, исходящий от огромного глаза какого то чудовища. А перед ним стоит мерзковатого вида рыболюд, по остаткам одежды которого вы узнаете Бродерика, ученика смотрителя маяка. Он открывает рот и вы вновь слышите тот же голос, что и оа прошлом этаже:\n\n- очень жаль что вы решили идти до конца. Конец будет вашим\n\nИнициатива",212725,null],[258031,"2026-10-06T15:39:09",17,"/r +2 Марко ини",212725,null],[258033,"2026-10-06T15:39:11",31,"/roll d20+2 Измененный Бродерик\n/roll d20 Глаз Бездны",212725,null],[258036,"2026-10-06T15:44:10",20,"/r d20+3",212725,null],[258038,"2026-10-06T15:44:30",20,"/рак кубов заразен",212725,null],[258039,"2026-10-06T15:46:36",31,"Надо иногда/",212725,null],[258040,"2026-10-06T15:46:48",31,"А то забодали меня большими цифрами",212725,null],[258041,"2026-10-06T15:47:06",31,"@lady_godzilla инициатива",212725,null],[258043,"2026-10-06T15:48:31",22,"/r +2",212725,null],[258045,"2026-10-06T15:50:27",31,"Измененный Бродерик 10 урона\nГлаз Бездны 42 урона\nЯсмин\nМарко\nБеатриче\nСмотритель",212725,null],[258048,"2026-10-06T15:51:02",31,"Как вы стоите?",212725,null],[258049,"2026-10-06T15:51:25",20,"/Беатриче точно впереди",212725,null],[258054,"2026-10-06T15:53:29",31,"/roll d20+5 когтем\n/roll d20+5 зубами\n\nВсе по Беатриче",212725,null],[258056,"2026-10-06T15:53:42",20,"/первая попала",212725,null],[258057,"2026-10-06T15:54:12",31,"/roll d6+3 \n/roll d6 урон некротикой",212725,null],[258059,"2026-10-06T15:54:20",31,"11 урона",212725,null],[258060,"2026-10-06T15:55:11",31,"Ход глаза",212725,null],[258061,"2026-10-06T15:55:25",31,"/roll d6 перезарядка",212725,null],[258063,"2026-10-06T15:55:43",31,"Не прошло, значит только обга атака",212725,null],[258064,"2026-10-06T15:55:56",31,"/roll d20+7",212725,null],[258066,"2026-10-06T15:56:15",31,"Спас мудрости от всех, СЛ 15",212725,null],[258067,"2026-10-06T15:56:21",22,"/r +6",258066,null],[258070,"2026-10-06T15:56:45",31,"/roll 2d6+4 если прошли спас то половина урона психического",212725,null],[258073,"2026-10-06T15:57:11",31,"Если не прошли, то еще и испуганный до конца своего хода",212725,null],[258076,"2026-10-06T15:59:16",31,"@PaIIasCat @dunchev спас мудрости сл 15, 8 урона если не пройдете и состояние испуганный, если пойдете то половина урона/",212725,null],[258078,"2026-10-06T16:02:31",20,"/r d20+1 🫡",212725,null],[258080,"2026-10-06T16:02:39",20,"/хех)",212725,null],[258081,"2026-10-06T16:03:04",20,"/так, пойду урон подсчитаю в сумме сколько по мне было",212725,null],[258082,"2026-10-06T16:04:26",20,"/ещё живём",212725,null],[258083,"2026-10-06T16:04:58",31,"Ждем спас Коли и будет ход Ясмин/",212725,null],[258096,"2026-10-06T16:09:05",17,"/r +6 Спас",258066,null],[258102,"2026-10-06T16:11:42",31,"Ну хоть кого то получилось уебать/",212725,null],[258103,"2026-10-06T16:11:53",31,"Ход Ясмин/",212725,null],[258118,"2026-10-06T16:16:29",22,"Как они стоят? Расстояние между нами и между ними /",212725,null],[258133,"2026-10-06T16:20:45",31,"Беатриче вплотную к Бродерику, Глаз за спиной Бродерика/",258118,null],[258148,"2026-10-06T16:29:32",22,"- Я...\n\nПризови глаз, дитя\nПризови свой глаз\nОткрой свой глаз\n\nДевушка так сильно закусила свою губу, что по подбородку стекла струйка крови.\n\nДевушка вытянула дрожащую руку вперед и за спиной Бродерика, между ним и глазом раскрылось огненное око\n\nСпас лвк 14 или половина",212725,null],[258149,"2026-10-06T16:29:45",22,"/r 2d6 Пылающий шар",212725,null],[258151,"2026-10-06T16:29:48",22,"Ход/",212725,null],[258152,"2026-10-06T16:30:18",31,"/roll d20+2 ловкость Бродерика\n/roll d20 ловкость Глаза",212725,null],[258155,"2026-10-06T16:31:25",20,"/жги их Ясмин",212725,null],[258156,"2026-10-06T16:31:35",31,"Бродерик пытается принимать на себя основной удар, защищая глаз, но огненный шар все равно бьет в Глаз, а Бродерик страдает не так сильно",212725,null],[258158,"2026-10-06T16:32:51",31,"Ход Марко\n С помехой",212725,null],[258163,"2026-10-06T16:43:21",17,"В следующий миг маяк исчез. Не было ни камня под ногами, ни голосов спутниц. Только холодная чёрная вода со всех сторон\n\nМарко застыл. Удар сердца. Ещё один\n\n\"Вот значит как...\"\n\nОн уже решил, что сейчас что-то придёт из темноты\nНо оказалось хуже\n\nГде-то далеко впереди сама тьма разошлась и открылся глаз. Огромный настолько, что Марко рядом с ним казался пылинкой в толще воды\nУзкий змеиный зрачок остановился точно на нём\nСледователь впервые за долгое время испугался\nТого, что сейчас смотрело на него\n\nИ тогда под кожей словно рассыпался золотой песок\nТень поднялась по шее, сомкнулась на лице шакальей мордой. Пальцы вытянулись чёрными когтями\nСтрах никуда не делся\nНо ноги снова слушались\n\nКогда мир вокруг вернулся, Марко резко развернулся к рыболюду возле линзы\nВ вытянутой руке из тени уже складывалась огромная чёрная голова шакала. Золотые глаза вспыхнули одновременно с глазами Марко\n\nШакал рванулся вперёд",212725,null],[258164,"2026-10-06T16:44:16",17,"/r +6 Божественное оружее d8+4 Силовым полем",212725,null],[258166,"2026-10-06T16:44:37",31,"Помеха для кого?",212725,null],[258167,"2026-10-06T16:44:38",17,"/r +6 Помеху забыл",212725,null],[258174,"2026-10-06T16:45:40",31,"Итого сколько и по кому?/",212725,null],[258175,"2026-10-06T16:45:55",31,"14 вроде?",212725,null],[258176,"2026-10-06T16:46:00",20,"/разве помеха от испуга действует на божественное оружие?",212725,null],[258177,"2026-10-06T16:46:09",17,"/ У меня удар божественным оружием с помехой = крит провал.\n\nАтаковать рапирой я не могу, страх не даёт приблизится",258174,null],[258179,"2026-10-06T16:47:15",31,"Гугл говорит что помеха есть если ты видишь того кто тебя пугает/",212725,null],[258181,"2026-10-06T16:48:13",17,"/ Да никто и не спорит Леша))",212725,null],[258182,"2026-10-06T16:48:31",31,"Я для себя выясняю. Я же правил не читал)/",212725,null],[258183,"2026-10-06T16:48:42",31,"Ты мне скажи сколько и куюому прилетело/",212725,null],[258184,"2026-10-06T16:49:04",17,"/ 0 ни по кому 1 удар и тот у меня крит провал",212725,null],[258186,"2026-10-06T16:49:19",31,"А, Крит провал, это же я могу тебя контратакой наказать",212725,null],[258188,"2026-10-06T16:49:34",31,"/roll d6 психического урона",212725,null],[258190,"2026-10-06T16:50:04",31,"Тоже не по правилам, но раз уже я так начал делать, то овдоьдо конца идти/",212725,null],[258191,"2026-10-06T16:50:19",17,"/Божественное оружее не имеет возможности быть атаковано",258186,null],[258192,"2026-10-06T16:50:41",17,"/Ну а по мне уебать конечно можно!",212725,null],[258193,"2026-10-06T16:50:46",31,"Сраные божьи колдуны/",212725,null],[258195,"2026-10-06T16:51:14",31,"Тогда отмена рикошета, уговорил",212725,null],[258196,"2026-10-06T16:51:26",31,"Лови одачу когтями от Бродерика",212725,null],[258197,"2026-10-06T16:51:36",31,"/roll d20+5",212725,null],[258200,"2026-10-06T16:51:48",31,"Лапа с когтями свистит мимо Марко/",212725,null],[258201,"2026-10-06T16:51:54",31,"Ход Беатриче",212725,null],[258204,"2026-10-06T16:52:41",20,"/r d20+6 тыкаем в глаз\n/r d20+5",212725,null],[258208,"2026-10-06T16:52:57",20,"/ладно, всплеск действий",212725,null],[258210,"2026-10-06T16:53:20",20,"/r d20+6 снова в глаз",212725,null],[258213,"2026-10-06T16:54:01",31,"А тебя не смущает что перед глазом стоит Бродерик? Он для тебя пустое место? Зря, провоцирку словила/",212725,null],[258214,"2026-10-06T16:54:11",20,"/r d10+3 второе дыхание",212725,null],[258216,"2026-10-06T16:54:35",20,"/я не выходила из его радиуса вроде, если он с глазом в 5 ф стоял",258213,null],[258217,"2026-10-06T16:55:03",31,"Он стоит спиной к глазу и прикрывает его/",258216,null],[258218,"2026-10-06T16:55:54",20,"/ну сбоку рядом с ним встать если комната позволяет и тыкнуть в глаз",212725,null],[258221,"2026-10-06T16:56:45",31,"Кинь проверку ловкости против его проверки ловкости/",212725,null],[258222,"2026-10-06T16:57:00",20,"/хотя тут как ты решишь - давай просто провоцированную если",212725,null],[258223,"2026-10-06T16:57:01",31,"/roll d20+2",212725,null],[258225,"2026-10-06T16:57:11",20,"/r d20+5",212725,null],[258227,"2026-10-06T16:57:19",20,"/во, теперь бей",212725,null],[258230,"2026-10-06T16:57:46",31,"/roll d20+5 Брлдрик наотмашь бьет тебя по руке, звщиая глаз",212725,null],[258235,"2026-10-06T16:58:04",20,"/не попал",212725,null],[258238,"2026-10-06T16:58:16",20,"/)",212725,null],[258240,"2026-10-06T16:58:29",31,"/roll d6+3\n/roll d6 урон некротикой",212725,null],[258242,"2026-10-06T16:58:41",31,"У тебя вырос кд?",258235,null],[258244,"2026-10-06T16:58:59",20,"/да, +2 от харизмы \n/Теперь 20",258242,null],[258248,"2026-10-06T17:00:37",20,"/r d8+4 это за урон рапиры",212725,null],[258251,"2026-10-06T17:01:45",31,"Тем временем ворон долетел до корабля с посланием",212725,null],[258252,"2026-10-06T17:02:04",31,"/roll d20 на мудрость капитана, получится ли понять птицу",212725,null],[258255,"2026-10-06T17:02:25",17,"/r -2 КААААР ВЫ ПЛЫВЁТЕ НА РИФЫ! Харизматичный ворон",212725,null],[258258,"2026-10-06T17:02:33",31,"- лево руля! Птица не врет, мне и казалось странным что не туда идем!",212725,null],[258259,"2026-10-06T17:03:18",31,"Глаз вспыхивает яростью, вы слышите в головах его голос:\n\n- придется выпить вас...",212725,null],[258260,"2026-10-06T17:03:45",31,"Корабль спасен. Если выживете, навестите капитана вместе с птицей/",212725,null],[258261,"2026-10-06T17:04:33",31,"Ход Бродерика:\n\n- вы разозлили хозяина волн. Он не простит такого...",212725,null],[258263,"2026-10-06T17:05:36",31,"/roll +d20+5 когти по Беатриче\n/roll +d20+5 клыки по ней же\n\nБродерик получил преимущество в этом раунде за счет ярости глаза",212725,null],[258266,"2026-10-06T17:05:52",31,"И он его поосрал, чмошник/",212725,null],[258267,"2026-10-06T17:05:58",31,"Ход глаза",212725,null],[258269,"2026-10-06T17:06:20",31,"/roll d6 перезарядка способности",212725,null],[258271,"2026-10-06T17:06:25",31,"Не прошло",212725,null],[258272,"2026-10-06T17:06:38",31,"/roll +d20+7",212725,null],[258276,"2026-10-06T17:09:01",31,"Спас мудрости от Ясмним, она одна тут с КД ниже 16. СЛ 15",212725,null],[258278,"2026-10-06T17:09:34",22,"/r +6",212725,null],[258280,"2026-10-06T17:09:56",31,"/roll 2d6+4 если не прошла, то полгй урон и испуг, если прошла то половина урона",212725,null],[258283,"2026-10-06T17:10:16",22,"//я тебе серьёзно говорю,  сбрось кубы у бота",258280,null],[258284,"2026-10-06T17:10:22",31,"Как вам прёт а. Глаз звонит тараску",212725,null],[258285,"2026-10-06T17:10:48",22,"//без шуток, у меня была такая же проблема,  сброс поправил. Это выглядит как глюк пока",212725,null],[258289,"2026-10-06T17:11:44",31,"Бросил 100д20. Средний результат 10,8, нормальное распределение. Это вам прет/",258285,null],[258291,"2026-10-06T17:12:26",31,"Ход испуганой Ясмин",212725,null],[258295,"2026-10-06T17:16:05",22,"Ясмин испуганно плачет.\n\nШар наносит урон всем в радиусе 5 фт",212725,null],[258296,"2026-10-06T17:16:16",22,"Спас лвк 14",212725,null],[258297,"2026-10-06T17:16:19",22,"/r 2d6",212725,null],[258299,"2026-10-06T17:16:24",22,"/ход",212725,null],[258300,"2026-10-06T17:16:30",31,"Включая Беатриче?/",258295,null],[258301,"2026-10-06T17:16:54",31,"/roll d20+2 Бродерик\n/roll d20 Глаз",212725,null],[258303,"2026-10-06T17:16:58",20,"/r d20+3",212725,null],[258305,"2026-10-06T17:17:28",20,"/печёт",212725,null],[258308,"2026-10-06T17:20:42",31,"Ход Марко, но видимо он пока в пути/",212725,null],[258309,"2026-10-06T17:26:01",17,"Все вернцло, Марко вынырнул из глубины страха и увидел всю картину как она есть. Он бесстрашно шагнул к рыбалюду подняв свои две теневые когтистые лапы, и обрушил их на него разрывая его плоть. А парящая голова шакала уцепилась ему за шею",212725,null],[258310,"2026-10-06T17:27:17",17,"/r +6 нанесение ран +6 божественное оружие \n\n3d10 некр \nd8+4 силовое поле",212725,null],[258313,"2026-10-06T17:27:42",31,"Мухахахахахах",212725,null],[258314,"2026-10-06T17:28:17",31,"/roll d20+5 наказание за Крит провал, когти Бродерика летят в тебя",212725,null],[258316,"2026-10-06T17:28:27",31,"Лох рыбоголовый/",212725,null],[258317,"2026-10-06T17:28:59",31,"Битва двух алкашей, махают руками и не могут попасть /",212725,null],[258318,"2026-10-06T17:29:23",31,"Беатриче, покажи как нужно/",212725,null],[258326,"2026-10-06T17:36:05",20,"/говоришь так будто ее предыдущие броски были лучше)",258318,null],[258328,"2026-10-06T17:36:22",31,"Ты верно уловила мою мысль/",258326,null],[258329,"2026-10-06T17:36:27",20,"*Беатриче снова упорно тыкает в глаз!*",212725,null],[258330,"2026-10-06T17:36:39",20,"/r d20+6\n/r d20+5",212725,null],[258333,"2026-10-06T17:37:09",20,"/r d8+4\n/r d4+3",212725,null],[258335,"2026-10-06T17:37:11",31,"Опять соревнуйся в ловкости)",212725,null],[258336,"2026-10-06T17:37:18",31,"/roll d20+2",212725,null],[258338,"2026-10-06T17:37:21",20,"/r d20+5",212725,null],[258340,"2026-10-06T17:37:26",31,"Хах",212725,null],[258341,"2026-10-06T17:37:32",20,"/ахаха",212725,null],[258343,"2026-10-06T17:37:40",22,"//Беатриче вошла в ярость\nИ вышла",258331,null],[258345,"2026-10-06T17:38:23",31,"Глаз начинает кровоточить, его голос в ваших головах звучит набатом:\n\n- ЖАЛКИЕ СМЕРТНЫЕ ТВАРИ!!!",212725,null],[258351,"2026-10-06T17:39:49",31,"Вы слышите шаги сзади. По лестнице поднимается нежить, мёртвый Смотритель маяка. Глаз вновь призвал его. Т сейчас вокруг кго головы видно прозрачное синее сияние, похоже, глаз дал ему какую то защиту от магии Марко",212725,null],[258352,"2026-10-06T17:39:57",17,"— Если бы мне платили каждый раз по медяку когда я это слышу... \n\nШакал улыбнулся",212725,null],[258353,"2026-10-06T17:40:13",31,"/roll d20+2 инициатива Смотрителя",212725,null],[258356,"2026-10-06T17:40:42",31,"Он начнёт в следующем круге",212725,null],[258357,"2026-10-06T17:40:50",31,"А пока ход Бродерика",212725,null],[258362,"2026-10-06T17:41:41",31,"- я обглвжаю тебя как воблу...\n\nБродерик в сторону Беатриче",212725,null],[258363,"2026-10-06T17:42:08",31,"/roll +d20+5 когти\n/roll +d20+5 клыки",212725,null],[258365,"2026-10-06T17:42:27",20,"/когти попали",212725,null],[258366,"2026-10-06T17:42:48",31,"/roll d6+3\n/roll d6 некротикой",212725,null],[258369,"2026-10-06T17:42:59",31,"7 урона/",212725,null],[258370,"2026-10-06T17:43:09",31,"Жива?/",212725,null],[258372,"2026-10-06T17:43:14",20,"/считаю",212725,null],[258376,"2026-10-06T17:44:29",20,"/да, ещё 7 хитов",212725,null],[258381,"2026-10-06T17:44:41",20,"/но хил бы не помешал:3",212725,null],[258386,"2026-10-06T17:45:31",31,"Хож глаза",212725,null],[258387,"2026-10-06T17:45:41",31,"/roll d6 перезарядка",212725,null],[258389,"2026-10-06T17:45:45",31,"Да бля/",212725,null],[258390,"2026-10-06T17:45:49",31,"Обычный ход",212725,null],[258391,"2026-10-06T17:45:54",31,"/roll d20+7",212725,null],[258393,"2026-10-06T17:46:16",31,"Опять только по Ясмин попадаю, спас мудрости 15)/",212725,null],[258394,"2026-10-06T17:47:38",31,"/roll 2d6+4 как всегда, половина урона если прошла, половина и испуганость если не прошла",212725,null],[258403,"2026-10-06T17:52:51",22,"/r +6",258393,null],[258405,"2026-10-06T17:53:14",31,"Ну и бей сразу",212725,null],[258416,"2026-10-06T17:57:38",22,"Ясмин подшагивает товарищам и аккуратно кладет ладони им на спину?(я так понимаю вы рядом стоите).\n\nИз рук девушки идет поток света, который заживляет раны.\n\nЗа метамагию лечение каждому @PaIIasCat @dunchev",212725,null],[258417,"2026-10-06T17:57:43",22,"/r 2d8+4",212725,null],[258420,"2026-10-06T17:58:17",22,"Бонусом чуть смещаю шар, чтобы не задевало Беатриче.\n\nВсе еще спас лвк 14",212725,null],[258421,"2026-10-06T17:58:21",22,"/r 2d6",212725,null],[258424,"2026-10-06T17:59:07",31,"/roll d20+2 Бродерик\n/roll d20 Глаз",212725,null],[258426,"2026-10-06T18:00:23",31,"Опиши как взорвался глаз и как Бродерик и Мертвый смотритель упали без движения Бродермк жив если что, хоть и зарыболюдел. Помбольшк мерзких подробностей, пожалуйста. Комментарии тётушек обязательны/",212725,null],[258428,"2026-10-06T18:01:36",22,"//через 20 мин",212725,null],[258429,"2026-10-06T18:03:12",31,"Я не тороплюсь/",212725,null],[258442,"2026-10-06T18:35:23",22,"Большой глаз наконец перестал двигаться.\nОгромный зрачок расширился, перекрыв собой радужку и замер.\n\nОбожженная плоть лопнула и из нее медленно вытекала густая тёмная жидкость, собираясь в неровную лужицу.\n\nБродерик и не-мертвый рухнули рядом.\n\nЯсмин первела взгляд на \"юношу\". Его человеческие черты теперь казались особенно неуместными на рыболюдном теле. Мокрая чешуя была покрыта копотью и кровью, жабры судорожно раскрывались и закрывались, выпуская влажный хрип. \n\nЯсмин посмотрела на них сверху вниз.\n\nНе шевелится.\nНо один ещё дышит.\nЖабры забавно дергаются.\n\n- Действительно. Забавно. - Ясмин чуть склонила голову и ее лицо исказила неестественная ухмылка.\n\nОни скоро перестанут.\n\n- Хотите помочь? Вы? - Ясмин смеётся.\n\nМне плевать.\nНам плевать.\n А смотреть интересно. \n\nЯсмин медленно присела возле рыболюда и наклонила голову.\n- Фу...\nТебе не нравится?\nА нам нравится.\nОсобенно глаз.\nОн был красивый.\nБыл. А теперь катаракта все испортит.\n\nЯсмин перевела взгляд на поверженный глаз. По его поверхности медленно ползла катаракта.\n\nОн смотрит.\n\nЯсмин замерла.\n\n- Нет.\n\nСмотрит.\n\n- Он мёртв. Катаракта пришла как-то быстро.\n\nСлишком быстро.\n\nЯсмин несколько секунд молчала и поднялась.\n\n- Почему что вы не можете вовремя замолчать? Я устала. УСТАЛА!\n\nКогти Ясмин налились золотистым сиянием и он полоснула по стене, оставляя тонкие борозды.\n\nЗато мы умеем замечать интересное.\nУ Бродерика сломано ребро.\nНет. Два.\nТри.\n\nЯсмин бросила на рыболюда короткий взгляд.\nПод чешуёй действительно проступали неестественные углы. При каждом вдохе одна из костей чуть двигалась, царапая изнутри плоть.\nЯсмин поморщилась. Она посмотрела на свои руки, затем снова на рыболюда.\n\nЗато ты победила. Гордись собой, малышка. В тебе появилась СИЛА.\nИ смелость.\n\n- Победила значит..\n\nГолоса ненадолго замолчали. А затем матушка тихо прошептала\nНо если он снова встанет...\n\nЯсмин улыбнулась.\n\n- Тогда разберёмся.\n\nИ где-то глубоко внутри её головы сразу несколько голосов довольно засмеялись.",212725,null],[258443,"2026-10-06T18:35:58",22,"//без оформления, неудобно в дороге.",212725,null],[258451,"2026-10-06T18:41:02",31,"Да ладно, и так норм/",212725,null],[258452,"2026-10-06T18:41:37",17,"— Ворон смог убедить капитана корабля остановиться до столкновения с рифами. Похоже дейтвительно не зря мы вызвались помочь. Правда... Прийдя мы днём, возможно спасли бы этих несчастных. \n\nМарко вынул монеты из кошеля и принялся проводить обряд упокения. \n\n— Я думаю, что должен упокоить обоих. Парень стал рыболюдом под влиянием этого глаза. Вот этот глаз, действительно был злой, Ясмин. \n\nМарко снял очки и помассировал глаза\n\n— Когда он взглянул на меня, я остался один, в пучине на глубине. И этот глаз раскрылся за мной, огромный. Древний. Голодный...",212725,null],[258454,"2026-10-06T18:42:55",17,"— Беатриче, ты прекрасно сражалась. Что это у тебя за рапира?",212725,null],[258455,"2026-10-06T18:43:22",31,"Парень-рыболюд кряхтит, кажется он очнулся. Теперь, без поддержки глаза, стало очевидно что ему трудно дышать на суше. Жабры на его шее трепещут, пытаясь наполнить грудь кислородом, но не могут",212725,null],[258456,"2026-10-06T18:44:34",17,"— Чееерт, так он жив.",212725,null],[258458,"2026-10-06T18:46:43",20,"- Это фамильное оружие...чтобы закончить дело, которое начал отец. *Отвечает Беатриче. А потом тоже замечает что парень ещё шевелиться*\n\n- Вот же...что будем с ним делать? *Она подходит ближе, хоть это и враг ей не хочется чтобы он вот так мучился*\n\n- Если он ещё в сознании, можно попробовать его спасти. Но если разум уже безвозвратно утерян...нужно даровать последнюю милость, чтобы он хотя бы не мучился",258454,null],[258460,"2026-10-06T18:47:36",20,"*она смотрит на марко, так как сама не знает как проверить это*",212725,null],[258461,"2026-10-06T18:48:03",17,"— Он вероятно проклят.",212725,null],[258462,"2026-10-06T18:48:18",17,"/r d20+4+d4 Медицина",212725,null],[258465,"2026-10-06T18:48:25",20,"/пока оглядываюсь, может тут есть какое-то ведро или ёмкость с водой, чтобы чел не помер",212725,null],[258466,"2026-10-06T18:48:37",20,"/r d20+3",212725,null],[258468,"2026-10-06T18:48:39",17,"— Ему нужна вода, жабры хватают воздух. Но долго он так не протянет.",212725,null],[258469,"2026-10-06T18:48:57",17,"— Нам бы только понять, избавился он от влияния этого глаза или нет...",212725,null],[258470,"2026-10-06T18:49:36",31,"Твоих знаний медицины хватает чтобы понять, парень мутировал в это существо под воздействием проклятия, но в целом он сейчас вполне здоров, вы не слишком сильно его побили",258463,null],[258505,"2026-10-06T19:35:06",20,"/ведра воды по близости нет всё-таки?",212725,null],[258506,"2026-10-06T19:37:48",31,"На первом этаже воды по пояс",258505,null],[258509,"2026-10-06T19:39:41",20,"- Думаю времени у него немного, давай отнесем его на первый этаж в воду, а потом уж свяжемся и будем решать что дальше с ним делать",258469,null],[258513,"2026-10-06T19:43:29",17,"— Давай, бери за ноги а я за плечи и понесли. Может бедолагу ещё можно успеть спасти.",212725,null],[258517,"2026-10-06T19:44:18",31,"Не душу проверками, вы просто стащили его вниз и закинули в воду",212725,null],[258519,"2026-10-06T19:46:41",31,"Через пару минут парень вынырнул из воды, взгляд рыбьих глаз стал более разумным. И в них вы увидели боль и вину\n\n- я... Я поддался шёпоту. Я убил наставника... Я должен умереть за это преступление ... Прошу, убейте меня, мне не хватает храбрости сдулть это самому...",212725,null],[258604,"2026-10-06T21:46:21",22,"Ясмин улыбнулась.\n\n- Интересно.",258452,null],[258605,"2026-10-06T21:46:46",22,"Девушка перевела взгляд на рыболюда.\n\n- Что он тебе обещал?",258519,null],[258606,"2026-10-06T21:47:20",17,"— Сеньеор Неро Фелино определит что с тобой делать. Мы столкнулись с чем то важнее чем твоя жизнь. Древнее зло. Нужно... Навести справки.",258519,null],[258607,"2026-10-06T21:47:26",17,"— А ты важный свидетель.",212725,null],[258624,"2026-10-06T21:58:10",20,"*Беатриче просто смотрит на парня с сочувствием. Она не знает насколько тот мог сопротивляться голосу и был ли шанс избежать трагедии, но все равно ей жаль его. Быть ответственным за смерть близкого, даже если и неподвольно...*",212725,null],[258630,"2026-10-06T22:06:42",22,"Ясмин посмотрела на рыболюда и отвернулась.\n\nТак значит такая судьба меня ждет?\n\nНет, дорогая, сожаления не будут тебя терзать\nЭти эмоции для слабых\nА ты же сильная девочка\nИ безжалостная\n\n- Омерзительно. - тихо сказала себе под нос Ясмин, и еще тише добавила. - Я просто омерзительна. Что же я за чудовище...\n\nУбедившись, что ее спутники отвлечены, Ясмин вернулась наверх и попыталась оттащить все тела, чтобы устроить этой мерзости погребальный костер.\nВымазавшись в выделениях, крови и в чем-то еще, девушка упорно складывала тела не-мертвого и глаза так, чтобы огонь от них не смог ничему навредить. Она посыпала тела травами и опустилась на колени, прикрыв глаза и начав молиться.",212725,null],[258646,"2026-10-06T22:12:27",17,"/r d20+6+d4 Слух\n\nd20+6+d4 Проницательность",258630,null],[258648,"2026-10-06T22:12:35",17,"/ Увы",212725,null],[258747,"2026-10-07T02:55:49",31,"Во время молитвы ты услышала шёпот. Неразборчивый, похожий на шум моря. Слова, если они и были, ты не разобрала. Только поняла что идут они от линзы, от того самого места, где находился Глаз",258630,null],[258748,"2026-10-07T02:59:08",31,"- Он не обещал. От требовал. Крови. Много крови. Говорил, что без этого ему не вернуть силу, но со мной он справится и так. Сломает. А когда я взял нож и напал на наставника, в потом обагрил линзу его кровью, то она засияла и я  стал превращатся вот в это...",258605,null],[258757,"2026-10-07T07:46:04",22,"Ясмин сжигает тела. \nА после пытается кинжалом подцепить линзу и завернуть ту в ткань, чтобы не прикасаться к ней.",212725,null],[258758,"2026-10-07T07:52:11",31,"От линзы остался один более или менее целый осколок. От него ты и слышишь шепоток. Заверецв его в ткань, ты прячешь сверток в сумку, затыкая его шёпот. Чуть позже надо с ним разобраться и понять, будет ли от него какой то толк",258757,null],[258779,"2026-10-07T08:19:29",22,"Закончив свои дела, Ясмин спускается вниз.\n\nЭй! Что за иждивенца ты подобрала?\nТак это не она бубнит?\nНет, у нас тут новый сосед заводится\nКакой еще сосед?! У нас что тут, коммуналка?!\n\n- Я-я пободобрала это.\n\nДевушка откликается товарищей, не решаюсь подойти ближе к рыболюду.\n\n- От него и-исходит шепот. Д-думаю стоит показать Фелино.",212725,null],[258780,"2026-10-07T08:24:42",17,"— Конечно, вам виднее на счета пколятых предметов, сиора. \n\nМарко поднимает рыболюда и закрывает его в наручники \n\nКивает Беатриче\n\n— Пора возвращаться. И кстате... Нам стоит навестить капитана того судна. Он нам должен, хоть мы делали это не из за меркантильности, я хотел бы получить от него информацию. Где плавал, что видел. Предполагаю что это чудище морское и сидит где то глубоко на дне.",212725,null],[258782,"2026-10-07T08:27:46",20,"*Беатриче кивает в ответ*\n- Да, разумная мысль. Надо ещё посоветовать что-то с синьором Феллино насчёт маяка - нельзя же городу с портом без ориентира оставаться",258780,null],[258783,"2026-10-07T08:31:38",31,"Решайте куда пойдёте и сообщите/",212725,null],[258785,"2026-10-07T08:35:40",17,"/ Ведём рыболюда к Неро",212725,null],[258787,"2026-10-07T08:41:18",31,"Путь в шторм на лодке от маяка к городу был нелёгким. Да еще иашьпленник старался утопиться. Хорошо что вы его сковали, так бы ушел в море. \n\nБлагополучно добравшись до города и проведя Бродерика темными переулками до дома Феллино, вы заявились к табакси-детективу незванныии. \n\nОн встретил вас в пижаме с изображением мышей в весьма фривольных позах (если можете, бахните арт недовольного Феллино в такой пижаме).\n\n- Что привело вас, друзья мои, в столь поздний час?",258785,null],[258793,"2026-10-07T09:11:25",22,"/ Коля, арты на тебе. Я после вчерашнего случая, такие запросы делать не буду🙈",212725,null],[258794,"2026-10-07T09:11:44",31,"А что было вчера?/",212725,null],[258795,"2026-10-07T09:12:07",22,"/я в личке покажу, тут не прилично",258794,null],[258882,"2026-10-07T11:00:33",31,"да, на это и уходит оперативка/",212725,null],[260152,"2026-10-07T23:05:22",17,"— Мило, мы случайно напали на след мистического происшествия. И по нашей уже традиции - дали злу отпор. \n\n\nМарко завел рыболюда в дверь \n\n\n— Маяк был захвачен, линза... Осквернена каким то существом. Злым, естественно. Огромный глаз вместо линзы вел корабль на рифы. Мы смогли помешать. А это помощник смотрителя маяка, он поддался шепоту и обратился в рыболюда, смотрителя он убил.\n\nНе выдержав следователь достал сигарету и закрыл\n\n— Стрессовый день. Так вот... Да. Взяли живым, в надежде разговорить и больше узнать об этом самом шептуне.",258787,null],[260793,"2026-10-08T05:07:22",31,"- ладно, послушаем, что там с вами произошло\n\nФеллино рассаживает вас по креслам, сам занимает свое, и накапав для бодрости ликера, обращается в слух. Выслушав, он задумывается, затем просит у Ясмин передать тот осколок, что она забрала после уничтожения Линзы. Получив просимое, он изучает осколок, словно медитируя над ним, а затем говорит:\n\n- не уверен, что за дрянь поселилась в линзе, но это что то очень древнее, и, похоже живучее или вообще бессмертное. Сейчас этот осколок стал артефактом, полезным, но опасным. Ну-ка, попробую использовать.\n\nФеллино берет осколок руками и подносит к глазу наподобие монокля или лорнета, на его морде появляется выражение боли, но он сдерживает крик, а затем смотрит сквозь осколок на Бродерика. Довольно ухмыляется сквозь гримасу боли и опускает осколок.\n\n- да, я был прав. Эта штука дает истинное зрение, но платить приходится своей болью. И возможно эта боль подпитывает тварь и дает ей возможность вернутся рано или поздно. Что до Бродерика, я вижу что его изменение может быть обратимо. В истинном зрении он все еще человек. Но вот как его вернуть.. Тут я не помогу, не моя сфера. Нужен кто то более подкованый в магии моря, ну или природе, а в идеале еще и сам связанный с морем. \n\nСтарый табакси задумывается на минутку и выдает:\n\n- Эльфы. Морские эльфы. Еще до Катаклизма, до основания Вальдории, тут был их город, ну или не город, они же вроде под водой живут. Не уверен. Но после Катаклизма их города тут нет, а Вальдория получила свое имя по созвучию сих старым названием, не уверен как оно произносится, но пишется вот так.\n\nНеро пишет на бумажке: Eldavaldórë\n\n- Что то вроде \"священная гавань\", насколько я могу судить. Ну да о чем бишь я? Думаю, чтобы разобраться как быть с этим созданием в линзе, нужно найти представителя этого народа. Хотя это будет сложно, эльфов в принципе немного осталось в мире, и где искать именно морского, да еще и сведущего в магии, я слабо представляю. Но думаю, могу поробовать что то выяснить в трансе. Но чуть позже, еще есть что обсудить. Пока заберите осколок, Ясмин. Можете пользоваться, но осторожно, не злоупотребляйте.",260152,null],[260807,"2026-10-08T05:09:49",31,"- я не уверен, что это полностью безопасно, и кажется что каждый раз когда вы отдаете часть здоровья, вы помогаете монстру стать более сильным. Но пользоваться можно. Иногда",212725,null],[260824,"2026-10-08T05:14:08",31,"- Что до Бродерика и маяка. Боюсь, молодого человека ждет тюрьма. Он убийца, хоть и действовал под внушением. Это скостит срок, но тюрьма или каторга обеспечены, тут я не буду выкручиваться. Постараюсь помочь добиться послабления, может каторги в море, потому что без воды он умрет, во всяком случае, пока не станет снова человеком. С маяком тоже решим вопрос, я напишу знакомомув Магистрате, нельзя портовый город без маяка оставлять. Возможно, вы получите награду, но сильно не надейтесь, Магистрат скуповат на похвалы тем, кто проявил инициативу без предварительного согласования бюджета.",212725,null],[260845,"2026-10-08T05:23:32",31,"- Ладно, теперь к самому неприятному, поищем морских эльфов.\n\nНеро закрывает глаза, откидывается в кресле и начинает что то вроде медитации, вы такое уже видели. Но в этот раз ему похоже тяжелее, дыхание прерывисто, старый табакси стонет от боли и открывает глаза. из обеих его ноздрей идет кровь, глаза тоже полны лопнувших каппилляров. Он обхватывает голову руками, и упирается локтями в стол. Шумно выдохнув, говорит:\n\n- Силён.... и скрытен. Друид, похоже... Где-то в лесу, на северо-западе. Точнее не скажу, не пустил он меня, отшвырнул как котенка... Старый, сильный... Он может что то знать, но как вы с ним будете говорить,  не представляю... Есть еще девушка того же народа, но она слишком молода и врядли вам поможет, у нее своя дорога...\n\nДетектив откидывается на спинку кресла, он измучен",212725,null],[260852,"2026-10-08T05:24:40",31,"//девочка-эльф это просто отсылка в персонажу соло-квеста, который я буду вести, ее можете не искать, просто введена тут для глубины мира//",212725,null],[260923,"2026-10-08T08:31:06",22,"Друиды? Какая мерзость!\nРаздражающие, глупые защитнички\nОни постоянно мешают нам веселиться!\nУбийцы веселья, да! Баланс! Нужен баланс! Фе!\n\n- Д-друид.. Друиды же добрые, да? Он не откажет в п-помощи?\n\nВ глазах Ясмин загорелась надежда.\n\nМожет друид поможет мне избавится от.. них.\n\nИзбавиться? Мы это ты!\nА ты это мы!\n\nЯсмин посмотрела на свою руку, покрытую копотью и морщинами. Она попыталась прочитать молитву, чтобы хотябы когти вернули обратно, но ничего не произошло.\n\nСкривившись неудаче, девушка опустила намотанную на предплечье ткань пониже, прикрывая кисть. \n\nОт своей природы не убежишь. Никакой друид тебя не \"спасет\", дочка. Ты не нуждаешься в спасении.",212725,null],[260934,"2026-10-08T08:34:07",31,"- Дброта друидов, милая Ясмин, сильно преувеличена. Они любят только природу, но даже такая любовь может принимать странные формы. Старый друид скорее будет людей просто терпеть.\n\nФеллионо смотрит на тебя и вокруг тебя. Он словно видит тех, кто кружит над тобой незримыми тенями. Похоже, истинное зрение показывает твою родню вокруг тебя. Или у тебя приступ паранойи",212725,null],[260940,"2026-10-08T08:41:02",22,"Ясмин кивнула и стиснула зубы.\n\n- Наверное н-нам пора. М-мы и так вас разбудили в такую р-рань.",212725,null],[260943,"2026-10-08T08:42:48",31,"Феллино, вытирая кровь с усов и с сожалением смотря на заляпаную пижаму\n\n- да, пожалуй. Если решите отправится в лес, о удачи вам тай найти друида. Без нее у вас ничего не выдет",212725,null],[263061,"2026-10-09T08:41:31",31,"@lady_godzilla @dunchev @PaIIasCat \n\nРебята и девчата, сегодня играем? Что то квест из побочного у меня вдруг начал вырастать с сюжетный и я даже под него кое чего переделал в плане. У вас сейчас несколько вариантов, из числа тех что я давал: Навестить гоблина, отправится искать друида в лесу (это будет сложно, я еще не дописал квест по его поиску), ждать прибытия корабля со свидетелем. Ну или искать что то еще в городе, я хрен знает чего вы хотите, может Орочи навестите и познакомитесь)) Это шутка если что, я его никак еще не вписывал сюда)",212725,null],[263062,"2026-10-09T08:42:06",17,"/Щас раздупляюсь с утренними делами",212725,null],[263064,"2026-10-09T08:43:21",31,"сколько уровней в домовятах? я до 287 вроде дошел, когда конец?)/",263062,null],[263065,"2026-10-09T08:43:36",17,"/ Там больше 5000",212725,null],[263066,"2026-10-09T08:43:46",31,"ебушки-воробушки/",263065,null],[263067,"2026-10-09T08:43:49",17,"/И по 200 в неделю стабильно выходит",212725,null],[263092,"2026-10-09T08:55:41",17,"— Сеньор Фелино. Есть сведения по черной земле?\n\nМарко выглядит уставшим, новая цель была намечена, он понимал важность расследовать связь морского существа и спокойствие Вальдории. Понимал значимость и важность. Но важнее всего для него был не город, не благополучие, не спокойствие, не даже собственная жизнь. Важным он считал найти свою дочь, поэтому всегда ставил эту цель выше остальных.\n\n— Я безусловно согласен с вами, нужно срочно заняться этим происшествием. Но я не могу не спросить о самом важном для меня деле, сиор.",260943,null],[263104,"2026-10-09T08:59:49",31,"- да, земля. Я послушал совета гоблина и обратился к тем, кто имеет отошение к земле. К могильщикам. Они признали, что земля похожа на ту, что им приходится копать для могил. Для самых глубоких могил. Подзол, они сказали. Такая земля под деревьями чаще всего. Это пока все",263092,null],[263114,"2026-10-09T09:06:43",22,"//вот это проблемы у людей😁\n\nА я в судоку залипаю",263066,null],[263115,"2026-10-09T09:07:13",31,"я думал быстро пройду) а тут жизни не хватит)/",263114,null],[263116,"2026-10-09T09:07:25",31,"судоку тема, тоже люблю/",212725,null],[263119,"2026-10-09T09:09:00",17,"Марко всё подробно записал\n\n— Уже что-то. Деревья значит. Нужно будет обращать внимание вдруг будет необычное. Спасибо, продолжим искать зацепки.",263104,null],[263121,"2026-10-09T09:10:55",17,"— Тогда отдохнём и отправи....\n\n— КХА КХА КХА\n\nТяжелый приступ кашля скрутил его, серебро рвало альвиолы внутри. Марко еле еле успел ухватится за сервант со стеклом и к сожалению продамил стекло на дверки внутрь.\n\nЗвук бутылок Лиёкера и красивых хрустальных бокалов внутри зазвенел алая кровь полилась по ним наполняя частично, Марко сильно порезал руку",212725,null],[263122,"2026-10-09T09:11:01",17,"/r d10 Снижение максимума ХП",212725,null],[263125,"2026-10-09T09:11:53",31,"тебя вроде подлечили, разве нет?/",212725,null],[263126,"2026-10-09T09:12:22",17,"/Частично",263125,null],[263127,"2026-10-09T09:12:35",17,"/ Ты что хочешь чтобы я отказался от кальяна в компании прекрасных дам?",212725,null],[263128,"2026-10-09T09:12:41",17,"/ Я выжму из этого максимум!",212725,null],[263129,"2026-10-09T09:12:46",17,"/ Лечение 1/100",212725,null],[263132,"2026-10-09T09:13:51",31,"1/100 все т аки многовато)/",212725,null],[263133,"2026-10-09T09:13:58",17,"/ 1/99",212725,null],[263134,"2026-10-09T09:14:03",31,"ты кончищься быстрее)",212725,null],[263135,"2026-10-09T09:14:27",31,"хотя дело твое, раз сам себе так прописал, доктор Марко/",212725,null],[263136,"2026-10-09T09:14:30",17,"/ По квенте у меня всего 5 лет осталось жизни",212725,null],[263137,"2026-10-09T09:15:02",22,"//это какой доктор тебе такое сказал? Показывай справку",263136,null],[263138,"2026-10-09T09:15:04",31,"мне нужно чтобы ты хоть покачаься успел для финала)/",263136,null],[263139,"2026-10-09T09:15:17",17,"/ Это в книге мёртвых появилось моё имя и дата смерти",263137,null],[263140,"2026-10-09T09:15:44",22,"//ой! Сомнительный источник! Ща пойдем лечиться, я кофейку только глотну",263139,null],[263142,"2026-10-09T09:17:00",31,"а скольео тебе осталось до этой даты? Меньше года?/",263139,null],[263143,"2026-10-09T09:17:26",17,"/ Не знаю, реши сам",263142,null],[263146,"2026-10-09T09:24:08",22,"Ясмин в ужасе перехватила руку Марко и попыталась излечить.\n\n- К-кажется одного сеанса было м-мало. Но у меня осталось еще несколько п-порций, нужно повторить л-лечение. Беатриче, с-сотавите нам компанию сегодня?\n\nДа куда ты в кровь то лезешь, фу!\nВон кровосиське дай, пусть поест, а то щеки уже впали\n\nЯсмин посмотрела на Беатриче внимательнее. \n\nА что если она и правда.. голодная?\nНет нет. Она же не будет нас есть. Она хорошая. Ведь не будет же, да?",212725,null],[263268,"2026-10-09T10:23:45",20,"- Лечение? Это та инга-штука которую вы упоминали, синьора? *Беатриче с беспокойством смотрит на Марко*\n\n- Конечно, я полностью к вашим услугам. Могу захватить бутылочку нашего фирменного семейного амаретто - неплохо помогает смягчить горло при кашле.\n\n*Выглядит она вроде не особо голодной, но вот по бокальчику похоже пропустить не против после всей этой херни на маяке*",263146,null],[263273,"2026-10-09T10:25:31",17,"/Хочу узнать поподробнее о чем Беариче говорила с семьёй по РП у нас ХАБ для социалки - кальянная",212725,null],[263274,"2026-10-09T10:25:39",17,"/Помоему ну просто супер!",212725,null],[263275,"2026-10-09T10:25:47",17,"/И у Ясмин припадок был в конце",212725,null],[263276,"2026-10-09T10:25:59",17,"/А я в этот раз сработал четенько без эксцессов!))",212725,null],[263278,"2026-10-09T10:27:08",22,"//ну не по барам же шататься, а тут вот атмосфера 👌",263273,null],[263287,"2026-10-09T10:30:08",31,"Соцтальте, ребята. А я поработать пока вынужден",212725,null],[263312,"2026-10-09T10:48:30",22,"//у меня уже истерика от бесячего оформления в тг, которое скачет если ты сначала пишешь в заметках",212725,null],[263321,"2026-10-09T10:54:29",20,"*Беатриче с любопытством оглядывается - несмотря на образ жизни она похоже не частно бывала в таких местах, больше предпочитая более классические для Вальдории заведения*\n\n- Какой у вас интересный выбор заведений, синьора. *Она на пробу втягивает воздух, с непривычки кашлянув от обилия благовоний*\n- Кхе, но интенсивность тут конечно не скромная.\n\n*Беатриче следует за спутниками - ей очень интересны традиции этого места, тем более что дух заведения и интерьер чем-то напоминают ей саму Ясмин.*",263311,null],[263324,"2026-10-09T11:01:26",20,"- Это ведь что-то из культуры вашей родины, Синьора Ясмин? Те узоры очень похожи на ваши в одеждах. Да и запах благовоний схож.",212725,null],[263348,"2026-10-09T11:38:45",22,"- Верно. Я.. Я чувствую б-близость к дому, когда п-прихожу сюда.\n\nЯсмин улыбнулась, иллюзия на ее глазах дернулась и золотой глаз мягко засиял. Голос девушки чуть изменился, приобретая лёгкую хрипотцу.\n\n-- Кардамон, роза, мята… Люди так старательно маскируют запах тления. А ведь всё живое уже начало гнить с момента рождения.\n\nКхе-кхе-кхе\n\nЯмин закашлялась.\n\n-- Устала. Н-ночь была долгая.",212725,null],[263351,"2026-10-09T11:41:16",31,"Кстати да, вы вообще не спите)/",212725,null],[263352,"2026-10-09T11:41:25",31,"Уже вторые сутки вроде/",212725,null],[263355,"2026-10-09T11:47:48",17,"Марко зашел последним усталость уже валила его с ног, человеческое тело имеет лимиты и они на исходе. После приступа он извинился перед Неро и оплатил ремонт серванта, хотя детектив не хотел брать брать денег, Марко настоял.\n\n— Мне действительно стало лучше после... прошлого лечебного сеанса. Видимо мы станем постоянными гостями. Спасибо, сиора Ясмин, что не бросаете безнадёжного пациента.\n\nМарко прошел внутрь за занавес, снял своё длинный плащ, закатал рукава на рубашке и вальяжно упал в россыпь подушек на диванчике.\n\n— Беатриче, сиора, не сочтите за грубость, мне очень интересно как прошел ваш разговор с роднёй, в свете того, что сказал сиор Сангвини. Если я лезу не в своё дело, скажите прямо, прошу прощения заранее.",263348,null],[263357,"2026-10-09T11:47:54",17,"/Щас все уснут в кальянной",212725,null],[263396,"2026-10-09T12:01:41",20,"- Не беспокойтесь синьор Марко - мне нечего скрывать от вас. *Беатриче тоже проходит, садясь на подушки. Слегка хмурится - странно, она вроде это уже рассказывала*\n\n- Ну, начну наверное с самого главного - этот ублюдок действительно не мой отец. Девятнадцать лет назад он пришел к моей семье с предложением - вырастить особый сорт винограда на земле, богатой серебром, какие-то бывшие рудники. Вино, получившееся из этого винограда он забрал себе, а вот родителям...в ту ночь он заставил их выпить вино, смешанное с его кровью в качестве своей 'милости'. *Она оскаливается на этом слове*\n\n- Это и стало причиной, почему я родилась такой какая есть. Хотя на думаю что Эдриан знает о моем существовании - почти сразу после произошедшего он как раз и был изгнан из города.\n\n*Она задумчиво проводит по витиеватой гарде рапиры*\n\n- Но это не надолго. Рано или поздно кто-то из нас найдет другого. И тогда я закончу то, что начал отец в ту ночь.",263355,null],[263398,"2026-10-09T12:02:30",22,"//как домой завалился. Надо было мне прописывать, что Яс тут живет, а не в таверне",263355,null],[263405,"2026-10-09T12:10:58",22,"// в общем __ это для курсива. Но тг издевается как может. Так что просто используйте силу воображения 🥲\nА - периодически становятся • \nЯ прям горю с этого",212725,null],[263407,"2026-10-09T12:12:19",17,"Марко, уже почти закрывший глаза, при упоминании серебряных рудников снова приподнял голову\n\n\"Серебро в почве, кровь в вине. Не слишком ли сложный способ кого-то обратить?\"\n\n— Сиора Беатриче, позвольте несколько вопросов. Во-первых, откуда вам известны подробности той ночи? \n\nМарко сел ровнее, усталость на время уступила профессиональному интересу\n\n— Вовторых, кто-нибудь кроме ваших родителей пил то вино? И что с ними произошло после? Они изменились или последствия проявились только в вас?\n\nОн задумался\n\n— И последнее. Что стало с тем виноградником? Вы знаете, где именно находились рудники? Возможно, дело было вовсе не в вине, а в том, что находилось под землёй",263396,null],[263408,"2026-10-09T12:12:36",17,"— Серебро не вызывает привыкание, обычно",212725,null],[263423,"2026-10-09T12:22:49",20,"- Хм, ну все что я рассказала мне известно со слов матери и отца. *Беатриче задумывается, начиная последовательно отвечать на вопросы*\n\n- Пили вино только родители, последствий помимо влияния на беременность у матери вроде не было. Ни привыкания, ни проявления вампирских черт у них самих.\n\n- А где находились виноградники я тоже не знаю, но могу спросить. Хотя я полагаю что Эдриан просто искал способ поэкспериментировать в употреблении серебра - вот и решил сделать вино с его высоким содержанием.\n\n- Ну а то что он сделал с родителями...синьор Энрико упоминал, что у него бывали резкие перепады между агрессией и милостью - возможно это был один из таких.",263407,null],[263426,"2026-10-09T12:24:41",20,"- Пожеланий у меня особых нет, синьора *она машет рукой, доверяясь профессионалу.*\n\n- Делайте на свой вкус - я в любом случае не задохнусь даже если постараюсь, хаха.",263403,null],[263466,"2026-10-09T12:45:45",17,"— Всё же думаю мы могли бы проверить, вдруг будем рядом, то что я вдохнул, возможно не совсем обычное серебро. Да, поступок был явно глупые, на секунду мне показалось, без такого риска нам всем конец. Поэтому я решился на крайние меры. Всё же зависимость вампирских отродий от серебра - очень странная вещь, ведь оно ранит их проста касаясь кожи, что уж говорить о приёме внутрь. Но зачем то они это делают. Должен признать, когда вдохнул его, почувствовал прилив сил.\n\nМарко вспомнил до мельчайших деталей и описал своё состояние тогда\n\n— Возможно природа, мистическая",263423,null],[263467,"2026-10-09T12:46:47",20,"- Ну, магию думаю можно и проверить - шкатулку с остатками серебряной пыли все ещё у вас",263466,null],[263470,"2026-10-09T12:48:34",17,"— И то верно\n\nмарко разворачивает кригу мёртвых и привычно собирается уколоть палец, но рука распаласована и так, так что он просто мокает указательный в рану под бинтами и вырисовывает глаз на странице книги\n\nЧерез некоторое время его глаза загораются золотым свечением и она направляет взор на тубакерку с остатками серебрянной пыли",212725,null],[263482,"2026-10-09T12:53:35",31,"Это заявка? Ну давай магию, анализ или природу/",263470,null],[263484,"2026-10-09T12:57:05",17,"/r +d20+6+d4 Великие следователи анализируют",263482,null],[263486,"2026-10-09T12:57:41",17,"/Вместе с Беатриче жестко анализируем",212725,null],[263487,"2026-10-09T12:58:22",31,"Ух вы анализаторы конечно. Ужаснах",212725,null],[263488,"2026-10-09T12:59:48",31,"Полуобморочный Марко и накуренная Беатриче умудрились понять, что серебро все таки неоднородное. Там есть мелкая примесь органики, судя по всему это грибная пыльца",212725,null],[263489,"2026-10-09T13:01:25",17,"— Вот как... Грибная пыльца мельчайшая. Скорее всего серебро чтобы пыльца впиталась в организм, ранит, а пыльца проникает в ранки",212725,null],[263490,"2026-10-09T13:01:34",17,"— Но вот что это за грибная пыльца...",212725,null],[263491,"2026-10-09T13:01:38",17,"— Новый вопрос",212725,null],[263496,"2026-10-09T13:08:11",22,"-- Можно с-спросить у друида. Если найдем его. \n\nЯсмин посмотрела на полуобморочных товарищей и убрала пару уголков, чтобы сделать кальян послабее.",263490,null],[263498,"2026-10-09T13:09:40",17,"— Точно... Друид. Очень правильное направление. Тогда всё сходится, нам не придётся распыляться по разным сторонам.",263496,null],[263500,"2026-10-09T13:14:01",31,"Наверное я вам засчитаю квест с маяком сейчас. Поиски друида будут сложнее, изначально он у меня по плану был позже. Думал после корабля и свидетеля будет. Но в целом нормально, один хрен мне вас убить сложно)))/",212725,null],[263501,"2026-10-09T13:15:36",22,"Ясмин насильно сунула Марко трубку в руку.\n\n- Х-хватит болтать. Вы так н-никогда не вылечитесь.\n\nВскоре подавальщица мягко спросила разрешения войти, после чего расставила ароматные блюда, напитки и удалилась, оставив гостей отдыхать.",212725,null],[263504,"2026-10-09T13:18:17",17,"Марко приложил ладонь к виску, что означало \"Как прикажите госпожа врач\" 🫡",263501,null],[263505,"2026-10-09T13:19:58",31,"Так, учитывая что бой для вас был очень легким, то я видимо занижу опыт. Это скорее пином мне, а не вам\n\n600 за бои\n300 за закрытие квеста\n200 за отыгрыш, тут бы больше дал, но лимит, сука\n\nИтого по 1100 опыта вам. Не знаю хватит ли вам для левел апа, но думаю что да./",212725,null],[263506,"2026-10-09T13:20:37",31,"Как досицивлите, скажите мне точно, куда идёте. К гоблину или сразу в леса, друида ловить/",212725,null],[263522,"2026-10-09T13:35:40",17,"— Сиора, Ясмин. Теперь хочу спросить вас. Я замечаю иногда, как вы говорите сами с собой, но будто бы отвечаете кому то, у вас строится диалог. Особенно это было заметно в стрессовой ситуации сразу после победы над дьявольской линзой... Вы устали... От чего вы устали? Может мы можем помочь?",258442,null],[263523,"2026-10-09T13:35:57",17,"Марко открыл блокнот с заметками о Ясмин",212725,null],[263525,"2026-10-09T13:37:44",17,"/ @lady_godzilla",212725,null],[263526,"2026-10-09T13:38:06",17,"/ Разбор полётов помогает синхронизироваться между собой, устаканить общее понимание, мне нравится",212725,null],[263536,"2026-10-09T13:40:15",22,"//20 мин вернусь с прогулки напишу пост",212725,null],[263671,"2026-10-09T14:24:41",17,"/ Беги это вслух?",263653,null],[263680,"2026-10-09T14:26:05",22,"//все,  я ультанула👌",212725,null],[263684,"2026-10-09T14:26:46",17,"/ Пупупу будем реакктить, надо подумать, шахматы начались снова",263680,null],[263690,"2026-10-09T14:28:10",22,"//а ты думал только тебе можно так со мной обращаться?😅",263684,null],[263708,"2026-10-09T14:33:50",22,"/Заметила что дурацкое погружение в лавкрафчину отразилось на стилистике моих текстов:\nНевозможные углы, невообразимые формы😭",212725,null],[263778,"2026-10-09T14:57:11",17,"Марко невольно отпрянул от трёх старух из дыма, рука сама потянулась к символу Анубиса под рубашкой\n\n\"Три старухи и все трое видят через её глаз?\"\n\n— Признаться, сиора, ваши родственницы меня несколько пугают. Особенно ваша маменька, что положила глаз на мои внутренние органы\n\nМарко нервно усмехнулся, но быстро стал серьёзным. Посмотрел на Ясмин, потом на открытый блокнот и закрыл его\n\n— Понимаю ли я? Нет, наверное нет. Я даже не представляю, каково это, не иметь возможности остаться наедине с собственными мыслями\n\nОн помолчал\n\n— Но знаете, Ясмин, я ведь разговариваю сейчас с вами. Не с ними. И мне бы очень хотелось, чтобы так оставалось и дальше\n\nМарко подался немного вперёд\n\n— Позвольте очень важный вопрос. Они могут заставить вас что-то сделать против вашей воли? Управлять вами? Вашими руками, вашим голосом?\n\nОн бросил ещё один настороженный взгляд на дымных старух, потом разогнал дым рукой\n\n— Я хочу попытаться понять и помочь, пока не знаю чем.",263677,null],[263834,"2026-10-09T15:08:00",20,"*Беатриче наблюдает за силуэтами из дыма, хмурясь*\n\n- Семья? Это? Ох сеньора... *Она смотрит на Ясмин с сочувствием и каким-то странным сожалением*\n- Мне жаль, что вместо того, чтобы быть вашей опорой и тихой гаванью, ваша семья вынуждает вас бежать и от них и от себя. Это как-то очень... неправильно. И грустно.\n\n- Мне тоже сложно представить через что вам приходится проходить. Для меня моя кровь и имя рода всегда были предметом гордости и моральной опорой. Сложно представить, что кому-то приходится идти против своих корней - даже будь эти корни, ну...такими. *она снова кидает взгляд на дымные фигуры*",263677,null],[266921,"2026-10-11T11:22:09",17,"Марко заметил, как Ясмин отодвинулась от него. Он немного смутился и вернулся на своё место, убрав блокнот подальше\n\n— Простите, сиора. Старая привычка. Порой забываю, что не каждый разговор должен превращаться в допрос\n\nОн посмотрел на три дымные фигуры\n\n— Я бы многое отдал, чтобы снова услышать голос своей семьи. Хотя бы на минуту\n\nОн замолчал, опустил глаза на свои руки\n\n— Но это не значит, что я хотел бы, чтобы семья заставляла меня делать. что то против моей воли.\n\nМарко посмотрел на её руку, которая только что изменилась прямо у него на глазах\n\n\"Она боится перестать быть собой\"\n\n— Я очень рад, что мы встретились, Ясмин. И с вами, сиора Бетариче. Наверное для этого и нужны друзья, чтобы не дать друг другу сойти с ума, чтобы помогать с некоторыми... недугами. \nМарко чуть улыбнулся\n\n— И просто проводить время вместе, кажется у нас с вами пока получается делать кое что хорошее",263923,null],[268676,"2026-10-12T07:11:44",31,"@lady_godzilla @dunchev @PaIIasCat \n\nДоброе утро. Пора заканчивать графоманить без дела))) Вас ждут два квеста, первый от гоблина по созданию огнемета (вероятно, более социальный), а второй по поиску друида в лесу (вероятно, более боевой). Решайте, куда идем, играть в лего или гулять по лесу))) И погнали. И не забудьте поднять уровень, там уже должно хватить///",212725,null],[268677,"2026-10-12T07:47:45",17,"/ Да будто бы за огнеметом можно заскочить собрать ресурсики и скрафтить",212725,null],[268684,"2026-10-12T08:26:25",22,"/уровень апнула, да, давайте за огнеметом",212725,null],[268687,"2026-10-12T09:02:41",31,"ну отписывайте тогда, что вам захотелось навестить Нак-Нака и узнать, что он там вычитал в чертежах./",212725,null],[268688,"2026-10-12T09:07:46",17,"Девушка из обслуги стоит за шторой\n\n— Кхм кхм, извините дорогие гости. Гонец передал письмо от Неро Фелино для вас сиора, Ясмин.\n\n\"Ясмин, ваш чертёж наделал шуму, в прямом и переносном смысле. Нак Нак что-то взорвал в мастерской которую ему обустроили, прошу вас явиться и разобраться с этим происшествием. Он всё бегает по дому и кричит \"Получилось получилось!\"\n\nНеро Фелино\"",212725,null],[268689,"2026-10-12T09:15:39",22,"Ясмин оторвалась от мыслей о собственной ничтожности и безхребетности и взглянула на записку. \n\nЕе глаза распахивались все больше, а по лицу расползалась широкая улыбка.\n\n-- Да будет свет! Я в-верила, что это с-случится однажды..\n\nДевушка повернулась к товарищам.\n\n-- Вам удалось отдохнуть? Если нет, то д-давайте я оставлю вас здесь, у меня п-появилось срочное дело по тому ч-чертежу, что я купила. Кажется гоблину у-удалось его реализовать. Н-наверное.",212725,null],[268690,"2026-10-12T09:18:46",20,"- Что-то случилось, Сеньора? *С интересом спрашивает Беатриче. Что этот забавный гоблин умудрился там учинить...*",268689,null],[268691,"2026-10-12T09:26:40",17,"Марко приподнялся потягиваясь\n\n— Удалось, покой нам только снился, что там?",268689,null],[268692,"2026-10-12T09:27:11",22,"-- Д-да! Когда я покупала т-травы для лечения,\n\nЯсмин махнула рукой в сторону кальяна,\n\n-- Торговец показал мне о-один чертеж. Я не очень х-хорошо в этом разбираюсь, но тут, с-словно сам с-свет велел мне обязательно взять чертеж и показать нашему г-гоблину.\n\nДевушка заикалась сильнее обычного из-за явного переизбытка эмоций.\n\nО, воистину, дева без огнемета - что склеп без свечки: темно и скучно \n\n-- И-и Ф-фелино пишет, что к-кажется гоблину удалось! Х-хочу с-скорее посмотреть !",268690,null],[268693,"2026-10-12T09:27:54",22,"//чет слабо конечно, но у меня тяжелое утро и всего одна чашка кофе. Пока.",212725,null],[268694,"2026-10-12T09:28:31",17,"/ Фонд золотых циатат",268692,null],[268696,"2026-10-12T09:29:03",22,"//да слабовато, но я не смогла выдавить больше ироничности\n\n\nМеня дебильный мем про инквизицию не отпускает",268694,null],[268698,"2026-10-12T09:32:20",20,"- Значит где-то там самый разгар веселья с огоньком, а мы сидим здесь?! - *Беатриче ахает, драматично прикладывая руку к груди*\n\n- Возмутительно, просто возмутительно. *Уже встаёт*\n- Мы срочно должны отправится туда. Если что-то и пойдет сегодня не так я хочу бы быть в первом ряду",268692,null],[268699,"2026-10-12T09:33:03",17,"/ Да помоему не плохо) Ты слишком строга к себе, а что за мем кста?",268696,null],[268701,"2026-10-12T09:34:12",22,"//если быть честной, то именно этот мем вдохновил на жрицу света🙈",212725,null],[268702,"2026-10-12T09:34:13",17,"/Драгн эдж инквизишон",268700,null],[268703,"2026-10-12T09:34:18",17,"/Спорная игруха, но я прошел",212725,null],[268704,"2026-10-12T09:34:57",22,"@QURTZZ сколько с нас? Затраты на существование богатое(4 зол с носа) или с правилами кутежа?",212725,null],[268705,"2026-10-12T09:35:53",31,"за посиделки? да сами решайте, я тут в ценах плаваю/",268704,null],[268706,"2026-10-12T09:36:35",22,"//тогда по 4 золотых за богатую тусовку \nПить не пили, так что без кутежа",212725,null],[268707,"2026-10-12T09:36:57",22,"//мне пришлось этот блок очень тщательно изучить...",212725,null],[268708,"2026-10-12T09:37:22",31,"Приняв решение, а заодно подгретые кальяном и разговором по душам, вы отправились к жилищу-мастерской Нак-Нака. Склад выглядел нормально, пок райней мер он был на месте. Это обнадеживало. Вы вошли без стука\n\nНак-Нак в своем складе очевидно времени не терял. Вас встретил полнейший разгром, все было перемешано, в углу валялись останки Крабика, а сам подкопченный хозяин помещения корпел над чертежом, высунув язык. Не сразу, но он заметил вас, и подскочил в крайней степени энтузиазма\n\n- Получилось! Бухнуло! Только, правда, один раз… Но я знаю как исправить! Давай свой арбалет -тянет лапы к Ясмин, и получив требуемое, пускается в объяснения\n\n- тут мы приладим бачок из латуни, я такой у дварфов видал, он им для литья нужен. Искру даст камешек что от Крабика остался. Еще нужен распылитель, чтобы огнем плевать, это нужно у гномов добыть, они такое делают, я точно знаю, механизм как у фонтанов, только меньше. Только вот с топливом затык… То что описано я смешал, но оно бухнуло и сожгло все. Нужно что то постабильнее, не кустарное. Это вам нужно в Восточный квартал, тамошние алхимики умеет фейерверки делать и много еще какой дряни. Вот вам  там надо порыскать, поискать алхимиков. Да и убедить отдать свои порошки, они там только тем кого знают продадут. Во вы в общем идите, поищите запчасти, а я пока к арбалету камень с искрой прилажу",212725,null],[268710,"2026-10-12T09:38:31",31,"- или непонятно чего?",212725,null],[268711,"2026-10-12T09:41:01",22,"-- З-значит бачок из латуни у дварфов, р-распылитель от гномов и п-порошки алхимиков.\n\nПусть первый залп сам сделает\nКопчёный гоблин\nЗвучит вкусно\n\n-- Ты с-с нами?",212725,null],[268712,"2026-10-12T09:42:33",31,"– ну, вооюще мне бы надо арбалет подготовить... но, ладно, схожу с вами, а то возьмете какую нибудь ерунду не ту\n\nГоблин старается казаться важным, но вы раскусили его, он рад что его позвали с собой",268711,null],[268713,"2026-10-12T09:46:43",22,"- Д-давайте начнем с д-дварфо, если никто не п-против?\n\nЯсмин закусила губу и теребила свое платье. Ее взгляд бегал от гоблина на арбалет, от арбалета на дверь.\n\n-- Т-так нетерпится!",212725,null],[268714,"2026-10-12T09:53:49",31,"- да, дварфы ближе всех со своими кузнями. Гномы чуть дальше живут, а алхимики вообще далеко, за Верфями. Только вы сами с ними говорите, а то я ляпну что то нето",212725,null],[268715,"2026-10-12T10:03:21",31,"Ремесленный кваратал встретил вас привычными лязгающими звуками, дварфы, вернув клещи, развернули бурную деятельность, спеша отрабоать отложенные заказы. Вам показалось логичным поболтать со знакомым страшиной Гильдии, мастером Боленом. Вы нашли его за обедом в кузне, он смачно слувал пену с кружки пива и выглядел крайне довольным жизнью",212725,null],[268716,"2026-10-12T10:14:26",17,"Марко первым подошел к дварфу\n\n— Мастер Болен, мы к вам с рабочим вопросом. Ищем бочек из латуни для одного агреггата. Можете подсобить?",212725,null],[268717,"2026-10-12T10:16:05",31,"Болен попыхивает трубочкой, улыбается своим мыслям и тебе.\n\n- ну найдется, конечно. А вам зачем?",268716,null],[268718,"2026-10-12T10:19:24",22,"- Дабы явить величие света смертным!\n\nЯсмин сложила руки в мотитвенном жесте и прикрыла глаза.",268717,null],[268719,"2026-10-12T10:20:04",31,"Выступление/",268718,null],[268720,"2026-10-12T10:20:29",31,"Можно с преимуществом, он благодушен/",212725,null],[268721,"2026-10-12T10:24:32",22,"/r +d20+1 Выступление со спецэффектами",268719,null],[268723,"2026-10-12T10:28:07",31,"Болен впечатлен, трубка падает из рта.\n\n- ну, раз дело такое, считай святое, то конечно дам.\n\nОн с кряхтением поднимается, идет в подсобку, пару минут там чес то гремит и выходит обратно с ёмкостью примерно в литровую банку, передает ее Ясмин. Но Нак-Нак перехватывает ёмкость, сует туда нос с важным видом, осматривает и одобрительно кивает, пряча емкость в мешок.",212725,null],[268725,"2026-10-12T10:36:49",22,"-- О-отлино! Так приятно о-осозновать, что мир не б-без добрый людей! \n\nЯсмин поворачивается к гоблину.\n\n-- Т-теперь к гномам?",212725,null],[268726,"2026-10-12T10:36:54",17,"— Что мы вам должны?",268723,null],[268727,"2026-10-12T10:37:24",31,"- оставьте себе, это один чёрт некондиция. Да и мы вам должны были",268726,null],[268728,"2026-10-12T10:37:30",22,"//я даже и не думала платить..  мне стыдно(",212725,null],[268729,"2026-10-12T10:40:39",17,"Марко кланяется и откланивается\n\n— Где мастерская гномов? Нак-нак ты знаешь?",268727,null],[268730,"2026-10-12T10:43:43",20,"- О, раз к гномам идём можно и шкетов проведать *Беатриче улыбается, вспоминая мальчишек с телескопом*\n- Я как раз хотела им кое-что передать",268729,null],[268731,"2026-10-12T11:19:23",31,"Извините, меня работа поймала, отпишу чуть позже/",212725,null],[268755,"2026-10-12T13:16:01",31,"- не мастерская, в мастерские. Много их. Я к ним ходил наниматься, но они меня прогнали. Я оттуда и знаю про распылители, сам их видел. Пойдем те, я вас провожу.\n\nГоблин потрусил дальше в глубь Ремесленного района. Гномья его часть была куда как менее шумной, чем у их соседей-дварфов. Тут занимались в осноаном мелкой машинерией и ювелирным делом. В одной из мастерских, не особо примечательных, вас и привел Нак-Нак. На небольшом аккуратном здании висела вывеска \"Мастерская Музыкальных фонтанов Боддинок и сыновья\".\n\n- Вот сюда я и приходил. Этот самый Ботинок меня и выпнул. \n\nВы входите в небольшое помещение, это приемная с большим рабочим столом, уставленном различными узлами и механизмами. Хозяина не видно, но на столе вы видите звонок.\n\nГоблин впивается взглядом в какую то конструкцию из трубок и бочком незаметно к ней подходит",268729,null],[268757,"2026-10-12T13:22:11",31,"В момент когда вороватые лапки Нак-Нака потянулись к конструкции, он взвизгивает и хваатется за ухо. Вы замечаете что от него отскакивает медкая гаечка.\n\n- Я так и знал что он до нас дойдет! А папа не верил!\n\n- из за стола показывется голова крошечного гноменка, который видимо и подбил Нак-Нака метким броском. Беатриче узнает своего мимолетного знакомого с крыши, который с приятелями пытался построить телескоп",212725,null],[268761,"2026-10-12T13:27:19",17,"— Доброго дня. Мы ищем распылитель для одного изобретения, можем приобрести его у вас?",212725,null],[268763,"2026-10-12T13:30:24",20,"*Беатриче посмеивается, наблюдая за этим*\n\n- Похоже эта мастерская под суровым надзором, Нак Нак. Так что трогать все только после покупки.\n\n*Она смотрит на мальчика*\n\n- Привет шкет, твой отец не в лавке?",268757,null],[268764,"2026-10-12T13:36:12",31,"- ой, миледи, здрасьте! Нет, папка на сим-по-зи-ме. Я не знаю что это, но мама сказал что если он придет пьяный, то она его побреет скалкой! А вы поймали этого зеленого вора, да!?\n\nПотом замечает и слышит Марко, и надувшись от важности выдает:\n\n- Боддинок и сыновья предлагают большой ассортимент сиор, чем я могу вам помочь?\n\nПисклявый голосок не очень вязался с явно заученной речью, но мальчик очень старался",268763,null],[268765,"2026-10-12T13:42:24",20,"- Ага, поймали - вот теперь перевоспитываем *Смеётся Беатриче, беззлобно подкладывая гоблина*\n- Он теперь с нами\n\n*Она копается в своей сумке, доставая набор тех самых линз, которые откопала в той лавке*\n\n- Кстати вот, хотела как раз передать - мой вклад в ваши будущие великие открытия *она отдает линзы мальчику*",268764,null],[268767,"2026-10-12T13:55:26",31,"- ого! Это же линзы! Папа только к новому году обещал!  Пацаны с ума сойдут, мы же только трубу сделали, спасибо!\n\n/Сегодня вашей компании крайне везет на довольных коротышек, кого порадуете после, полурослика?/\n\nМальчик с неохотой отпускает сокровище, полученное от Беатриче и снова задает вопрос:\n\n- так что вам нужно, сиоры?",268765,null],[268768,"2026-10-12T13:59:11",20,"- Нам нужен распылитель. Это такая штука которая...эээ... *Она смотрит на спутников, явно прося помощи объяснить что именно им вообще надо*",268767,null],[268769,"2026-10-12T14:01:17",31,"Включается гоблин:\n\nРаспылитель, форсунка, короче что то, что сможет разбрасывать горючую жидкость. Вот такого примерно размера\n\n*показывает руками*\n\nГноменок:\n\n- таких маленьких нет в каталоге...\n\nИ тут же сияет\n\n- но у меня есть! Сейчас принесу\n\nУбегает куда то, судя по звукам, на второй этаж, в жилые помещения",268768,null],[268773,"2026-10-12T14:14:42",31,"Мальчик возвращается через пару минут и с гордостью демонстрирует вам видимо собственный проект - водяной пистолет, или скорее это можно назвать многоствольной водной мортирой, но с учётом размера самого изобретателя, для вас это было что то одноручное.\n\nГоблин реагирует соответственно, и между коротышками завязывается диалог, полный сопротивлений, плотности и температуры плавления. Вам остаётся только наблюдать в восхищении. Наконец гоблин оглядывается и говорит\n\n- то что надо. Но мелкий торгаш отдает за 5 золотых! Торговаться не желает, говорит патент!",212725,null],[268777,"2026-10-12T14:17:11",22,"Ясмин протягивает монеты.\n\n//в анкете учла траты, включая кальян",268773,null],[268785,"2026-10-12T14:29:42",31,"Монеты исчезают моментально. Парень отдаёт вам свое изобретение и с поклонами провожает. Большой день у него, и подарок получил, и первую инженерную идею продал.\n\nВы тем временем выходите на улицу, и Нак-Нак говорит\n\n- ну, теперь осталось самое сложное, найти и уговорить алхимика из Восточного района поделиться своими запасами.\n\nВы согласно киваете, и отправляетесь в путь. Восточный район встречает вас резко изменившейся архитектурой. Тут очевиден дух Востока, с его вычурными крышами, пагодами и садами. Вот только как искать тут алхимиков? Объявлений они точно не дают...",268777,null],[268787,"2026-10-12T14:30:03",31,"Сорян, картинка осталась на компе/",212725,null],[268788,"2026-10-12T14:30:51",31,"Но Ясмин тут как дома/",212725,null],[268789,"2026-10-12T14:31:18",31,"/третья часть микро квест будет поживее, надеюсь/",212725,null],[268790,"2026-10-12T14:32:00",17,"— Я бы подыграл, но кажется я никудышный актёр, в прошлый раз он меня раскусил на раз два.\n\nМарко слегка улыбается вспоминая как реально начал кашлять во время выступления, а ему всё равно не поверили",212725,null],[268791,"2026-10-12T14:32:50",31,"Короче, клчт сами не придумаете план поиска алхимика, включу рельсы. Минут через 30/",212725,null],[268792,"2026-10-12T14:34:03",17,"/А я думал мы у травника того же будем",212725,null],[268793,"2026-10-12T14:34:04",17,"/Ок",212725,null],[268796,"2026-10-12T14:45:55",20,"*Беатриче чешет затылок*\n\n- Хм...и как нам здесь искать алхимиков? \n\n*Решает подняться чуть повыше, осмотрев квартал сверху. Может из какой-то трубы идёт цветной дым или что-то вроде того, что укажет что владелец дома химичит свои алхимические штучки\"",212725,null],[268805,"2026-10-12T14:51:32",31,"Беатриче почти сразу обнаруживает искомое. Но это даже не дым, это целый салют! Над одним из зданий с большим двором взрываются фейерверки. Хмм, а ведь ели хозяин где-то нашел эти самые фейерверки, то может и вам подскажет?",268796,null],[268808,"2026-10-12T14:55:05",20,"*Она тут же спрыгивает обратно к спутникам, указывая в сторону, откуда запускают фейерверки.*\n\n- Скорее туда, там точно смогут подсказать где можно отыскать алхимика!\n\n*Она примерно запомнила дом и путь по улочкам к нему по виду с крыши, поэтому начинает вести остальных прямо туда*",268805,null],[268813,"2026-10-12T15:02:54",31,"Место, куда вы пришли, оказывается... Школой? Во всяком случае, на табличке написано \"Хея Ояката Орочи\", а ниже висит ещё одна, утверждающая, что идет набор учеников. \n\nВы решаете зайти. вашему  взору предстает открытая тренировка бойцов рукопашников самых разных рас. А за ней наблюдает огромного размера нага, очевидно, это учитель. На ваших глазах какой-то полуорк укладывает на землю тифлинга, и в его честь взрывается очередной салют. Похоже, в школе праздник какой то",212725,null],[268814,"2026-10-12T15:03:04",17,"— Замечательно",268808,null],[268816,"2026-10-12T15:04:34",31,"Пригодился арт/",212725,null],[268817,"2026-10-12T15:17:24",31,"Жду вашего хода, Орочи вас не видит. Или делает вид что не видит/",212725,null],[268818,"2026-10-12T15:19:43",17,"Марко проходит мимо и засматривается на отточеные движения монахов которые мутузят друг друга по лицу\n\nОдин боец особенно привлекает его внимание\n\nОн стоит и крутит... лестницу, раскидывая противников в разные стороны",268813,null],[268819,"2026-10-12T15:20:38",17,"Подойдя к распорядите он делает небольшой поклон кладя руку на грудь\n\n— Прошу прощения, могу я вас отвлечь? Или сейчас не совсем удобно?",212725,null],[268822,"2026-10-12T15:22:58",31,"Джеки Чан, ты ли это?/",268818,null],[268823,"2026-10-12T15:23:58",31,"Наг смотрит на тебя немигающими глазами\n\n- не отвлекаете, у нас тут так, что то вроде подготовки к выпускному. С кем имею честь беседовать?",268819,null],[268825,"2026-10-12T15:28:00",17,"— Моё имя Марко Веньер, сиор. Мы ищем топливо, которое по слухам может быть в вашей пиротехнике. У вас же есть пиротехника, сиор Орочи?",268823,null],[268833,"2026-10-12T15:31:29",31,"- да, я закупаю ее периодически. Очень люблю красочные эффекты, знаете ли. Поддерживает момент торжества для победителя и скрашивает горечь поражения проигравшего",268825,null],[268838,"2026-10-12T15:32:35",20,"- Беатриче Висконти да Вальдрио *Беатриче кланяется, представляясь. Хотя заметно что ее внимание больше привлекают спарингующиеся люди, чем нить разговора*",268823,null],[268855,"2026-10-12T15:38:27",22,"Ясмин просто молча осматривалась вокруг.",212725,null],[268955,"2026-10-12T16:38:33",31,"Орочи:\n\n- могу ли я узнать, зачем вам топливо? Это та еще дрянь, алхимик у которого я покупаю фейерверки выглядит не очень хорошо из за постоянного контакта с ними",212725,null],[268962,"2026-10-12T16:43:41",17,"— Хотим заставить нечисть сиять, очиститься огнём. Верно?\n\nМарко посмотрел на остальных с широкой улыбкой и прищуром",268955,null],[268964,"2026-10-12T16:46:00",31,"- герои значит... Раньше и меня вела дорога приключений...",212725,null],[268970,"2026-10-12T16:48:01",31,"- я вам помогу. Сведу с алхимиком. Но в обмен на услугу. Есть у меня один ученик, диковатый, но сильный. И потому нагловатый. Никто из его соучеников с ним не справляется. Я попрошу у вас спарринг с ним. Преподайте ему урок смирения, меня то он уважает, но остальных ни в грош ни ставит. Мне бы хотелось чтобы он понял, что в мире полно скрытых драконов",212725,null],[268989,"2026-10-12T16:54:12",20,"- Преподать кому-то урок? *Интерес Беатриче тут же подскакивает до небес*\n\n- Хех, ну так бы сразу и сказали! Когда начнем? *Она уже хрустит костяшками, предчувствуя неплохую разминку*",268970,null],[268991,"2026-10-12T16:55:39",31,"- да хоть сейчас. Но вы же понимаете, что мы тут сражаемся без оружия, верно?",268989,null],[269000,"2026-10-12T17:01:50",20,"- Да без проблем *Беатриче с азартом ухмыляется, отстегивая пояс с оружием*\n\n- Какие ещё правила во время боя? Как засчитывается победа/поражение?",268991,null],[269011,"2026-10-12T17:06:17",31,"- разрешены любые нелетальные удары, захваты, подсчечки. Проигрывает либо тот кто отрубился, либо тот кто не может выйти из захвата противника",269000,null],[269013,"2026-10-12T17:06:37",31,"- готовьтесь, Ми-Шань сейчас выйдет",212725,null],[269015,"2026-10-12T17:07:52",31,"И действительно, ученик Орочи не заставил себя ждать. Это оказался средних размеров молодой бирфолк в кимоно. Он с интересом посматривает на Беатриче, оценивая движения и жилистость противницы",212725,null],[269017,"2026-10-12T17:08:11",20,"/КД без оружия - 19 на всякий случай",212725,null],[269018,"2026-10-12T17:09:29",20,"*Беатриче тоже оценивает противника, откладывая все лишнее снаряжение и направляясь к нему*\n\n- Мое имя Беатриче Висконти и сегодня я стану твоим оппонентом.",269015,null],[269020,"2026-10-12T17:09:30",31,"Вы выходите в центр двора. Ми-Шань делает традиционный поклон, ты немного неуклюже отвечаешь тем же. Противник принимает стойку\n\nИнициативу/",212725,null],[269021,"2026-10-12T17:09:45",20,"/r d20+3",212725,null],[269023,"2026-10-12T17:10:07",31,"/roll d20+1",212725,null],[269026,"2026-10-12T17:10:23",31,"Ход Беатриче",212725,null],[269027,"2026-10-12T17:11:09",20,"*Беатриче молниеносно устремляется вперёд, вместо удара делая противнику подсечку, пытаясь уронить*",212725,null],[269028,"2026-10-12T17:11:19",20,"/так, что на это надо?",212725,null],[269029,"2026-10-12T17:11:35",17,"/Быть воином МБИ)",212725,null],[269030,"2026-10-12T17:11:54",31,"Упростим я думаю/",212725,null],[269032,"2026-10-12T17:12:10",31,"Акробатику давай против его акробатики",212725,null],[269033,"2026-10-12T17:12:20",20,"/r d20+5",212725,null],[269037,"2026-10-12T17:12:49",31,"/roll d20+3",212725,null],[269040,"2026-10-12T17:13:10",31,"Бирфолк ловко уходит от такой подсечки",212725,null],[269041,"2026-10-12T17:13:13",20,"/ловкий Мишаня",212725,null],[269045,"2026-10-12T17:13:41",20,"/конец хода",212725,null],[269046,"2026-10-12T17:14:07",31,"И в свою очередь проводит захват. Его медвежья хватка против твой ловкости или акробатики",212725,null],[269047,"2026-10-12T17:14:14",31,"/roll d20+8",212725,null],[269050,"2026-10-12T17:15:00",20,"/r d20+5",212725,null],[269052,"2026-10-12T17:15:07",20,"/схватил",212725,null],[269053,"2026-10-12T17:15:19",31,"Бонусный удар",212725,null],[269054,"2026-10-12T17:15:31",31,"/roll +d20+4",212725,null],[269056,"2026-10-12T17:15:42",20,"/ауч",212725,null],[269057,"2026-10-12T17:15:46",31,"/roll 2d6+4",212725,null],[269059,"2026-10-12T17:16:19",31,"Бирфолк заламывает тебя и наносит мощный удар по спине",212725,null],[269060,"2026-10-12T17:16:22",31,"Ход",212725,null],[269061,"2026-10-12T17:16:42",20,"/r d20+5 вырываемся из захвата",212725,null],[269063,"2026-10-12T17:16:48",20,"/удача",212725,null],[269064,"2026-10-12T17:16:53",20,"/r d20+5",212725,null],[269067,"2026-10-12T17:17:14",31,"/roll d20+8 Ми-Шань держит тебя крепко",212725,null],[269069,"2026-10-12T17:17:30",20,"/вырваться это действие?",212725,null],[269070,"2026-10-12T17:17:36",31,"Да/",212725,null],[269072,"2026-10-12T17:17:57",20,"/пофиг, тогда всплеск действий",212725,null],[269073,"2026-10-12T17:18:04",31,"Давай",212725,null],[269074,"2026-10-12T17:18:06",20,"/r d20+5",212725,null],[269076,"2026-10-12T17:18:19",31,"/roll d20+8",212725,null],[269078,"2026-10-12T17:18:34",31,"О, вывернулась и можешь удао т бонусом",212725,null],[269081,"2026-10-12T17:19:19",20,"/заменить удар на подсечку/захват можно?",212725,null],[269083,"2026-10-12T17:19:51",31,"Да",212725,null],[269084,"2026-10-12T17:20:02",20,"/r d20+5 подсечка",212725,null],[269086,"2026-10-12T17:20:21",31,"/roll d20+3",212725,null],[269088,"2026-10-12T17:20:25",20,"/да чтож за рак кубов опять начался",212725,null],[269089,"2026-10-12T17:20:32",20,"/конец хода",212725,null],[269090,"2026-10-12T17:20:37",31,"Лучше в спарринге/",269088,null],[269092,"2026-10-12T17:21:32",31,"Ми-Шань не понял как ты вывернулась, го реакции хватило чтобы самом не упасть. Он решает немного с тобой поиграть без борьбы. Подходит и проводит два удара лапами",212725,null],[269093,"2026-10-12T17:21:56",31,"/roll d20+6 правой\n/roll d20+6 левой",212725,null],[269095,"2026-10-12T17:22:15",17,"Шепотом Ясмин\n\n— Это точно спарринг? Похоже на странный танец медведей во время брачного периода, читал пару энциклопедий с  картинками",212725,null],[269097,"2026-10-12T17:22:30",31,"/roll d6+4 правый попал",212725,null],[269099,"2026-10-12T17:22:37",31,"Ход/",212725,null],[269100,"2026-10-12T17:22:49",20,"/r d20+5 подсечка",212725,null],[269102,"2026-10-12T17:22:59",31,"/roll d20+3",212725,null],[269104,"2026-10-12T17:23:14",31,"Ми-Шань падает",212725,null],[269105,"2026-10-12T17:23:22",31,"Бонусный удар можешь",212725,null],[269107,"2026-10-12T17:24:07",20,"/напомните мне пожалуйста я от ловкости или от силы бью рукопашно?",212725,null],[269108,"2026-10-12T17:24:19",17,"/ От силы",212725,null],[269109,"2026-10-12T17:24:24",31,"От силы если нет умения специального/",212725,null],[269110,"2026-10-12T17:24:28",20,"/пупупу",212725,null],[269111,"2026-10-12T17:24:40",17,"/Давай незаметно ворон Нанесение ран?",212725,null],[269112,"2026-10-12T17:25:06",31,"/Орочи капец как не любит нарушения правил. Даже в анкете так написано",269111,null],[269113,"2026-10-12T17:25:15",20,"/r d20+1 тогда захватом заламываем мишаню",212725,null],[269116,"2026-10-12T17:25:29",31,"Везунчик?/",212725,null],[269119,"2026-10-12T17:25:46",20,"/преимущество за то что он упал только на атаку? На захват вроде не действует?",212725,null],[269120,"2026-10-12T17:26:03",31,"Думаю нет/",269119,null],[269121,"2026-10-12T17:26:05",20,"/r d20+1 за везунчика, помолимся",212725,null],[269124,"2026-10-12T17:26:22",20,"/чтож",212725,null],[269125,"2026-10-12T17:26:27",20,"/конец хода",212725,null],[269127,"2026-10-12T17:27:23",31,"Ми-Шань тратит половину действия и встаёт. Он серьёзен. И в глазах горит нехороший огонек. Да это медведь в ярости! Опять кидается на тебя с желанием взять в захват",212725,null],[269128,"2026-10-12T17:27:30",31,"/roll +d20+8",212725,null],[269130,"2026-10-12T17:27:46",20,"/r d20+5",212725,null],[269132,"2026-10-12T17:28:02",31,"Ты в захвате",212725,null],[269133,"2026-10-12T17:28:05",31,"Хож/",212725,null],[269134,"2026-10-12T17:28:08",20,"/мда, а кусаться там тоже против правил?",212725,null],[269135,"2026-10-12T17:28:14",31,"Можно",269134,null],[269136,"2026-10-12T17:28:23",31,"Это руклавшгое оружие",212725,null],[269137,"2026-10-12T17:28:28",31,"Сам Орочи так делал/",212725,null],[269143,"2026-10-12T17:29:36",20,"/r d20+5 пытаемся вырваться для начала",212725,null],[269145,"2026-10-12T17:29:49",31,"/roll d20+8",212725,null],[269147,"2026-10-12T17:29:54",31,"Хах",212725,null],[269148,"2026-10-12T17:29:54",20,"/ахаха",212725,null],[269149,"2026-10-12T17:30:06",31,"Вырвалась",212725,null],[269151,"2026-10-12T17:30:11",20,"/r d20+4 кусь",212725,null],[269153,"2026-10-12T17:30:14",22,"- Беатриче!!! Жги!!! \n\nЯсмин подбадривает, слегка оглушая своим визгом Орочи и Марко, которые этого не ожидали",212725,null],[269154,"2026-10-12T17:30:17",31,"Попала",212725,null],[269155,"2026-10-12T17:30:50",20,"/r d4+2 колющего",212725,null],[269159,"2026-10-12T17:31:12",20,"/это немного, но это честный урон",212725,null],[269160,"2026-10-12T17:31:13",31,"Кровь бирфлдка в твоей глотке, вкус мёда",212725,null],[269161,"2026-10-12T17:31:18",20,"/конец хода",212725,null],[269164,"2026-10-12T17:32:28",31,"Ми-Шань не оценил твою оригинальность. И опять решает тебя захватит",212725,null],[269165,"2026-10-12T17:32:38",31,"//roll +d20+8",212725,null],[269166,"2026-10-12T17:32:45",20,"/r d20+5",212725,null],[269169,"2026-10-12T17:32:59",31,"/roll +d20+8",212725,null],[269170,"2026-10-12T17:33:18",31,"/r +d20+8",212725,null],[269174,"2026-10-12T17:33:37",31,"Захват не прошёл, а пройдите до вторая атака лапой?",212725,null],[269175,"2026-10-12T17:33:44",31,"/r +6",212725,null],[269177,"2026-10-12T17:33:56",20,"/прошла...",212725,null],[269178,"2026-10-12T17:33:57",31,"/roll d6+4",212725,null],[269181,"2026-10-12T17:34:12",31,"Ход/",212725,null],[269182,"2026-10-12T17:34:31",20,"/так, ну теперь только половина хитов, можно кусь с преимуществом, найс",212725,null],[269183,"2026-10-12T17:34:51",20,"/r +d20+4 кусь!",212725,null],[269185,"2026-10-12T17:34:57",31,"Попала",212725,null],[269186,"2026-10-12T17:35:08",20,"/r d4+4",212725,null],[269188,"2026-10-12T17:35:31",20,"/востанавливаю себе 7 хитов",212725,null],[269191,"2026-10-12T17:35:45",20,"/бонусным ещё второе дыхание",212725,null],[269192,"2026-10-12T17:35:54",20,"/r d10+4",212725,null],[269194,"2026-10-12T17:36:05",20,"/конец хода",212725,null],[269196,"2026-10-12T17:36:22",31,"/roll +d20+8 ещё одна попытка захвата",212725,null],[269198,"2026-10-12T17:36:38",20,"/r +d20+5",212725,null],[269200,"2026-10-12T17:36:57",20,"/эх почти",212725,null],[269201,"2026-10-12T17:37:07",31,"Особый приём Супплекс. Кидай спас тела 14",212725,null],[269204,"2026-10-12T17:37:29",20,"/r +d20+4 преимущество от укуса прошлого",212725,null],[269207,"2026-10-12T17:37:55",20,"/мы здесь надолго",212725,null],[269208,"2026-10-12T17:38:06",31,"/roll 2d6+4 получай половину урона за счет проходы спаса",212725,null],[269212,"2026-10-12T17:38:45",31,"Ми-Шань пытается бросить тебя через себя, но ты выворачиваешься и получаешь урон только от его лап",212725,null],[269214,"2026-10-12T17:38:59",31,"Ты все ещё в захвате/",212725,null],[269215,"2026-10-12T17:39:06",31,"Ход/",212725,null],[269218,"2026-10-12T17:39:22",31,"А ты думала танцы с медведем это быстро?)",269207,null],[269220,"2026-10-12T17:39:38",20,"/r d20+5 вырваться",212725,null],[269225,"2026-10-12T17:40:22",20,"/не победю так хоть понадкусываю",269218,null],[269228,"2026-10-12T17:40:55",31,"/roll d20+8",212725,null],[269231,"2026-10-12T17:41:16",31,"Ми-Шань кажется заболел. Это что, рак? Рак кубов?",212725,null],[269232,"2026-10-12T17:41:21",31,"Бей бонусом",212725,null],[269233,"2026-10-12T17:41:34",20,"/r +d20+4 кусь",212725,null],[269235,"2026-10-12T17:41:46",31,"Попала",212725,null],[269236,"2026-10-12T17:41:51",20,"/r d4+2",212725,null],[269239,"2026-10-12T17:41:56",27,"// Последствия жизни в Чернобыле",269231,null],[269240,"2026-10-12T17:42:31",20,"/конец хода",212725,null],[269241,"2026-10-12T17:43:04",31,"/roll d20+6 левой\n/roll d20+6 правой\n\nМи-Шагь вновь переходит на простые удары",212725,null],[269243,"2026-10-12T17:43:21",31,"/roll 2d6+8",212725,null],[269245,"2026-10-12T17:43:30",20,"/живём...",212725,null],[269246,"2026-10-12T17:43:34",31,"Ход/",212725,null],[269247,"2026-10-12T17:43:54",20,"/r +d20+4 кусь",212725,null],[269249,"2026-10-12T17:44:08",31,"Загрызла медведя/",212725,null],[269250,"2026-10-12T17:44:08",20,"/кусь бонусным ещё можно?",212725,null],[269251,"2026-10-12T17:44:19",31,"Давай, чего уж",212725,null],[269252,"2026-10-12T17:45:00",20,"/r +d20+4",212725,null],[269256,"2026-10-12T17:45:36",20,"/r d4+2 кусь\n/r 2d4+2 критовый кусь",212725,null],[269258,"2026-10-12T17:46:03",31,"Живой еще/",212725,null],[269259,"2026-10-12T17:46:07",20,"/на 8 хитов отлих ещё \n/конец хода",212725,null],[269260,"2026-10-12T17:46:08",31,"Но шатается/",212725,null],[269262,"2026-10-12T17:46:25",31,"/roll +d20+8 захват из последних медвежьих сил",212725,null],[269265,"2026-10-12T17:46:42",20,"/r +d20+5 🙏",212725,null],[269267,"2026-10-12T17:46:52",20,"/удача последняя",212725,null],[269268,"2026-10-12T17:46:58",20,"/r d20+5",212725,null],[269271,"2026-10-12T17:47:11",20,"/хватай",212725,null],[269272,"2026-10-12T17:47:14",31,"/roll +d20+6 удар лапой по захваченной цели",212725,null],[269274,"2026-10-12T17:47:23",31,"Лапа мимо/",212725,null],[269275,"2026-10-12T17:47:25",20,"/фух",212725,null],[269276,"2026-10-12T17:47:26",31,"Ход/",212725,null],[269277,"2026-10-12T17:47:49",20,"/в захвате мне же не накладывает помеху его кусать?",212725,null],[269279,"2026-10-12T17:48:23",31,"Хз, надо гуглить)/",269277,null],[269284,"2026-10-12T17:49:00",31,"Да, кусай/",212725,null],[269287,"2026-10-12T17:49:59",20,"/r +d20+4\n/r +d20+4",212725,null],[269291,"2026-10-12T17:50:32",31,"Описывай как загрызла до беспамятства/",212725,null],[269312,"2026-10-12T17:55:24",20,"*Беатриче попадается в очередной захват, яростно барахтаясь. Однако вместо того, чтобы снова вырываться, в ней просыпается ее дампирская часть и она с боевым кликом:*\n\n\"Не уроню так понадкусываю!\"\n\n*Вцепается прямо в лапу мишани. Тот взревев от боли оступается, падая назад, ударяясь о землю. Беатриче выползает из его хватки отплевываясь от шерсти*\n\n- Пфе...Кхе...Знай как идти против самой Вискон-...апчхи!",212725,null],[269319,"2026-10-12T17:56:26",20,"/в 4 хитах осталась, жесть",212725,null],[269321,"2026-10-12T17:56:56",31,"Жирного Мишу завалила, красотка)",212725,null],[269325,"2026-10-12T17:58:27",20,"/Кстати, там на проверки у меня не должно было быть преимущества - там либо хил либо преимущество\n/они и так конечно мне не помогали против таких захватов, но на будущее запомню",212725,null],[269327,"2026-10-12T18:00:15",20,"/на попадания все правильно работало, всегда преимущество если меньше половины хитов",212725,null],[269339,"2026-10-12T18:03:02",31,"Орочи хлопает в ладоши\n\n- довольно. Ми-Шань, ты понял свой урок?\n\nБирфолк стоит потупив глаза\n\n- Что нужно сказать нашей гостте?\n\nБирфолк неохотно кланяется и говорит\n\n- Благодарю за науку, госпожа Висконти\n\nОрочи продолжает:\n\n- я отправлю за алхимиком, а вам, госпожа Висконти, пока предлагаю выпить моего травяного чая, сугубо для восстановления сил и здоровья",212725,null],[269347,"2026-10-12T18:05:43",20,"- Чай был бы очень кстати, мастер Орочи *Беатриче тоже кланяется, стараясь повторить этот традиционный поклон*\n\n*Чай бы ей действительно не помешал. Вкус крови бирфолка одновременно и утолил, и подстегнул ее внутреннюю жажду. Нужно поскорее запить чем-то этот вкус...*",269339,null],[269352,"2026-10-12T18:07:45",31,"И так, Орочи отпаивает Беатриче чайком (аналог зелья  лечения), а за это время кто то из учеников сбегал за раскосым мужичком алхимиком. Он и правда выглядит неважно. Выслушав вашу просьбу о заправке для огнемёты, он подумал и притащил какую то красную жижу с запахом серы. За нее он запросил 100 золота. Нае-Нак оценил эту дрянь положительно",212725,null],[269353,"2026-10-12T18:07:54",20,"*Она также делает лёгкий поклон бирфолку, прежде чем направится обратно к спутникам*\n\n- Вы были достойным оппонентом, благодарю за бой\n\n/Это перед чаем, все по чести",212725,null],[269394,"2026-10-12T18:13:31",31,"@PaIIasCat @dunchev @lady_godzilla \n\nЖду подтверждения списания денег и перехожу к описанию готового прибора",212725,null],[269457,"2026-10-12T18:34:31",22,"Ясмин отдаёт деньги",212725,null],[269497,"2026-10-12T18:52:22",31,"Забрав вещество и  попрощавшись с Орочи (который намекнул, что не против видеть вас снова как спаррингов для своих учеников), вы отправились домой к Нак-Наку. Там гоблин быстро и целеустремлённо собрал прибор и с придыханием вручил его Ясмин для первого пробного выстрела.",212725,null],[269498,"2026-10-12T18:52:37",31,"@lady_godzilla ты получаешь в свои руки оружие, которое может быть опасно и для тебя. Будь осторожна",212725,null],[269500,"2026-10-12T18:53:16",31,"Картинка не соответствует задумке, но все равно неплохая/",212725,null],[269558,"2026-10-12T19:13:46",22,"- Оооооо! Я назову тебя \"Несущий свет\"! \n\nНа глазах у Ясмин проступили слезы.\n\nТехника техникой, дорогая, но не забывай о своём наследии\n\n-- Теперь все узреют мощь света! И прочувствуют как свет наполняет их души...\n\nДевочки, это НЕ НОРМАЛЬНО!\nПоддерживаю, проверьте, нет ли у нас еще одного \"жильца\"?",269499,null],[269561,"2026-10-12T19:15:06",22,"//в голове у Ясмин на момент получения огнемета. Только 3 бабки",212725,null],[269867,"2026-10-13T10:12:22",31,"Порадовавшись за Ясмин с ее обновкой, но все таки опасаясь за ее психическое здоровье, вы разошлись по домам. Завтра будет сложный день, вы отправитесь в леса на поиски друида\n\n/через час-два дам стартовую локацию, пока я должен, увы, поработать/",212725,null],[269911,"2026-10-13T12:28:52",31,"@dunchev @lady_godzilla @PaIIasCat \n\nЭту ночь вы провели по разному.\n\nМарко мучился приступами кашля и кошмарами, ему снилось его имя и дата смерти и подлый голосок внутри говорил: \"Никчемный человечишка, смотри, тебе осталось всего ничего жить, а ты так ничего и не успел сделать... жалкая ничтожная смертная серость. Ты умрешь, так и не узнав правды. И на ой стороны ты тоже ничего не узнаешь. И поделом, слабые недостойны ни жалости, ни правды...\"\n\nЯсмин, напротив, спала отлично. Было ли тому причиной новое оружие, что влюбило в себя девушку, или же отсутствие голосов в голове, словно бы напуганных ее новообретенной силой и уверенностью? Это не важно, сейчас Ясмин просто наслаждалась жизнью.\n\nБеатриче спала меньше всех этой ночью. Кровь Ми-Шаня и чай Орочи дали ей такой прилив сил, что в кровати не лежалось. Она выбралась на крышу, вооружилась бутылкой легкого вина и просто и незатейливо выпивала, разглядывая звезд и набирающую силу и вес Луну. Здесь же Беатриче и задремала на часок, а проснувшись чувствовала себя отлично.\n\nУтром, как и договаривались вчера, вы встретились у ворот, что вели на Северо-Запад, где Феллино почуял друида. Вы и понятия не имели, где его конкретно искать, но решили разбираться на месте. Выяснив у стражников на воротах, что в паре часов пути как раз на северо-западе лежит небольшая деревня Каталуна, вы подумали, что у местных может быть информация и направились туда. \n\nВаш путь проходил спокойно. Никто не бросался из кустов, никто не стремился отнять у вас все имущество. Даже никто не пугал страшными сказками. Вы просто спокойно добрались до деревни. Видимо, все что возможно в пути, ждало вас уже там.\n\n//Ребята, эта деревня - хаб этой арки. Тут будет и старт основного сюжетного квеста и пары-тройки дополонительных, которые вы конечно можете и не проходить. Но вы же понимаете что я один хрен их вам потом опять подкину, просто переделав?))//",212725,null],[269917,"2026-10-13T12:33:24",20,"- Какое мило местечко *Беатриче оглядывается по сторонам, оценивая деревенские пейзажи. Эх, сюда бы ещё пару виноградников для полной идиллии...*\n\n- Ну что, идём в таверну дегустировать местные вина со слухами на закуску?",269911,null],[269918,"2026-10-13T12:34:36",17,"Марко вдыхал лесной чистый воздух не загаженный смогом индустриализации\n\nКажется даже кашель тут ослаб, может воздух, может ингаляции с травами, которые прописала доктор Ясмин. Было легче.\n\nВойдя в деревню он первым делом обратил внимание на указатель\n\n— Хм.. Таверна или церковь я полагаю? Первые места где можно расспросить о друидах.\n\nПотом Услышал предложение Беатриче. И уже определился\n\n— Да, в таверну сиоры. Все прекрасные истории начинаются оттуда.",212725,null],[269919,"2026-10-13T12:44:44",31,"Таверна \"У Дуба\" располагается в самом центре деревне. Дерева, или даже пня, вы не обнаружили, что несколько смущало. Но зайдя внутрь вы поняли, что не зря слово Дуб было написано с заглавной буквы.\n\nЗа стойкой, едва помещаясь, стоял огромный кряжистый мужик. Прозвище Дуб само просилось на язык. В этот час он был тут один, не считая миниатюрной официантки, но не оставалось сомнений, что в обеденный час, совсем скоро, таверна будет полна.\n\nЗаметив вас, трактирщик отложил тряпку, которой полировал бокал и заговорил низким, рокочущим басом:\n\n- чего сиоры изволят?",212725,null],[269920,"2026-10-13T12:44:45",22,"-- Да, т-таверна звучит отлично. \n\nЯсмин была просто в великолепном настроении. Свет солнца сияет так ярко и так приятно. На душе так тепло!\n\nАга, конечно, на душе ей тепло\nЕще бы тепло не было с огнеметом то в руках\n\nОн в сумочке!\n\nОй извините, госпожа \"сгорите до тла еретики!\" Он же в су‐у-умочке!\nМаленькая женская сумочка. Ничего необычного. Я вот в ней ношу ухо своего первого эльфа, а она огнемет. У каждой карги свои причуды, верно, девочки?\nИхихи-хи-хи",212725,null],[269965,"2026-10-13T15:33:59",31,"Тут кажется мое сообщение под Полининым затерялось",212725,null],[269966,"2026-10-13T15:33:59",31,"Таверна \"У Дуба\" располагается в самом центре деревне. Дерева, или даже пня, вы не обнаружили, что несколько смущало. Но зайдя внутрь вы поняли, что не зря слово Дуб было написано с заглавной буквы.\n\nЗа стойкой, едва помещаясь, стоял огромный кряжистый мужик. Прозвище Дуб само просилось на язык. В этот час он был тут один, не считая миниатюрной официантки, но не оставалось сомнений, что в обеденный час, совсем скоро, таверна будет полна.\n\nЗаметив вас, трактирщик отложил тряпку, которой полировал бокал и заговорил низким, рокочущим басом:\n\n- чего сиоры изволят?",212725,null],[269977,"2026-10-13T15:54:29",20,"- Доброго дня, Синьор. *Беатриче приветственно кивает, подходя к стойке*\n- Что разливают по бокалам в этом славном заведении? С долгой дороги так и хочется пропустить бокальчик другой вина\n\n/Беатриче ушла изучать местную винную карту",269966,null],[269979,"2026-10-13T15:56:35",22,"//извините",269965,null],[269984,"2026-10-13T16:06:18",31,"В нная карта, если ее можно так назвать, не поражает своим объёмом. Пиво, молодое вино и медовуха. Пиво - 5 медных за кружку, 2 серебряных за кувшин, медовуха - 1 серебряная за кружку и 5 за кувшин, вино - 2 серебряных за бокал, 1 золотой за бутылку",269977,null],[269985,"2026-10-13T16:07:27",20,"/надо налаживать сюда поставки 🤔",212725,null],[269986,"2026-10-13T16:08:20",31,"Никто не запрещает/",269985,null],[269993,"2026-10-13T16:53:06",22,"-- М-можно что-нибудь полегче п-пожалуйста? И какие нибудь з-закуски. Ваша деревушка т-такая милая. Р-раскажите путник, что интересного у вас т-тут есть?",269984,null],[270002,"2026-10-13T17:12:19",31,"- могу салат предложить. И травяной чай. В пять медяков уложитесь.\n\nДождавшись положительного ответа, и выствив перед Ясмин заказанное, Дуб заговорил\n\n- ну как вам сказать, что интересного. Хотел бы сказать что все как всегда, но неправда это. Охотники за Лесники говорят, опять Зверь шалит, задрал кого-то на дальней ферме. Хитрая тварь, никто прибить не может, ладно хоть не часто о нем слышно. Видать, переваривает долго",269993,null],[270038,"2026-10-13T17:41:46",22,"-- З-зверь?! Что за зверь? М-медведь?\n\nЯсмин нервно прижала к губам чашку чая.",270002,null],[270059,"2026-10-13T18:05:07",31,"- да ктож его знает... Кто видел - уже не расскажут. А вы разве не слышали о Каталунском Звере? Старая же история",270038,null],[270061,"2026-10-13T18:07:08",17,"— Нет, мы в основном по городским байкам и легендам специализируемся.",212725,null],[270062,"2026-10-13T18:07:19",17,"Марко сел рядом",212725,null],[270077,"2026-10-13T18:19:19",22,"Ясмин кивнула.\n\n-- Расскажите?",212725,null],[270079,"2026-10-13T18:21:28",31,"- ну дак я расскажу\n\nДуб явно обрадовался свободным ушам\n\n/сука, в кои то веки лонгрид сделал и не скопировал. Сейчас буду вспоминать что калякал/",212725,null],[270115,"2026-10-13T18:52:04",31,"- Зверь тут много лет промышляет, еще мой отец жив был, а он почитай 24 года как помер. То есть уже годков тридцать как они впервые появился. Тогда семью Чиро разорвал, всех подчистую, вместе с собаками и козами.\n\nДуб переводит дух\n\n- тогда нашли следы, вот не вру, вроде как волчьи, да только с мою ладонь.\n\nПоказывает растопыренную пятерню, которая размерами почти что с тележное колесо\n\n- Никто из охотников таких не видал. Но устроили облаву, с собаками пошли по следу. А он в ручей ушёл. И запаха не оставил, хитрая тварь. И ч тех пор нет-нет, да появится. В первые годы чуть не каждый месяц задирал людей, бывало что и семьями, бывало что и по одиночке. Потом стал реже промышлять, самое долгое - четыре года без него прожили, уже думали издох. Но нет, вернулся, мельника задрал. И с тех пор снова терроризирует нас. И следов не оставляет, чтобы поймать или прибить его.\n\nДуб замолкает ненадолго, в затем продолжает.\n\n- в последний год совсем охамел. Чаще стал нападать, уже чуть не по два-три трупа в месяц оставляет. И вот семью недавно опять задрал, на ферме Норри. Я сам не видал, охотники рассказывали, вас если подробностей надо, лучше Антуана дождитесь, он мужик старый, но охотник наш лучший. Уже который год Зверя хочет завалить, тот его невесту задрал одной из первых, она из семьи Чиро была. Вот с тех пор он Зверя и выслеживает.",212725,null],[270511,"2026-10-14T10:52:38",31,"//Ребята, у меня сегодня нет особо времени вести. Надеюсь, завтра сможем расшевелится. Я уже определился с тремя квестами на локации, будем их по очереди играть. Завтра утром постараюсь вам выдать пост-продолжение ко вчерашнему, где будут завязки на два остальных. Если что, завязка на Зверя - основной квест, я бы вам посоветовал сначала сделать два других, иначе потом у вас не останется логичного обоснования торчать в деревне//",212725,null],[270512,"2026-10-14T10:53:35",22,"/я за, у меня очень много работы на этой неделе, сама еле живая",212725,null],[270513,"2026-10-14T11:49:58",17,"/ И у меня)",212725,null],[271463,"2026-10-15T04:30:24",31,"@dunchev @lady_godzilla @PaIIasCat \n\nПока вы слушали историю от Дуба, и осмысливали ее, таверна успела наполниться посетителями. Хозяин, извинившись, отошел от вас и занялся обслуживанием остальных клиентов (не забыв взять и ваши заказы).\n\nВы занялись едой и разговором между собой. Но отвлеклись оа двух проходящих мимо мужиков, обрывки разговора которых долетели до вас:\n\n- пропала, бегает, ищет\n- да в колодце...\n- говорит, не дура, не пошла бы\n- загуляла, бывает\n\nПодключается ещё один голос\n\n- Елена то? Загуляла? Да с кем? Пусть бы других девок расспросил...\n- а колодец?\n- не, не пошла бы...\n- а вдруг Зверь?\n- когда это Зверь не бросал тело на виду?\n\nДалее неразборчиво, вы уже не улавливаете слова и фразы.",212725,null],[271474,"2026-10-15T09:32:37",22,"/r +7 Ясмин прислушивается",212725,null],[271476,"2026-10-15T09:33:03",22,"Ясмин толкает Беатриче и Марко.\n\n--Ч-что там происходит?",212725,null],[271478,"2026-10-15T09:35:03",17,"/r d20+6+d4 Внимательное подслушивание",271463,null],[271480,"2026-10-15T09:35:43",20,"*Беатриче отрывается от своего бокальчика вина, переводя взгляд сначала на Ясмин, потом на этих людей*\n\n*Прислушивается*\n\n- ...может пропал ещё кто? Вроде какая-то девушка.",271476,null],[271481,"2026-10-15T09:35:46",17,"— Кажется пропала девушка, про колодец говорят, осмотреть бы его. На тварь пеняют, но она оставляет тела на виду после того как убьёт\n\nМарко шепотом сообщает что услышал",212725,null],[271484,"2026-10-15T09:39:02",22,"Ясмин встревоженно подняла взгляд.\n\n--Н-наверное это не н-наше дело, но м-может попробуем им п-помочь? Вдруг д-девушка еще жива?!",212725,null],[271486,"2026-10-15T09:39:42",17,"— Хорошо. Быть может исчезновение связано с друидом которого мы ищем. Давайте распросим подробнее вон ту компанию",271484,null],[271488,"2026-10-15T09:42:02",20,"*Беатриче залпом допивает бокал*\n\n- Ах, что не день то спасение прекрасных дам. Che vita!\n\n*Поднимает из-за стола, смотря в сторону компании о которой говорит Марко*\n\n- За дело, друзья мои",212725,null],[271493,"2026-10-15T09:52:14",22,"--У-уважаемые! Расскажите, п-пожалуйста, что случилось? Мы хотим п-помочь!",271463,null],[271494,"2026-10-15T10:42:55",31,"Простите, меня опять тормозят внешние обстоятельства. Машина отказывается заводиться, прыгаю вокрг нее и птыаюсь оживить(((//",212725,null],[271505,"2026-10-15T14:02:35",31,"Мужики-сплетники поднимают головы.\n\n- а вы кто такие вообще? Мы вас не знаем. Да и помощи не просили. - первый начинает практически с наезда.\n\nВторой:\n\n- да не начинай, Шарль. Может, люди и правда помочь хотят. Мы просто обсуждали, что у Робена, нашего мясника, дочь пропала. Ну, он так говорит. Хотя как по мне, взрослая девка уже, загулеванилась поди с парнем, а теперь домой стыдно идти.\n\n- про колодец скажи\n\n- да никто в деревне не ходит к колодцу, даже малые дети, окстись",271493,null],[271532,"2026-10-15T15:26:21",22,"Ясмин повела плечами.\n\n--А что за и-история с колодцем?",212725,null],[271533,"2026-10-15T15:37:29",31,"- колодец это наша местная, ну типа, достопримечательность. Он, вроде как, говорящий. Только говорит одно и тоже, типа иди ко мне, нырни, тут хорошо. У наших мальчишек от роду развлечение, кто дольше перед колодцем усидит и не побежит нырять - тот и победил. Ну бывает что и проигрывают, да, ныряют. А обратно не выныривают. Поэтому матери гоняют пацанов подальше. А девочки туда и вовсе не ходят",212725,null],[271615,"2026-10-15T18:13:24",17,"— С колодцем разобраться нужно, почему вы не сообщили куда следует, вдруг там бес какой то засел? Да и как пьёте оттуда, если такое происходит? Вода из него тоже говорящая?",212725,null],[271616,"2026-10-15T18:18:13",31,"- колодец за деревней, никто из него не пьет. А что до бесовства - так ходил жрец туда, помолится. Не вернулся. Другие видать струхнули и велели нам не ходить туда",271615,null],[271618,"2026-10-15T18:19:59",17,"— Мы посмотрим. Мы друида ищем местного, может известно что-то?",212725,null],[271621,"2026-10-15T18:29:13",31,"- Друида? Не, не слыхал. Друиды же в лесу живут, вы лучше охотников спросите, или лесорубов, как с делянок вернутся",271618,null],[271624,"2026-10-15T18:31:46",22,"-- И д-даже никто не захотел проверить? А в-вдруг жрецу нужна была п-помощь?!",271616,null],[271626,"2026-10-15T18:34:26",17,"— Следы находили рядом? Зверей или людей?",212725,null],[271629,"2026-10-15T18:36:15",31,"- ну, мы люди простые, в делвьжрецлв не лезем. Что там они меж собой решили, то их дело",271624,null],[271630,"2026-10-15T18:36:43",31,"- Где, возле колодца? Да пес его знает",271626,null],[271654,"2026-10-15T19:05:11",20,"- А почему вы думаете, что эта Елена могла пойти к колодцу? Сами ж говорили - девки туда побаиваются ходить. *Спрашивает Беатриче*\n\n- Или пропал у нее там кто недавно?",212725,null],[271655,"2026-10-15T19:08:36",31,"- да я ж как раз говорю, что не пошла бы она туда, чо ей там делать то? Робер бегает, ищет ее, а я ведь ему сразу сказал, да расспроси ты ее подруг, ну по-любому же она им рассказала про какую нибудь неземную любовь со случайным бродягой",271654,null],[271656,"2026-10-15T19:13:17",31,"Влезает второй, тот что говорил про колодец:\n\n- у нас тут если и пропадают, то либо Зверь сожрет, либо в Колодец нырнут",212725,null],[271690,"2026-10-15T20:19:06",20,"- Ну тогда думаю если хотим разобраться нужно просто идти к колодцу *Беатриче поворачивается к спутникам*\n\n- Идём? Посмотрим что такого там завелось",212725,null],[271692,"2026-10-15T20:24:40",22,"Ясмин согласно кивнула и приготовилась идти.",212725,null],[271833,"2026-10-16T06:16:33",31,"Выяснив у болтунов местоположение колодца, вы направились к нему. Он располагается за деревней, на опушке леса и его зловещий вид несколько контрастирует с мирным на вид лесом. Хотя деревья неподалёку выглядят не лучшим образом, они явно больны. Вы остановились в 30 футах от колодца",212725,null],[271836,"2026-10-16T08:16:02",22,"Ясмин использует свои навыки выживания и осматривает колодец.\n\nОна хочет понять, действительно ли он заброшен и есть ли следы того, что его посещали или как либо тревожили",212725,null],[271837,"2026-10-16T08:16:05",22,"/r +7",212725,null],[271839,"2026-10-16T08:20:07",17,"Марко выпустил ворона в небо и осматривает местность неподалёку от колодца на предмет следов\n\n— Если тут проклятье, вы его почувствуете?\n\nОбращается он к Ясмин",212725,null],[271840,"2026-10-16T08:20:23",17,"/r +d20+4+d4 Выживание на поиск следов с помощью фамильяра",212725,null],[271842,"2026-10-16T08:20:33",22,"- Д-думаю да.",271839,null],[271855,"2026-10-16T08:27:37",31,"ты легко замечаешь следы, но людских мало, в основном следу различных животных. Может они приходят на водопой. А может колодец их как то зовет?",271838,null],[271856,"2026-10-16T08:27:55",31,"ты тоже видишь в основном следы животных",271841,null],[271857,"2026-10-16T08:28:31",31,"проклятий ты не чувствуешь, но что то магичиеское тут точно есть",271842,null],[271858,"2026-10-16T08:30:29",22,"/r -1 Ясмин пытаетсч вспомнить школьный курс магии",212725,null],[271860,"2026-10-16T08:30:48",17,"— Следы обычных животных, ничего интересного. Но все идут к колодцу, что само по себе странно. Косули не умеют доставать воду ведром...\n\n— Что у вас, сиора?",212725,null],[271861,"2026-10-16T08:32:39",31,"Ясмин была прогульщицей, таскала записки от мамы",271859,null],[271863,"2026-10-16T08:56:18",17,"Марко поднял камень с земли, подходит ближе к колодцу и кидает его туда. \n\nСлушает когда тот упадет в воду.",212725,null],[271864,"2026-10-16T08:56:54",31,"бульк",271863,null],[271865,"2026-10-16T09:07:21",31,"пропустил момент что ты подошел ближе, сорян.\n\nГолос в твоей голове:\n\n- иди ссссюда, идиии ко мнеееее.....\n\nСпас мудрости СЛ 16",271863,null],[271866,"2026-10-16T09:13:42",17,"/r +6 Спасаемся",212725,null],[271868,"2026-10-16T09:14:17",17,"Марко хватается за голову\n\n— Черт... В голове голос... Зовёт...!\n\n— НАЗАД!\n\nМарко спешно отходит",212725,null],[271869,"2026-10-16T09:21:30",31,"голос разочаровано гудит",212725,null],[271871,"2026-10-16T09:29:47",20,"- Ого, вы чего так отшатнулись синьор Марко. Там и правда кто-то есть? *Беатриче наблюдает за этим, подходя к Марко*\n\n/Мы с Ясмин этот голос похоже не слышали",212725,null],[271872,"2026-10-16T09:36:13",22,"-- И-извините, п-пожалуйста. У меня есть и-идея.\n\nЯсмин достаёт из сумочки огнемет.",212725,null],[271873,"2026-10-16T09:36:45",22,"Тетушки начинают давиться от смеха.",212725,null],[271879,"2026-10-16T09:42:09",31,"мне кжк интересно/",271872,null],[271881,"2026-10-16T09:47:13",22,"Ясмин воодушевляет себя сопротивлением и аккуратно подходит к колдцу, придерживаясь за  ремень огнемета",212725,null],[271890,"2026-10-16T10:09:58",31,"Голос в голове зовет и тебя. Спас мудрости СЛ 16",271881,null],[271893,"2026-10-16T10:14:54",22,"/r +7",271890,null],[271895,"2026-10-16T10:15:01",22,"/начинается",212725,null],[271896,"2026-10-16T10:15:49",22,"//я сожгу Мерсо? Или Беатриче? Или они оба будут танцевать в языках моего пламени? 😈",212725,null],[271897,"2026-10-16T10:16:17",31,"Голос, что манил тебя, оазался сильнее. Огнемет выпадает из ослабевших руки, а ты идешь к колодцу с четкой целью туда упасть",271894,null],[271898,"2026-10-16T10:16:47",31,"хорошая мысль, запишу на будущее. тут к сожалению все проще/",271896,null],[271899,"2026-10-16T10:16:53",22,"Ясмин рыбкой прыгает в колодец.",212725,null],[271900,"2026-10-16T10:17:00",20,"/план перехват?",271897,null],[271901,"2026-10-16T10:17:07",22,"/r +4 акробатическая рыбка",212725,null],[271903,"2026-10-16T10:17:23",31,"попробуй, проверка ловскости СЛ 16",271900,null],[271904,"2026-10-16T10:17:38",20,"/r d20+5 ловим",212725,null],[271907,"2026-10-16T10:18:34",31,"ты ловишь Ямин за ногу, но большая часть ее тела в колодце. По ясмин снизу прилетеает удар",212725,null],[271908,"2026-10-16T10:18:36",17,"Марко не успел среагировать пока приходил в себя оперевшись на ствол дерева",212725,null],[271909,"2026-10-16T10:18:42",31,"/roll d20+7",212725,null],[271912,"2026-10-16T10:18:59",31,"попал?/",212725,null],[271913,"2026-10-16T10:19:43",31,"/roll d10+4 дробящего и Ясмин схвачена",212725,null],[271915,"2026-10-16T10:20:04",31,"Беатриче, проверка оталетики против атдетики того кто сидит в колодце",212725,null],[271916,"2026-10-16T10:20:10",31,"иначе Ясмн утащат",212725,null],[271917,"2026-10-16T10:20:20",22,"//украли женщину!",212725,null],[271918,"2026-10-16T10:20:39",31,"/roll d20+5 Атлетика обитателя колодца",212725,null],[271920,"2026-10-16T10:21:07",20,"- Марко! Ясмин умыкнуть пытаюсь, помогайте! *Кричит Беатриче, тяня Ясмин обратно*",212725,null],[271921,"2026-10-16T10:21:10",17,"Марко подбегает и тянет Беатриче от колодца\n\n/Тянем репку, помощь",212725,null],[271922,"2026-10-16T10:21:26",20,"/r +d20+1",212725,null],[271925,"2026-10-16T10:22:04",31,"вы вырываете Ясмин из хватки чего то, подозрительно похожего на язык",212725,null],[271926,"2026-10-16T10:24:05",17,"/Атаковать можно?",212725,null],[271927,"2026-10-16T10:24:18",31,"нет, он ушел вниз",271926,null],[271928,"2026-10-16T10:25:46",20,"- Фух *Беатриче ставит Ясмин на ноги, придерживая ее за плечо. На всякий случай*\n- Эм...у вас все ещё есть желание нырнуть туда, сеньора?",212725,null],[271929,"2026-10-16T10:26:07",31,"вы около колодца или отошлти?/",212725,null],[271930,"2026-10-16T10:26:23",20,"/отошли немного",212725,null],[271931,"2026-10-16T10:27:38",31,"из колодца слышно что то вроде скрипа несмазанного тележного колеса",212725,null],[271934,"2026-10-16T11:19:24",22,"Ясмин одновременно и в ужасе и в ярости.\n\n- О-оно меня т-трогало!\n\nДевочка, покажи, где тебя трогали\nЯ предлагаю это сжечь\n\n- Надо спалить этот шайтанов колодец до тла! \n\nВ руках Ясмин стало формироваться пламя.\n\n- Нет! Н-нет это н-неправильно.\n\nДевушка отшагнула назад и упала на землю.\n\n- Елена, т-та, что пропала. В-вдруг она жива и я ей н-наврежу? Н-надо спуститься. Т-точно надо. М-может там еще есть тот, кому м-можно помочь?",212725,null],[271945,"2026-10-16T11:54:13",17,"— Ваша идея с очищением огнём мне импонирует, но вы правы. Может всё более запутано чем кажется на первый взгляд\n\nВ любом случае кажется нам нужно спустится в колодец и быть готовыми даь отпор, этому... Щупальцу",212725,null],[271947,"2026-10-16T11:56:01",22,"Ясмин кивнула, готовая к погружению в колодец.\n\nНо прежде она аккуратно начала водить по своему телу ладонями, исцеляя ранения",212725,null],[271948,"2026-10-16T11:56:08",22,"/r d8+5",212725,null],[271950,"2026-10-16T11:57:03",22,"-‐Я г-готова, мне н-немного лучше.",212725,null],[271953,"2026-10-16T12:03:10",20,"- Хотите всё-таки туда спуститься? *Беатриче переводит взгляд на колодец*\n\n- Ладно, главное чтобы тварь действительно просто сидела внутри, а не была, ну...самим колодцем.",212725,null],[271954,"2026-10-16T12:03:42",22,"- Я д-думаю, что надо т-туда.",271953,null],[271955,"2026-10-16T12:11:37",31,"с интересом ожидаю вашего плана по проникновению в колодец)/",212725,null],[271956,"2026-10-16T12:12:08",20,"*Беатриче кивает, хотя все ещё собирается протыкать этот подозрительный колодец рапирой. Так, чисто из вредности*",271954,null],[271957,"2026-10-16T12:13:52",20,"- Тогда нужно понять, как мы будем спускаться. И что самое важное - сражаться внутри. \n\n- У меня с этим проблем наверное будет меньше, чем у вас с синьором Марко. Но все же нужно что-то придумать.",271954,null],[271958,"2026-10-16T12:15:54",17,"— Сперва небольшая разведка\n\n\"Вестник посмотри что там\"\n\nМарко кладёт ладонь ему на голову и произносит молитву, ворон начинает источать яркий свет\n\n/Заклинание свет на ворона\n\nПосле чего фамильяр залетает в колодец, а Марко смотрит его глазами",212725,null],[271959,"2026-10-16T12:16:21",31,"Картинкой сброшу",212725,null],[271961,"2026-10-16T12:17:00",31,"/roll d20+7 по ворону языком",212725,null],[271963,"2026-10-16T12:17:19",17,"/ Ворон пал",212725,null],[271964,"2026-10-16T12:17:19",31,"/roll d10+4 ням нМ",212725,null],[271967,"2026-10-16T12:17:49",17,"Марко зажмуривается будто яркий свет ударил в глаза\n\nи трёт переносицу\n\n— Разведчика у нас больше нет...",212725,null],[271968,"2026-10-16T12:18:12",17,"— Внизу огромная жаба монстр, по видимости которая обладает еще и псионными способностями влиять на разум",212725,null],[271969,"2026-10-16T12:18:28",17,"— Это может быть проклятая жертва или просто монстр?",212725,null],[271970,"2026-10-16T12:20:22",20,"- Жертва? По мне огромная лягуха просто сидит внизу и жрет всех кто подходит достаточно близко к колодцу *Беатриче чешет затылок*\n\n- Вы хотите попробовать с ней поговорить, Сеньор Марко?",271969,null],[271971,"2026-10-16T12:20:26",31,"Источник вдохновения",212725,null],[271972,"2026-10-16T12:33:03",17,"— К сожалению я не умею говорить с животными. Хотя в голове четко звучала человеческая речь.\n\nМарко поднял руку и его тень обрела форму головы шакала.\n\n— Я предлагаю без разговоров.\n\n/Божественное оружие вызвал",212725,null],[271973,"2026-10-16T12:42:00",22,"/Сколько глубина примерно?",271960,null],[271974,"2026-10-16T13:01:48",20,"- Полностью поддерживаю *Беатриче оскаливается, вытаскивая рапиру*",271972,null],[271975,"2026-10-16T13:34:58",31,"От 30 до 50 футов",271973,null],[271986,"2026-10-16T14:14:06",22,"В руках Ясмин начинает формироваться огненная сфера.\n\nНабравшись смелости и отмахнувшись от надоедливых теток, Ясмин подходит вновь к колодцу.\n\n/есть зов?",212725,null],[271987,"2026-10-16T14:16:09",17,"/Мы все подходим к колодцу",212725,null],[271988,"2026-10-16T14:16:25",31,"Все спас мудрости сл 16",212725,null],[271989,"2026-10-16T14:16:35",31,"Ща втроем нырнете)",212725,null],[271992,"2026-10-16T14:17:51",22,"/r +7 мудрая Ясмин не повторяет ошибок",271988,null],[271994,"2026-10-16T14:18:00",22,"//не ребят, я нырять!",212725,null],[271995,"2026-10-16T14:18:13",20,"/r d20+1",212725,null],[271997,"2026-10-16T14:18:29",20,"/подожди, я за тобой",271994,null],[271998,"2026-10-16T14:18:41",31,"У жабы ксть меню)/",212725,null],[271999,"2026-10-16T14:18:43",22,"- Бестриче, пошли купаться!",212725,null],[272000,"2026-10-16T14:18:54",20,"- А пошли!",271999,null],[272001,"2026-10-16T14:20:08",17,"/r +6 Марко",212725,null],[272005,"2026-10-16T14:20:58",31,"Ахахвхвхв//",212725,null],[272006,"2026-10-16T14:21:03",31,"Тройной нырок",212725,null],[272008,"2026-10-16T14:21:35",31,"/roll d3 единица Ясмин, двойка Беатриче, тройка Марко",212725,null],[272010,"2026-10-16T14:21:36",22,"/ожидание",212725,null],[272011,"2026-10-16T14:22:13",31,"Ясмин и Беатриче плюхаются в воду и с них сходит очарование. По Марко в полете прилетает язык жабы",212725,null],[272013,"2026-10-16T14:22:19",31,"/roll d20+7",212725,null],[272015,"2026-10-16T14:22:30",31,"Попал вроде?/",212725,null],[272016,"2026-10-16T14:22:44",31,"/roll d10+4 дробящий и схвачен",212725,null],[272018,"2026-10-16T14:22:58",31,"Инициативу кидайте",212725,null],[272019,"2026-10-16T14:23:18",22,"/r +2 ини",212725,null],[272021,"2026-10-16T14:23:21",31,"/roll d20+3 инициатива Гипножабы",212725,null],[272023,"2026-10-16T14:23:54",20,"/r d20+4 иня Беатриче",212725,null],[272025,"2026-10-16T14:25:54",17,"/r +2 Иня Марко",212725,null],[272027,"2026-10-16T14:27:39",31,"Беатриче\nЯсмин\nГипножаба 114 урона\nМарко",212725,null],[272029,"2026-10-16T14:27:49",31,"Беатриче ход",212725,null],[272030,"2026-10-16T14:30:54",20,"*Беатриче отплевываясь от воды выхватывает оружие и бежит прямо на жабу, охватившую Марко*\n\n*Наносит две атаки, целясь по языку чтобы освободить союзника*",212725,null],[272031,"2026-10-16T14:31:12",20,"/r d20+7 рапира\n/r d20+6 кинжал",212725,null],[272033,"2026-10-16T14:31:36",20,"/за удачу перекину, это просто уже дело принципа",212725,null],[272034,"2026-10-16T14:31:43",20,"/r d20+7",212725,null],[272036,"2026-10-16T14:35:19",20,"/r d8+5\n/r d4+4",212725,null],[272038,"2026-10-16T14:35:30",20,"/конец хода",212725,null],[272047,"2026-10-16T14:44:17",31,"Оба прошли/",212725,null],[272048,"2026-10-16T14:44:24",31,"Ход Ясмин",212725,null],[272055,"2026-10-16T14:45:52",22,"В руках Ясмин начинает разгораться пламя. \n\nДевушка возбуждено прикусывает губу и отправляет свой пылающий шар в жабу.\n\n//спас лвк 15\nПылающий шар встаёт за жабой так, чтобы жарить только ее, не цепляя ребят",212725,null],[272056,"2026-10-16T14:46:05",22,"/r 2d6 огонь фул дмг",212725,null],[272058,"2026-10-16T14:46:14",22,"/ход",212725,null],[272059,"2026-10-16T14:46:35",31,"/roll d20+3 жабья ловкость",272055,null],[272061,"2026-10-16T14:46:46",31,"Пригорела/",212725,null],[272062,"2026-10-16T14:47:08",31,"Ход жабы/",212725,null],[272063,"2026-10-16T14:47:30",31,"/roll d6 перезарядка спец приёма",212725,null],[272065,"2026-10-16T14:47:37",31,"Не прокатило/",212725,null],[272066,"2026-10-16T14:47:52",31,"Тогда рывком подтягиваю Марко и кусаю его",212725,null],[272068,"2026-10-16T14:48:17",31,"/roll d20+7\n/roll 2d6+4",212725,null],[272070,"2026-10-16T14:48:27",31,"Хорошо куснула/",212725,null],[272071,"2026-10-16T14:48:30",31,"Ход/",212725,null],[272072,"2026-10-16T14:49:13",31,"Марко, ты схвачен, скорость ноль, бить можешь без помехи, если хочешь вырваться, то соревнование атлетики или акробатики против ее атлетики/",212725,null],[272073,"2026-10-16T14:49:18",31,"Ход Марко",212725,null],[272076,"2026-10-16T14:51:57",31,"Пока жабке везет с кубами/",212725,null],[272080,"2026-10-16T14:54:19",17,"Марко превращает обе руки в черные когти и впивается в язык жабы. Рядом этот же язык кусает парящая голова шакала\n\n/Нанесение ран и атака оружием божества",212725,null],[272081,"2026-10-16T14:54:50",17,"/r +6 Нанесение\n\n4d10 Некротический\n\n+6 Оружие\n\nd8+4",212725,null],[272083,"2026-10-16T14:56:08",17,"Впившись когтями поглубже тень проникла еще и внутрь жабьего языка\n\n/Божественный канал жреца смерти еще + 13 урона некротикой",212725,null],[272084,"2026-10-16T14:57:37",17,"/Конец хода",212725,null],[272085,"2026-10-16T15:18:11",31,"14 не прошло, у жабы кд 15. Посчитай пожалуйста весь урон/",212725,null],[272086,"2026-10-16T15:18:26",31,"Вроде, 28?/",212725,null],[272090,"2026-10-16T15:23:43",31,"Ход Беатриче/",212725,null],[272091,"2026-10-16T15:25:07",20,"Беатриче продолжает пырять жабу \n\n/снова две атаки",212725,null],[272093,"2026-10-16T15:25:33",20,"/r d20+7\n/r d20+6",212725,null],[272095,"2026-10-16T15:25:42",31,"Обе прошли/",212725,null],[272096,"2026-10-16T15:25:53",20,"/r d8+5\n/r d4+4",212725,null],[272098,"2026-10-16T15:26:29",20,"/и всплеск действий еще - хочу попробовать вытащить Марко",212725,null],[272099,"2026-10-16T15:26:43",31,"Давай/",212725,null],[272100,"2026-10-16T15:26:58",31,"/roll d20+5 атлетика жабы",212725,null],[272101,"2026-10-16T15:26:58",20,"/r d20+1 тянем потянем",212725,null],[272104,"2026-10-16T15:27:15",31,"Увы, Марко все еще в плену/",212725,null],[272105,"2026-10-16T15:27:22",31,"Ход Ясмин/",212725,null],[272109,"2026-10-16T15:43:03",22,"/r 2d6 сфера пассивно жарит",212725,null],[272113,"2026-10-16T15:47:43",22,"Ясмин призывает свое Божественное оружие в виде куриной лапы и бьет жабу.\n\nДевушка широко улыбается, наслаждаясь видом огня. Потом ее взгляд цепляется за раненого Марка и она бросает все свои силы на то, чтобы ему помочь.\n\nЯс чего усиливается метамагией и лечит Марко издалека. \n\n//вроде как оружие - бонус, лечение -действие",212725,null],[272114,"2026-10-16T15:48:39",22,"/r d20+7 оружием цап\n/r d8+5 урон режущий лапкой\n/r d8+5 лечим Марко",212725,null],[272116,"2026-10-16T15:49:00",22,"//Ясмин определенно больше нравится Марко, чем жаба",212725,null],[272117,"2026-10-16T15:49:03",22,"/ход",212725,null],[272118,"2026-10-16T15:51:20",31,"Ход жабы",212725,null],[272119,"2026-10-16T15:51:32",31,"/roll d6 зарядка спец удара",212725,null],[272121,"2026-10-16T15:51:38",31,"Охохонюшки/",212725,null],[272122,"2026-10-16T15:51:57",22,"/каждый ход тут надо лвк кидать как я поняла и будет урон либо половина",272110,null],[272123,"2026-10-16T15:52:43",31,"Специальная атака Психо Крик. Ваши головы наполняются инфернальным кваканьем. Спас мудрости СЛ 18 от всех",212725,null],[272127,"2026-10-16T15:53:31",31,"/roll 4d6 половина при прохождении спаса, если не прошли, то полный урон и состояние испуганный",212725,null],[272129,"2026-10-16T15:55:03",31,"В этот раз буду считать что жаба не увернулась/",272122,null],[272130,"2026-10-16T15:56:59",31,"/roll d20+7 укус по Марко",212725,null],[272132,"2026-10-16T15:57:09",31,"/roll 2d6+4",212725,null],[272134,"2026-10-16T15:57:18",31,"Марко еще живой?/",212725,null],[272135,"2026-10-16T15:58:56",31,"Что то мне подсказывает, что упал/",212725,null],[272137,"2026-10-16T16:01:08",22,"/r +7 Ясмин смотрит на Марко, преисполнясь вдохновением",272123,null],[272141,"2026-10-16T16:01:32",22,"/эх такая попытка, я уже думала что у неё и правда кубы хорошо только на мужиков летят",212725,null],[272147,"2026-10-16T16:03:49",22,"/стоит, я лечила",272135,null],[272150,"2026-10-16T16:06:37",31,"Ну жду броски Коли и Кати/",212725,null],[272187,"2026-10-16T16:37:14",20,"/r d20+1 тяжко немудрым воинам",212725,null],[272229,"2026-10-16T17:32:47",17,"/r +6 Спас",272123,null],[272237,"2026-10-16T17:38:29",31,"Коля, живой?/ если да, то твой ход/",212725,null],[272238,"2026-10-16T17:38:43",17,"/Щас секунду считаю",212725,null],[272240,"2026-10-16T17:41:17",17,"/ Хиты Марко 27/27\n\nУрон:  14\n\nЛечение: 13\n\nУрон: 6+15 \n\n\nИтоговые хиты: 5/27",212725,null],[272241,"2026-10-16T17:41:36",17,"Из шакальей головы окутавшей голову Марко льётся кровь",212725,null],[272242,"2026-10-16T17:41:55",17,"Он кусает тварь сам и еще кусает парящее божественное оружее",212725,null],[272243,"2026-10-16T17:42:25",17,"/r +6 Нанесение ран \n\n4d10 Некротика\n\n+6 Оружие\n\nd8+4 Урон",212725,null],[272245,"2026-10-16T17:42:38",17,"/ Опачки 42 урона",212725,null],[272248,"2026-10-16T17:42:49",31,"Откуда столько некротики?/",212725,null],[272249,"2026-10-16T17:42:54",17,"/ 30",212725,null],[272251,"2026-10-16T17:44:53",31,"Не, ну ты посмотри, ровно все хп добил, тика в тику",212725,null],[272252,"2026-10-16T17:45:07",22,"/нанесение ран 2 круг. На 1 круге 3д10, а дальше скейлится",272248,null],[272253,"2026-10-16T17:45:17",31,"Описывай смерть жабы, убивец-живодёр",212725,null],[272254,"2026-10-16T17:45:34",17,"/ Ох я щас опишу",212725,null],[272255,"2026-10-16T17:45:59",31,"Давай, не ограничивай себя в кровяке, мясе и жабьем говне/",212725,null],[272262,"2026-10-16T17:52:31",17,"Марко в образе тёмного шакала набросился на монстра \n\nЗубастая пасть сомкнулась на мягком языке, он сжал зубы, оторвал кусок, тот истлел в зубах, снова и снова он кусал и кусал рвал и метал ошмётки жабьего языка в стороны продвигаясь глубже в рот монстра.\n\nСклизкая жижа, вперемешку с кровью и грязью лилась по сторонам.\n\nПарящая шакалья голова тоже рвала с другой стороны как свора голодных и... бешеных собак Марко добрался и нырнул внутрь жабьего рта.\n\nСледователь скрылся внутри монстра полностью, как не билась дьявольская жаба марко внутри драл когтями и кусал всё до чего мог дотянуться, от чего тело жабы вздрагивало при каждом ударе изнутри.\n\nПарящая пасть схватилась в мёртвой хватке за глаз монстра и вырвала его с чавкающим звуком из образовавшегося прогала вылез Марко полностью покрытый слизью, желчью и ихором демонической твари.\n\nОн вылез медленно и пошатываясь шагнул два шага, после свалился без сознания\n\nОбе головы шакала медленно, как будто песок ссыпали на землю, стекли вниз и вернулись в его тень",212725,null],[272274,"2026-10-16T17:57:04",31,"Итак, жаба мертва, Марко без сознания, девушки, вам слово/",212725,null],[272304,"2026-10-16T18:28:06",22,"Ясмин пошатываясь подходит к товарищам и аккуратно до них дотрагивается.\n\nДевушка собирает остатки своих сил, чтобы излечить их обоих.\n\nКакая расточительная трата магии",212725,null],[272305,"2026-10-16T18:28:22",22,"/r d8+5 лечение Беатрисс и Марко",212725,null],[272307,"2026-10-16T18:29:12",22,"/r d8+5 лечение себя",212725,null],[272309,"2026-10-16T18:30:10",22,"Убедившись, что товарищи в порядке, девушка прислоняется к стене и, прикрыв глаза, читает молитву, чтобы немного излечить уже себя.",212725,null],[272316,"2026-10-16T18:37:06",20,"*Беатриче благодарно кивает Ясмин за излечение, а сама принимается вытаскивать бессознательное тело Марко из лужи крови и грязи у тела монстра.*",212725,null],[272321,"2026-10-16T18:39:58",17,"Теплая энергия Ясмин разлилась по телу и залечила самые критические раны, Марко, кряхтя, опираясь на Беатриче поднялся\n\nОн снял разбитые очки, по левой линзе поползла паутинка трещин, убрал в нагрудный карман.\n\n— Благодарю вас обеих. \n\nЧучуть поклонился прижав руку к груди\n\n— Давайте поищем тела или вещи девушки или жреца... Думаю в живых никого тут явно нет.",212725,null],[272324,"2026-10-16T18:42:32",31,"Ща будет вам лут, не буду душить проверками//",212725,null],[272327,"2026-10-16T18:44:52",31,"/roll d10*20 золото в разных монетах",212725,null],[272329,"2026-10-16T18:45:02",31,"Так, это не все",212725,null],[272331,"2026-10-16T18:45:38",31,"Амулет благочестия +1",212725,null],[272336,"2026-10-16T18:47:11",31,"Молитвенник с именем \"отец Марк\", видимо это то, что осталось от того жреца, что приходил ранее. Стоит отнести в церковь",212725,null],[272338,"2026-10-16T18:48:01",31,"А также кучу костей людей и животных, куски ткани, клочь шкочт и очень много жабьего дерьма. Брать это с собой или нет решайте сами",212725,null],[272339,"2026-10-16T18:48:06",17,"/ @lady_godzilla забирай, если я буду ресать божественный канал у Лёши все враги станут по 200 хитов мешками",212725,null],[272340,"2026-10-16T18:48:09",31,"И да, как будете вылезать?",212725,null],[272341,"2026-10-16T18:48:50",31,"Ну я и не думал тебе кго отдавать, это все твуи Аскелаторсткй знак, а ты точно не пол свет)/",272339,null],[272362,"2026-10-16T19:34:02",22,"//амулет имба.. да, все дела.. но с именем Акселатора он мне тоже не нужен, извините 🙈\n\nЯ напишу пост о торжественной передачи в церковь этого добра, но попозже",212725,null],[272523,"2026-10-16T20:55:16",22,"Ясмин держалась исключительно на упрямстве.\nПосле схватки с жабой каждый вдох отдавался болью, пальцы дрожали. Девушка подошла к Беатриче и Марко. Она прислонила ладони к их ранам и призвала свой свет. Ясмин сосредоточилась, стараясь выдавить из своего тела как можно больше тепла и света.\n\nВ глазах поплыло, а в голове вновь раздались голоса.\n\nНачинай всегда с себя!\nТвоя добросердечность доведет тебя до гроба!\nДурочка\n\nЯсмин грустно улыбнулась и опустилась возле стены, переводя дыхание, а после занялась и своими ранами, однако свет предательски иссякал.\n\nСреди кучи мусора, ткани и костей был найден молитвенник и какой-то амулет. Ясмин даже особо не смотрела, пытаясь сосредоточиться на том, чтобы не упасть лицом в смердящую тушу жабы.\n\n— Смотри, Ясмин, это для тебя!\n\nМарко передал девушке амулет павшего жреца.\n\nО-о-о как это мило!\nПусть в следующий раз твой добытчик принесет нам печень!\nЯсмин, дорогая, я нашел этот мусор, он точно для тебя!\n\nИ-хи-хи-хи!\n\nЯсмин устало подняла взгляд. Она сочла бы этот жест очаровательным, будь это даже простой дорожный камень или листик, но амулет...\n\n—  С-спасибо, конечно. П-правда. Это очень мило с вашей с-стороны. Но, М-марко, если хотите сделать мне подарок, пусть л-лучше это будет браслет. М-можно даже с маленькими п-подвесками. А не а-амулет, п-покойника.\n\nДевушка тяжело вздохнула и посерьезнела.\n\n— А-амулет, молитвенник и о-останки, которые н-найдем, передадим в церковь его б-бога. Так буде п-правильно.",212725,null],[272538,"2026-10-16T21:08:59",20,"- Вот это правильный ход мыслей, Синьора *Беатриче кивает, смотря теперь на девушку даже с большим уважением*\n- И кости давайте тоже достанем - пусть хоть упокоят этих бедняг по человечески",272523,null],[272540,"2026-10-16T21:09:39",20,"*Она осматривает своды пещеры и выход наверх из колодца*\n\n/Сможет добраться туда скорость лазания?",212725,null],[272541,"2026-10-16T21:12:42",22,"— У-у меня есть веревка!",212725,null],[272546,"2026-10-16T21:16:36",17,"— Я вам услышал, отнесем его в Церковь. А чем вас порадовать я обещаю придумать. \n\n\nМарко зажав рану на животе которая затянулась но саднила покидал в сумку молитвенник и амулет",272523,null],[272550,"2026-10-16T21:18:07",20,"- Это хорошо *Беатриче прикидывает, сколько займет вытащить такой объем костей*\n\n- Но синьора, вы уверены что этот бой вас не слишком измотал? Я всегда могу просто поднять вас и синьора Марко наверх сама. *Она с беспокойством осматривает Ясмин и раненого Марко*\n\n- В случае в сеньором Марко я бы сказала что даже настаиваю. Нельзя в таком состоянии самому лезть",212725,null],[272555,"2026-10-16T21:22:15",17,"— Верно. Я займусь. \n\nИз сумки он достал мужской шейный платок. Красивый, шелковый. и начал складывать в него как в кулёк кости несчастных мертвецов",272538,null],[272556,"2026-10-16T21:22:59",17,"— Сиора Ясмин меня исцелила, Беатриче. Не переживай.",212725,null],[272577,"2026-10-16T22:32:54",22,"-- Я-я справлюсь! Н-наверное.",212725,null],[272597,"2026-10-17T12:27:20",31,"Как опишите что вылезли, дам вам сцену в церкви и закроем этот побочный квест/",212725,null],[272602,"2026-10-17T12:35:47",20,"*Беатриче фыркает, когда они оба отказываются от помощи*\n\n- Вот всегда вы так, сиоры. Нужно же не только помощь оказывать, но и уметь ее принимать.\n\n*Она забирается по стене на верх колодца, закрепляя и спуская вниз верёвку для своих упрямых спутников. Хотя если кто-то из них все же не удержится и сорвётся обратно в воду, то точно не отвертеться больше от ее помощи, хмпф.*\n\n*Сама она не теряя времени довольно шустро начинает таскать груды костей вверх, по охапке за заход*",272556,null],[272632,"2026-10-17T13:20:13",22,"Ясмин медленно, но аккуратно вылезает из колодца, с помощью Беатриче.",212725,null],[273220,"2026-10-17T17:45:50",17,"Марко вылазит последним превращая руки в черные когти благодаря этому цепляется за скалу",212725,null],[273232,"2026-10-17T17:49:43",31,"Ок, сейчас дам сцену/",212725,null],[273241,"2026-10-17T17:52:23",31,"Церковь Святой Катарины встретила вас тишиной, запахом ладана и обеспокоенным видом пожилого жреца.\n\n- Сиоры, что с вами произошло? Вам нужна помощь? И что это за мешок с костями? Неужели опять Зверь?",212725,null],[273314,"2026-10-17T18:24:07",22,"Ясмин осторожно протянула останки, амулет и молитвенник. Она прижала руку к своей груди и на её пальцах дрогнуло золотое сияние, тёплое и тихое.\n\nОна не стала произносить чужих молитв, одако склонила голову в коротком молчании, позволяя Свету коснуться останков.\n\n—Я не знаю вашей веры, однако в-верю, что это человек с-следовал ей до конца. Надеюсь, что в конце своего пути он в-встретит нечто доброе.\n\nДевушка грустно улыбнулась и кратко рассказала о встрече в колодце.",212725,null],[273371,"2026-10-17T18:59:29",31,"- О, Свет... Мы не знали что случилось с Марком, он был самым стойким из нас, и когда он не вернулся, все что мы могли - это только оградить паству от этого проклятого места. \n\n- Церковь не забудет вашего подвига. И вашей скромности. Амулет вновь займёт своё место в Алтаре. Вас же я прошу принять его благословение на этой земле и этот скромный ответный дар от нашей общины.\n\n//вы получаете Благословение Аскелатора на этой локации. Все проверки, связанные с Мудростью, вы совершаете с преимуществом.\n\nТакже вы получаете по 200 золота каждый//\n\n//первый побочный квест на локации вы выполнили. Но девушку пока не нашли. Да и друида тоже//",212725,null],[273376,"2026-10-17T19:03:36",22,"Девушка покорно приняла благословение, однако карги не были столь миролюбивы и отчаянно шипели в её голове, вызывая сильную мигрень.\n\n-- С-скажите, а вы знаете Елену? Г'говорят, что она пропала, в-вам часом не известно ли ч-что-нибудь?",212725,null],[273378,"2026-10-17T19:06:19",31,"- Дочь мельника? Хорошая девушка, прилежная в молитвах, радость родителей. Я слышал что она пропала, и вознес молитвы за то, чтобы она нашлась невредимой. Но боюсь, я не знаю ничего о том, куда бы она могла пропасть. Ввиду своей молодости, она пока не обрела привычки к регулярной исповеди",273376,null],[273382,"2026-10-17T19:09:54",22,"Ясмин кивнула и обернулась к товарищам.\n\n-- М-может спросим у ее о-отца? Где и когда он в-видел её в п-последний раз.",212725,null],[273388,"2026-10-17T19:11:13",31,"- Робер на мельнице. На ветряной, неподалёку от Церкви",212725,null],[274991,"2026-10-19T10:09:47",31,"Как будете готовы, отпишите. Ближайщие пару часов я тут//",212725,null],[274994,"2026-10-19T10:13:33",17,"Марко было не по себе в церкви, голова шумела. Куда бы он не посмотрел он вспышками видел иконостас в огне, упавший колокол раздробивший алтарь и другие подобные разрушения.",212725,null],[274996,"2026-10-19T10:14:01",17,"— Спасибо вам. Мы наведаемся к нему прямо сейчас.",212725,null],[274999,"2026-10-19T10:21:12",22,"Ясмин кивнула и покинула церковь вместе с остальными.",212725,null],[275007,"2026-10-19T10:34:21",31,"Мельница Робера и впрямь была неподалеку. И сам он был там. Уставший мужчина сидел неподалеку от входа на мельницу, опустив голову. Похоже, он с ног сбился в поисках дочери и сейчас просто исчерпал силы и просто покорно ждал новостей",212725,null],[275008,"2026-10-19T10:39:23",17,"— Добрый день синьор Робер. Мы занялись поисками вашей дочери, у старого колодца её нет. Ни живой, ни мёртвой. Поэтому возможно еще есть надежда. Расскажите где вы еще не искали вашу дочь?",212725,null],[275009,"2026-10-19T10:41:50",17,"Сердце Марко сжималось когда он видел этого мужчину\n\nОн ложил паралели на себя\n\nПервые часы, когда узнал, что Лючия пропала. Он был сам не свой, метался без еды и сна в поисках. \n\nКогда он поднял её мёртвое тело у причала и понял, что не успел. Это был конец всего. Так ему казалось.\n\nНедели, месяцы после, он узнал, что души его дочери нет в загробном мире. И тогда он снова начал поиски. Снова эта рана на сердце была вскрыта, снова самое страшное, что существует в этом мире одолело его и начало мучать.\n\nНадежда.",212725,null],[275010,"2026-10-19T10:46:00",31,"Робер поднимает голову\n\n- Что, колодец? Елена бы не пошла туда... Она умная девочка, и знает что там опасно... Но спасибо вам, что проверили. Я оббежал всю деревню, но никто словно ее не видел. Или не говорят мне...",212725,null],[275011,"2026-10-19T10:47:27",17,"— КОго вы подозреваете во вранье?",212725,null],[275012,"2026-10-19T10:51:01",31,"- подружек ее, Марту и Клаудию. Обе божаться, что не знают где Елена. Но я чувствую, что это не так, что то они знают. Но не могу же я из как то принудить говорит правду? В конце то концов, мои подозрения ведь могут быть и напрасными... А прошло уже три дня, как Елена пропала...",212725,null],[275013,"2026-10-19T10:56:04",20,"- Она раньше никогда так на долго не пропадала?\n\n*Беатриче тоже невольно перекладывает ситуацию на себя, хотя в отличие от Марко на роль самой Елены, а не ее отца. Всё-таки она не раз сама пропадала днями, потрепав нервы родителям*",212725,null],[275014,"2026-10-19T10:57:40",22,"Ясмин подходит ближе и кладёт руку на плечо Роберу. \n\n-- Мы постараемся в-вам помочь. Р-раскажи, что это з-за подруги?",212725,null],[275015,"2026-10-19T10:58:13",31,"Робер улыбается.\n\n- Нет, никогда. Я понимаю, что она взрослеет, все таки 16 лет это уже почти невеста, но нет, она никогда не пропадала",275013,null],[275016,"2026-10-19T11:00:24",31,"- Клаудия - дочь мясника, они с Еленой с детства дружат, одногодки. А Марта чуть старше их, недавно в Каталуну переехала с матерью, она у Дуба официанткой работает",275014,null],[275017,"2026-10-19T11:02:48",20,"- Хм, тогда это действительно странно, обычно такое начинается лет, ну...с 13? Во всяком случае у нас с старшим братом так было. \n\n*Беатриче задумывается. Что-то тут действительно нечисто. Она поворачивается к Ясмин*\n\n- Вы правы, сеньора. Нужно искать.",275015,null],[275018,"2026-10-19T11:07:59",22,"Ясмин опустилась на корточки рядом с мужчиной и заглянула ему в глаза.\n\n-- Эти д-девочки, они плохо на Елену в-влияют?\n\nКак мы на тебя плохо влияем!\nНет, как свет на нее плохо влияет!\nДа ну глупости, вы посмотрите, ей же явно понравилось причинять свет\n\nЯсмин чуть порощилась и выпрямилась. Она достала флягу с водой и сделала несколько глотков, в надежде, что это поможет сглотнуть этот мерзкий, вонючий горелым мясом ком.\n\n\"Надо будет не забыть снять комнату в таверне, да взять бутылочку вина. И спросить, можно ли будет разжечь в комнате кальян. Хотя нет, нельзя спрашивать, потом сама найду место.\n\nИ заказать мясную нарезку\n\nТочно. И мясную нарезку. Так стоп! Такую нарезку?! \n\nНет-нет-нет. \n\nО, свет! Почему мои мысли крутятся вокруг собственных прихотей. \nДевочка. Я должна найти эту девочку. Все остальное неважно.\"\n\nОпять пытаешься забыться в проблемах других? Слабачка!",212725,null],[275019,"2026-10-19T11:08:57",22,"‐‐ Нужно н-навестить девочек. Кто б-будет ближе всего?",212725,null],[275020,"2026-10-19T11:09:43",31,"- Да у нас все близко. Но таверна поближе наверное будет",212725,null],[275026,"2026-10-19T11:23:39",17,"Марко тоже ближе подошел. Похлопал мужчину по плечу\n\n— Мы найдём её или найдём правду о её судьбе. Крепитесь.",212725,null],[275182,"2026-10-19T14:06:28",22,"-- Тогда н-начннм с таверны, если н-никто не против?",212725,null],[275187,"2026-10-19T14:57:32",31,"Таверна вновь встречает вас гомоном, казалось бы, вы ушли отсюда всего пару часов назад, а словно несколько дней прошло. \n\nОфициантка, видимо та самая Марта, занята разносом заказов.\n\nДуб, огромный трактирщик, тоже занят. Он подсел на уши к очередному посетителю и что то рассказывает",212725,null],[275189,"2026-10-19T15:00:37",17,"Марко присел за столик приглашая и спутниц с собой. Потом жестом подозвал официантку.\n\n— Марта? Можно вас ненадолго на разговор по поводу вашей подруги Елены.",212725,null],[275190,"2026-10-19T15:01:19",31,"Девушка подходит, не сказать что с большой охотой.\n\n- а вам то какое дело? И вообще, я работаю",275189,null],[275191,"2026-10-19T15:01:58",17,"— Не беспокойтесь о работе. С вашим начальником оговорено.\n\nВрёт Марко чтобы ускорить дело\n\n— Всего пара вопросов.",212725,null],[275192,"2026-10-19T15:02:11",31,"- ну если только быстро",212725,null],[275193,"2026-10-19T15:02:35",17,"/r d20+6+d4 Проницательность на её мимику и выражение лица когда она услышала о Елене",212725,null],[275196,"2026-10-19T15:03:43",22,"-- А п-почему вы так реагируете? Р-разве вы не хотите найти свою п-подругу? \n\nЯсмин пристально посмотрела на девушку.",212725,null],[275197,"2026-10-19T15:03:49",22,"/помощь",275194,null],[275199,"2026-10-19T15:05:00",31,"Ты видишь по лицу девушки, что она не переживает за судьбу подруги. Она не боится за нее, го что то знает",275194,null],[275200,"2026-10-19T15:05:32",31,"- я ее и не теряла. Все с ней нормально",275196,null],[275201,"2026-10-19T15:06:03",22,"- А где она? Вся д-деревня только и говорит, что она п-пропала.",275200,null],[275204,"2026-10-19T15:06:58",17,"— Скажите, она нашла кого то, кто помог ей вырваться из деревни? Она уехала с ним?\n\nСледователь делает смелое заявление основаное только на внутренней чуечке",275200,null],[275205,"2026-10-19T15:07:29",17,"Марко выкладывает на стол мешочек с золотыми монетами и пододвигает его девушке по столу",212725,null],[275206,"2026-10-19T15:07:36",31,"- это ее дело, а не ваше",275201,null],[275207,"2026-10-19T15:07:40",17,"— Мы очень хотим знать, что с ней всё хорошо",212725,null],[275210,"2026-10-19T15:10:52",31,"Золото исчезает в переднике. Марта садится за стол и говорит, понищив голос\n\n- она замуж за старика не хочет. Ее отец почти разорился с тех пор как новая водяная мельница открылась. И этот мельник новый, старый мужик, к Лениному отцу пришёл и пркдложил сватовство, десуть дела объединить. Вот она и спряталась, говорила что сама заработает и долги отца покроет, чтобы только за старого козла не выходить",275205,null],[275211,"2026-10-19T15:11:28",22,"Какой расточитель!\nПросто отвратительно.\nМожно же просто поджечь девке пятки и она запоет. И я вижу, нашему солнышку нравится эта идея.\n\nЯсмин усилием подавила в себе желание пригрозить хамке.\n\n-- О, как жаль, я правда думала, что столь завидная невеста, как вы, сможет нам помочь. Шарль говорил, что ваша доброта вашей души способна тронуть любое сердце.",275205,null],[275213,"2026-10-19T15:12:14",22,"//а злато уже потрачено, ладно",212725,null],[275214,"2026-10-19T15:13:00",31,"- в общем, не ищите вы ее. Сама найдется",212725,null],[275216,"2026-10-19T15:14:21",22,"-- А разорился п-почему? Новый м-мельник дешевле продаёт? И к-как его зовут?",212725,null],[275218,"2026-10-19T15:16:26",31,"- дешевле мелет, и быстрее. Вода то всегда льётся, а не от силы ветра зависит. Вот и идут к нему чаще. Прогресс. А зовут его Огюст",275216,null],[275228,"2026-10-19T15:24:29",20,"- Лезть с такими предложениями к синьорите, которой всего 16?! *Беатриче заметно закипает*\n- вот ведь figlio di puttana!\n\n*Будь на месте Елены ее сестра, она бы была уже на полпути чтобы набить рожу этому ублюдку. Но здесь человек мало знакомый, такой помощью можно только дело усугубить...*",212725,null],[275230,"2026-10-19T15:25:06",31,"- вот и Елена так подумала. Но по закону то можно уже",275228,null],[275237,"2026-10-19T15:28:59",20,"- Закон законом, а порядочность всяко надо иметь *бурчит под нос девушка, думая что делать. Может вызвать этого мельника на дуэль? Или раскопать на него какие-нибудь темные секреты?*\n\n*Она вздыхает, поворачиваясь к спутникам*\n\n- Что будем делать?",275230,null],[275241,"2026-10-19T15:37:59",22,"-- Н-надо послушать Клаудию, а после д-думаю, что все пути в-ведут к самому Огюсту.",212725,null],[275245,"2026-10-19T15:42:44",31,"Идёте к Клаудии?/",212725,null],[275246,"2026-10-19T15:45:06",17,"— Милая, мы поняли ситуацию. Конечно, мы низачто не отдадим Елену в лапы старика. Знаешь ли ты где девочка спряталась?",212725,null],[275253,"2026-10-19T15:51:55",31,"- нет, не знаю. Да и не пряталась она. Она хотела заработать денег, чтобы ее саму не продали как вещь",275246,null],[275265,"2026-10-19T15:58:17",31,"Сейчас поужинаю и дам вам сцену у Клаудии/",212725,null],[275267,"2026-10-19T15:59:39",17,"/Приятного аппетита",212725,null],[275268,"2026-10-19T16:02:43",22,"-- Мне с-страшно представить, как она с-собралась зарабатывать.\n\nНаследство!\nТочно, я как овдовела, так сразу разбогатела!\n\nЯсмин нахмурилась и задумчиво стала теребить в руках локон волос.\n\n-- Н-надеюсь, что она не решила о-одолеть того зверя, о котором все г-говорят.",212725,null],[275270,"2026-10-19T16:03:31",17,"— Это было очень глупо с её стороны. Судя по тому как нас троих чуть не отделала жаба из колодца.",212725,null],[275277,"2026-10-19T16:06:11",22,"-- Какие м-мозги в шестнадцать л-лет...\n\nЯсмин посталась унять нервы и спрятала дрожащие руки в складках одежды.\n\n-- М-мне кажется, что она м-моглп посчитать это самым б-быстрым заработком. Очень х-хочу верить, что заблуждаюсь. \n\nПо себе судит",212725,null],[275279,"2026-10-19T16:07:33",17,"— КТо то из подруг может знать где она прячется. И к каждой можно найти подход.",212725,null],[275281,"2026-10-19T16:07:45",17,"— Я тактично положил три золотых сверху мешка полного медных",212725,null],[275287,"2026-10-19T16:08:24",17,"— А с Клаудией возможно не сработает подкуп. Я попробую подобрать нужный рычаг, нужно только взглянуть на неё повнимательнее.",212725,null],[275291,"2026-10-19T16:08:48",20,"*Беатриче хмурится, вспоминая себя в шестнадцать и чем она занималась (что учитывая ее возраст не так сложно, всего пара лет минуло). Неужели Ясмин имеет ввиду...*\n\n- Азартные игры?! *Она поворачивается к девушке с широко раскрытыми глазами*\n- Уж не думаете что она пошла на такое?",275277,null],[275298,"2026-10-19T16:12:31",17,"— Она хочет выплатить долг отца, верно? А что будет потом? Ветряная мельница проигрывает в эфективности и экономической выгоде водяной.",212725,null],[275321,"2026-10-19T16:17:43",20,"*Беатриче идёт, глубоко задумавшись. Потом щелкает пальцами*\n\n- Хм...может предложить ему контракт от семьи Висконти на поставку вина в эту деревню? Ассортимент тут довольно скудный, так что есть ниша которую можно занять. Он будет получать процент как поставщик и сможет поправить свои дела.\n\n- Ну и конечно имя Висконти и качество нашего вина прославится ещё и здесь, что не менее важно! *Гордо вздергивает подбородок*",275298,null],[275323,"2026-10-19T16:17:46",22,"Ясмин показательно осмотрела деревушку.\n\n-- Д-да как будто бы тут и в-выбора особо нет... В-ветрянач, водная.. я не разбираюсь в таких в-вещах. Но разве о-они обе не зависят от сил природы?",275291,null],[275324,"2026-10-19T16:18:20",22,"//Беатриче явно решила поиграть в экономический симулятор😁",212725,null],[275328,"2026-10-19T16:19:14",31,"Вот так, за обсуждением версий (спасибо за это), вы и дошли до мясницкой лавки отца Клаудии. Девушку не пришлось искать долго, она занималась тем, что подметала двор.",212725,null],[275332,"2026-10-19T16:20:39",31,"А я жду что она подкатит с этим к Дубу. Даже подумал аргументы)/",275324,null],[275362,"2026-10-19T16:25:25",20,"/ну как раз план - подходим к дубу, даём дегустировать вино и убеждаем что это именно то, чего ему всю жизнь не хватало\n/Потом идём к мельнику и предлагаем заняться поставками этого самого вина из города в таверну\n/Профит 😎",275332,null],[275366,"2026-10-19T16:26:24",22,"//ждем, когда Беатриче пройдёт эту игру",212725,null],[275368,"2026-10-19T16:27:08",22,"-- К-клаудия?\n\nРобко откликнулась девушку Ясмин.",275328,null],[275401,"2026-10-19T16:34:59",31,"- да?\n\nДевушка отвечает неожиданно низким голосом, и оборачивается. Крепкая, статная, кровь с молоком",275368,null],[275413,"2026-10-19T16:36:16",31,"Видно что папа мясник не обделял ребенка мяском на обед/",212725,null],[275418,"2026-10-19T16:37:16",17,"— Добрый день. Мы ищем Елену по просьбе её безутешного отца .",212725,null],[275424,"2026-10-19T16:38:13",31,"- а почему ко мне пришли? Думаете, я подругу под прилавком спрятала?",212725,null],[275425,"2026-10-19T16:38:16",17,"Марко внимательно присмотрелся, чтобы понять отношение девушки к Елене и всей ситуации связаной с ней. Чобы подобрать стратегию переговоров более осознано",212725,null],[275426,"2026-10-19T16:38:27",17,"/r d20+6+d4 Проницательность",212725,null],[275429,"2026-10-19T16:38:40",31,"Ты забодал все проходить/",212725,null],[275430,"2026-10-19T16:38:49",31,"Хер соврёшь/",212725,null],[275438,"2026-10-19T16:39:48",31,"В глазах девушки ты читаешь легкое беспокойство. Она знает куда делась Елена, точно знает. И похоже, винит себя",212725,null],[275440,"2026-10-19T16:39:57",22,"//это же Коля. Просто накинь там сверху сложность да и все 😁",275429,null],[275444,"2026-10-19T16:40:39",31,"Запишу это на своей коробке для завтрака/",275440,null],[275452,"2026-10-19T16:42:46",17,"— Я же вижу, за этой нервной шуткой скрывается беспокойная подруга, которая знает что случилось и даже винит себя. Мы уже вкурсе о сделке на которую её хотели обречь, связать судьбы со стариком в молодом возрасте это ужасно. Мы стараемся найти выход из ситуации, но сперва, хотим найти Елену. Ей может грозить опасность.",212725,null],[275483,"2026-10-19T16:50:23",31,"- откуда вы... Врочем, неважно.  Елена не в беде. Она... Просто она нашла работу, точнее, я подсказала, что графиня Монаро ищет горничную. Ну я и посоветовала Елене к ней попроситься. Заработать немного, и заодно спрятаться от отца и этого Огюста мерзкого. Ну она и ушла к особняку третьего дня как. И с тех пор нет вестей о ней. Хотя из особняка редко новости бывают, графиня уединенно живёт. Но я все равно немного волнуюсь. И отцу ее ничего не могу сказать, я молчать обещала. И вы не говорите!",212725,null],[275499,"2026-10-19T16:54:26",22,"-- Р-раскажите о графине. Она х-хороший человек?\n\nХороших людей не бывает, милочка, пора бы тебе это запомнить\n\nЯсмин опять заметила пары глаз за спиной собеседницы.\n\n\"Устала, я просто устала. Мы ведь даже не отдыхали, после этой ситуации с колодцем. Скоро они исчезнут, всегда ведь исчезают.\"",212725,null],[275502,"2026-10-19T16:56:27",31,"- я не знаю... Да никто не знает. Графиня затворница, говорят она годами не выходит из дома. Иногда нанимает слуш, что живут в ее большом доме. Хорошая она или нет? Наверное да, я не слышала чтобы она кого то обижала. Про нее вообще мало кто что знает",275499,null],[275597,"2026-10-19T17:19:59",17,"— Откуда вы узнали, что графиня ищет себе горничную?",212725,null],[275603,"2026-10-19T17:23:05",31,"- ее дворецкий, Маркус, сообщил. Он единственный, кто регулярно спускается в деревню. Продукты покупает, или еще чего. Остальные редко бывают. Вот и сейчас он мяса закупил и попросил поспрашивать, может кто из девушек работу ищет.",275597,null],[275604,"2026-10-19T17:23:35",17,"— Очень подозрительно, недавно ушел? Может еще нагоним по пути к особняку?",212725,null],[275606,"2026-10-19T17:24:14",31,"- Так 5 дней назад был. А 4 дня назад я об этом Елене и сказала",275604,null],[275712,"2026-10-19T18:35:35",22,"-- Т-тогда предлагаю нам тоже с-сходить в особняк, узнать, как д-девушка. А ее жених, д-думаю, что он может подождать.",212725,null],[275713,"2026-10-19T18:39:51",20,"- Поддерживаю, нужно хотя бы убедиться, что она в безопасности, чтобы успокоить ее отца. *Соглашается Беатриче*\n\n- Как найти особняк графини? *Уже обращаясь к Клаудии*",275712,null],[275715,"2026-10-19T18:42:27",31,"- идите на северо Восток, вон туда, в гору\n\nУказывает рукой. \n\n- за час доберётесь",275713,null],[275716,"2026-10-19T18:42:50",31,"/завтра продолжим, арты особняка и графини у меня на рабочем компе/",212725,null],[276049,"2026-10-20T07:51:31",31,"Как и обещала Клаудия, примерно через час вы добрались до старого особняка. Он выглядит не особо привлекательным, даже скорее запущенным. Но он обитаем, вы заметили и окликнули мужчину во дворе.\n\nМужчина, представившийся Янником, был высок, бледен и по его словам, был садовником. Похоже, с работой он не очень то справлялся.",212725,null],[276062,"2026-10-20T08:53:15",17,"— Добрый день. Моё имя Марко Веньер. Мы пришли просить аудиенции у графини. Может ли она нас принять?",212725,null],[276064,"2026-10-20T08:53:45",17,"Поместье навевало плохие мысли. В таком запущении живут нищие, а не аристократы.",212725,null],[276068,"2026-10-20T09:06:33",22,"Ясмин в это время пристально рассматривала садовника. Его поведение, одежду и следы на ней. Точно ли он садовник или же просто притворяется, судя по запущенности сада.",212725,null],[276069,"2026-10-20T09:06:41",22,"/r +6 внимание",212725,null],[276071,"2026-10-20T09:06:59",22,"/r +d4 забываю добавлять",212725,null],[276073,"2026-10-20T09:07:27",22,"/там без преимущества, с утра чутка косит",212725,null],[276109,"2026-10-20T09:43:38",31,"Мужик болезненного и чутка запуганого вида, но вроде настоящий. Может просто рукожоп?",276070,null],[276110,"2026-10-20T09:44:42",31,"Янник:\n\n- я спрошу у Госпожи\n\nОн удаляется, оставляя вас наедине накакое то время. \n\n/можете что то обсудаить, или сразу дайте отмашку и выдам вам графиню/",276062,null],[276112,"2026-10-20T09:51:43",22,"Этот мужик похож на каннибала\n\n-- Согласна. П-правда похож. Еще и заросли эти п-подозрительные.\n\nЯсмин испуганно обернулась и зашептала.\n\n-- Они же н-нанимают людей, но где в-все? Что если...\n\nДевушка снова начала теребить волосы, а ее рука наливаться светом.\n\n-- Что, если они к-каннибалы?! И жрут ю-юных дев?! А кости з-закапывают.\n\nЯсмин вздохнула и отошла чуть ближе к забору, пытаясь прогнать накатившую на нее паранойю.",212725,null],[276113,"2026-10-20T09:52:20",17,"— Как один из тысячи возможных вариантов. Надо бы осмотреться пока его нет, может найдем костички обглоданые.",212725,null],[276114,"2026-10-20T09:52:42",17,"/r d20+6+d4 Внимательно осматривает сад",212725,null],[276116,"2026-10-20T09:53:25",22,"/100% найдёшь собачью кость и у Яс истерика начнётся",212725,null],[276117,"2026-10-20T09:53:55",31,"Стремный неухоженный сад. Заросли, паразитные растения. Останков не замечано. Или они зарыты глубоко",276115,null],[276118,"2026-10-20T09:55:43",17,"— Ничего примечательного",212725,null],[276119,"2026-10-20T09:58:48",22,"Я предлагаю бежать\nПоддерживаю\nБеги, маленькая мышка, БЕГИ!\n\nЯсмин отвернулась от товарищей и прошла еще немного вдоль забора, сильно сжимая в руке четки и пытаясь сосредоточиться на своей мантре.\n\n\"Дыши, Ясмин, главное дыши. Это просто мысли. Чужие мысли.\"\n\nИли твои?\n\n\"Девочка, нужно сосредоточиться на деле, я веду себя очень глупо и странно, нужно сделать вид, что я просто любуюсь природой. Точно.\"\n\n-- Д-да, просто п-природа тут красивая. Идем к г-графине? Хочу у-убедиться, что Елена в порядке.\n\nСказала Яс, возвращаясь к товарищам.",212725,null],[276131,"2026-10-20T10:43:56",31,"Янник возвращается и просит вас следовать за ним. Тем временем день уже подходит к концу, вечереет. \n\n/а вы ведь так и не отдохнули после битвы с жабой, верно?/\n\nХозяйка дома встречает вас в гостинной. Красивая бледнокожая девушка, чье лицо больше напоминает маску. Вы не видите ни следа морщин, даже тех, что остаются от смеха.\n\nНо голос у нее приятный, мягкий и грудной, с небольшим придыханием\n\n- Добро пожаловать в мой дом, сиоры. Гости редко навещают меня. Признаться, я скучаю по компании новых людей. Может быть, разделите со мной скромный ужин и расскажите о деле, что привело вас ко мне?",212725,null],[276132,"2026-10-20T10:59:44",22,"-- Д-добрый.\n\nЯсмин аккуратно осматривает женщину и самое помещение, не решаясь продолжить диалог с грифиней.",212725,null],[276133,"2026-10-20T10:59:49",22,"/не отдыхали",212725,null],[276134,"2026-10-20T11:00:03",22,"/r d20+6+1d4 внимание",212725,null],[276136,"2026-10-20T11:00:46",31,"что именно ты хочешь разглядеть? на что обращаешь в7нимание7/",276134,null],[276138,"2026-10-20T11:02:56",22,"//по женщине понять есть ли у нее клыки, а то подозрительно много клыкастых товарищей в последнее время Яс встречает\n\nПо дому понять, запущен он или нет. Есть ли признаки того, что в доме вообще есть слуги",212725,null],[276139,"2026-10-20T11:05:53",31,"Клыков у графини ты не замечаешь, как не вглядываешься. Но вновь отмечаешь чистоту и белизну ее кожи. \n\nДом внутри выглядет лучше чем сад. Тут нет кричащего богатого убранства, все довольно старомодно, но чисто.",276138,null],[276143,"2026-10-20T11:34:47",17,"— Благодарю сиора. Мы непременно любезно воспользуемся вашим гостеприимством и поделимся новостями из Вальдории и близлежащие деревни Каталуны.\n\nМарко сделал аккуратный поклон \n\n— Моё имя Марко Веньер. Следователь из Вальдории. А это мои коллеги Ясмин и Беатриче. Мы все работаем в сыскном бюро Неро Фелино.",276131,null],[276146,"2026-10-20T11:40:52",31,"- как интересно. Ну да пройдёмте в столовую\n\nВы переходите в большую комнату с накрытым столом. Тут вновь вы видите следы былой роскоши - хорошего качества, но старомодную мебель, старое фамильное серебро.\n\nВы рассаживаетесь за столом, за ужином вам прислуживают дворецкий, которого хозяйка представила Маркусом, и пожилой повар с дергающимся глазом по имени Бран. \n\nВам подали каплуна и налили хорошего вина, даже Беатриче отметила его качество, даром что это не производство ее семьи.\n\nХозяйка смотрит на вас с интересом. Это первая эмоция, что вы разглядели на ее лице",276143,null],[276183,"2026-10-20T12:21:12",22,"Ясмин покосилась на птичью тушку и постаралась не скривиться. Чуть пигубив вино, девушка, стесняясь, спросила \n\n-- П-прошу простить нам с-столь неожиданный визит. Мы вас не с-сильно потревожили?\n\nДа пей нормально\nДа, да, глоток побольше делай и не закусывай\nДа тут то и нечем. Вот, чую будет веселуха!\n\nЯсмин чуть дернула головой и посмотрела на женщину.",212725,null],[276262,"2026-10-20T12:36:14",31,"- нет, ну что вы. я рада гостям и их историям. я скучно живу, а так хоть что то новое начинает занимать мои мысли",276183,null],[276345,"2026-10-20T12:59:51",20,"- О, вам нравятся истории? У нас как раз есть одна - свежее некуда! *Беатриче приободряется. В разного вида допросах она не очень хороша, но вот дать время спутникам подумать как подойти к теме 'где Елена?' она вполне может*\n\n- Так вот, прибыли вы в эти места из Вальдории, и знаете что нас первым встретило? Нет, не только скудная винная карта в таверне - а слухи! Представляете, некий говорящих колодец, что заманивал деревенских поближе, многие даже прыгали в него и...не возвращались *она понижает тон голоса до зловещего, будто рассказывает страшилку*\n\n- И вот отправились мы туда - и местных успокоить, и себя испытать. Пришли к колодцу и вдруг слышим прямо в голове...'Прыгай!' *Дальше следует 'слегка' приукрашенный и сдобленный комментариями Беатриче пересказ их прыжка в колодец и битвы с огромной гипножабой*",276262,null],[276349,"2026-10-20T13:02:10",31,"- удивительно! Даже и не думала, что такие чудовища могут существовать на свете! Но чо привело вас после такой великой битвы ко мне? В коем колодце таких чудищ нет, насколько я знаю",276345,null],[276352,"2026-10-20T13:05:20",20,"- Ах, точно - мы же не просто за легендой к этому колодцу пошли. Пару дней назад в деревне пропала девушка, вот ее и искали. Слава богу среди прошлых обедов монстра ее не обнаружили \n\n- Звали ту девушку Елена. Мы пораспрашивали ее подруг и узнали, что она к вам устроилась служанкой совсем недавно. Вот, пришли проведать ее.",276349,null],[276357,"2026-10-20T13:07:53",31,"- Елена? Ах да, миленькая девочка, приходила ко мне пару дней назад. Но ее не устроили условия, увы. После этого она покинула мой дом",212725,null],[276358,"2026-10-20T13:08:02",31,"Можете бросить на проницательность/",212725,null],[276391,"2026-10-20T13:22:13",17,"Марко следит за её ответами и ищет ложь в её словах, если она сама чудовище тут будет играть роль.",276349,null],[276392,"2026-10-20T13:22:22",17,"/r d20+6+d4 Проницательность",212725,null],[276414,"2026-10-20T13:27:34",31,"Тебе с двумя помехами надо кидать//",276393,null],[276415,"2026-10-20T13:28:49",31,"Марко уловил нотку иронии в словах графини о том что ТАКИХ чудовищ тут нет. Похоже, другие все таки есть",212725,null],[276417,"2026-10-20T13:29:46",31,"Также ты ясно понимаешь, что она тебе врёт о Елене. Но что ты можешь ей предъявить?",212725,null],[276420,"2026-10-20T13:32:19",17,"— А какие условия вы предлагаете? Знаете мы точно знаем, что девушка в бедственном положении и готова была согласиться на любую работу.",212725,null],[276426,"2026-10-20T13:38:38",20,"/надо напроситься к ней на ночлег, а то мы без ресурсов и отдыха\n/Ну и будет время расследовать",212725,null],[276429,"2026-10-20T13:43:06",17,"/Я тоже хотел за ужином поинтересоваться где служанки",212725,null],[276430,"2026-10-20T13:43:11",31,"Отвечу позже, сел за руль/",212725,null],[276565,"2026-10-20T15:13:32",31,"- я предложила стандартные условия, даже щедрые. 3 золотых в месяц, жить предстояло тут. Но девушка сказала что ей срочно нужны деньги, около 100 золотых, что то там про долги отца и попросила их авансом. А я ведь не ростовщик и не рабовладелец, чтобы деньги давать авансом сразу на три года",276420,null],[276575,"2026-10-20T15:15:15",22,"-- К-какие хорошие условия. Но п-почему тут нет п-прислуги?\n\nДевушка замялась.\n\n-- Н-налеюсь, что не слишком грубо себя в-веду.",212725,null],[276580,"2026-10-20T15:20:40",31,"- у меня трое слуг. Вы их видели. До недавнего времени была и горничная, но ушла. Поэтому я и попросила Маркуса поискать замену в деревне. Ее искать что у меня тут много работы, но статус обязывает, знаете ли, держать штат",276575,null],[276583,"2026-10-20T15:22:28",22,"-- А Е-елена часом не сказала куда пойдет д-дальше или может вы смогли ей п-предложить что-то, что позволило бы з-заработать такие деньги быстрее?",212725,null],[276594,"2026-10-20T15:24:52",31,"- вы знаете, я ка кто не поинтересовалась ее планами. Я ведь ей не мама, в конце то концов. Я высказала предложение, она его не приняла. Вот и все",276583,null],[276597,"2026-10-20T15:25:22",17,"Марко ловит её на вранье",276594,null],[276603,"2026-10-20T15:28:29",31,"А сложность была 30, бе-бе-бе//",212725,null],[276606,"2026-10-20T15:29:14",31,"Ты видишь, что она нагло врет. Но как доказать?",212725,null],[276614,"2026-10-20T15:33:13",22,"-- К-конечно не мама, вы слишком м-молоды, чтобы быть кому-то мамой!\n\nЯсмин с воодушевлением распахнула глаза, смотря прямо на графиню.\n\n-- Но я у-уверера, что вы очень м-мудры, быть может вы дали ей с-совет?",212725,null],[276615,"2026-10-20T15:33:29",17,"— Могли бы мы остаться у вас сегодня, кажется вы предлагали остаться на ужин. Просим разрешить нам так же остаться на ночь, графиня\n\nМарко сделал самое милое выражение лица на которое был способен",212725,null],[276616,"2026-10-20T15:33:37",22,"/r d20+3+d4 дипломатия от Яс",212725,null],[276618,"2026-10-20T15:33:46",22,"//помощь, да?",276615,null],[276621,"2026-10-20T15:34:33",22,"\"О, свет, какая же я жалкая\"",212725,null],[276630,"2026-10-20T15:41:33",31,"Графиня смотрит на вас с долей удивления, а потом улыбается. Как то механически\n\n- конечно, я буду рада гостям. Да и опасно на дорогах по ночам, Зверь всегда где то рядом. Маркус, проводи наших гостей в их комнаты",212725,null],[276660,"2026-10-20T16:07:02",31,"Маркус ведёт вас на второй этаж особняка, вы проходите через коридор, украшенный портретами хозяйки и попадаете каждый в свою комнату. Небольшие спальни с хорошими кроватями, просто и уютно",212725,null],[276661,"2026-10-20T16:09:07",22,"Ясмин сразу идет проверять окна, балкон, проходы на крышу.\n\nА также внимательно изучает пол на предмет особо скрипучих досок.",212725,null],[276662,"2026-10-20T16:09:28",22,"/r d20+7+d4 внимание",212725,null],[276664,"2026-10-20T16:09:40",31,"Ну вы реально бесите уже)/",212725,null],[276665,"2026-10-20T16:09:53",31,"Где рак кубов? Почему только у меня?)/",212725,null],[276666,"2026-10-20T16:09:57",22,"/слабо было на дипломатию кинуть. Поганые кубы",212725,null],[276667,"2026-10-20T16:10:24",20,"/Беатриче за этих двоих им страдает)",276665,null],[276668,"2026-10-20T16:11:24",22,"/у меня хорошие броски на внимательность исключительно при наличии каких-то непотребностей. Так что мне уже страшно",212725,null],[276670,"2026-10-20T16:11:27",31,"Окна не зарешечены, из можно открыть изнутри. Балкона нет. Некоторые половицы скрипят от старости, но в целом довольно тихо, особенно если ходят легкие девушки , а не более крупный Марко",276661,null],[276671,"2026-10-20T16:11:57",31,"Страдаешь за их грехи/😇",276667,null],[276677,"2026-10-20T16:24:36",17,"Марко первым делом рисует кровью в книге мёртвых ритуал обнаружения магии и будет смотреть проходя по коридорам простов ертя головой, надеясь найти что то необычное и магически отмеченное",212725,null],[276678,"2026-10-20T16:24:49",17,"/r d20+6+d4 Внимание на поиски магического ууу",212725,null],[276680,"2026-10-20T16:24:57",17,"/Пробил 30)))",212725,null],[276681,"2026-10-20T16:25:01",17,"/Первый успех!",212725,null],[276683,"2026-10-20T16:29:07",22,"/давай. Добивай нашего мастера!",276680,null],[276684,"2026-10-20T16:30:18",20,"/следующая проверка походу будет минимум 40)",212725,null],[276685,"2026-10-20T16:33:08",31,"Ну вас нахрен, читеры/",212725,null],[276686,"2026-10-20T16:33:20",22,"Тем временем Ясмин открыла свое окно, убедилась в том, что ее никто не видит и достала свой походный кальян, аккуратно раскуривая его. Чудотворством она выгоняла дым в окно, чтобы не смущать хозяев.\n\n-- О, свет, наконец-то тишина. К-как же утомителен был этот день.\n\nЭй, а мы?\nМы тоже тебя утомили?\n\nЯсмин не обращала внимания на старух и с каждой новой затяжкой, их голоса становились все тише.\n\n\"Значит девочка скорее всего здесь. Надо будет пробраться к Марко и Беатриче и вместе изучить этот дом получше. Но все потом, сначала надо расслабиться. \"",276670,null],[276687,"2026-10-20T16:33:49",22,"/пока я писала этот пост, увидела у Коли 30\nКажется я знаю, кто меня спалит первым",212725,null],[276688,"2026-10-20T16:34:25",31,"Прямо сейчас будешь, или ночи дождешься?/",276677,null],[276690,"2026-10-20T16:35:32",17,"/Планировал сразу",212725,null],[276692,"2026-10-20T16:36:54",31,"Вечером по чужому дому с неспящими слугами бродит мужик с окровавленной книгой. Обычный вторник/",276690,null],[276694,"2026-10-20T16:37:24",31,"Ну в принципе тебе везет с проверками. Может и со скрытностью сработает/",212725,null],[276698,"2026-10-20T16:39:24",31,"Ну если готов, то кидай скрытность и выходи на исследование. СЛ 16",212725,null],[276699,"2026-10-20T16:40:12",17,"/r d20+2+d4 И что будет если меня найдут? Что съедят?",212725,null],[276702,"2026-10-20T16:40:25",20,"/ахаха",212725,null],[276703,"2026-10-20T16:40:38",20,"/все, кончилась походу удача",212725,null],[276704,"2026-10-20T16:40:58",22,"/пока пока Марко, точно съедят",212725,null],[276705,"2026-10-20T16:41:09",31,"Девушки слышат чавкающий звук из да угла, там доедают Марко/",212725,null],[276706,"2026-10-20T16:41:58",22,"Ясмин тяжело вздохнула и сделала еще затяжку.\n\n\"Да что такое, почему эти галлюцинации не прекращаются.\"",212725,null],[276707,"2026-10-20T16:42:20",31,"Ну а если серьёзно, то под Марко оглушительно скрипит половица, и из Библиотеки, что расположена на этом же этаже появляется дворецкий Маркус\n\n- Сиор Веньер, что то не так?",212725,null],[276708,"2026-10-20T16:42:36",31,"Кинь внимание Марко",212725,null],[276710,"2026-10-20T16:43:59",31,"Маруус замечает кровь:\n\n- вы ранены? Вам нужна помощь?",212725,null],[276715,"2026-10-20T16:52:02",17,"У Марко светятся золотым светом глаза и летает мелкий песочек",276707,null],[276716,"2026-10-20T16:52:08",17,"— Да нет, просто ищу уборную сиор.",212725,null],[276717,"2026-10-20T16:52:31",17,"/r d20+6+d4 А у меня его нож уже в печени торчит?",276708,null],[276719,"2026-10-20T16:52:56",31,"- не стоило идти так далеко, в каждой избспален есть своя",276716,null],[276720,"2026-10-20T16:53:59",31,"Ты успеваешь бросить взгляд на книгу, когда в дверях появился Маркус. И краем глаза заметил, что книга определяет его как конструкт",276718,null],[276721,"2026-10-20T16:54:15",31,"Я же верно понимаю что результаты ритуала ты в книге смотришь?/",212725,null],[276723,"2026-10-20T16:55:08",17,"/ Нифига ты выдал, ну вообще обнаружение магии такого не даёт, но в книге может быть ЛЮБАЯ подсказка какую хочет дать мастер",276721,null],[276724,"2026-10-20T16:55:35",17,"— Ох вот как. А что это сейчас так скрипнуло? Половица или ваш шарнир?",212725,null],[276725,"2026-10-20T16:58:20",31,"Я просто правил не знаю, веду как вижу/",276723,null],[276726,"2026-10-20T16:59:11",31,"- не понимаю вашего вопроса, сиор. Но вообще это старый дом, и половицы бывают скрипят",276724,null],[276727,"2026-10-20T16:59:52",31,"Даже если конструкт не металлический? Да и надо же было тебе что то дать за выбитую 30/",276723,null],[276728,"2026-10-20T17:00:18",17,"/Магически измененный наверное другое дело, я думал просто металлическая марионетка",212725,null],[276729,"2026-10-20T17:00:48",31,"Ну пусть так. Надо хоть почитать что это такое)/",276728,null],[276730,"2026-10-20T17:02:06",17,"— Что ж, а можете что нибудь рассказать об девушке Елене? Безутешный отец ее ищет",212725,null],[276731,"2026-10-20T17:02:39",31,"- мне нечего добавить к словам госпожи Монаро",276730,null],[277717,"2026-10-21T08:44:14",31,"Высказавшись, Маркус вновь скрылся в библиотеке. Марко же остался в коридоре, украшенном портретами хозяйки дома. Ему тоже не оставалось ничего иного как вернуться в комнату. \n\nЧем в это время заняты Беатриче и Ясмин? Если нечем, то предлагаю всем устроиться на долгий отдых. Ну или что вы там задумали в ночи",212725,null],[277721,"2026-10-21T08:58:13",22,"Ясмин докурила кальян. Избавилась от улик и еще раз проверила каждый угол,  после чего попыталась уснуть.",212725,null],[277724,"2026-10-21T09:09:09",31,"Мастерским производом приказываю всем уснуть. Время около 9 вечера, уже стемнело, и вы вымотались за день. Следом будет сцена пробуждения, не для всех приятная. Но в любом случае у ее началу вы уже получите результат долгого отдыха//",212725,null],[277727,"2026-10-21T09:13:27",31,"Вы проваливаетесь в сон без сновидений. Тяжелый, но необходимый. Впрочем, длится он недолго, уже в полночь вы все просыпаетесь от боя часов где-то в доме. \n\nМарко просыпается резко открыв глаза и сев на кровати, словно готовый к бою.\n\nБеатриче и Ясмин поосыпаются также, но полнятся сразу не могут. По их органам чувств словно наносится сильнейший ментальный удар\n\n@lady_godzilla @PaIIasCat спас мудрости СЛ 18",212725,null],[277728,"2026-10-21T09:16:49",31,"СЛ 16, поспешил/",212725,null],[277729,"2026-10-21T09:17:50",22,"/r +7",277727,null],[277731,"2026-10-21T09:18:16",22,"/r +d4 и закл сопротивление",212725,null],[277733,"2026-10-21T09:18:35",22,"//итог 15, я опять случайно преимущество кидаю",212725,null],[277736,"2026-10-21T09:20:30",17,"/ К спасу прибавляется заклинание благословение оно на концентрации\n\nА указание на проверки характеристик это заговор бесконечный",212725,null],[277737,"2026-10-21T09:20:37",31,"/roll d8 психический урон для непрошедших спас, также +1 уровень истощения со всеми соответствующими дебафами. Если спас пройден, то полоина урона и нет истощения",212725,null],[277739,"2026-10-21T09:22:02",31,"ждем от Беатриче спас мудрости/",212725,null],[277765,"2026-10-21T11:19:27",22,"Ясмин села на кровати, сжимая виски. \n\n\"Какое отвратительное место. Какие мерзкие старухи. Как же мне... нехорошо...\"",212725,null],[277774,"2026-10-21T11:47:05",17,"Марко встрепенулся\n\nОн ожидал, что в доме нечисть, сама графиня много лгала и планировал найти доказательства, что она причасна в исчезновению Елены\n\nВсё таки слишком гладкая кожа, для её возраста, слишком наглая ложь в лицо. \n\nОн сразу же схватил книгу мёртвых и выбежал из комнаты намереваясь разбудить Ясмин и Беатриче\n\nОн подбежал к первой двери рядом и начал колотить кулаком в неё\n\n— ЯСМИН, ПРОСНИСЬ!",212725,null],[277775,"2026-10-21T11:47:45",20,"/r +d20+1",212725,null],[277778,"2026-10-21T11:51:13",20,"*Беатриче вскакивает от резкого звука, как Марко колотит в дверь Ясмин. Возможно именно это и спасает ее от странной истощающей угрозы во сне, даже если она это не успела осознать*\n\n*Наспех нацепив бригантину она выскакивает в коридор, встречаясь с мужчиной слегка дизориентированными широко раскрытыми глазами*\n\n- Сеньора? Что случилось?!",212725,null],[277779,"2026-10-21T11:51:45",31,"4 урона, без истощеия/",277776,null],[277780,"2026-10-21T11:53:18",22,"С тёмными кругами под глазами, Ясмин открывает дверь.\n\n-- Наверное нам п-пора.\n\nСказала девушка, поднимая голову.\n\n-- Стоило этой н-ночью не спать, а и-изучить это место. Извините, я просто о-отключилась.",277774,null],[277781,"2026-10-21T11:56:08",17,"— Кажется мы попали в ловушку. Я ожидал этого, но не так скоро. Берите вещи попробуем покинуть это место. Вчера я смог разузнать лишь одно. Дворецкий это магический конструкт, который притворяется человеком.",212725,null],[277782,"2026-10-21T11:56:46",20,"- Сбежать? А как же Елена?",277781,null],[277783,"2026-10-21T11:57:39",17,"— У меня нет зацепок, где она могла бы находиться.",212725,null],[277787,"2026-10-21T12:02:39",22,"БЕГИ\n\n-- Н-нет.\n\nЯсмин поправила сумку и посмотрела на Марко. \n\n-- Д-девочка может быть жива, а м-может и нет. Но э-эта женщина... \n\nЯсмин глубоко вздохнула.\n\n-- Н-нужно подкинуть ей сувенир. Тогда я с-смогу за ней проследить. Или этому к-конструкту.\n\nНа слове \"сувенир\" золотой глаз Ясмин вспыхнул. Девушка чуть дернула головой.\n\n-- Либо м-можем сами поискать \"к-клозет\". Что д-думаете?",212725,null],[277789,"2026-10-21T12:07:47",20,"- Согласна, уходить ничем не хочется. *Кивает Беатриче, оглядываясь*\n\n- Хотя сдается мне нас ещё могут и не выпустить просто так",277787,null],[277795,"2026-10-21T12:27:18",22,"‐‐ П-посмотрим.\n\nЯсмин попыталась выдавить из себя счастливую улыбку.\n\n-- З-значит завтрак? Или п-поищем \"уборную\"?",212725,null],[277796,"2026-10-21T12:28:00",22,"//вопрос к мастеру, я верно понимаю, что у меня отдыха не было в связи с истощением? Вроде правила днд говорят что отдыха не было",212725,null],[277797,"2026-10-21T12:31:14",31,"Был, я по доброте свое вам всем его выдал. Истощение ты получила когда проснулась и провалила спас/",277796,null],[277798,"2026-10-21T12:31:42",31,"время если что, полночь с небольшим, вас разбудил бой часов/",212725,null],[278107,"2026-10-21T17:11:14",22,"-- Т-так, сейчас ночь и эти часы...\n\nЯсмин поморщилась. \n\n-- Д-давайте аккуратно осмотрим этот этаж.",212725,null],[278109,"2026-10-21T17:12:34",22,"/r -d20+6+1d4 Ясмин внимательно осматривает этаж, на котором находятся их комнаты. По возможности заглядывая в те, что не заперты",212725,null],[278125,"2026-10-21T17:14:46",20,"*Беатриче помогает Ясмин осмотреться*\n\n/Действие помощь, чтоб нивелировать помеху",212725,null],[278150,"2026-10-21T17:19:59",31,"Вы в коридоре, в левом крыле второго этажа. Тут есть 4 двери  в спальни, три из которых занимаете вы. Они идентичные. В середине коридора лестничный пролет вверх и вниз. В правом крыле большая библиотека. Стены коридора увешкны портретами графини, гу или крайне похожих на нее женщин. Вы понимаете, что изображенные женщины наряжены в платья разных эпох, да и в целом некоторые картины смотрятся старыми",212725,null],[278168,"2026-10-21T17:23:00",22,"Ясмин дергает Беатриче.\n\n-- Эти к-картины. Посмотри, там точно р-разные люди? Давай позовём М-марко и попробуем посмотреть,  что за четвёртой дверью.",212725,null],[278174,"2026-10-21T17:26:23",17,"— Я здесь. Давайте активно искать девушку. Явно тут нам добра не желают, поэтому и мы отбросим гостевой этикет",212725,null],[278177,"2026-10-21T17:26:50",17,"— Графиня слишком молодо и идеально выглядит.",212725,null],[278178,"2026-10-21T17:27:12",17,"— Подозреваю, что тут замешана магия. Быть может наша Елена стала жертвой.",212725,null],[278185,"2026-10-21T17:28:59",31,"Тем временем, прошло 15 минут после полуночи//",212725,null],[278187,"2026-10-21T17:29:55",22,"-- С-сможете открыть ту дверь?\n\nЯсмин показала пальцем на дверь. Палец сильно дрожал, девушка заметила это и быстро спрятала руку за спиной.",212725,null],[278188,"2026-10-21T17:30:08",17,"Марко открывает случайную дверь. Если заперта идет к следующей. Если все заперты выбивает случайную плечом",212725,null],[278189,"2026-10-21T17:30:39",31,"Дверь что возле ваших комнат не заперта. Она пуста. Дверь в библиотеку тоже не заперта",212725,null],[278190,"2026-10-21T17:32:01",17,"Марко заходит в библиотеку из своей тени он вытаскивает ворона и подбрасывает его в воздух, тот вспархивает\n\n\"Осмотри всё. Ищи необычное\"\n\nВорон начинает летать по верхним рядам книг дергая всё подряд и осматривая.\n\nМарко внизу делает тоже самое",212725,null],[278191,"2026-10-21T17:32:22",17,"/r +d20+6+d4 Внимание на поиск скрытых возможно комнат",212725,null],[278193,"2026-10-21T17:34:33",22,"-- М-марко. Мне п-почему-то кажется, что нам надо в п-подвал...\n\nРобко сказала Ясмин, вспоминая свой сон про падение. Может он был вещим?",212725,null],[278195,"2026-10-21T17:35:25",17,"— Подвал? Я не заметил, ты уверена? Спустимся вниз?",212725,null],[278197,"2026-10-21T17:36:38",31,"Ворон облетет библиотеку по периметру и сообщает тебе, что за одним из стеллажей чувствуется сквозняк",278192,null],[278198,"2026-10-21T17:37:02",17,"— Сейчас Ясмин, там что то есть.\n\nМарко пытается отодвинуть стеллаж",212725,null],[278199,"2026-10-21T17:38:09",31,"Стеллаж не поддается. Может надо обойтись без грубой силы?",278198,null],[278200,"2026-10-21T17:38:58",17,"— Беатриче, Ясмин, не поддаётся, там точно что то есть за ним",212725,null],[278201,"2026-10-21T17:39:10",22,"-- В т-таких домах не может не б-быть подвала. Х-хорошо, я не буду мешать, п-посмотрим там.\n\nЯсмин хотела было подойти к Марко, но заметила, что стеллаж не поддаётся. Тогда девушка попытались осмотреться в поисках предмета, который был бы рычагом",278195,null],[278202,"2026-10-21T17:39:19",20,"- Может тут как в тех детективных романах? Нужно найти тайный рычаг",278200,null],[278203,"2026-10-21T17:39:23",22,"/r -d20+7+1d4",212725,null],[278205,"2026-10-21T17:40:06",17,"— Рычаг! Конечно, старый добрый рычаг, видите его?",212725,null],[278206,"2026-10-21T17:40:32",20,"*Беатриче просто методично начинает трогать книги, смотря какие вынимаются а какие могут оказаться скрытым рычагом*\n\n/Не верю в свои броски внимания, пробую просто все перебрать",212725,null],[278207,"2026-10-21T17:40:33",31,"Ты кое что замечаешь на стеллаже\n\n/сейчас дам описание, как всегда если я что то пишу, оно остается на компе/",278204,null],[278209,"2026-10-21T17:44:37",31,"Ясмин замечает, что на полке под книгами есть шесть вырезаных символов, они изображают последовательно: молот, череп, цепь, перо, камень и свечу.\n\nНа самой полке стоят в ряд 7 книг: \"Тень и Пепел\", \"Корни и Камни\", \"Ветер и Пыль\", \"Трактат о Началах\", \"Узы и Мосты\", \"Свет и Стекло\" и \"Пламя и Кузня\"",212725,null],[278210,"2026-10-21T17:45:18",17,"/Опа моя школа",212725,null],[278211,"2026-10-21T17:45:19",31,"Не обессудьте, впервые пишу загадку для ДНД/",212725,null],[278212,"2026-10-21T17:45:32",17,"/ Я тебе такую же давал?)) ахахах",212725,null],[278213,"2026-10-21T17:45:35",17,"/В доме Вахтеров",212725,null],[278214,"2026-10-21T17:45:49",22,"*Ясмин обращает внимание ребят на находку.*",212725,null],[278215,"2026-10-21T17:46:11",17,"— Что ж собираем последовательность. Доверю это вам, а сам прикрою спину, вдруг нагрянет дворетский",212725,null],[278216,"2026-10-21T17:46:12",31,"Нет, у тебя было меньше книг и подсказка по расстановке была более явная. Хотя хз, тут тоже не сложно/",278213,null],[278217,"2026-10-21T17:46:33",17,"/Теже яйца только в профиль))",212725,null],[278220,"2026-10-21T17:48:15",22,"/ Полька, которая предмет \"Логика\" сдала только с 3го раза - 🤤",212725,null],[278222,"2026-10-21T17:51:01",22,"Ясмин задумалась и попыталась расставить книги:\nМолот-Пламя и кузня\nЧереп‐Тень и пепел \nЦепь‐Узы и мосты\nПеро‐Трактат о началах \nКамень‐Корни и камни\nСвеча‐Свет и стекло\n\n/наверное по мужской прямолинейной логике должно быть так",212725,null],[278223,"2026-10-21T17:51:56",20,"/я бы на место пера Ветер и пыль попробовала поставить",212725,null],[278227,"2026-10-21T17:53:53",31,"Так какой вариант в итоге?",212725,null],[278228,"2026-10-21T17:54:31",22,"/катин",212725,null],[278229,"2026-10-21T17:54:42",31,"Ок/",212725,null],[278230,"2026-10-21T17:55:02",31,"А 7 книгу куда?/",212725,null],[278231,"2026-10-21T17:55:05",20,"/а книгу о началах тогда перед ними всеми первой поставить",212725,null],[278232,"2026-10-21T17:55:25",31,"Умные все такие/",278231,null],[278233,"2026-10-21T17:55:30",31,"Молодцы/",212725,null],[278236,"2026-10-21T17:56:57",31,"Расставив книги по логичному порядку, вы активировали механизм, который со скрипом повернул скрытую дверь за стеллажом. Вы видите винтовую лестницу наверх",212725,null],[278243,"2026-10-21T17:59:51",20,"- Жуть, неужели им каждый раз приходить расставлять книги просто чтобы закрыть или открыть дверь *Беатриче заглядывает в проход*\n\n- Им тут похожу реально нечем заняться, если решили придумать такое вместо обычного скрытого рычага",212725,null],[278244,"2026-10-21T18:00:13",20,"- Ну что, идём?",212725,null],[278245,"2026-10-21T18:00:32",17,"/Я тактично не стал мешать, стронг брейн",278232,null],[278246,"2026-10-21T18:01:22",17,"— Маги ленивые, у них для этого волшебные руки и невидимые слуги",278243,null],[278256,"2026-10-21T18:18:22",22,"-- Д-да, конечно идем.",212725,null],[278260,"2026-10-21T18:20:19",31,"Так, у меня арт на работе. Думаю и без него можем двигаться/",212725,null],[278261,"2026-10-21T18:20:44",31,"/время 00:40/",212725,null],[278262,"2026-10-21T18:23:06",20,"*Беатриче идёт впереди союзников, чтобы если что прикрыть их*",212725,null],[278263,"2026-10-21T18:23:33",31,"Вы поднимаетесь по винтовой лестнице вверх и оказываетесь перед еще одной незапертой дверью. Открыв ее, вы попадаете небольшую, го хорошо обставленную спальню, правда, без окон. Посередине комнаты стоит огромная кровать под балдахином, а на ней лежит молоденькая русоволосая девушка, не старше 16 лет. Ее глаза закрыты, дыхание замедленно. Ваше появление не приводит ее в чувство",212725,null],[278264,"2026-10-21T18:24:01",31,"/время 00:45/",212725,null],[278265,"2026-10-21T18:25:01",17,"— Ясмин, проклятье чувствуешь? Я попробую определить есть ли магическое заклятие",212725,null],[278266,"2026-10-21T18:25:09",17,"/ Ритуал обнаружении магии 10 минут",212725,null],[278267,"2026-10-21T18:25:37",17,"Марко колет палец и рисует глаз Имха на странице книги мертвых",212725,null],[278268,"2026-10-21T18:26:02",17,"— Думаю это Елена, возраст сходится",212725,null],[278269,"2026-10-21T18:28:03",20,"- Боже, что же с ней сделали... *Беатриче оглядывается по сторонам. В медицине или проклятых она мало сведуща, но постарается помочь Ясмин*\n\n/Помощь на все проверки Ясмин",212725,null],[278270,"2026-10-21T18:29:03",31,"Жду реакцию Ясмин и потом скажу что видит Марко/",212725,null],[278271,"2026-10-21T18:29:16",31,"Тебе не нужно на него бросать что то?/",278266,null],[278272,"2026-10-21T18:35:15",22,"Ясмин в ужасе подбегает к девушке и осматривает ее",212725,null],[278273,"2026-10-21T18:35:22",22,"/r -d20+6+d4",212725,null],[278275,"2026-10-21T18:35:50",22,"//не заметила,но там все равно бросок не оч",278269,null],[278276,"2026-10-21T18:36:45",31,"Ты не видишь следов проклятия. Магия тут явно есть, но какая то иная",278274,null],[278277,"2026-10-21T18:38:06",22,"Ясмин ищет магию",212725,null],[278278,"2026-10-21T18:38:18",22,"/r d20-1+d4",212725,null],[278280,"2026-10-21T18:38:42",31,"Ясмин не может точно понять что с девушкой",212725,null],[278281,"2026-10-21T18:38:47",22,"-- Я-я не понимаю, что с девушкой,  но м-мне это не нравится!",212725,null],[278282,"2026-10-21T18:38:59",31,"Ща опишу что там Марко увидел/",212725,null],[278283,"2026-10-21T18:40:39",20,"/r d20+1 была не была, медецина",212725,null],[278285,"2026-10-21T18:40:46",22,"-- О-осмотритесь, может вы найдёте что-то, что м-может на нее влиять?\n\nЯсмин пыталась унять дрожь в руках.\n\n\"Волнение. Я просто переживаю. И сон был дурной. Но.. почему так тихо? Как перед бурей... страшно, мне так страшно, но нельзя. Нет. Я должна держать себя в руках.\"",212725,null],[278286,"2026-10-21T18:41:30",31,"Марко проводит ритуал обнаружения магии, 10 минут его кропотливого труда показывают, что девушка находится под сильнейшим Очарованием, ее жизненная сила и сама душа находится в резонансе с домом, или возможно, с каким то якорем в доме. Ритуал показывает, что жизненная сила уходит из девушки рывками, передаваясь куда то еще.\n\nВремя 00:55",212725,null],[278287,"2026-10-21T18:42:00",31,"Если ты пытаешься как то реанимировать девушку, то у тебя не выходит. Она не просыпается",278283,null],[278288,"2026-10-21T18:42:13",22,"/ох уж эти Батори",212725,null],[278289,"2026-10-21T18:42:31",22,"/признаться, я ожидала кровавую ванну",212725,null],[278290,"2026-10-21T18:42:57",31,"Изначально фамилия графини была Браттори)) но я решил что это уж слишком)/",278288,null],[278291,"2026-10-21T18:43:27",31,"Одной жертвы мало для целой ванны. 5 литров крови, ерунда какая/",278289,null],[278293,"2026-10-21T18:54:43",17,"/ нет",278271,null],[278296,"2026-10-21T18:58:21",31,"Что делаете?",212725,null],[278297,"2026-10-21T19:04:56",20,"- Сеньор, вы видите куда ведёт  магический след? Нужно прервать ритуал как можно скорее! *Беатриче уже выхватывает рапиру, готовая бежать как только Марко укажет куда*",212725,null],[278298,"2026-10-21T19:12:11",31,"Если что, я еще примерно час тут/",212725,null],[278299,"2026-10-21T19:16:53",22,"Ясмин тоже готова следовать за следом, по которому нас поведёт Марко.",212725,null],[278300,"2026-10-21T19:17:41",31,"Тем временем пробило час ночи. Беатриче и Ясмин снова бросают спасы мудрости СЛ 16",212725,null],[278301,"2026-10-21T19:18:39",20,"/r +d20+1",212725,null],[278302,"2026-10-21T19:18:39",31,"У Беатриче есть преимущество, Благословение Аскклатора работает",212725,null],[278304,"2026-10-21T19:18:47",31,"Не помогло",212725,null],[278305,"2026-10-21T19:18:57",20,"/ну ладно, пробуем ещё за удачу разок",212725,null],[278306,"2026-10-21T19:19:05",20,"/r d20+1",212725,null],[278308,"2026-10-21T19:19:11",31,"Ууу",212725,null],[278309,"2026-10-21T19:19:13",20,"/ахаха",212725,null],[278310,"2026-10-21T19:19:17",20,"/ну ладно",212725,null],[278311,"2026-10-21T19:19:46",31,"/roll d8 пчмхичесутц урон по Беатриче полный и первая стадия истощения",212725,null],[278313,"2026-10-21T19:20:17",20,"/я полагаю такой спас мы кидаем потому что являемся девушками?\n/А Марко этот эффект избегает",212725,null],[278314,"2026-10-21T19:20:21",31,"Ну должно же т мне иногда везти на кубы/",212725,null],[278315,"2026-10-21T19:20:39",31,"Ты весьма догадливая/",278313,null],[278316,"2026-10-21T19:21:12",31,"Елена тоже отгадала часть жизненной силы в этот момент/",212725,null],[278317,"2026-10-21T19:22:03",31,"Поэтому в ваших интересах побыстрее свалить отсюда, иначе ночь не переживёте/",212725,null],[278318,"2026-10-21T19:23:24",31,"@lady_godzilla",212725,null],[278319,"2026-10-21T19:28:06",22,"/r -d20+7",278300,null],[278321,"2026-10-21T19:28:51",31,"4 урона, без повышения уровня истощения",278320,null],[278322,"2026-10-21T19:29:33",31,"Ждем Марко, который вас поведет вниз/",212725,null],[278323,"2026-10-21T19:35:08",22,"Ясмин пошатнулась и заметила, что из у нее идет кровь носом.\n\nДевушка подняла голову и бросилась к Елене, излечивая ее и себя.\n\n(Метамагия+ячейка 2кр)",212725,null],[278324,"2026-10-21T19:35:34",22,"/r 2d8+5 лечим",212725,null],[278326,"2026-10-21T19:36:22",22,"Потом Ясмин встала и осмотрела Беатриче.",212725,null],[278327,"2026-10-21T19:36:26",22,"/r d8+5",212725,null],[278329,"2026-10-21T19:37:20",20,"- Спасибо, синьора. *Беатриче благодарно кивает, чувствуя что давящее на голову ощущение хоть и не прошло, но чуть легче определенно стало*",212725,null],[278330,"2026-10-21T19:38:02",31,"Видимо, столкновение с боссом играть будем уже завтра. Ну еще полчаса я тут/",212725,null],[278331,"2026-10-21T19:39:50",17,"— Девушки, что с вами? Ясмин у тебя кровь вдруг пошла из носа",212725,null],[278332,"2026-10-21T19:40:57",22,"-- Э-это место, оно будто в-выпивает из меня силы.",212725,null],[278333,"2026-10-21T19:41:13",22,"-- Попробуйте н-найти источник, Марко.",212725,null],[278334,"2026-10-21T19:41:51",17,"— Возможно проклят весь дом. Ну-ка\n\nМарко берет предположительно Елену на руки \n\n— Давайте покинем это место и будем разбираться уже на безопасной территории",212725,null],[278335,"2026-10-21T19:42:52",22,"-- Я-я думала, что это просто был плохой сон, но тут что-то не так со всем д-домом.\n\nДевушка обхватила себя руками, будьо пытается защититься.\n\n-- Н-нужно уходить, д-да",212725,null],[278336,"2026-10-21T19:43:21",31,"Выход отсюда один, через ту же винтовую лестницу и библиотеку",212725,null],[278337,"2026-10-21T19:43:22",17,"/ Каждый час будет жёсткий спас",212725,null],[278338,"2026-10-21T19:43:31",17,"— Поспешим на выход",212725,null],[278339,"2026-10-21T19:47:42",31,"Вы спускаетесь по лестнице в библиотку с целью свалить из особняка. Но похоже, так просто это вам не удастся.\n\nВы выходите из-за потайной двери и видите перед собой графиню в окружении троих ее слуг.\n\n- Любопытные гости... Кажется, вы узнали мою маленькую тайну. Только из из искринеей симпатии у таким геолясгероям как вы, я позволю вам испарить вашу ошибку. Верните девушку в постель и тихо растворитесь в ночи, забыв о нашей встрече. Совестьас немого помучает, но ведь лучше быть живым и вообще хоть что то чувствовать?",212725,null],[278340,"2026-10-21T19:50:20",22,"Ясмин достаёт огнемет",212725,null],[278341,"2026-10-21T19:50:35",20,"- О, а я уж было решила что мы и правда уйдем, не поквитавшись за такое 'гостеприимство' *Беатриче выступает вперёд, прикрывая собой Марко и Ясмин*\n- Кажется у судьбы другие планы, сеньора",278339,null],[278342,"2026-10-21T19:50:59",31,"Инициатива)",212725,null],[278343,"2026-10-21T19:51:24",20,"/r -d20+4 давай...",212725,null],[278345,"2026-10-21T19:53:05",22,"/r -d20+2",212725,null],[278347,"2026-10-21T19:53:29",31,"/roll d20+3 Графиня\n/roll d20+2 Дворецкий с подносом\n/roll d20+1 Садовник с секатором\n/roll d20 повар с топором для рубки мяса",212725,null],[278349,"2026-10-21T19:54:10",31,"/roll d20-1 Логово",212725,null],[278351,"2026-10-21T20:03:49",31,"@dunchev брось пожалуйста инициативу, я вас соберу в общий список и завтра утром нарисую карту и буду вас бить/",212725,null],[278355,"2026-10-21T20:26:32",17,"/r +2 Извините занятая я колбаска вечером",212725,null],[278383,"2026-10-22T02:27:16",31,"Графиня 3 урона\nЛогово\nДворецкий с подносом 6 урона\nМарко\nБеатриче\nПовар с топором 25 урона - мертв\nЯсмин\nСадовник с секаторм 6 урона",212725,null],[278385,"2026-10-22T06:42:28",31,"Это лучшее что я смог сделать. Хорошо что у нас у всех наименовая с разных букв)) Клетки из расчета 5 на 5 утов",212725,null],[278386,"2026-10-22T06:44:29",31,"Ход Графини//",212725,null],[278387,"2026-10-22T06:45:20",31,"/roll d6 на перезарядку способности",212725,null],[278389,"2026-10-22T06:45:25",31,"прошло",212725,null],[278390,"2026-10-22T06:48:41",31,"Графиня применяет Шепот Искушения против Марко\n\n- Вы же не обидите леди, правда? А я найду чем отблагодарить...\n\nСпас Мудрости о Марко, СЛ 15, иначе Очарован на минуту",212725,null],[278391,"2026-10-22T06:49:38",31,"Вторая атака по Беатриче, Ментальный удар",212725,null],[278392,"2026-10-22T06:49:44",31,"/roll d20+7",212725,null],[278394,"2026-10-22T06:50:35",31,"/roll 2d6+4 психического урона",212725,null],[278396,"2026-10-22T06:50:59",31,"ход окончен//",212725,null],[278397,"2026-10-22T06:51:05",31,"Ход Логова//",212725,null],[278398,"2026-10-22T06:51:26",31,"/roll d10",212725,null],[278400,"2026-10-22T06:52:19",31,"Все часы в доме начинают оглушительно бить, от всех троих спас Тела 15",212725,null],[278401,"2026-10-22T06:52:43",31,"/roll d6 для тех кто не прошел спас тела",212725,null],[278403,"2026-10-22T06:52:58",31,"/ход окончен",212725,null],[278404,"2026-10-22T06:53:08",31,"/ход дворецкого",212725,null],[278405,"2026-10-22T06:53:20",17,"/ Гениальная графиня наложит очарование и логовом его снимет)",212725,null],[278406,"2026-10-22T06:53:41",17,"/r +6 Спас мудрости +1 Спас тела",212725,null],[278408,"2026-10-22T06:53:48",31,"Он поднимает поднос наподобие щита, тготов защитить госпожу",212725,null],[278409,"2026-10-22T06:54:32",31,"немножко урона от боя часов и разве он снимет очарование?/",278407,null],[278410,"2026-10-22T06:55:31",31,"мне кажется нет/",212725,null],[278411,"2026-10-22T06:56:15",31,"В Общем, Графина теперь друг Марко, ее обижать нельзя. Но слуг можно))) и в конце соего хода можно бросить спас заново",212725,null],[278412,"2026-10-22T06:56:34",31,"ход Марко, у него на руках Елена",212725,null],[278413,"2026-10-22T07:16:10",17,"/ В библиотеке есть окна?",212725,null],[278414,"2026-10-22T07:16:52",31,"Есть, два. Ты возле одного из них/",278413,null],[278415,"2026-10-22T07:17:03",31,"В 10 футах",212725,null],[278416,"2026-10-22T07:18:06",17,"Обнаружении магии ещё работает вероятно они не светятся заградительными магическими барьерами?",212725,null],[278417,"2026-10-22T07:19:20",31,"Увы, окна часть логова/",278416,null],[278418,"2026-10-22T07:25:27",17,"Марко вдруг видит в графине и остальных обсолютно адекватных людей, забыв обо всех открытиях, лжи и злом умысле. Он не осознает что это магия и это его пугает.\n\nОн помнит, что секунду назад была какая то опасность. Но откуда. От кого уже заблокировано магией. \n\n\nОн бережно кладет тело Елены на читальный стол рядом. \n\nСмотрит на своих союзниц. Они тоже выглядят как и раньше. \n\nВ замешательстве он призывает из теней голову шакала парящую над землёй и сам встаёт перед столом где положил девушку. \n\nГлядя на бледное тело молодой девушки он точно помнит зачем выносил не на руках из потайной комнаты - чтобы спасти.\n\nОдно намерение, если кто то будет пытаться навредить ей, Марко ударит несмотря ни на что.",212725,null],[278419,"2026-10-22T07:25:55",17,"/ Бонусным призвал божественное оружие. \n\nЗаготовлено дейтвие атака если кто то пытается навредить Елене.\n\nКонец хода",212725,null],[278420,"2026-10-22T07:26:25",31,"Ход Беатриче/",212725,null],[278421,"2026-10-22T07:27:27",31,"@PaIIasCat залетай как будешь готова. Тебя уже успели поранить и еще нужен спас тела. ПРочитай короче все что выше и вперед))/",212725,null],[278422,"2026-10-22T07:28:16",31,"ты забыл бросить спас в конце хода. один ты бросал при атаке графини, последующие в конце своих ходв/",278419,null],[278423,"2026-10-22T07:43:13",17,"/r +6 И то верно",212725,null],[278425,"2026-10-22T07:45:08",17,"Морок спал когда Марко сосредоточился на защите девушки. Графиня и слуги вновь предстали в своем истинною обличии\n\n— Спасибо за оказанное гостеприимство. Мы нашли девушку и спешим покинуть вас, графиня. Окажите милость, пропустите.",212725,null],[278426,"2026-10-22T07:45:22",17,"— И никто не пострадает.",212725,null],[278427,"2026-10-22T07:52:56",31,"- увы, милый Марко. Твои спутницы уже подняли оружие. Кто то все таки пострадает.",212725,null],[278428,"2026-10-22T08:25:15",22,"/r -d20+2 тело Яс",278400,null],[278430,"2026-10-22T08:26:04",31,"Сильна мать/",278429,null],[278431,"2026-10-22T08:27:34",22,"/Ясмин мощь!",212725,null],[278442,"2026-10-22T10:06:57",20,"/r d20+4 спас тела",212725,null],[278446,"2026-10-22T10:08:26",31,"Вымещай свое зло на этих говнюках)/",212725,null],[278448,"2026-10-22T10:08:55",20,"/с помехой на атаки это конечно интересная задачка)",212725,null],[278450,"2026-10-22T10:09:32",20,"*Беатриче бросается вперёд на врагов - а именно на повора с топором*",212725,null],[278451,"2026-10-22T10:10:05",20,"/r -d20+7\n/r -d20+6",212725,null],[278453,"2026-10-22T10:10:14",31,"Рапира прошла",212725,null],[278454,"2026-10-22T10:10:31",20,"/r d8+5 урона",212725,null],[278457,"2026-10-22T10:10:56",20,"/конец хода, дальше ловим топор лицом с такими кубами",212725,null],[278458,"2026-10-22T10:11:20",17,"/Благословить надо магией бога смерти эту сиору",212725,null],[278459,"2026-10-22T10:11:45",31,"Ща убьём, потом благословишь)/",278458,null],[278460,"2026-10-22T10:12:26",31,"/roll d20 повар, раненый рапирой, бьёт Беатриче в ответ",212725,null],[278462,"2026-10-22T10:12:38",31,"Топор свистит мимо",212725,null],[278463,"2026-10-22T10:12:39",20,"/кстати с повышением уровня КД 21 теперь:3",278458,null],[278464,"2026-10-22T10:12:43",31,"Ход/",212725,null],[278465,"2026-10-22T10:12:57",20,"/Ясмин ЖГИ",212725,null],[278466,"2026-10-22T10:13:01",31,"@lady_godzilla Ясмин, жги!",212725,null],[278467,"2026-10-22T10:13:04",22,"//погоди, почему помеха",278448,null],[278468,"2026-10-22T10:13:25",22,"//истощение 1 на атаки не даёт помеху",212725,null],[278469,"2026-10-22T10:13:41",31,"Только проверки и спасы/",212725,null],[278470,"2026-10-22T10:13:45",20,"/а это разве не проверка?",278467,null],[278471,"2026-10-22T10:14:01",22,"/неа, только истощение 3 даёт помеху на атаки\n\nВообще и на спасы нет помехи,",278470,null],[278472,"2026-10-22T10:14:17",20,"/поняла, спасибо",212725,null],[278473,"2026-10-22T10:14:20",31,"Ну там в любом случае не прошло/",212725,null],[278475,"2026-10-22T10:15:33",31,"О, мой проеб/",212725,null],[278476,"2026-10-22T10:15:42",31,"Был уверен что и спасы тоже/",212725,null],[278477,"2026-10-22T10:15:54",22,"/я тоже, ладно пофиг, продолжаем",212725,null],[278480,"2026-10-22T10:17:52",22,"Ясмин смещается так, чтобы накрывать 10фт конусом С Д Г \n\nПосле чего даёт залп огня по ним и за спиной Г призывает куриную лапку, которая сразу бьет.\n\n//где-то явно \"В\" потеряли😅\nС товарищей спас лвк 13, иначе половина",212725,null],[278481,"2026-10-22T10:19:00",22,"/r 4d6 огонь\n/r d10+1 проверка прочности\n/r d20+7 лапка цап\n/r d8+5 урон лапкой",212725,null],[278483,"2026-10-22T10:19:08",22,"/ход",212725,null],[278484,"2026-10-22T10:19:24",31,"/roll d20+3 Графиня\n/roll d20+2 Дворецкий\n/roll d20+1 Садовник",212725,null],[278487,"2026-10-22T10:20:54",31,"Ход садовника",212725,null],[278488,"2026-10-22T10:21:15",31,"Бежит на Ясмин, замахиваясь секатором",212725,null],[278489,"2026-10-22T10:21:37",31,"/roll d20+2",212725,null],[278491,"2026-10-22T10:21:38",22,"Вспышка",212725,null],[278492,"2026-10-22T10:22:16",22,"/вспышка  - атака с помехой, если цель может быть ослеплена(тк это конструкт, то сомневаюсь,но Яс то не знает)",212725,null],[278493,"2026-10-22T10:22:35",31,"Да и так не попал/",212725,null],[278494,"2026-10-22T10:23:03",31,"Вспышка яркого света дезориентировала Янника, он промахнулся",212725,null],[278495,"2026-10-22T10:25:30",31,"Извините, рисовать не буду, и так перематерился. Просто знайте что Марко у стола, Ясмин рядом, перед ней садовник, чуть дальше графиня и дворецкий, а в стороне Беатриче и повар",212725,null],[278496,"2026-10-22T10:25:34",31,"Ход графини",212725,null],[278497,"2026-10-22T10:26:18",31,"/roll d6 перезарядка Шепота",212725,null],[278499,"2026-10-22T10:26:23",31,"не прошло/",212725,null],[278500,"2026-10-22T10:26:50",31,"/roll d20+7 Ментальный удар по Ясмин",212725,null],[278502,"2026-10-22T10:27:04",31,"/roll 2d6+4",212725,null],[278504,"2026-10-22T10:27:34",31,"Графиня в ярости от боли, что причинила ей Ясмин и стремится наказать ее",212725,null],[278505,"2026-10-22T10:27:44",31,"ход окончен/",212725,null],[278506,"2026-10-22T10:27:48",31,"ход логова/",212725,null],[278507,"2026-10-22T10:27:53",31,"/roll d10",212725,null],[278509,"2026-10-22T10:29:14",31,"Где то внизу бьют часы. Тело граини окутывается призрачным красным светом, ее раны исцелены, +15 ХП",212725,null],[278510,"2026-10-22T10:29:24",31,"ход окончен/",212725,null],[278511,"2026-10-22T10:29:34",31,"Ход Дворецкого",212725,null],[278512,"2026-10-22T10:29:49",31,"Все также стоит, прикрывая госопжу подносом",212725,null],[278513,"2026-10-22T10:29:55",31,"ход окончен/",212725,null],[278514,"2026-10-22T10:29:59",31,"Ход Марко",212725,null],[278550,"2026-10-22T11:21:50",17,"Марко указывает теневым когтем на графиню и приказывает ей\n\n— ПОДОЙДИ!",212725,null],[278551,"2026-10-22T11:21:57",17,"/Спас мудрости СЛ 14",212725,null],[278552,"2026-10-22T11:22:04",17,"/Если она не нежить",212725,null],[278553,"2026-10-22T11:22:07",17,"/Иначе ну как обычно",212725,null],[278554,"2026-10-22T11:22:10",17,"/Обтекаю",212725,null],[278558,"2026-10-22T11:24:03",31,"Ну как тебе сказать... У меня записано средняя нежить)/",212725,null],[278559,"2026-10-22T11:24:16",17,"/Конец хода",212725,null],[278560,"2026-10-22T11:24:40",31,"- смешно, простолюдин с претензией. Я убью тебя последним",212725,null],[278561,"2026-10-22T11:24:58",31,"@PaIIasCat ход",212725,null],[278562,"2026-10-22T11:25:24",17,"Марко рычит злобно\n\nКогда нибудь он заставит кого то слушаться",212725,null],[278563,"2026-10-22T11:26:08",31,"/дорогой дневник. Словами не передать ту боль и унижение.../",212725,null],[278564,"2026-10-22T11:26:37",20,"*Беатриче снова наносит два удара по повару с топором*",278561,null],[278565,"2026-10-22T11:26:51",20,"/r d20+7\n/r d20+6",212725,null],[278567,"2026-10-22T11:26:57",31,"Обе прошли",212725,null],[278568,"2026-10-22T11:27:28",20,"/r d8+5\n/r d4+4",212725,null],[278574,"2026-10-22T11:28:22",31,"Убила, описывай смерть и взрыв его кристаллического ядра, с выходом молнии",212725,null],[278577,"2026-10-22T11:30:25",31,"Молния не по тебе, а по графине)/",212725,null],[278579,"2026-10-22T11:30:52",20,"*Беатриче делает два быстрых удара, чередуя лезвия рапиры и кинжала. Последний приходится противнику прямо в сердце*\n\n- Ага! \n\n*Ее торжество слегка прерывается, когда она чувствует странный электрический разряд, пришедший по ее кинжалу*",212725,null],[278580,"2026-10-22T11:31:19",20,"/а",278577,null]]);
